for (i = 0x1161; i <= 0x1175; i++) unicode_ga.push(i);
for (i = 0x11A8; i <= 0x11C2; i++) unicode_ggeut.push(i);

var unicode_NFD_hangeul_phoneme = unicode_cheos.concat(unicode_ga, unicode_ggeut);

// 쿼티 키 매핑
var dkey = [96, 49, 50, 51, 52, 53, 54, 55, 56, 57, 48, 45, 61, 8,
    9, 113, 119, 101, 114, 116, 121, 117, 105, 111, 112, 91, 93, 92,
