    0x61, 0x62, 0x63, 0x64, 0x65, 0x66, 0x67, 0x68, 0x69, 0x6A, 0x6B, 0x6C, 0x6D, 0x6E, 0x6F, 0x70,
    0x71, 0x72, 0x73, 0x74, 0x75, 0x76, 0x77, 0x78, 0x79, 0x7A, 0x7B, 0x7C, 0x7D, 0x36, 0x2D, 0x7E,
    0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4A, 0x4B, 0x4C, 0x4D, 0x4E, 0x4F, 0x50,
    0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59, 0x5A, 0x5B, 0x5C, 0x5D, 0x60
];

var layout_Sin3_P2 = [
    [0x0021, 0x0000], [0x002F, 0x0000], [0x0023, 0x0000], [0x0024, 0x0000],
    [0x0025, 0x0000], [0x0026, 0x0000], [0x1110, 0x0000], [0x0028, 0x0000],
    [0x0029, 0x0000], [0x002A, 0x0000], [0x002B, 0x0000], [0x002C, 0x0000],
    [0x002D, 0x0000], [0x002E, 0x0000], [0x110F, 0x1169], [0x0030, 0x0000],
    [0x0031, 0x0000], [0x0032, 0x0000], [0x0033, 0x0000], [0x0034, 0x0000],
    [0x0035, 0x0000], [0x0036, 0x0000], [0x0037, 0x0000], [0x0038, 0x0000],
    [0x0039, 0x0000], [0x003A, 0x0000], [0x1107, 0x0000], [0x003C, 0x0000],
    [0x003D, 0x0000], [0x003E, 0x0000], [0x003F, 0x0000], [0x0040, 0x0000],
    [0x1172, 0x11AA], [0x116E, 0x0000], [0x1166, 0x11A9], [0x1175, 0x11B6],
    [0x1162, 0x11B2], [0x1161, 0x11B5], [0x1173, 0x0000], [0x25A1, 0x0000],
    [0x0000, 0x0000], [0x0027, 0x0000], [0x0022, 0x0000], [0x00B7, 0x0000],
    [0x2026, 0x0000], [0x2015, 0x0000], [0x0000, 0x0000], [0x003B, 0x0000],
    [0x1164, 0x11B3], [0x1165, 0x11B4], [0x1168, 0x11AD], [0x1167, 0x0000],
    [0x25CB, 0x0000], [0x1169, 0x11AC], [0x1163, 0x11B0], [0x116D, 0x11B9],
    [0x00D7, 0x0000], [0x119E, 0x11B1], [0x005B, 0x0000], [0x005C, 0x0000],
    [0x005D, 0x0000], [0x005E, 0x0000], [0x005F, 0x0000], [0x0060, 0x0000],
    [0x11BC, 0x0000], [0x11BE, 0x0000], [0x11A8, 0x0000], [0x11C2, 0x0000],
    [0x11B8, 0x0000], [0x11C1, 0x0000], [0x11AE, 0x0000], [0x1102, 0x0000],
    [0x1106, 0x1173], [0x110B, 0x0000], [0x1100, 0x0000], [0x110C, 0x0000],
    [0x1112, 0x0000], [0x1109, 0x0000], [0x110E, 0x116E], [0x1111, 0x119E],
    [0x11BA, 0x0000], [0x11C0, 0x0000], [0x11AB, 0x0000], [0x11BF, 0x0000],
