    [0x1105, 0x0000], [0x11B7, 0x0000], [0x007B, 0x0000], [0x007C, 0x0000],
    [0x007D, 0x0000], [0x007E, 0x0000]
];

var hangeul_combination_table_default = [
    [0x11001100, 0x1101], [0x11031103, 0x1104], [0x11071107, 0x1108],
    [0x11091109, 0x110A], [0x110C110C, 0x110D], [0x11691161, 0x116A],
    [0x11691162, 0x116B], [0x11691175, 0x116C], [0x116E1165, 0x116F],
    [0x116E1166, 0x1170], [0x116E1175, 0x1171], [0x11731175, 0x1174],
    [0x119E1175, 0x11A1], [0x119E119E, 0x11A2], [0x11A811A8, 0x11A9],
    [0x11A811BA, 0x11AA], [0x11AB11BD, 0x11AC], [0x11AB11C2, 0x11AD],
    [0x11AF11A8, 0x11B0], [0x11AF11B7, 0x11B1], [0x11AF11B8, 0x11B2],
    [0x11AF11BA, 0x11B3], [0x11AF11C0, 0x11B4], [0x11AF11C1, 0x11B5],
    [0x11AF11C2, 0x11B6], [0x11B811BA, 0x11B9], [0x11BA11BA, 0x11BB]
];

var ohiQ = [0, 0, 0, 0, 0, 0, 0, 0, 0];
var NFD_stack = { phoneme: [], phoneme_R: [], combined_phoneme: [] };

function with_shift_key(key) {
    if (key < 0x21) return false;
    else if (key <= 0x26) return true;
    else if (key == 0x27) return false;
    else if (key <= 0x2B) return true;
    else if (key <= 0x39) return false;
    else if (key == 0x3A) return true;
    else if (key == 0x3B) return false;
    else if (key == 0x3C) return true;
    else if (key == 0x3D) return false;
    else if (key <= 0x5A) return true;
    else if (key <= 0x5D) return false;
    else if (key <= 0x5F) return true;
    else if (key <= 0x7A) return false;
    else if (key <= 0x7E) return true;
    return false;
}

function convert_into_ohi_hangeul_phoneme(c) {
    var idx = unicode_cheos.indexOf(c);
    if (idx >= 0) return ohi_cheos[idx];
    idx = unicode_ga.indexOf(c);
    if (idx >= 0) return ohi_ga[idx];
    idx = unicode_ggeut.indexOf(c);
    if (idx >= 0) return ohi_ggeut[idx];
    return c;
}

function convert_into_unicode_hangeul_phoneme(c) {
    var idx = ohi_cheos.indexOf(c);
    if (idx >= 0) return unicode_cheos[idx];
    idx = ohi_ga.indexOf(c);
    if (idx >= 0) return unicode_ga[idx];
    idx = ohi_ggeut.indexOf(c);
    if (idx >= 0) return unicode_ggeut[idx];
    return c;
}

function combine_unicode_NFD_hangeul_phoneme(c1, c2) {
    var combined_phoneme = 0x10000 * c1 + c2;
    for (var i = 0; i < hangeul_combination_table_default.length; ++i) {
        if (combined_phoneme == hangeul_combination_table_default[i][0]) {
            return hangeul_combination_table_default[i][1];
        }
    }
    return 0;
}

function ohiInput(f, c) {
    if (!f || !c) return;
    var charStr = String.fromCharCode(c);
    var start = f.selectionStart;
    var end = f.selectionEnd;
    f.value = f.value.substring(0, start) + charStr + f.value.substring(end);
    f.selectionStart = f.selectionEnd = start + charStr.length;
}

function ohiBackspace(f) {
    var start = f.selectionStart;
    var end = f.selectionEnd;
    if (start === end && start > 0) {
        f.value = f.value.substring(0, start - 1) + f.value.substring(end);
        f.selectionStart = f.selectionEnd = start - 1;
    } else if (start !== end) {
        f.value = f.value.substring(0, start) + f.value.substring(end);
        f.selectionStart = f.selectionEnd = start;
    }
}

function complete_hangeul_syllable(f) {
    if (!(ohiQ[0] + ohiQ[3] + ohiQ[6])) return;

    var i = ohiQ[0] ? ohiQ[0] : 0;
    var j = ohiQ[3] ? ohiQ[3] : 0;
    var k = ohiQ[6] ? ohiQ[6] : 0;

    var c = 0;
    if (i && j) {
        c = 0xAC00 + (i - (i < 3 ? 1 : i < 5 ? 2 : i < 10 ? 4 : i < 20 ? 11 : 12)) * 588 + (j - 31) * 28 + k - (k < 8 ? 0 : k < 19 ? 1 : k < 25 ? 2 : 3);
    } else {
        c = 0x3130 + (i || j || k);
    }

    if (ohiQ[0] || ohiQ[3] || ohiQ[6]) {
        var len = (ohiQ[0] > 0 ? 1 : 0) + (ohiQ[3] > 0 ? 1 : 0) + (ohiQ[6] > 0 ? 1 : 0);
        for (var x = 0; x < len; x++) ohiBackspace(f);
        ohiInput(f, c);
    }

    ohiQ = [0, 0, 0, 0, 0, 0, 0, 0, 0];
}

function NFC_galmadeuli_preprocess(f, e, key) {
    var c1, c2, sub_c1 = 0, sub_c2 = 0;
    var layout = layout_Sin3_P2;

    if (typeof layout[key - 33] == 'number') {
        c1 = layout[key - 33];
        c2 = layout[shift_table[key - 33] - 33];
    } else {
        c1 = layout[key - 33][0];
        c2 = layout[shift_table[key - 33] - 33][0];
        sub_c1 = layout[key - 33][1];
        sub_c2 = layout[shift_table[key - 33] - 33][1];
    }

    var isShift = with_shift_key(key);
    var c = c1;

    if (!isShift && unicode_ga.indexOf(convert_into_unicode_hangeul_phoneme(c1)) >= 0 && unicode_ggeut.indexOf(convert_into_unicode_hangeul_phoneme(c2)) >= 0) {
        if (ohiQ[0] && !ohiQ[3] && !ohiQ[6]) {
        } else if (ohiQ[0] && ohiQ[3]) {
            c = c2; 
        }
    }

    return convert_into_unicode_hangeul_phoneme(c);
}

function ohiDoubleJamo(a, c, d) {
    var j = [
        [[1, 7, 18, 21, 24], 1, 7, 18, 21, 24],
        [[39, 44, 49], [31, 32, 51], [35, 36, 51], 51],
        [[1, 4, 9, 18, 21], [1, 21], [24, 30], [1, 17, 18, 21, 28, 29, 30], [0, 21], 21]
    ];
    a = j[a];
    for (var i = a[0].length; c != a[0][i - 1]; i--) if (!i) return i;
    for (a = a[i], i = a.length || 1; 1; i--) if (!i || d == a || d == a[i - 1]) return i;
    return 0;
}

function ohiKeypress(e) {
    if (!OHI_STATUS.active) return true;
    e = e || window.event;
    var f = e.target || e.srcElement;
    if (f.id !== 'wpTextbox1') return true;

    var key = e.which || e.keyCode;

    if (e.ctrlKey || e.altKey) return true;

    if (key === 13 || key === 32) {
        complete_hangeul_syllable(f);
        return true;
    }

    if (key > 32 && key < 127) {
        e.preventDefault();

        var c = NFC_galmadeuli_preprocess(f, e, key);
        if (c <= 0) return false;

        c = convert_into_ohi_hangeul_phoneme(c);

        if (ohi_cheos.indexOf(c) >= 0) {
            c -= 127;
            if (ohiQ[3]) complete_hangeul_syllable(f);
            ohiQ[0] = c;
            ohiInput(f, 0x3130 + c);
        } else if (ohi_ga.indexOf(c) >= 0) {
            c -= 35;
            if (ohiQ[3] && !ohiQ[6]) {
                var double_val = ohiDoubleJamo(1, ohiQ[3], c);
                if (double_val) {
                    ohiBackspace(f);
                    ohiQ[3] = double_val;
                    ohiInput(f, 0x3130 + double_val + 35);
                } else {
                    complete_hangeul_syllable(f);
                    ohiQ[3] = c;
                    ohiInput(f, 0x3130 + c + 35);
                }
            } else {
                if(ohiQ[6]) complete_hangeul_syllable(f);
                ohiQ[3] = c;
                ohiInput(f, 0x3130 + c + 35);
            }
        } else if (ohi_ggeut.indexOf(c) >= 0) {
            if(!ohiQ[3]) return false;
            var double_val = ohiDoubleJamo(2, ohiQ[6], c);
            if(ohiQ[6] && double_val) {
                ohiBackspace(f);
                ohiQ[6] = double_val;
                ohiInput(f, 0x3130 + double_val);
            } else {
                if(ohiQ[6]) complete_hangeul_syllable(f);
                ohiQ[6] = c;
                ohiInput(f, 0x3130 + c);
            }
        }

        var key_td = document.getElementById('key' + (key - 33));
        if(key_td) {
            key_td.className += ' pressed';
            setTimeout(function() { key_td.className = key_td.className.replace(' pressed', ''); }, 100);
        }
        return false;
    }
    return true;
}

function ohiKeydown(e) {
    if (!OHI_STATUS.active) return true;
    e = e || window.event;
    var f = e.target || e.srcElement;
    if (f.id !== 'wpTextbox1') return true;

    if (e.keyCode === 8) { // Backspace
        if (ohiQ[0] || ohiQ[3] || ohiQ[6]) {
            e.preventDefault();
            ohiBackspace(f);
            if (ohiQ[6]) ohiQ[6] = 0;
            else if (ohiQ[3]) ohiQ[3] = 0;
            else if (ohiQ[0]) ohiQ[0] = 0;
        }
    }
}

// 키보드 UI 렌더링
function renderKeyboard() {
    var wrap = document.getElementById('wpTextbox1');
    if (!wrap) return;

    var container = document.getElementById('ohi_keyboard_container');
    if (!container) {
        container = document.createElement('div');
        container.id = 'ohi_keyboard_container';
        container.style.marginTop = '10px';
        container.style.textAlign = 'center';
        container.style.fontFamily = 'sans-serif';
        wrap.parentNode.insertBefore(container, wrap.nextSibling);
    }

    var html = '<div style="background:#f8f9fa; border:1px solid #c8ccd1; padding:10px; border-radius:2px; display:inline-block;">';

    // 단순화된 헤더 (켜기/끄기 토글)
    html += '<div style="text-align:left; margin-bottom:5px;">';
    html += '<label><input type="checkbox" checked onclick="OHI_STATUS.active=this.checked; document.getElementById(\'wpTextbox1\').focus();"> 한글 입력기 (신세벌식 P2)</label>';
    html += '</div>';

    // 4줄의 키보드 레이아웃 렌더링
    var ue = [
        ['`','1','2','3','4','5','6','7','8','9','0','-','=','Back'],
        ['Tab','q','w','e','r','t','y','u','i','o','p','[',']','\\'],
        ['Caps','a','s','d','f','g','h','j','k','l',';','\'','Enter'],
        ['Shift','z','x','c','v','b','n','m',',','.','/','Shift']
    ];

    var dh = [
        ['', '', '', '', '', '', '', '', '', '', '', '', '', ''],
        ['', 'ㅂ', 'ㅈ', 'ㄷ', 'ㄱ', 'ㅅ', 'ㅛ', 'ㅕ', 'ㅑ', 'ㅐ', 'ㅔ', '【', '】', ''],
        ['', 'ㅁ', 'ㄴ', 'ㅇ', 'ㄹ', 'ㅎ', 'ㅗ', 'ㅓ', 'ㅏ', 'ㅣ', ';', '\'', ''],
        ['', 'ㅋ', 'ㅌ', 'ㅊ', 'ㅍ', 'ㅠ', 'ㅜ', 'ㅡ', ',', '.', '/', '']
    ];

    for (var i = 0; i < ue.length; i++) {
        html += '<div style="margin: 2px 0; white-space:nowrap;">';
        for (var j = 0; j < ue[i].length; j++) {
            var width = '36px';
            if (ue[i][j] === 'Back') width = '62px';
            if (ue[i][j] === 'Tab') width = '56px';
            if (ue[i][j] === 'Caps') width = '67px';
            if (ue[i][j] === 'Enter') width = '71px';
            if (ue[i][j] === 'Shift' && j === 0) width = '87px';
            if (ue[i][j] === 'Shift' && j !== 0) width = '91px';

            var keyCharCode = ue[i][j].length === 1 ? ue[i][j].charCodeAt(0) : 0;
            var keyId = 'key' + (keyCharCode ? keyCharCode - 33 : 'S' + i + j);

            var bgColor = '#fff';
            if (dh[i][j]) bgColor = '#eaf3ff'; // 임의 색상

            html += '<div id="' + keyId + '" style="display:inline-block; width:' + width + '; height:38px; border:1px solid #ccc; background:' + bgColor + '; margin:1px; vertical-align:bottom; cursor:pointer; border-radius:2px; text-align:center; box-sizing:border-box;">';
            html += '<div style="color:#72777d; font-size:12px; text-align:left; padding-left:2px; height:18px;">' + ue[i][j] + '</div>';
            if (dh[i][j]) {
                html += '<div style="color:#202122; font-weight:bold; font-size:14px; text-align:right; padding-right:2px;">' + dh[i][j] + '</div>';
            }
            html += '</div>';
        }
        html += '</div>';
    }

    html += '<div style="margin: 2px 0;"><div style="display:inline-block; width:312px; height:38px; border:1px solid #ccc; background:#fff; cursor:pointer; border-radius:2px; line-height:38px;">Space</div></div>';

    html += '</div>';
    container.innerHTML = html;
}

// 초기화
$(function() {
    mw.hook('wikipage.editform').add(function() {
        var textbox = document.getElementById('wpTextbox1');
        if (textbox) {
            targetTextarea = textbox;
            textbox.addEventListener('keypress', ohiKeypress, false);
            textbox.addEventListener('keydown', ohiKeydown, false);
            renderKeyboard();
        }
    });
});

