    for (var i = 0; i < hangeul_combination_table_default.length; ++i) {
        if (combined_phoneme == hangeul_combination_table_default[i][0]) {
            return hangeul_combination_table_default[i][1];
        }
    }
    return 0;
}

function ohiInput(f, c) {
    if (!f || !c) return;
    var charStr = String.fromCharCode(c);
    var start = f.selectionStart;
    var end = f.selectionEnd;
    f.value = f.value.substring(0, start) + charStr + f.value.substring(end);
    f.selectionStart = f.selectionEnd = start + charStr.length;
}

function ohiBackspace(f) {
    var start = f.selectionStart;
    var end = f.selectionEnd;
    if (start === end && start > 0) {
        f.value = f.value.substring(0, start - 1) + f.value.substring(end);
        f.selectionStart = f.selectionEnd = start - 1;
    } else if (start !== end) {
        f.value = f.value.substring(0, start) + f.value.substring(end);
        f.selectionStart = f.selectionEnd = start;
    }
}

function complete_hangeul_syllable(f) {
    if (!(ohiQ[0] + ohiQ[3] + ohiQ[6])) return;

    var i = ohiQ[0] ? ohiQ[0] : 0;
    var j = ohiQ[3] ? ohiQ[3] : 0;
    var k = ohiQ[6] ? ohiQ[6] : 0;

    var c = 0;
    if (i && j) {
        c = 0xAC00 + (i - (i < 3 ? 1 : i < 5 ? 2 : i < 10 ? 4 : i < 20 ? 11 : 12)) * 588 + (j - 31) * 28 + k - (k < 8 ? 0 : k < 19 ? 1 : k < 25 ? 2 : 3);
    } else {
        c = 0x3130 + (i || j || k);
    }

    if (ohiQ[0] || ohiQ[3] || ohiQ[6]) {
        var len = (ohiQ[0] > 0 ? 1 : 0) + (ohiQ[3] > 0 ? 1 : 0) + (ohiQ[6] > 0 ? 1 : 0);
        for (var x = 0; x < len; x++) ohiBackspace(f);
        ohiInput(f, c);
    }

    ohiQ = [0, 0, 0, 0, 0, 0, 0, 0, 0];
