        c1 = layout[key - 33];
        c2 = layout[shift_table[key - 33] - 33];
    } else {
        c1 = layout[key - 33][0];
        c2 = layout[shift_table[key - 33] - 33][0];
        sub_c1 = layout[key - 33][1];
        sub_c2 = layout[shift_table[key - 33] - 33][1];
    }

    var isShift = with_shift_key(key);
    var c = c1;

    if (!isShift && unicode_ga.indexOf(convert_into_unicode_hangeul_phoneme(c1)) >= 0 && unicode_ggeut.indexOf(convert_into_unicode_hangeul_phoneme(c2)) >= 0) {
        if (ohiQ[0] && !ohiQ[3] && !ohiQ[6]) {
        } else if (ohiQ[0] && ohiQ[3]) {
            c = c2; 
        }
    }

    return convert_into_unicode_hangeul_phoneme(c);
}

function ohiDoubleJamo(a, c, d) {
    var j = [
        [[1, 7, 18, 21, 24], 1, 7, 18, 21, 24],
        [[39, 44, 49], [31, 32, 51], [35, 36, 51], 51],
        [[1, 4, 9, 18, 21], [1, 21], [24, 30], [1, 17, 18, 21, 28, 29, 30], [0, 21], 21]
    ];
    a = j[a];
    for (var i = a[0].length; c != a[0][i - 1]; i--) if (!i) return i;
    for (a = a[i], i = a.length || 1; 1; i--) if (!i || d == a || d == a[i - 1]) return i;
    return 0;
}

function ohiKeypress(e) {
    if (!OHI_STATUS.active) return true;
    e = e || window.event;
    var f = e.target || e.srcElement;
    if (f.id !== 'wpTextbox1') return true;

    var key = e.which || e.keyCode;

    if (e.ctrlKey || e.altKey) return true;

    if (key === 13 || key === 32) {
        complete_hangeul_syllable(f);
        return true;
    }

    if (key > 32 && key < 127) {
        e.preventDefault();

        var c = NFC_galmadeuli_preprocess(f, e, key);
        if (c <= 0) return false;

        c = convert_into_ohi_hangeul_phoneme(c);

        if (ohi_cheos.indexOf(c) >= 0) {
            c -= 127;
            if (ohiQ[3]) complete_hangeul_syllable(f);
            ohiQ[0] = c;
            ohiInput(f, 0x3130 + c);
        } else if (ohi_ga.indexOf(c) >= 0) {
            c -= 35;
            if (ohiQ[3] && !ohiQ[6]) {
                var double_val = ohiDoubleJamo(1, ohiQ[3], c);
                if (double_val) {
                    ohiBackspace(f);
                    ohiQ[3] = double_val;
                    ohiInput(f, 0x3130 + double_val + 35);
                } else {
                    complete_hangeul_syllable(f);
                    ohiQ[3] = c;
                    ohiInput(f, 0x3130 + c + 35);
                }
            } else {
                if(ohiQ[6]) complete_hangeul_syllable(f);
                ohiQ[3] = c;
                ohiInput(f, 0x3130 + c + 35);
            }
        } else if (ohi_ggeut.indexOf(c) >= 0) {
            if(!ohiQ[3]) return false;
            var double_val = ohiDoubleJamo(2, ohiQ[6], c);
            if(ohiQ[6] && double_val) {
                ohiBackspace(f);
                ohiQ[6] = double_val;
                ohiInput(f, 0x3130 + double_val);
            } else {
                if(ohiQ[6]) complete_hangeul_syllable(f);
                ohiQ[6] = c;
                ohiInput(f, 0x3130 + c);
            }
        }

        var key_td = document.getElementById('key' + (key - 33));
        if(key_td) {
            key_td.className += ' pressed';
            setTimeout(function() { key_td.className = key_td.className.replace(' pressed', ''); }, 100);
        }
        return false;
    }
    return true;
}

function ohiKeydown(e) {
    if (!OHI_STATUS.active) return true;
    e = e || window.event;
    var f = e.target || e.srcElement;
    if (f.id !== 'wpTextbox1') return true;

    if (e.keyCode === 8) { // Backspace
        if (ohiQ[0] || ohiQ[3] || ohiQ[6]) {
            e.preventDefault();
            ohiBackspace(f);
            if (ohiQ[6]) ohiQ[6] = 0;
            else if (ohiQ[3]) ohiQ[3] = 0;
            else if (ohiQ[0]) ohiQ[0] = 0;
        }
    }
}

