function renderKeyboard() {
    var wrap = document.getElementById('wpTextbox1');
    if (!wrap) return;

    var container = document.getElementById('ohi_keyboard_container');
    if (!container) {
        container = document.createElement('div');
        container.id = 'ohi_keyboard_container';
        container.style.marginTop = '10px';
        container.style.textAlign = 'center';
        container.style.fontFamily = 'sans-serif';
        wrap.parentNode.insertBefore(container, wrap.nextSibling);
    }

    var html = '<div style="background:#f8f9fa; border:1px solid #c8ccd1; padding:10px; border-radius:2px; display:inline-block;">';

    // 단순화된 헤더 (켜기/끄기 토글)
    html += '<div style="text-align:left; margin-bottom:5px;">';
    html += '<label><input type="checkbox" checked onclick="OHI_STATUS.active=this.checked; document.getElementById(\'wpTextbox1\').focus();"> 한글 입력기 (신세벌식 P2)</label>';
    html += '</div>';

    // 4줄의 키보드 레이아웃 렌더링
    var ue = [
        ['`','1','2','3','4','5','6','7','8','9','0','-','=','Back'],
        ['Tab','q','w','e','r','t','y','u','i','o','p','[',']','\\'],
        ['Caps','a','s','d','f','g','h','j','k','l',';','\'','Enter'],
        ['Shift','z','x','c','v','b','n','m',',','.','/','Shift']
    ];

    var dh = [
        ['', '', '', '', '', '', '', '', '', '', '', '', '', ''],
        ['', 'ㅂ', 'ㅈ', 'ㄷ', 'ㄱ', 'ㅅ', 'ㅛ', 'ㅕ', 'ㅑ', 'ㅐ', 'ㅔ', '【', '】', ''],
        ['', 'ㅁ', 'ㄴ', 'ㅇ', 'ㄹ', 'ㅎ', 'ㅗ', 'ㅓ', 'ㅏ', 'ㅣ', ';', '\'', ''],
        ['', 'ㅋ', 'ㅌ', 'ㅊ', 'ㅍ', 'ㅠ', 'ㅜ', 'ㅡ', ',', '.', '/', '']
    ];

    for (var i = 0; i < ue.length; i++) {
        html += '<div style="margin: 2px 0; white-space:nowrap;">';
        for (var j = 0; j < ue[i].length; j++) {
            var width = '36px';
            if (ue[i][j] === 'Back') width = '62px';
            if (ue[i][j] === 'Tab') width = '56px';
            if (ue[i][j] === 'Caps') width = '67px';
            if (ue[i][j] === 'Enter') width = '71px';
            if (ue[i][j] === 'Shift' && j === 0) width = '87px';
            if (ue[i][j] === 'Shift' && j !== 0) width = '91px';

            var keyCharCode = ue[i][j].length === 1 ? ue[i][j].charCodeAt(0) : 0;
            var keyId = 'key' + (keyCharCode ? keyCharCode - 33 : 'S' + i + j);

            var bgColor = '#fff';
            if (dh[i][j]) bgColor = '#eaf3ff'; // 임의 색상

            html += '<div id="' + keyId + '" style="display:inline-block; width:' + width + '; height:38px; border:1px solid #ccc; background:' + bgColor + '; margin:1px; vertical-align:bottom; cursor:pointer; border-radius:2px; text-align:center; box-sizing:border-box;">';
            html += '<div style="color:#72777d; font-size:12px; text-align:left; padding-left:2px; height:18px;">' + ue[i][j] + '</div>';
            if (dh[i][j]) {
                html += '<div style="color:#202122; font-weight:bold; font-size:14px; text-align:right; padding-right:2px;">' + dh[i][j] + '</div>';
            }
            html += '</div>';
        }
        html += '</div>';
    }

    html += '<div style="margin: 2px 0;"><div style="display:inline-block; width:312px; height:38px; border:1px solid #ccc; background:#fff; cursor:pointer; border-radius:2px; line-height:38px;">Space</div></div>';

    html += '</div>';
    container.innerHTML = html;
}

