$(function() {
    const action = mw.config.get('wgAction');
    if (action !== 'edit' && action !== 'submit') return;

    let currentLayout = 'qwerty';
    let isShiftPressed = false;
    let isCapsLockOn = false;

    const $container = $('<div>').attr('id', 'ohi-keyboard-container');
    const $header = $('<div>').attr('id', 'ohi-header');
    const $title = $('<span>').text('가상 키보드');

    $header.append($title);
    $container.append($header, $('<div>').attr('id', 'ohi-keyboard'));

    $('#wpTextbox1').after($container);

    const $keyboard = $('#ohi-keyboard');

    const modifierLabels = {
        'Backspace': 'Backspace',
        'Tab': 'Tab',
        'CapsLock': 'CapsLock',
        'Enter': 'Enter',
        'ShiftLeft': 'Shift',
        'ShiftRight': 'Shift',
        'LangToggle': '한/영'
    };

    function renderKeyboard() {
        $keyboard.empty();
        const rowsData = window.OhiKeyboardData.rows;

        rowsData.forEach(row => {
            const $row = $('<div>').addClass('ohi-row');
            row.forEach(code => {
                const $key = $('<div>').addClass('ohi-key').attr('data-code', code);

                if (code === 'Space') {
                    $key.addClass('ohi-key-space').text(' ');
                } else if (modifierLabels[code]) {
                    $key.addClass('ohi-key-modifier').addClass('ohi-key-' + code.toLowerCase()).text(modifierLabels[code]);
                }

                $row.append($key);
            });
            $keyboard.append($row);
        });
        updateKeyLabels();
    }

    function updateKeyLabels() {
        const layoutData = window.OhiKeyboardData.layouts[currentLayout];

        $keyboard.find('.ohi-key').each(function() {
            const code = $(this).attr('data-code');
            if (code === 'Space' || modifierLabels[code]) return;

            let char = layoutData.base[code] || '';

            if (currentLayout === 'qwerty' && char.match(/[a-z]/)) {
                let isUpper = isCapsLockOn;
                if (isShiftPressed) isUpper = !isUpper;
                if (isUpper) char = char.toUpperCase();
            } else if (isShiftPressed) {
                if (layoutData.shift && layoutData.shift[code]) {
                    char = layoutData.shift[code];
                }
            }
            $(this).text(char);
        });

        const $capsKey = $keyboard.find('.ohi-key-capslock');
        if (isCapsLockOn) {
            $capsKey.addClass('caps-on');
        } else {
            $capsKey.removeClass('caps-on');
        }
    }

    if (window.OhiKeyboardData) {
        renderKeyboard();
    }

    function toggleLanguage() {
        currentLayout = currentLayout === 'qwerty' ? 'dubeolsik' : 'qwerty';
        updateKeyLabels();
    }

    $keyboard.on('click', '.ohi-key-langtoggle', function(e) {
        e.preventDefault();
        toggleLanguage();
    });

    function handleKeyEvent(e, isKeyDown) {
        const code = e.originalEvent.code;

        if (e.originalEvent.getModifierState) {
            const capsState = e.originalEvent.getModifierState('CapsLock');
            if (isCapsLockOn !== capsState) {
                isCapsLockOn = capsState;
                updateKeyLabels();
            }
        }

        if (code === 'ShiftLeft' || code === 'ShiftRight') {
            if (isShiftPressed !== isKeyDown) {
                isShiftPressed = isKeyDown;
                updateKeyLabels();
            }
        }

        if (isKeyDown && (code === 'Lang1' || code === 'HangulMode')) {
            toggleLanguage();
        }

        let targetCode = code;
        if (code === 'Lang1' || code === 'HangulMode' || code === 'AltRight') {
            targetCode = 'LangToggle';
        }

        const $key = $keyboard.find(`.ohi-key[data-code="${targetCode}"]`);
        if ($key.length) {
            if (isKeyDown) {
                $key.addClass('active');
            } else {
                $key.removeClass('active');
            }
        }
    }

    $('#wpTextbox1').on('keydown', function(e) { handleKeyEvent(e, true); });
    $('#wpTextbox1').on('keyup', function(e) { handleKeyEvent(e, false); });
});

