#ohi-keyboard-container {
    margin-top: 15px;
    margin-bottom: 15px;
    padding: 10px;
    background-color: #f8f9fa;
    border: 1px solid #c8ccd1;
    border-radius: 2px;
    max-width: 630px;
    font-family: sans-serif;
    user-select: none;
    clear: both;
}

#ohi-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
    padding: 0 5px;
}

#ohi-keyboard-status {
    font-weight: bold;
    color: #202122;
    font-size: 13px;
}

#ohi-toggle-visibility {
    background: none;
    border: none;
    color: #36c;
    cursor: pointer;
    font-size: 12px;
}

#ohi-toggle-visibility:hover {
    text-decoration: underline;
}

.ohi-row {
    display: flex;
    justify-content: center;
    margin-bottom: 2px;
}

.ohi-key {
    width: 38px;
    height: 40px;
    margin: 0 1px;
    background-color: #ffffff;
    border: 1px solid #a2a9b1;
    border-radius: 3px;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 14px;
    color: #202122;
    box-shadow: 0 1px 0 0 #a2a9b1;
    transition: all 0.05s ease-in-out;
    position: relative;
    cursor: pointer;
}

#ohi-keyboard-container.layout-dubeolsik .ohi-key-consonant,
#ohi-keyboard-container.layout-dubeolsik_old .ohi-key-consonant {
    background-color: #f1f7ff;
}
#ohi-keyboard-container.layout-dubeolsik .ohi-key-vowel,
#ohi-keyboard-container.layout-dubeolsik_old .ohi-key-vowel {
    background-color: #fff0f5;
}

.ohi-eng-label {
    position: absolute;
    top: 3px;
    left: 4px;
    font-size: 10px;
    color: #72777d;
}

.ohi-kor-shift {
    position: absolute;
    top: 3px;
    right: 4px;
    font-size: 11px;
}

.ohi-kor-base {
    position: absolute;
    bottom: 3px;
    right: 4px;
    font-size: 13px;
}

.ohi-kor-shift.active-char, .ohi-kor-base.active-char {
    font-weight: bold;
    color: #202122;
}
.ohi-kor-shift:not(.active-char), .ohi-kor-base:not(.active-char) {
    color: #a2a9b1;
}

.ohi-key-modifier {
    background-color: #eaecf0;
    font-size: 11px;
}
.ohi-key-backspace { width: 60px; }
.ohi-key-tab { width: 50px; }
.ohi-key-shiftlock { width: 75px; font-weight: bold; color: #d33; }
.ohi-key-enter { width: 70px; }
.ohi-key-shiftleft { width: 90px; }
.ohi-key-shiftright { width: 90px; }
.ohi-key-space { width: 170px; }
.ohi-key-langtoggle { width: 55px; font-weight: bold; color: #36c; }
.ohi-key-layouttoggle { width: 65px; color: #202122; }

.ohi-key:active, .ohi-key.active {
    background-color: #eaf3ff;
    border-color: #3366cc;
    color: #3366cc;
    transform: translateY(1px);
    box-shadow: 0 0 0 0 #3366cc;
}

.ohi-key.locked-on {
    background-color: #fee7e6;
    border-color: #d33;
    color: #d33;
    transform: translateY(1px);
    box-shadow: none;
}

$(function() {
    const action = mw.config.get('wgAction');
    if (action !== 'edit' && action !== 'submit') return;

    let currentLang = 'qwerty';
    let currentKorLayout = 'dubeolsik';
    let isShiftPressed = false;
    let isShiftLockOn = false;
    let isTempShiftOn = false;
    let isKeyboardVisible = true;

    const $container = $('<div>').attr('id', 'ohi-keyboard-container').addClass('layout-qwerty');
    const $header = $('<div>').attr('id', 'ohi-header');

    const $status = $('<span>').attr('id', 'ohi-keyboard-status').text('');
    const $toggleVisibilityBtn = $('<button>').attr('id', 'ohi-toggle-visibility').text('키보드 숨기기');

    $header.append($status, $toggleVisibilityBtn);
    const $keyboard = $('<div>').attr('id', 'ohi-keyboard');

    $container.append($header, $keyboard);
    $('.editOptions').before($container);

    const modifierLabels = {
        'Backspace': 'Backspace',
        'Tab': 'Tab',
        'ShiftLock': 'Shift Lock',
        'Enter': 'Enter',
        'ShiftLeft': 'Shift',
        'ShiftRight': 'Shift',
        'LangToggle': '한/영',
        'LayoutToggle': '자판 바꿈'
    };

    const consonantKeys = ['KeyQ','KeyW','KeyE','KeyR','KeyT','KeyA','KeyS','KeyD','KeyF','KeyG','KeyZ','KeyX','KeyC','KeyV'];
    const vowelKeys = ['KeyY','KeyU','KeyI','KeyO','KeyP','KeyH','KeyJ','KeyK','KeyL','KeyB','KeyN','KeyM'];

    function renderKeyboard() {
        $keyboard.empty();
        const rowsData = window.OhiKeyboardData.rows;

        rowsData.forEach(row => {
            const $row = $('<div>').addClass('ohi-row');
            row.forEach(code => {
                const $key = $('<div>').addClass('ohi-key').attr('data-code', code);

                if (code === 'Space') {
                    $key.addClass('ohi-key-space').text(' ');
                } else if (modifierLabels[code]) {
                    $key.addClass('ohi-key-modifier').addClass('ohi-key-' + code.toLowerCase()).text(modifierLabels[code]);
                } else if (consonantKeys.includes(code)) {
                    $key.addClass('ohi-key-consonant');
                } else if (vowelKeys.includes(code)) {
                    $key.addClass('ohi-key-vowel');
                }

                $row.append($key);
            });
            $keyboard.append($row);
        });
        updateKeyLabels();
    }

    function updateKeyLabels() {
        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        $container.removeClass('layout-qwerty layout-dubeolsik layout-dubeolsik_old').addClass('layout-' + activeLayout);

        if (currentLang === 'qwerty') {
            $status.text('');
        } else if (currentKorLayout === 'dubeolsik') {
            $status.text('[두벌식 표준]');
        } else {
            $status.text('[두벌식 옛한글]');
        }

        $keyboard.find('.ohi-key').each(function() {
            const code = $(this).attr('data-code');
            if (code === 'Space' || modifierLabels[code]) return;

            if (currentLang !== 'qwerty' && code.startsWith('Key')) {
                const baseEng = window.OhiKeyboardData.layouts.qwerty.base[code] || '';
                const baseKor = window.OhiKeyboardData.layouts[currentKorLayout].base[code] || '';
                const shiftKor = window.OhiKeyboardData.layouts[currentKorLayout].shift[code] || '';

                $(this).empty();
                $('<span>').addClass('ohi-eng-label').text(baseEng.toUpperCase()).appendTo(this);

                if (shiftKor && shiftKor !== baseKor) {
                    $('<span>').addClass('ohi-kor-shift').text(shiftKor).appendTo(this);
                }
                $('<span>').addClass('ohi-kor-base').text(baseKor).appendTo(this);

                if (isEffectiveShift && shiftKor) {
                    $(this).find('.ohi-kor-shift').addClass('active-char');
                    $(this).find('.ohi-kor-base').removeClass('active-char');
                } else {
                    $(this).find('.ohi-kor-base').addClass('active-char');
                    $(this).find('.ohi-kor-shift').removeClass('active-char');
                }
            } else {
                let char = layoutData.base[code] || '';
                if (isEffectiveShift) {
                    if (layoutData.shift && layoutData.shift[code] !== undefined) {
                        char = layoutData.shift[code];
                    } else if (currentLang === 'qwerty' && char.match(/[a-z]/)) {
                        char = char.toUpperCase();
                    }
                }
                $(this).empty().text(char);
            }
        });

        $keyboard.find('.ohi-key-shiftlock').toggleClass('locked-on', isShiftLockOn);
        $keyboard.find('.ohi-key-shiftleft, .ohi-key-shiftright').toggleClass('locked-on', isTempShiftOn);
    }

    if (window.OhiKeyboardData) renderKeyboard();

    function toggleLanguage() {
        currentLang = currentLang === 'qwerty' ? 'korean' : 'qwerty';
        updateKeyLabels();
    }

    function toggleKorLayout() {
        if (currentLang === 'qwerty') return;
        currentKorLayout = currentKorLayout === 'dubeolsik' ? 'dubeolsik_old' : 'dubeolsik';
        updateKeyLabels();
    }

    $toggleVisibilityBtn.on('click', function(e) {
        e.preventDefault();
        isKeyboardVisible = !isKeyboardVisible;
        if (isKeyboardVisible) {
            $keyboard.show();
            $(this).text('키보드 숨기기');
        } else {
            $keyboard.hide();
            $(this).text('키보드 보이기');
        }
    });

    $keyboard.on('mousedown', '.ohi-key', function(e) {
        e.preventDefault(); 
        const code = $(this).attr('data-code');

        if (code === 'LangToggle') {
            toggleLanguage();
            return;
        } else if (code === 'LayoutToggle') {
            toggleKorLayout();
            return;
        } else if (code === 'ShiftLock') {
            isShiftLockOn = !isShiftLockOn;
            updateKeyLabels();
            return;
        } else if (code === 'ShiftLeft' || code === 'ShiftRight') {
            isTempShiftOn = !isTempShiftOn;
            updateKeyLabels();
            return;
        }

        let charToInsert = '';
        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        if (code === 'Space') charToInsert = ' ';
        else if (code === 'Enter') charToInsert = '\n';
        else if (code === 'Tab') charToInsert = '\t';
        else if (code === 'Backspace') {
            triggerBackspace();
        } else if (!modifierLabels[code]) {
            charToInsert = layoutData.base[code] || '';
            if (isEffectiveShift) {
                if (layoutData.shift && layoutData.shift[code] !== undefined) {
                    charToInsert = layoutData.shift[code];
                } else if (currentLang === 'qwerty' && charToInsert.match(/[a-z]/)) {
                    charToInsert = charToInsert.toUpperCase();
                }
            }
        }

        if (charToInsert) {
            $('#wpTextbox1').focus();
            $('#wpTextbox1').textSelection('encapsulateSelection', { pre: charToInsert });
        }

        if (isTempShiftOn && code !== 'ShiftLeft' && code !== 'ShiftRight') {
            isTempShiftOn = false;
            updateKeyLabels();
        }
    });

    function triggerBackspace() {
        const el = $('#wpTextbox1')[0];
        if (!el) return;
        el.focus();
        let start = el.selectionStart;
        let end = el.selectionEnd;
        if (start === end && start > 0) {
            el.value = el.value.substring(0, start - 1) + el.value.substring(end);
            el.selectionStart = el.selectionEnd = start - 1;
        } else if (start !== end) {
            el.value = el.value.substring(0, start) + el.value.substring(end);
            el.selectionStart = el.selectionEnd = start;
        }
        $(el).trigger('input');
    }

    function handleKeyEvent(e, isKeyDown) {
        const code = e.originalEvent.code;

        if (code === 'ShiftLeft' || code === 'ShiftRight') {
            if (isShiftPressed !== isKeyDown) {
                isShiftPressed = isKeyDown;
                updateKeyLabels();
            }
        }

        if (isKeyDown && code === 'CapsLock') {
            isShiftLockOn = !isShiftLockOn;
            updateKeyLabels();
        }

        if (isKeyDown && (code === 'Lang1' || code === 'HangulMode')) toggleLanguage();

        let targetCode = code;
        if (code === 'Lang1' || code === 'HangulMode' || code === 'AltRight') targetCode = 'LangToggle';
        if (code === 'CapsLock') targetCode = 'ShiftLock';

        const $key = $keyboard.find(`.ohi-key[data-code="${targetCode}"]`);
        if ($key.length) {
            if (isKeyDown) $key.addClass('active');
            else $key.removeClass('active');
        }
    }

    $('#wpTextbox1').on('keydown', function(e) { handleKeyEvent(e, true); });
    $('#wpTextbox1').on('keyup', function(e) { handleKeyEvent(e, false); });
});

