    const vowelKeys = ['KeyY','KeyU','KeyI','KeyO','KeyP','KeyH','KeyJ','KeyK','KeyL','KeyB','KeyN','KeyM'];

    function renderKeyboard() {
        $keyboard.empty();
        const rowsData = window.OhiKeyboardData.rows;

        rowsData.forEach(row => {
            const $row = $('<div>').addClass('ohi-row');
            row.forEach(code => {
                const $key = $('<div>').addClass('ohi-key').attr('data-code', code);
                if (code === 'Space') $key.addClass('ohi-key-space').text(' ');
                else if (modifierLabels[code]) $key.addClass('ohi-key-modifier').addClass('ohi-key-' + code.toLowerCase()).text(modifierLabels[code]);
                else if (consonantKeys.includes(code)) $key.addClass('ohi-key-consonant');
                else if (vowelKeys.includes(code)) $key.addClass('ohi-key-vowel');
                $row.append($key);
            });
            $keyboard.append($row);
        });
        updateKeyLabels();
    }

    function updateKeyLabels() {
        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        $container.removeClass('layout-qwerty layout-dubeolsik layout-dubeolsik_old').addClass('layout-' + activeLayout);

        if (currentLang === 'qwerty') $status.text('');
        else if (currentKorLayout === 'dubeolsik') $status.text('[두벌식 표준]');
        else $status.text('[두벌식 옛한글]');

        $keyboard.find('.ohi-key').each(function() {
            const code = $(this).attr('data-code');
            if (code === 'Space' || modifierLabels[code]) return;

            if (currentLang !== 'qwerty' && code.startsWith('Key')) {
                const baseEng = window.OhiKeyboardData.layouts.qwerty.base[code] || '';
                const baseKor = window.OhiKeyboardData.layouts[currentKorLayout].base[code] || '';
                const shiftKor = window.OhiKeyboardData.layouts[currentKorLayout].shift[code] || '';

                $(this).empty();
                $('<span>').addClass('ohi-eng-label').text(baseEng.toUpperCase()).appendTo(this);
                if (shiftKor && shiftKor !== baseKor) $('<span>').addClass('ohi-kor-shift').text(shiftKor).appendTo(this);
                $('<span>').addClass('ohi-kor-base').text(baseKor).appendTo(this);

                if (isEffectiveShift && shiftKor) {
                    $(this).find('.ohi-kor-shift').addClass('active-char');
                    $(this).find('.ohi-kor-base').removeClass('active-char');
                } else {
                    $(this).find('.ohi-kor-base').addClass('active-char');
                    $(this).find('.ohi-kor-shift').removeClass('active-char');
                }
            } else {
                let char = layoutData.base[code] || '';
                if (isEffectiveShift) {
                    if (layoutData.shift && layoutData.shift[code] !== undefined) char = layoutData.shift[code];
                }
                $(this).empty().text(char);
            }
        });

        $keyboard.find('.ohi-key-shiftlock').toggleClass('locked-on', isShiftLockOn);
        $keyboard.find('.ohi-key-shiftleft, .ohi-key-shiftright').toggleClass('locked-on', isTempShiftOn);
    }

    if (window.OhiKeyboardData) renderKeyboard();

    function toggleLanguage() {
        currentLang = currentLang === 'qwerty' ? 'korean' : 'qwerty';
        updateKeyLabels();
    }

    function toggleKorLayout() {
        if (currentLang === 'qwerty') return;
        currentKorLayout = currentKorLayout === 'dubeolsik' ? 'dubeolsik_old' : 'dubeolsik';
        updateKeyLabels();
    }

    $toggleVisibilityBtn.on('click', function(e) {
        e.preventDefault();
        isKeyboardVisible = !isKeyboardVisible;
        if (isKeyboardVisible) {
            $keyboard.show();
            $(this).text('키보드 숨기기');
        } else {
            $keyboard.hide();
            $(this).text('키보드 보이기');
        }
    });

    function insertNativeText(char) {
        const el = $('#wpTextbox1')[0];
        el.focus();
        const start = el.selectionStart;
        const end = el.selectionEnd;
        el.setRangeText(char, start, end, 'end');
        el.dispatchEvent(new InputEvent('beforeinput', { inputType: 'insertText', data: char, bubbles: true, cancelable: true }));
        el.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: char, bubbles: true, cancelable: true }));
    }

    $keyboard.on('mousedown', '.ohi-key', function(e) {
        e.preventDefault(); 
        const code = $(this).attr('data-code');

        if (code === 'LangToggle') { toggleLanguage(); return; }
        else if (code === 'LayoutToggle') { toggleKorLayout(); return; }
        else if (code === 'ShiftLock') { isShiftLockOn = !isShiftLockOn; updateKeyLabels(); return; }
        else if (code === 'ShiftLeft' || code === 'ShiftRight') { isTempShiftOn = !isTempShiftOn; updateKeyLabels(); return; }

        let charToInsert = '';
        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        if (code === 'Space') charToInsert = ' ';
        else if (code === 'Enter') charToInsert = '\n';
        else if (code === 'Tab') charToInsert = '\t';
        else if (code === 'Backspace') triggerBackspace();
        else if (!modifierLabels[code]) {
            charToInsert = layoutData.base[code] || '';
            if (isEffectiveShift && layoutData.shift && layoutData.shift[code] !== undefined) {
                charToInsert = layoutData.shift[code];
            }
        }

        if (charToInsert) insertNativeText(charToInsert);

        if (isTempShiftOn && code !== 'ShiftLeft' && code !== 'ShiftRight') {
            isTempShiftOn = false;
            updateKeyLabels();
        }
    });

    function triggerBackspace() {
        const el = $('#wpTextbox1')[0];
        if (!el) return;
        el.focus();
        let start = el.selectionStart;
        let end = el.selectionEnd;
        if (start === end && start > 0) {
            el.value = el.value.substring(0, start - 1) + el.value.substring(end);
            el.selectionStart = el.selectionEnd = start - 1;
        } else if (start !== end) {
            el.value = el.value.substring(0, start) + el.value.substring(end);
            el.selectionStart = el.selectionEnd = start;
        }
        $(el).trigger('input');
    }

    function handleKeyEvent(e, isKeyDown) {
        const code = e.originalEvent.code;

        if (code === 'ShiftLeft' || code === 'ShiftRight') {
            if (isShiftPressed !== isKeyDown) {
                isShiftPressed = isKeyDown;
                updateKeyLabels();
            }
        }

        if (isKeyDown && code === 'CapsLock') {
            isShiftLockOn = !isShiftLockOn;
            updateKeyLabels();
        }

        if (isKeyDown && (code === 'Lang1' || code === 'HangulMode')) toggleLanguage();

        if (isKeyDown && currentLang !== 'qwerty') {
            const layoutData = window.OhiKeyboardData.layouts[currentKorLayout];
            if (layoutData.base[code] !== undefined) {
                e.preventDefault(); 

                let charToInsert = '';
                const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

                if (isEffectiveShift && layoutData.shift[code] !== undefined && layoutData.shift[code] !== '') {
                    charToInsert = layoutData.shift[code];
                } else if (layoutData.base[code] !== undefined) {
                    charToInsert = layoutData.base[code];
                }

                if (charToInsert) insertNativeText(charToInsert);

                if (isTempShiftOn && code !== 'ShiftLeft' && code !== 'ShiftRight') {
                    isTempShiftOn = false;
                    updateKeyLabels();
                }
            }
        }

        let targetCode = code;
        if (code === 'Lang1' || code === 'HangulMode' || code === 'AltRight') targetCode = 'LangToggle';
        if (code === 'CapsLock') targetCode = 'ShiftLock';

        const $key = $keyboard.find(`.ohi-key[data-code="${targetCode}"]`);
        if ($key.length) {
            if (isKeyDown) $key.addClass('active');
            else $key.removeClass('active');
        }
    }

    $('#wpTextbox1').on('keydown', function(e) { handleKeyEvent(e, true); });
    $('#wpTextbox1').on('keyup', function(e) { handleKeyEvent(e, false); });
});

$(function() {
    const action = mw.config.get('wgAction');
    if (action !== 'edit' && action !== 'submit') return;

    let NFD_stack = { phoneme: [], combined_phoneme: [] };
    const FILLER_CHO = 0x115F;
    const FILLER_JUNG = 0x1160;

    function initNFDStack() {
        NFD_stack.phoneme = [];
        NFD_stack.combined_phoneme = [];
    }

    function combineNFD(c1, c2) {
        let combined = 0x10000 * c1 + c2;
        for (let i = 0; i < hangeul_combination_table_full.length; ++i) {
            if (combined === hangeul_combination_table_full[i][0]) {
                return hangeul_combination_table_full[i][1];
            }
        }
        return 0;
    }

    function processNFDInput(f, c) {
        if (c === FILLER_JUNG && NFD_stack.phoneme[0] === FILLER_JUNG) return;

        let combined_phoneme = NFD_stack.combined_phoneme.length ? combineNFD(NFD_stack.combined_phoneme[0], c) : 0;

        if (!combined_phoneme && unicode_cheos.indexOf(c) >= 0) {
            initNFDStack();
        } else if (!combined_phoneme && unicode_ga.indexOf(c) >= 0 && unicode_cheos.indexOf(NFD_stack.phoneme[0]) < 0) {
            initNFDStack();
            insertNativeText(f, String.fromCharCode(FILLER_CHO));
            NFD_stack.combined_phoneme.unshift(FILLER_CHO);
        } else if (!combined_phoneme && unicode_ggeut.indexOf(c) >= 0) {
            if (unicode_cheos.indexOf(NFD_stack.phoneme[0]) >= 0 && NFD_stack.combined_phoneme.indexOf(FILLER_JUNG) < 0) {
                insertNativeText(f, String.fromCharCode(FILLER_JUNG));
                NFD_stack.combined_phoneme.unshift(FILLER_JUNG);
            } else if (unicode_cheos.indexOf(NFD_stack.phoneme[0]) < 0 && unicode_ga.indexOf(NFD_stack.phoneme[0]) < 0) {
                initNFDStack();
                insertNativeText(f, String.fromCharCode(FILLER_CHO) + String.fromCharCode(FILLER_JUNG));
                NFD_stack.combined_phoneme.unshift(FILLER_JUNG, FILLER_CHO);
            }
        }

        NFD_stack.phoneme.unshift(c);

        if (combined_phoneme) {
            NFD_stack.combined_phoneme[0] = combined_phoneme;
            triggerBackspace(f);
            insertNativeText(f, String.fromCharCode(combined_phoneme));
        } else {
            NFD_stack.combined_phoneme.unshift(c);
            insertNativeText(f, String.fromCharCode(c));
        }

        if (unicode_cheos.indexOf(c) >= 0) {
            insertNativeText(f, String.fromCharCode(FILLER_JUNG));
            NFD_stack.combined_phoneme.unshift(FILLER_JUNG);
        }
    }

    let currentLang = 'qwerty';
    let currentKorLayout = 'dubeolsik';
    let isShiftPressed = false;
    let isShiftLockOn = false;
    let isTempShiftOn = false;
    let isKeyboardVisible = true;

    const $container = $('<div>').attr('id', 'ohi-keyboard-container').addClass('layout-qwerty');
