        const start = f.selectionStart, end = f.selectionEnd;
        f.setRangeText(char, start, end, 'end');
        f.dispatchEvent(new InputEvent('input', { bubbles: true }));
    }

    function triggerBackspace(f) {
        if (!f) return;
        f.focus();
        let start = f.selectionStart, end = f.selectionEnd;
        if (start === end && start > 0) { f.value = f.value.substring(0, start - 1) + f.value.substring(end); f.selectionStart = f.selectionEnd = start - 1; }
        else if (start !== end) { f.value = f.value.substring(0, start) + f.value.substring(end); f.selectionStart = f.selectionEnd = start; }
        f.dispatchEvent(new InputEvent('input', { bubbles: true }));
    }

    $keyboard.on('mousedown', '.ohi-key', function(e) {
