$(function() {
    const action = mw.config.get('wgAction');
    if (action !== 'edit' && action !== 'submit') return;

    let NFD_stack = { phoneme: [], combined_phoneme: [] };
    const FILLER_CHO = 0x115F;
    const FILLER_JUNG = 0x1160;

    let currentLang = 'qwerty';
    let currentKorLayout = 'dubeolsik';
    let isShiftPressed = false;
    let isShiftLockOn = false;
    let isTempShiftOn = false;
    let isKeyboardVisible = true;

    const $container = $('<div>').attr('id', 'ohi-keyboard-container').addClass('layout-qwerty');
    const $header = $('<div>').attr('id', 'ohi-header');
    const $status = $('<span>').attr('id', 'ohi-keyboard-status').text('');
    const $toggleVisibilityBtn = $('<button>').attr('id', 'ohi-toggle-visibility').text('키보드 숨기기');

    $header.append($status, $toggleVisibilityBtn);
    const $keyboard = $('<div>').attr('id', 'ohi-keyboard');
    $container.append($header, $keyboard);
    $('.editOptions').before($container);

    const modifierLabels = {
        'Backspace': 'Backspace', 'Tab': 'Tab', 'ShiftLock': 'Shift Lock', 'Enter': 'Enter',
        'ShiftLeft': 'Shift', 'ShiftRight': 'Shift', 'LangToggle': '한/영', 'LayoutToggle': '자판 바꿈'
    };

    function initNFDStack() {
        NFD_stack.phoneme = [];
        NFD_stack.combined_phoneme = [];
    }

    function combineNFD(c1, c2) {
        let combined = 0x10000 * c1 + c2;
        for (let i = 0; i < hangeul_combination_table_full.length; ++i) {
            if (combined === hangeul_combination_table_full[i][0]) {
                return hangeul_combination_table_full[i][1];
            }
        }
        return 0;
    }

    function NFD_hangeul2_preprocess(c) {
        if (unicode_cheos.indexOf(c) >= 0) {
            if (unicode_ggeut.indexOf(NFD_stack.phoneme[0]) >= 0) {
                let comb = combineNFD(NFD_stack.combined_phoneme[0], unicode_cheos_to_ggeut[unicode_cheos.indexOf(c)]);
                if (comb) {
                    return unicode_cheos_to_ggeut[unicode_cheos.indexOf(c)];
                } else {
                    initNFDStack();
                    return c;
                }
            } else if (unicode_ga.indexOf(NFD_stack.phoneme[0]) >= 0 || NFD_stack.phoneme[0] === FILLER_JUNG) {
                return unicode_cheos_to_ggeut[unicode_cheos.indexOf(c)];
            }
            return c;
        } else if (unicode_ga.indexOf(c) >= 0 || c === FILLER_JUNG) {
            if (unicode_ggeut.indexOf(NFD_stack.phoneme[0]) >= 0) {
                let backup_phoneme = unicode_ggeut_to_cheos[unicode_ggeut.indexOf(NFD_stack.phoneme[0])];
                triggerBackspace();
                initNFDStack();
                NFD_hangeul_input(backup_phoneme);
            }
            return c;
        }
        return c;
    }

    function NFD_hangeul_input(c) {
        if (c === FILLER_JUNG && NFD_stack.phoneme[0] === FILLER_JUNG) return;

        let combined_phoneme = NFD_stack.combined_phoneme.length ? combineNFD(NFD_stack.combined_phoneme[0], c) : 0;

        if (c === FILLER_JUNG) {
            if (unicode_ga.indexOf(NFD_stack.phoneme[0]) >= 0 || NFD_stack.phoneme[0] === FILLER_JUNG) {
                initNFDStack();
            }
            if (NFD_stack.phoneme.length === 0) {
                NFD_stack.combined_phoneme.unshift(FILLER_CHO);
                insertNativeText(String.fromCharCode(FILLER_CHO));
            }
            if (NFD_stack.combined_phoneme[0] !== FILLER_JUNG) {
                NFD_stack.phoneme.unshift(c);
                NFD_stack.combined_phoneme.unshift(FILLER_JUNG);
                insertNativeText(String.fromCharCode(FILLER_JUNG));
            }
            return;
        }

        if (!combined_phoneme && unicode_cheos.indexOf(c) >= 0) {
            if (unicode_cheos.indexOf(NFD_stack.phoneme[0]) >= 0 && NFD_stack.combined_phoneme.indexOf(FILLER_JUNG) < 0) {
                insertNativeText(String.fromCharCode(FILLER_JUNG));
                NFD_stack.combined_phoneme.unshift(FILLER_JUNG);
            }
            initNFDStack();
        }

        if (!combined_phoneme && unicode_ga.indexOf(c) >= 0 && unicode_cheos.indexOf(NFD_stack.phoneme[0]) < 0) {
            initNFDStack();
            insertNativeText(String.fromCharCode(FILLER_CHO));
            NFD_stack.combined_phoneme = [FILLER_CHO];
        } else if (!combined_phoneme && unicode_ggeut.indexOf(c) >= 0) {
            if (unicode_cheos.indexOf(NFD_stack.phoneme[0]) >= 0 && NFD_stack.combined_phoneme.indexOf(FILLER_JUNG) < 0) {
                insertNativeText(String.fromCharCode(FILLER_JUNG));
                NFD_stack.combined_phoneme.unshift(FILLER_JUNG);
            } else if (unicode_cheos.indexOf(NFD_stack.phoneme[0]) < 0 && unicode_ga.indexOf(NFD_stack.phoneme[0]) < 0 && NFD_stack.combined_phoneme.indexOf(FILLER_CHO) < 0 && NFD_stack.combined_phoneme.indexOf(FILLER_JUNG) < 0) {
                initNFDStack();
                insertNativeText(String.fromCharCode(FILLER_CHO) + String.fromCharCode(FILLER_JUNG));
                NFD_stack.combined_phoneme.unshift(FILLER_JUNG, FILLER_CHO);
            }
        }

        NFD_stack.phoneme.unshift(c);

        if (combined_phoneme) {
            NFD_stack.combined_phoneme[0] = combined_phoneme;
            triggerBackspace();
            insertNativeText(String.fromCharCode(combined_phoneme));
        } else {
            if (unicode_ggeut.indexOf(c) >= 0 && unicode_ggeut.indexOf(NFD_stack.combined_phoneme[0]) >= 0) {
                initNFDStack();
                insertNativeText(String.fromCharCode(FILLER_CHO) + String.fromCharCode(FILLER_JUNG));
                NFD_stack.combined_phoneme.unshift(FILLER_JUNG, FILLER_CHO);
                NFD_stack.phoneme.unshift(c);
            }
            NFD_stack.combined_phoneme.unshift(c);
            insertNativeText(String.fromCharCode(c));
        }

        if (unicode_cheos.indexOf(c) >= 0) {
            insertNativeText(String.fromCharCode(FILLER_JUNG));
            NFD_stack.combined_phoneme.unshift(FILLER_JUNG);
        }
    }

    function renderKeyboard() {
        $keyboard.empty();
        window.OhiKeyboardData.rows.forEach(row => {
            const $row = $('<div>').addClass('ohi-row');
            row.forEach(code => {
                const $key = $('<div>').addClass('ohi-key').attr('data-code', code);
                if (code === 'Space') $key.addClass('ohi-key-space').text(' ');
                else if (modifierLabels[code]) $key.addClass('ohi-key-modifier').addClass('ohi-key-' + code.toLowerCase()).text(modifierLabels[code]);
                $row.append($key);
            });
            $keyboard.append($row);
        });
        updateKeyLabels();
    }

    function updateKeyLabels() {
        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        $container.removeClass('layout-qwerty layout-dubeolsik layout-dubeolsik_old').addClass('layout-' + activeLayout);

        if (currentLang === 'qwerty') {
            $status.text('');
            $('#wpTextbox1').off('compositionstart.ohi');
        } else {
            $status.text(currentKorLayout === 'dubeolsik' ? '[두벌식 표준]' : '[두벌식 옛한글]');
            $('#wpTextbox1').on('compositionstart.ohi', function(e) {
                e.preventDefault();
                $(this).blur().focus();
            });
        }

        $keyboard.find('.ohi-key').each(function() {
            const code = $(this).attr('data-code');
            if (code === 'Space' || modifierLabels[code]) return;

            if (currentLang !== 'qwerty' && code.startsWith('Key')) {
                const baseEng = window.OhiKeyboardData.layouts.qwerty.base[code] || '';
                const baseKor = window.OhiKeyboardData.layouts[currentKorLayout].base[code] || '';
                const shiftKor = window.OhiKeyboardData.layouts[currentKorLayout].shift[code] || '';

                $(this).empty();
                $('<span>').addClass('ohi-eng-label').text(baseEng.toUpperCase()).appendTo(this);
                if (shiftKor && shiftKor !== baseKor) $('<span>').addClass('ohi-kor-shift').text(shiftKor).appendTo(this);
                $('<span>').addClass('ohi-kor-base').text(baseKor).appendTo(this);

                if (isEffectiveShift && shiftKor) {
                    $(this).find('.ohi-kor-shift').addClass('active-char');
                    $(this).find('.ohi-kor-base').removeClass('active-char');
                } else {
                    $(this).find('.ohi-kor-base').addClass('active-char');
                    $(this).find('.ohi-kor-shift').removeClass('active-char');
                }
            } else {
                let char = layoutData.base[code] || '';
                if (isEffectiveShift && layoutData.shift && layoutData.shift[code] !== undefined) char = layoutData.shift[code];
                $(this).empty().text(char);
            }
        });
        $keyboard.find('.ohi-key-shiftlock').toggleClass('locked-on', isShiftLockOn);
        $keyboard.find('.ohi-key-shiftleft, .ohi-key-shiftright').toggleClass('locked-on', isTempShiftOn);
    }

    if (window.OhiKeyboardData) renderKeyboard();

    function toggleLanguage() { currentLang = currentLang === 'qwerty' ? 'korean' : 'qwerty'; initNFDStack(); updateKeyLabels(); }
    function toggleKorLayout() { if (currentLang === 'qwerty') return; currentKorLayout = currentKorLayout === 'dubeolsik' ? 'dubeolsik_old' : 'dubeolsik'; initNFDStack(); updateKeyLabels(); }

    $toggleVisibilityBtn.on('click', function(e) {
        e.preventDefault(); isKeyboardVisible = !isKeyboardVisible;
        if (isKeyboardVisible) { $keyboard.show(); $(this).text('키보드 숨기기'); } else { $keyboard.hide(); $(this).text('키보드 보이기'); }
    });

    function insertNativeText(char) {
        const el = $('#wpTextbox1')[0];
        if (!el) return;
        el.focus();
        const start = el.selectionStart;
        const end = el.selectionEnd;
        el.setRangeText(char, start, end, 'end');
        el.selectionStart = el.selectionEnd = start + char.length;
        el.dispatchEvent(new InputEvent('input', { bubbles: true }));
    }

    function triggerBackspace() {
        const el = $('#wpTextbox1')[0];
        if (!el) return;
        el.focus();
        let start = el.selectionStart;
        let end = el.selectionEnd;
        if (start === end && start > 0) {
            el.value = el.value.substring(0, start - 1) + el.value.substring(end);
            el.selectionStart = el.selectionEnd = start - 1;
        } else if (start !== end) {
            el.value = el.value.substring(0, start) + el.value.substring(end);
            el.selectionStart = el.selectionEnd = start;
        }
        el.dispatchEvent(new InputEvent('input', { bubbles: true }));
    }

    $keyboard.on('mousedown', '.ohi-key', function(e) {
        e.preventDefault(); 
        const code = $(this).attr('data-code');

        if (code === 'LangToggle') { toggleLanguage(); return; }
        else if (code === 'LayoutToggle') { toggleKorLayout(); return; }
        else if (code === 'ShiftLock') { isShiftLockOn = !isShiftLockOn; updateKeyLabels(); return; }
        else if (code === 'ShiftLeft' || code === 'ShiftRight') { isTempShiftOn = !isTempShiftOn; updateKeyLabels(); return; }

        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        if (code === 'Space') { insertNativeText(' '); initNFDStack(); }
        else if (code === 'Enter') { insertNativeText('\n'); initNFDStack(); }
        else if (code === 'Backspace') {
            if (currentLang !== 'qwerty' && NFD_stack.phoneme.length) {
                triggerBackspace();
                let backup_phoneme = NFD_stack.phoneme.slice();
                initNFDStack();
                if (backup_phoneme[0] === FILLER_JUNG && backup_phoneme.length === 1) triggerBackspace();
                for (let i = backup_phoneme.length - 1; i >= 1; --i) {
                    NFD_hangeul_input(backup_phoneme[i]);
                }
            } else {
                triggerBackspace();
                initNFDStack();
            }
        }
        else if (!modifierLabels[code]) {
            let charToInsert = layoutData.base[code] || '';
            if (isEffectiveShift && layoutData.shift && layoutData.shift[code]) charToInsert = layoutData.shift[code];

            if (currentLang !== 'qwerty' && charToInsert) {
                let processedC = NFD_hangeul2_preprocess(charToInsert.charCodeAt(0));
                NFD_hangeul_input(processedC);
            } else if (charToInsert) {
                insertNativeText(charToInsert);
            }
        }

        if (isTempShiftOn && !code.startsWith('Shift')) { isTempShiftOn = false; updateKeyLabels(); }
    });

    $('#wpTextbox1').on('mousedown blur', function() { initNFDStack(); });

    function handleKeyEvent(e, isKeyDown) {
        const code = e.originalEvent.code;

        if (code.startsWith('Shift')) { isShiftPressed = isKeyDown; updateKeyLabels(); }
        if (isKeyDown && code === 'CapsLock') { isShiftLockOn = !isShiftLockOn; updateKeyLabels(); }
        if (isKeyDown && (code === 'Lang1' || code === 'HangulMode')) toggleLanguage();

        if (isKeyDown && currentLang !== 'qwerty') {
            const activeLayout = window.OhiKeyboardData.layouts[currentKorLayout];
            if (activeLayout.base[code] !== undefined) {
                e.preventDefault(); 
                const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;
                let charToInsert = isEffectiveShift && activeLayout.shift[code] ? activeLayout.shift[code] : activeLayout.base[code];

                if (charToInsert) {
                    let processedC = NFD_hangeul2_preprocess(charToInsert.charCodeAt(0));
                    NFD_hangeul_input(processedC);
                }
                if (isTempShiftOn && !code.startsWith('Shift')) { isTempShiftOn = false; updateKeyLabels(); }
            } else if (code === 'Space' || code === 'Enter') {
                initNFDStack();
            } else if (code === 'Backspace') {
                e.preventDefault();
                if (NFD_stack.phoneme.length) {
                    triggerBackspace();
                    let backup_phoneme = NFD_stack.phoneme.slice();
                    initNFDStack();
                    if (backup_phoneme[0] === FILLER_JUNG && backup_phoneme.length === 1) triggerBackspace();
                    for (let i = backup_phoneme.length - 1; i >= 1; --i) {
                        NFD_hangeul_input(backup_phoneme[i]);
                    }
                } else {
                    triggerBackspace();
                    initNFDStack();
                }
            }
        }

        let targetCode = code === 'Lang1' || code === 'HangulMode' || code === 'AltRight' ? 'LangToggle' : (code === 'CapsLock' ? 'ShiftLock' : code);
        const $key = $keyboard.find(`.ohi-key[data-code="${targetCode}"]`);
        if ($key.length) { if (isKeyDown) $key.addClass('active'); else $key.removeClass('active'); }
    }

    $('#wpTextbox1').on('keydown', function(e) { handleKeyEvent(e, true); });
    $('#wpTextbox1').on('keyup', function(e) { handleKeyEvent(e, false); });
});

