function buildLayoutFromCArray(targetLayout, sourceArray) {
    var qwerty = window.OhiKeyboardData.layouts.qwerty;
    for (var code in qwerty.base) {
        var charCode = qwerty.base[code].charCodeAt(0);
        if (charCode >= 0x21 && charCode <= 0x7E) {
            var val = sourceArray[charCode - 0x21];
            targetLayout.base[code] = (val && val !== 0x001B) ? String.fromCharCode(val) : '';
        } else { targetLayout.base[code] = qwerty.base[code]; }
    }
    for (var code in qwerty.shift) {
        var charCode = qwerty.shift[code].charCodeAt(0);
        if (charCode >= 0x21 && charCode <= 0x7E) {
            var val = sourceArray[charCode - 0x21];
            targetLayout.shift[code] = (val && val !== 0x001B) ? String.fromCharCode(val) : '';
        } else { targetLayout.shift[code] = qwerty.shift[code]; }
    }
}

