$(function() {
    const action = mw.config.get('wgAction');
    if (action !== 'edit' && action !== 'submit') return;

    let currentLang = 'qwerty';
    let currentKorLayout = 'dubeolsik';
    let isShiftPressed = false;
    let isShiftLockOn = false;
    let isTempShiftOn = false;
    let isKeyboardVisible = true;
    let lastKeyTime = 0;

    const $container = $('<div>').attr('id', 'ohi-keyboard-container').addClass('layout-qwerty');
    const $header = $('<div>').attr('id', 'ohi-header');
    const $status = $('<span>').attr('id', 'ohi-keyboard-status').text('');
    const $toggleVisibilityBtn = $('<button>').attr('id', 'ohi-toggle-visibility').text('키보드 숨기기');
    $header.append($status, $toggleVisibilityBtn);
    const $keyboard = $('<div>').attr('id', 'ohi-keyboard');
    $container.append($header, $keyboard);
    $('.editOptions').before($container);

    const modifierLabels = { 'Backspace': 'Backspace', 'Tab': 'Tab', 'ShiftLock': 'Shift Lock', 'Enter': 'Enter', 'ShiftLeft': 'Shift', 'ShiftRight': 'Shift', 'LangToggle': '한/영', 'LayoutToggle': '자판 바꿈' };

    function renderKeyboard() {
        $keyboard.empty();
        window.OhiKeyboardData.rows.forEach(row => {
            const $row = $('<div>').addClass('ohi-row');
            row.forEach(code => {
                const $key = $('<div>').addClass('ohi-key').attr('data-code', code);
                if (code === 'Space') $key.addClass('ohi-key-space').text(' ');
                else if (modifierLabels[code]) $key.addClass('ohi-key-modifier').addClass('ohi-key-' + code.toLowerCase()).text(modifierLabels[code]);
                $row.append($key);
            });
            $keyboard.append($row);
        });
        updateKeyLabels();
    }

    function updateKeyLabels() {
        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        $container.removeClass('layout-qwerty layout-dubeolsik layout-dubeolsik_old').addClass('layout-' + activeLayout);

        if (currentLang === 'qwerty') { $status.text(''); }
        else { $status.text(currentKorLayout === 'dubeolsik' ? '[두벌식 표준]' : '[두벌식 옛한글]'); }

        $keyboard.find('.ohi-key').each(function() {
            const code = $(this).attr('data-code');
            if (code === 'Space' || modifierLabels[code]) return;

            if (currentLang !== 'qwerty' && code.startsWith('Key')) {
                const baseEng = window.OhiKeyboardData.layouts.qwerty.base[code] || '';
                const baseKor = window.OhiKeyboardData.layouts[currentKorLayout].base[code] || '';
                const shiftKor = window.OhiKeyboardData.layouts[currentKorLayout].shift[code] || '';

                $(this).empty();
                $('<span>').addClass('ohi-eng-label').text(baseEng.toUpperCase()).appendTo(this);
                if (shiftKor && shiftKor !== baseKor) {
                    let dispShiftKor = shiftKor;
                    if (shiftKor.length === 1 && shiftKor.charCodeAt(0) >= 0x1100 && shiftKor.charCodeAt(0) <= 0x11FF) {
                        dispShiftKor = String.fromCharCode(0x115F) + shiftKor;
                        if (shiftKor.charCodeAt(0) >= 0x11A8) dispShiftKor = String.fromCharCode(0x115F) + String.fromCharCode(0x1160) + shiftKor;
                    }
                    $('<span>').addClass('ohi-kor-shift').text(dispShiftKor).appendTo(this);
                }

                let dispBaseKor = baseKor;
                if (baseKor.length === 1 && baseKor.charCodeAt(0) >= 0x1100 && baseKor.charCodeAt(0) <= 0x11FF) {
                    dispBaseKor = String.fromCharCode(0x115F) + baseKor;
                    if (baseKor.charCodeAt(0) >= 0x11A8) dispBaseKor = String.fromCharCode(0x115F) + String.fromCharCode(0x1160) + baseKor;
                }
                $('<span>').addClass('ohi-kor-base').text(dispBaseKor).appendTo(this);

                if (isEffectiveShift && shiftKor) {
                    $(this).find('.ohi-kor-shift').addClass('active-char');
                    $(this).find('.ohi-kor-base').removeClass('active-char');
                } else {
                    $(this).find('.ohi-kor-base').addClass('active-char');
                    $(this).find('.ohi-kor-shift').removeClass('active-char');
                }
            } else {
                let char = layoutData.base[code] || '';
                if (isEffectiveShift && layoutData.shift && layoutData.shift[code] !== undefined) char = layoutData.shift[code];
                $(this).empty().text(char);
            }
        });
        $keyboard.find('.ohi-key-shiftlock').toggleClass('locked-on', isShiftLockOn);
        $keyboard.find('.ohi-key-shiftleft, .ohi-key-shiftright').toggleClass('locked-on', isTempShiftOn);
    }

    if (window.OhiKeyboardData) renderKeyboard();

    function toggleLanguage() { currentLang = currentLang === 'qwerty' ? 'korean' : 'qwerty'; updateKeyLabels(); }
    function toggleKorLayout() { if (currentLang === 'qwerty') return; currentKorLayout = currentKorLayout === 'dubeolsik' ? 'dubeolsik_old' : 'dubeolsik'; updateKeyLabels(); }

    $toggleVisibilityBtn.on('click', function(e) {
        e.preventDefault(); isKeyboardVisible = !isKeyboardVisible;
        if (isKeyboardVisible) { $keyboard.show(); $(this).text('키보드 숨기기'); } else { $keyboard.hide(); $(this).text('키보드 보이기'); }
    });

    function isCho(c) { return (c >= 0x1100 && c <= 0x115E) || (c >= 0xA960 && c <= 0xA97C); }
    function isJung(c) { return (c >= 0x1161 && c <= 0x11A7) || (c >= 0xD7B0 && c <= 0xD7C6); }
    function isJong(c) { return (c >= 0x11A8 && c <= 0x11FF) || (c >= 0xD7CB && c <= 0xD7FB); }

    function combine(c1, c2) {
        return window.OhiKeyboardData.combinations[0x10000 * c1 + c2] || 0;
    }

    function handleOldHangulInput(charToInsert) {
        const el = $('#wpTextbox1')[0];
        el.focus();
        let val = el.value;
        let pos = el.selectionStart;
        let charCode = charToInsert.charCodeAt(0);

        if (charCode === 0x1161) {
            let now = Date.now();
            if (now - lastKeyTime < 300) {
                let prevChar = val.charCodeAt(pos - 1);
                if (prevChar === 0x1161) {
                    el.setRangeText(String.fromCharCode(0x119E), pos - 1, pos, 'end');
                    el.dispatchEvent(new InputEvent('input', { bubbles: true }));
                    return;
                }
            }
            lastKeyTime = now;
        }

        if (isCho(charCode)) {
            let prevChar = val.charCodeAt(pos - 1);
            if (isJung(prevChar)) {
                let jongCode = window.OhiKeyboardData.choToGgeut[charCode];
                if (jongCode) {
                    el.setRangeText(String.fromCharCode(jongCode), pos, pos, 'end');
                    el.dispatchEvent(new InputEvent('input', { bubbles: true }));
                    return;
                }
            } else if (isJong(prevChar)) {
                let jongCode = window.OhiKeyboardData.choToGgeut[charCode];
                if (jongCode) {
                    let comb = combine(prevChar, jongCode);
                    if (comb) {
                        el.setRangeText(String.fromCharCode(comb), pos - 1, pos, 'end');
                        el.dispatchEvent(new InputEvent('input', { bubbles: true }));
                        return;
                    }
                }
            } else if (isCho(prevChar)) {
                let comb = combine(prevChar, charCode);
                if (comb) {
                    el.setRangeText(String.fromCharCode(comb), pos - 1, pos, 'end');
                    el.dispatchEvent(new InputEvent('input', { bubbles: true }));
                    return;
                }
            }
            el.setRangeText(String.fromCharCode(charCode), pos, pos, 'end');
        } else if (isJung(charCode)) {
            let prevChar = val.charCodeAt(pos - 1);
            if (isCho(prevChar)) {
                el.setRangeText(String.fromCharCode(charCode), pos, pos, 'end');
            } else if (isJung(prevChar)) {
                let comb = combine(prevChar, charCode);
                if (comb) {
                    el.setRangeText(String.fromCharCode(comb), pos - 1, pos, 'end');
                } else {
                    el.setRangeText(String.fromCharCode(0x115F) + String.fromCharCode(charCode), pos, pos, 'end');
                }
            } else if (isJong(prevChar)) {
                let prevPrevChar = val.charCodeAt(pos - 2);
                let jongCho = 0;
                let newJong = 0;

                for (let cho in window.OhiKeyboardData.choToGgeut) {
                    if (window.OhiKeyboardData.choToGgeut[cho] === prevChar) { jongCho = parseInt(cho); break; }
                }

                if (!jongCho) {
                    for (let combKey in window.OhiKeyboardData.combinations) {
                        if (window.OhiKeyboardData.combinations[combKey] === prevChar) {
                            newJong = Math.floor(combKey / 0x10000);
                            let pulledJong = combKey % 0x10000;
                            for (let cho in window.OhiKeyboardData.choToGgeut) {
                                if (window.OhiKeyboardData.choToGgeut[cho] === pulledJong) { jongCho = parseInt(cho); break; }
                            }
                            break;
                        }
                    }
                }

                if (jongCho) {
                    if (newJong) {
                        el.setRangeText(String.fromCharCode(newJong) + String.fromCharCode(jongCho) + String.fromCharCode(charCode), pos - 1, pos, 'end');
                    } else {
                        el.setRangeText(String.fromCharCode(jongCho) + String.fromCharCode(charCode), pos - 1, pos, 'end');
                    }
                } else {
                    el.setRangeText(String.fromCharCode(0x115F) + String.fromCharCode(charCode), pos, pos, 'end');
                }
            } else {
                el.setRangeText(String.fromCharCode(0x115F) + String.fromCharCode(charCode), pos, pos, 'end');
            }
        } else {
            el.setRangeText(charToInsert, pos, pos, 'end');
        }
        el.dispatchEvent(new InputEvent('input', { bubbles: true }));
    }

    $keyboard.on('mousedown', '.ohi-key', function(e) {
        e.preventDefault(); 
        const code = $(this).attr('data-code');
        const el = $('#wpTextbox1')[0];
        if (!el) return;

        if (code === 'LangToggle') { toggleLanguage(); return; }
        else if (code === 'LayoutToggle') { toggleKorLayout(); return; }
        else if (code === 'ShiftLock') { isShiftLockOn = !isShiftLockOn; updateKeyLabels(); return; }
        else if (code === 'ShiftLeft' || code === 'ShiftRight') { isTempShiftOn = !isTempShiftOn; updateKeyLabels(); return; }

        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        if (code === 'Space') { el.setRangeText(' ', el.selectionStart, el.selectionEnd, 'end'); }
        else if (code === 'Enter') { el.setRangeText('\n', el.selectionStart, el.selectionEnd, 'end'); }
        else if (code === 'Backspace') {
            if (el.selectionStart === el.selectionEnd && el.selectionStart > 0) {
                el.setRangeText('', el.selectionStart - 1, el.selectionEnd, 'end');
            } else if (el.selectionStart !== el.selectionEnd) {
                el.setRangeText('', el.selectionStart, el.selectionEnd, 'end');
            }
        }
        else if (!modifierLabels[code]) {
            let charToInsert = layoutData.base[code] || '';
            if (isEffectiveShift && layoutData.shift && layoutData.shift[code]) charToInsert = layoutData.shift[code];

            if (currentKorLayout === 'dubeolsik_old' && currentLang !== 'qwerty') {
                handleOldHangulInput(charToInsert);
            } else {
                el.setRangeText(charToInsert, el.selectionStart, el.selectionEnd, 'end');
            }
        }

        if (code !== 'Backspace') el.dispatchEvent(new InputEvent('input', { bubbles: true }));
        if (isTempShiftOn && !code.startsWith('Shift')) { isTempShiftOn = false; updateKeyLabels(); }
    });

    $('#wpTextbox1').on('keydown', function(e) {
        const code = e.originalEvent.code;
        if (code.startsWith('Shift')) { isShiftPressed = true; updateKeyLabels(); }
        if (code === 'CapsLock') { isShiftLockOn = !isShiftLockOn; updateKeyLabels(); }
        if (code === 'Lang1' || code === 'HangulMode') toggleLanguage();

        if (currentLang !== 'qwerty' && currentKorLayout === 'dubeolsik_old') {
            const activeLayout = window.OhiKeyboardData.layouts[currentKorLayout];
            if (activeLayout.base[code] !== undefined) {
                e.preventDefault();
                const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;
                let charToInsert = isEffectiveShift && activeLayout.shift[code] ? activeLayout.shift[code] : activeLayout.base[code];
                if (charToInsert) handleOldHangulInput(charToInsert);
                if (isTempShiftOn && !code.startsWith('Shift')) { isTempShiftOn = false; updateKeyLabels(); }
            }
        }

        let targetCode = code === 'Lang1' || code === 'HangulMode' || code === 'AltRight' ? 'LangToggle' : (code === 'CapsLock' ? 'ShiftLock' : code);
        const $key = $keyboard.find(`.ohi-key[data-code="${targetCode}"]`);
        if ($key.length) $key.addClass('active');
    });

    $('#wpTextbox1').on('keyup', function(e) {
        const code = e.originalEvent.code;
        if (code.startsWith('Shift')) { isShiftPressed = false; updateKeyLabels(); }
        let targetCode = code === 'Lang1' || code === 'HangulMode' || code === 'AltRight' ? 'LangToggle' : (code === 'CapsLock' ? 'ShiftLock' : code);
        const $key = $keyboard.find(`.ohi-key[data-code="${targetCode}"]`);
        if ($key.length) $key.removeClass('active');
    });
});

$(function() {
    const action = mw.config.get('wgAction');
    if (action !== 'edit' && action !== 'submit') return;

    const CHO_TO_GGEUT = {
        0x1100: 0x11A8, 0x1101: 0x11A9, 0x1102: 0x11AB, 0x1103: 0x11AE, 0x1105: 0x11AF,
        0x1106: 0x11B7, 0x1107: 0x11B8, 0x1109: 0x11BA, 0x110A: 0x11BB, 0x110B: 0x11BC,
        0x110C: 0x11BD, 0x110E: 0x11BE, 0x110F: 0x11BF, 0x1110: 0x11C0, 0x1111: 0x11C1, 0x1112: 0x11C2,
        0x1140: 0x11EB, 0x114C: 0x11F0, 0x1159: 0x11F9
    };
    const GGEUT_TO_CHO = {};
    for (let cho in CHO_TO_GGEUT) GGEUT_TO_CHO[CHO_TO_GGEUT[cho]] = parseInt(cho);

    let comp = { cho: 0, jung1: 0, jung2: 0, jong1: 0, jong2: 0 };
    let isComposing = false;
    let compStart = -1;

    // 미디어위키 텍스트 에디터 객체
    const $wpTextbox1 = $('#wpTextbox1');

    function commitComp() {
        if (!isComposing) return;
        isComposing = false;
        compStart = -1;
        comp = { cho: 0, jung1: 0, jung2: 0, jong1: 0, jong2: 0 };
    }

    function combineNFD(c1, c2) {
        let combined = 0x10000 * c1 + c2;
        for (let i = 0; i < window.hangeul_combination_table_full.length; ++i) {
            if (combined === window.hangeul_combination_table_full[i][0]) return window.hangeul_combination_table_full[i][1];
        }
        return 0;
    }

    function getComposedString() {
        if (!comp.cho && !comp.jung1) return '';
        let cho = comp.cho;
        let jung = comp.jung2 ? combineNFD(comp.jung1, comp.jung2) : comp.jung1;
        let jong = comp.jong2 ? combineNFD(comp.jong1, comp.jong2) : comp.jong1;

        if (cho >= 0x1100 && cho <= 0x1112 && jung >= 0x1161 && jung <= 0x1175 && (jong === 0 || (jong >= 0x11A8 && jong <= 0x11C2))) {
            let nfcCode = 0xAC00 + ((cho - 0x1100) * 588) + ((jung - 0x1161) * 28) + (jong ? jong - 0x11A7 : 0);
            return String.fromCharCode(nfcCode);
        }

        let res = '';
        if (jung && !cho) res += String.fromCharCode(0x115F);
        if (cho) res += String.fromCharCode(cho);
        if (jung) res += String.fromCharCode(jung);
        if (jong) res += String.fromCharCode(jong);
        return res;
    }

    // ★ 미디어위키의 textSelection API를 사용하여 이중 입력 버그 원천 차단
    function updateDOM() {
        let str = getComposedString();
        $wpTextbox1.focus();

        let el = $wpTextbox1[0];

        if (!isComposing) {
            compStart = el.selectionStart;
            isComposing = true;
        }

        // 현재 조합 중인 글자 길이만큼 블록을 잡아서 새로운 조합 글자로 덮어씌움
        el.setSelectionRange(compStart, el.selectionEnd);
        $wpTextbox1.textSelection('encapsulateSelection', { pre: str, replace: true });

        // 삽입 후 커서 위치 보정
        el.setSelectionRange(compStart + str.length, compStart + str.length);
    }

    function insertFinalText(char) {
        $wpTextbox1.focus();
        commitComp();
        $wpTextbox1.textSelection('encapsulateSelection', { pre: char });
    }

    function processKey(c) {
        let isCho = (c >= 0x1100 && c <= 0x115E) || (c >= 0xA960 && c <= 0xA97C);
        let isJung = (c >= 0x1161 && c <= 0x11A7) || (c >= 0xD7B0 && c <= 0xD7C6);

        if (isCho) {
            if (comp.jung1) {
                let jongC = CHO_TO_GGEUT[c] || 0;
                if (comp.jong1) {
                    if (!comp.jong2 && jongC && combineNFD(comp.jong1, jongC)) {
                        comp.jong2 = jongC;
                        updateDOM();
                    } else { commitComp(); processKey(c); }
                } else {
                    if (jongC) { comp.jong1 = jongC; updateDOM(); } 
                    else { commitComp(); processKey(c); }
                }
            } else {
                if (comp.cho && !comp.jung1) {
                    let comb = combineNFD(comp.cho, c);
                    if (comb) { comp.cho = comb; updateDOM(); } 
                    else { commitComp(); processKey(c); }
                } else { comp.cho = c; updateDOM(); }
            }
        } else if (isJung) {
            if (comp.jong1) {
                let newCho = comp.jong2 ? (GGEUT_TO_CHO[comp.jong2] || 0) : (GGEUT_TO_CHO[comp.jong1] || 0);
                if (comp.jong2) comp.jong2 = 0; else comp.jong1 = 0;

                updateDOM(); // 받침이 떨어진 이전 글자를 확정
                commitComp();

                comp.cho = newCho;
                comp.jung1 = c;
                updateDOM(); // 분리된 초성과 새로운 중성으로 새 글자 시작
            } else {
                if (comp.jung1) {
                    if (!comp.jung2 && combineNFD(comp.jung1, c)) { comp.jung2 = c; updateDOM(); } 
                    else { commitComp(); processKey(c); }
                } else { comp.jung1 = c; updateDOM(); }
            }
        }
    }

    function handleBackspace() {
        let el = $wpTextbox1[0];

        if (isComposing) {
            if (comp.jong2) comp.jong2 = 0;
            else if (comp.jong1) comp.jong1 = 0;
            else if (comp.jung2) comp.jung2 = 0;
            else if (comp.jung1) comp.jung1 = 0;
            else if (comp.cho) comp.cho = 0;

            if (!comp.cho && !comp.jung1) {
                commitComp();
                // 완전히 지워졌을 때 블록을 잡아서 빈 문자열로 덮어씌움
                el.setSelectionRange(compStart, el.selectionEnd);
                $wpTextbox1.textSelection('encapsulateSelection', { pre: '', replace: true });
                el.setSelectionRange(compStart, compStart);
            } else { 
                updateDOM(); 
            }
        } else {
            let start = el.selectionStart, end = el.selectionEnd;
            if (start === end && start > 0) {
                el.setSelectionRange(start - 1, end);
                $wpTextbox1.textSelection('encapsulateSelection', { pre: '', replace: true });
                el.setSelectionRange(start - 1, start - 1);
            } else if (start !== end) {
                el.setSelectionRange(start, end);
                $wpTextbox1.textSelection('encapsulateSelection', { pre: '', replace: true });
                el.setSelectionRange(start, start);
            }
        }
    }

    let currentLang = 'qwerty';
    let currentKorLayout = 'dubeolsik';
    let isShiftPressed = false;
    let isShiftLockOn = false;
    let isTempShiftOn = false;
    let isKeyboardVisible = true;

    const $container = $('<div>').attr('id', 'ohi-keyboard-container').addClass('layout-qwerty');
    const $header = $('<div>').attr('id', 'ohi-header');
    const $status = $('<span>').attr('id', 'ohi-keyboard-status').text('');
    const $toggleVisibilityBtn = $('<button>').attr('id', 'ohi-toggle-visibility').text('키보드 숨기기');
    $header.append($status, $toggleVisibilityBtn);
    const $keyboard = $('<div>').attr('id', 'ohi-keyboard');
    $container.append($header, $keyboard);
    $('.editOptions').before($container);

    const modifierLabels = { 'Backspace': 'Backspace', 'Tab': 'Tab', 'ShiftLock': 'Shift Lock', 'Enter': 'Enter', 'ShiftLeft': 'Shift', 'ShiftRight': 'Shift', 'LangToggle': '한/영', 'LayoutToggle': '자판 바꿈' };

    function renderKeyboard() {
        $keyboard.empty();
        window.OhiKeyboardData.rows.forEach(row => {
            const $row = $('<div>').addClass('ohi-row');
            row.forEach(code => {
                const $key = $('<div>').addClass('ohi-key').attr('data-code', code);
                if (code === 'Space') $key.addClass('ohi-key-space').text(' ');
                else if (modifierLabels[code]) $key.addClass('ohi-key-modifier').addClass('ohi-key-' + code.toLowerCase()).text(modifierLabels[code]);
                $row.append($key);
            });
            $keyboard.append($row);
        });
        updateKeyLabels();
    }

    function updateKeyLabels() {
        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        $container.removeClass('layout-qwerty layout-dubeolsik layout-dubeolsik_old').addClass('layout-' + activeLayout);

        if (currentLang === 'qwerty') { 
            $status.text(''); 
        } else { 
            $status.text(currentKorLayout === 'dubeolsik' ? '[두벌식 표준]' : '[두벌식 옛한글]'); 
        }

        $keyboard.find('.ohi-key').each(function() {
            const code = $(this).attr('data-code');
            if (code === 'Space' || modifierLabels[code]) return;

            if (currentLang !== 'qwerty' && code.startsWith('Key')) {
                const baseEng = window.OhiKeyboardData.layouts.qwerty.base[code] || '';
                const baseKor = window.OhiKeyboardData.layouts[currentKorLayout].base[code] || '';
                const shiftKor = window.OhiKeyboardData.layouts[currentKorLayout].shift[code] || '';

                $(this).empty();
                $('<span>').addClass('ohi-eng-label').text(baseEng.toUpperCase()).appendTo(this);
                if (shiftKor && shiftKor !== baseKor) {
                    let dispShiftKor = shiftKor;
                    if (shiftKor.length === 1 && shiftKor.charCodeAt(0) >= 0x1100 && shiftKor.charCodeAt(0) <= 0x11FF) {
                        dispShiftKor = String.fromCharCode(0x115F) + shiftKor;
                        if (shiftKor.charCodeAt(0) >= 0x11A8) dispShiftKor = String.fromCharCode(0x115F) + String.fromCharCode(0x1160) + shiftKor;
                    }
                    $('<span>').addClass('ohi-kor-shift').text(dispShiftKor).appendTo(this);
                }

                let dispBaseKor = baseKor;
                if (baseKor.length === 1 && baseKor.charCodeAt(0) >= 0x1100 && baseKor.charCodeAt(0) <= 0x11FF) {
                    dispBaseKor = String.fromCharCode(0x115F) + baseKor;
                    if (baseKor.charCodeAt(0) >= 0x11A8) dispBaseKor = String.fromCharCode(0x115F) + String.fromCharCode(0x1160) + baseKor;
                }
                $('<span>').addClass('ohi-kor-base').text(dispBaseKor).appendTo(this);

                if (isEffectiveShift && shiftKor) {
                    $(this).find('.ohi-kor-shift').addClass('active-char');
                    $(this).find('.ohi-kor-base').removeClass('active-char');
                } else {
                    $(this).find('.ohi-kor-base').addClass('active-char');
                    $(this).find('.ohi-kor-shift').removeClass('active-char');
                }
            } else {
                let char = layoutData.base[code] || '';
                if (isEffectiveShift && layoutData.shift && layoutData.shift[code] !== undefined) char = layoutData.shift[code];
                $(this).empty().text(char);
            }
        });
        $keyboard.find('.ohi-key-shiftlock').toggleClass('locked-on', isShiftLockOn);
        $keyboard.find('.ohi-key-shiftleft, .ohi-key-shiftright').toggleClass('locked-on', isTempShiftOn);
    }

    if (window.OhiKeyboardData) renderKeyboard();

    function toggleLanguage() { currentLang = currentLang === 'qwerty' ? 'korean' : 'qwerty'; commitComp(); updateKeyLabels(); }
    function toggleKorLayout() { if (currentLang === 'qwerty') return; currentKorLayout = currentKorLayout === 'dubeolsik' ? 'dubeolsik_old' : 'dubeolsik'; commitComp(); updateKeyLabels(); }

    $toggleVisibilityBtn.on('click', function(e) {
        e.preventDefault(); isKeyboardVisible = !isKeyboardVisible;
        if (isKeyboardVisible) { $keyboard.show(); $(this).text('키보드 숨기기'); } else { $keyboard.hide(); $(this).text('키보드 보이기'); }
    });

    $keyboard.on('mousedown', '.ohi-key', function(e) {
        e.preventDefault(); 
        const code = $(this).attr('data-code');

        if (code === 'LangToggle') { toggleLanguage(); return; }
        else if (code === 'LayoutToggle') { toggleKorLayout(); return; }
        else if (code === 'ShiftLock') { isShiftLockOn = !isShiftLockOn; updateKeyLabels(); return; }
        else if (code === 'ShiftLeft' || code === 'ShiftRight') { isTempShiftOn = !isTempShiftOn; updateKeyLabels(); return; }

        const activeLayout = currentLang === 'qwerty' ? 'qwerty' : currentKorLayout;
        const layoutData = window.OhiKeyboardData.layouts[activeLayout];
        const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;

        if (code === 'Space') { insertFinalText(' '); }
        else if (code === 'Enter') { insertFinalText('\n'); }
        else if (code === 'Backspace') { handleBackspace(); }
        else if (!modifierLabels[code]) {
            let charToInsert = layoutData.base[code] || '';
            if (isEffectiveShift && layoutData.shift && layoutData.shift[code]) charToInsert = layoutData.shift[code];

            if (currentKorLayout === 'dubeolsik_old' && currentLang !== 'qwerty') {
                processKey(charToInsert.charCodeAt(0));
            } else {
                insertFinalText(charToInsert);
            }
        }
        if (isTempShiftOn && !code.startsWith('Shift')) { isTempShiftOn = false; updateKeyLabels(); }
    });

    $wpTextbox1.on('mousedown blur', function() { commitComp(); });

    function handleKeyEvent(e, isKeyDown) {
        const code = e.originalEvent.code;

        if (code.startsWith('Shift')) { isShiftPressed = isKeyDown; updateKeyLabels(); }
        if (isKeyDown && code === 'CapsLock') { isShiftLockOn = !isShiftLockOn; updateKeyLabels(); }
        if (isKeyDown && (code === 'Lang1' || code === 'HangulMode')) toggleLanguage();

        if (isKeyDown && currentLang !== 'qwerty' && currentKorLayout === 'dubeolsik_old') {
            const activeLayout = window.OhiKeyboardData.layouts[currentKorLayout];
            if (activeLayout.base[code] !== undefined) {
                // OS 입력 완전 차단
                e.preventDefault(); 
                const isEffectiveShift = isShiftPressed || isShiftLockOn || isTempShiftOn;
                let charToInsert = isEffectiveShift && activeLayout.shift[code] ? activeLayout.shift[code] : activeLayout.base[code];

                if (charToInsert) {
                    processKey(charToInsert.charCodeAt(0));
                }
                if (isTempShiftOn && !code.startsWith('Shift')) { isTempShiftOn = false; updateKeyLabels(); }
            } else if (code === 'Space' || code === 'Enter') {
                commitComp();
            } else if (code === 'Backspace') {
                e.preventDefault();
                handleBackspace();
            }
        }

        let targetCode = code === 'Lang1' || code === 'HangulMode' || code === 'AltRight' ? 'LangToggle' : (code === 'CapsLock' ? 'ShiftLock' : code);
        const $key = $keyboard.find(`.ohi-key[data-code="${targetCode}"]`);
        if ($key.length) { if (isKeyDown) $key.addClass('active'); else $key.removeClass('active'); }
    }

    $wpTextbox1.on('keydown', function(e) { handleKeyEvent(e, true); });
    $wpTextbox1.on('keyup', function(e) { handleKeyEvent(e, false); });
});

#ohi-keyboard-container {
    margin-top: 15px; margin-bottom: 15px; padding: 10px; background-color: #f8f9fa;
    border: 1px solid #c8ccd1; border-radius: 2px; max-width: 630px; font-family: sans-serif;
    user-select: none; clear: both;
}
#ohi-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; padding: 0 5px; }

#ohi-keyboard-container .row { display: flex; justify-content: center; margin-bottom: 2px; }

#ohi-keyboard-container div.e1, #ohi-keyboard-container div.e2, #ohi-keyboard-container div.e3, 
#ohi-keyboard-container div.h1, #ohi-keyboard-container div.h2, #ohi-keyboard-container div.h3 {
    display:flex; flex-direction: column; justify-content: center; align-items: center; font-size:13px; height:38px; cursor:pointer;
    border: 1px solid #a2a9b1; border-radius: 3px; margin: 0 1px; color: #202122; box-shadow: 0 1px 0 0 #a2a9b1; position: relative;
}
#ohi-keyboard-container div.e1 { background-color: #ffffff; }
#ohi-keyboard-container div.e2 { background-color: #eaecf0; font-size: 11px; } /* 특수키 */
#ohi-keyboard-container div.h1, #ohi-keyboard-container div.h2, #ohi-keyboard-container div.h3 { background-color: #ffffff; } /* 파스텔톤 제거 시 */
#ohi-keyboard-container div.gin-hol { background-color: #ffffff; }

#ohi-keyboard-container div.e1:hover, #ohi-keyboard-container div.e2:hover, #ohi-keyboard-container div.e3:hover, 
#ohi-keyboard-container div.h1:hover, #ohi-keyboard-container div.h2:hover, #ohi-keyboard-container div.h3:hover { background-color:#eaf3ff; }

#ohi-keyboard-container div.clicked, #ohi-keyboard-container div.pressed { background-color: #eaf3ff !important; border-color: #3366cc; color: #3366cc; transform: translateY(1px); box-shadow: 0 0 0 0 #3366cc; }

#ohi-keyboard-container div.up, #ohi-keyboard-container div.down { width: 100%; display: flex; justify-content: space-between; padding: 0 4px; box-sizing: border-box; }
#ohi-keyboard-container div.up { align-items: flex-start; height: 16px; margin-top:2px; }
#ohi-keyboard-container div.down { align-items: flex-end; height: 18px; margin-bottom:2px; }

#ohi-keyboard-container div.ue, #ohi-keyboard-container div.de { color:#72777d; font-size: 10px; }
