					prev_pressed_keys = [];
					double_multikey_abbreviated_state = 1;
					return abbreviation_table[i].chars;
				}
			}
		}

		l.push(i);
	}

	if(l.length) {
		prev_class = typeof abbreviation_table[l[0]].class != 'undefined' ? abbreviation_table[l[0]].class.slice() : [];
		return abbreviation_table[l[0]].chars;
	}
	else return [];
}


