/**
 * Gadget: RaceResult Editor
 * Menambahkan tombol edit (+/-) pada setiap baris {{Result}} di halaman wiki
 * yang menggunakan {{RaceResultTable}}.
 *
 * Instalasi:
 *  1. Salin file ini ke MediaWiki:Gadget-RaceResultEditor.js
 *  2. Daftarkan di MediaWiki:Gadgets-definition:
 *       * RaceResultEditor[ResourceLoader|default]|RaceResultEditor.js
 *  3. Tambahkan CSS pendamping di MediaWiki:Gadget-RaceResultEditor.css
 *     (atau embed langsung via mw.util.addCSS seperti di bawah)
 */

( function ( mw, $ ) {
	'use strict';

	/* Hanya aktif di halaman yang memiliki tabel RaceResult */
	if ( !document.querySelector( '.raceresult-table, table.wikitable' ) ) {
		return;
	}

	/* ── CSS ───────────────────────────────────────────────────── */
	mw.util.addCSS( `
		.rre-btn {
			display: inline-flex;
