		}
		.rre-btn-cancel {
			padding: 6px 16px; border: 1px solid #a2a9b1;
			border-radius: 4px; background: #fff; color: #202122;
			font-size: 13px; cursor: pointer;
		}
		.rre-btn-cancel:hover { background: #eaecf0; }
		.rre-btn-save {
			padding: 6px 18px; border: 1px solid #3366cc;
			border-radius: 4px; background: #3679b8; color: #fff;
			font-size: 13px; font-weight: bold; cursor: pointer;
		}
		.rre-btn-save:hover { background: #2a5ea8; }

		/* Toast */
		#rre-toast {
			position: fixed; bottom: 24px; left: 50%;
			transform: translateX(-50%) translateY(12px);
			background: #14866d; color: #fff;
			padding: 8px 18px; border-radius: 4px;
			font-size: 13px; font-family: sans-serif;
			opacity: 0; transition: opacity .25s, transform .25s;
			z-index: 10100; pointer-events: none;
		}
