				// Ambil teks sel pertama sebagai "date", sel ke-6 sebagai "name"
				// (sesuaikan index jika urutan kolom berbeda)
				const dateCell  = cells[ 0 ];
				const nameCell  = cells[ 5 ] || cells[ 1 ];

