			gap: 3px;
			margin-left: 4px;
			padding: 2px 7px;
			font-size: 11px;
			line-height: 1.6;
			border: 1px solid #a2a9b1;
			border-radius: 4px;
			background: #f8f9fa;
			color: #202122;
			cursor: pointer;
			vertical-align: middle;
			white-space: nowrap;
		}
		.rre-btn:hover { background: #eaf3fb; border-color: #36c; }
		.rre-btn-del:hover { background: #fee7e6; border-color: #d33; color: #d33; }

		/* Overlay */
		#rre-overlay {
			position: fixed; inset: 0;
			background: rgba(0,0,0,.45);
			z-index: 10000;
			display: flex; align-items: center; justify-content: center;
		}

		/* Dialog */
		#rre-dialog {
			background: #fff;
			border: 1px solid #a2a9b1;
			border-radius: 6px;
			width: 560px;
			max-width: 96vw;
