	/* ── Parse parameter {{Result}} dari satu baris teks wikitext ─ */
	function parseResultParams( wikitext ) {
		const params = {};
		// Cocokkan setiap |key= value
		const re = /\|\s*([\w]+)\s*=\s*((?:[^|{}]|\{\{[^}]*\}\})*)/g;
		let m;
		while ( ( m = re.exec( wikitext ) ) !== null ) {
			params[ m[ 1 ].trim() ] = m[ 2 ].trim();
