			color: #202122;
		}
		.rre-field input:focus, .rre-field select:focus {
			border-color: #3679b8; outline: none;
			box-shadow: 0 0 0 2px rgba(54,121,184,.15);
		}
		.rre-hint { font-size: 11px; color: #72777d; }

		#rre-dialog-footer {
			display: flex; justify-content: flex-end; gap: 8px;
			padding: 10px 16px;
			border-top: 1px solid #eaecf0;
			background: #f8f9fa;
			border-radius: 0 0 6px 6px;
			position: sticky; bottom: 0;
		}
		.rre-btn-cancel {
			padding: 6px 16px; border: 1px solid #a2a9b1;
			border-radius: 4px; background: #fff; color: #202122;
			font-size: 13px; cursor: pointer;
		}
		.rre-btn-cancel:hover { background: #eaecf0; }
		.rre-btn-save {
			padding: 6px 18px; border: 1px solid #3366cc;
			border-radius: 4px; background: #3679b8; color: #fff;
			font-size: 13px; font-weight: bold; cursor: pointer;
		}
		.rre-btn-save:hover { background: #2a5ea8; }

		/* Toast */
		#rre-toast {
			position: fixed; bottom: 24px; left: 50%;
			transform: translateX(-50%) translateY(12px);
			background: #14866d; color: #fff;
			padding: 8px 18px; border-radius: 4px;
			font-size: 13px; font-family: sans-serif;
			opacity: 0; transition: opacity .25s, transform .25s;
			z-index: 10100; pointer-events: none;
		}
		#rre-toast.rre-toast-show { opacity: 1; transform: translateX(-50%) translateY(0); }
		#rre-toast.rre-toast-err { background: #b32424; }
	` );

	/* ── Struktur field ────────────────────────────────────────── */
	const FIELDS = [
		{ id: 'date',       label: 'Date',                placeholder: 'Jun 26, 1988',    hint: 'Format: Month DD, YYYY' },
		{ id: 'racecourse', label: 'Racecourse',          placeholder: 'Pulomas' },
		{ id: 'entry',      label: 'Entry',               placeholder: 'jumlah kuda' },
		{ id: 'number',     label: 'Horse No. (HN)',      placeholder: 'nomor kuda' },
		{ id: 'jockey',     label: 'Jockey',              placeholder: 'nama joki' },
		{ id: 'name',       label: 'Race Name',           placeholder: 'nama perlombaan', full: true },
		{ id: 'class',      label: 'Class',               placeholder: 'Derby, 3 y.o Div I' },
		{
			id: 'finished', label: 'Finished',
			type: 'select',
			options: [ '', '1st', '2nd', '3rd', '4th', '5th', 'PL', 'NP' ]
		},
		{ id: 'distance',   label: 'Distance',            placeholder: '1400m' },
		{ id: 'winner',     label: 'Winner / Runner-up',  placeholder: 'nama kuda' },
		{ id: 'time',       label: 'Time',                placeholder: '1.23,7' },
		{
			id: 'source',   label: 'Source (ref tag)',
			placeholder: '<ref name="kuda2"/>',
			hint: 'Isi lengkap tag <ref> termasuk markup wiki',
			full: true
		}
	];

	/* ── Parse parameter {{Result}} dari satu baris teks wikitext ─
	 *  Mendukung nilai yang mengandung {{template}} bersarang satu level.
	 *  Contoh: |source= <ref name="x">{{Cite news |...}}</ref>
	 * ─────────────────────────────────────────────────────────── */
	function parseResultParams( wikitext ) {
		const params = {};
		// Hapus pembungkus {{Result ... }} terlebih dahulu
		const inner = wikitext.replace( /^\{\{Result\s*/i, '' ).replace( /\}\}\s*$/, '' );
		// Split berdasarkan | yang tidak berada di dalam {{ }}
		const parts = [];
		let depth = 0, current = '';
		for ( let i = 0; i < inner.length; i++ ) {
			if ( inner[ i ] === '{' && inner[ i + 1 ] === '{' ) { depth++; current += '{{'; i++; }
			else if ( inner[ i ] === '}' && inner[ i + 1 ] === '}' ) { depth--; current += '}}'; i++; }
			else if ( inner[ i ] === '|' && depth === 0 ) { parts.push( current ); current = ''; }
			else { current += inner[ i ]; }
		}
		if ( current ) { parts.push( current ); }

		parts.forEach( part => {
			const eq = part.indexOf( '=' );
			if ( eq === -1 ) { return; }
			const key = part.slice( 0, eq ).trim();
			const val = part.slice( eq + 1 ).trim();
			if ( key ) { params[ key ] = val; }
		} );
		return params;
	}

	/* ── Cari dan kembalikan teks mentah satu blok {{Result}} ─────
	 *  berdasarkan nilai date (dan opsional name) dari wikitext halaman.
	 *  Mendukung {{Result}} multi-baris dan nilai bersarang {{ }}.
	 * ─────────────────────────────────────────────────────────── */
	function findResultBlock( fullWikitext, dateHint, nameHint ) {
		// Temukan semua posisi awal {{Result
		const starts = [];
		const openRe = /\{\{Result\b/gi;
		let m;
		while ( ( m = openRe.exec( fullWikitext ) ) !== null ) {
			starts.push( m.index );
		}

		for ( const start of starts ) {
			// Jalan maju untuk menemukan penutup }} yang sesuai (depth-aware).
			// Konten di dalam <ref>...</ref> dan <ref .../> diabaikan dari
			// perhitungan depth karena bisa mengandung {{Cite news}} yang
			// akan membuat depth salah hitung.
			let depth = 0, i = start;
			while ( i < fullWikitext.length ) {
				// Lewati blok <ref ...>...</ref> secara keseluruhan
				if ( fullWikitext[ i ] === '<' && fullWikitext.slice( i, i + 4 ).toLowerCase() === '<ref' ) {
					// Self-closing: <ref name="x"/>
					const selfClose = fullWikitext.indexOf( '/>', i );
					const tagClose  = fullWikitext.indexOf( '>', i );
					if ( selfClose !== -1 && ( tagClose === -1 || selfClose <= tagClose ) ) {
						i = selfClose + 2;
					} else {
						// Cari </ref>
						const endRef = fullWikitext.toLowerCase().indexOf( '</ref>', i );
						i = endRef === -1 ? fullWikitext.length : endRef + 6;
					}
					continue;
				}
				if ( fullWikitext[ i ] === '{' && fullWikitext[ i + 1 ] === '{' ) { depth++; i += 2; }
				else if ( fullWikitext[ i ] === '}' && fullWikitext[ i + 1 ] === '}' ) {
					depth--;
					i += 2;
					if ( depth === 0 ) { break; }
				} else { i++; }
			}
			const block = fullWikitext.slice( start, i );
			const p = parseResultParams( block );
			if ( p.date && p.date.trim() === dateHint.trim() ) {
				if ( !nameHint || ( p.name && p.name.trim() === nameHint.trim() ) ) {
					return { block, params: p };
				}
			}
		}
		return null;
	}

	/* ── Serialisasi kembali ke {{Result|...}} ─────────────────────
	 *  mergedParams = gabungan originalParams + perubahan user.
	 *  Parameter yang tidak dikenal FIELDS tetap dipertahankan di akhir.
	 * ─────────────────────────────────────────────────────────── */
	function buildResultWikitext( mergedParams ) {
		const knownIds = new Set( FIELDS.map( f => f.id ) );
		const parts = FIELDS.map( f => `|${ f.id }= ${ mergedParams[ f.id ] !== undefined ? mergedParams[ f.id ] : '' }` );
		Object.keys( mergedParams ).forEach( key => {
			if ( !knownIds.has( key ) ) {
				parts.push( `|${ key }= ${ mergedParams[ key ] }` );
			}
		} );
		return `{{Result${ parts.join( '' ) }}}`;
	}

	/* ── Ambil & simpan wikitext halaman via API ───────────────── */
	function getPageWikitext( title ) {
		return new mw.Api().get( {
			action: 'parse',
			page: title,
			prop: 'wikitext',
			formatversion: 2
		} ).then( data => data.parse.wikitext );
	}

	function savePageEdit( title, newContent, summary ) {
		return new mw.Api().postWithEditToken( {
			action: 'edit',
			title: title,
			text: newContent,
			summary: summary || 'RaceResult Gadget: edit baris Result',
			minor: true
		} );
	}

	/* ── Cari & ganti satu {{Result}} di wikitext ─────────────────
	 *  Menggunakan findResultBlock (depth-aware) untuk menemukan teks
	 *  blok mentah, lalu ganti dengan string replace literal agar aman
	 *  terhadap karakter khusus di dalam nilai parameter (ref, cite, dll).
	 * ─────────────────────────────────────────────────────────── */
	function replaceResultInWikitext( fullWikitext, originalWikitextBlock, mergedParams ) {
		const newBlock = buildResultWikitext( mergedParams );
		// Gunakan split+join untuk menghindari masalah karakter khusus di replace()
		const idx = fullWikitext.indexOf( originalWikitextBlock );
		if ( idx === -1 ) { return fullWikitext; } // tidak ditemukan, kembalikan apa adanya
		return fullWikitext.slice( 0, idx ) + newBlock + fullWikitext.slice( idx + originalWikitextBlock.length );
	}

	/* ── Tambah baris {{Result}} baru ke akhir {{RaceResultTable}} */
	function appendResultInWikitext( fullWikitext, newParams ) {
		const newWikitext = buildResultWikitext( newParams );
		// Sisipkan sebelum penutup }}  dari {{RaceResultTable
		return fullWikitext.replace( /(\}\}\s*)$/, '\n' + newWikitext + '\n$1' );
	}

	/* ── Hapus satu {{Result}} dari wikitext ──────────────────────
	 *  Menggunakan findResultBlock untuk menemukan teks blok mentah.
	 * ─────────────────────────────────────────────────────────── */
	function deleteResultInWikitext( fullWikitext, originalWikitextBlock ) {
		const idx = fullWikitext.indexOf( originalWikitextBlock );
		if ( idx === -1 ) { return fullWikitext; }
		// Hapus juga newline sebelum/sesudah blok jika ada
		let start = idx, end = idx + originalWikitextBlock.length;
		if ( fullWikitext[ start - 1 ] === '\n' ) { start--; }
		return fullWikitext.slice( 0, start ) + fullWikitext.slice( end );
	}

	/* ── Toast ─────────────────────────────────────────────────── */
	let toastTimer;
	function showToast( msg, isError ) {
		let el = document.getElementById( 'rre-toast' );
		if ( !el ) {
			el = document.createElement( 'div' );
			el.id = 'rre-toast';
			document.body.appendChild( el );
		}
		el.textContent = msg;
		el.className = isError ? 'rre-toast-err' : '';
		// reflow trick
		void el.offsetWidth;
		el.classList.add( 'rre-toast-show' );
		clearTimeout( toastTimer );
		toastTimer = setTimeout( () => el.classList.remove( 'rre-toast-show' ), 2500 );
	}

	/* ── Dialog ────────────────────────────────────────────────── */
	let originalParams = null;   // params yang diparsing dari wikitext asli
	let originalBlock  = null;   // teks mentah blok {{Result}} asli (untuk replace/delete)
	let isNewRow = false;

	function openDialog( cellParams, newRow ) {
		isNewRow = !!newRow;
		buildDialog();

		if ( isNewRow ) {
			// Mode tambah: langsung buka dialog dengan field kosong
			originalParams = {};
			originalBlock  = null;
			document.getElementById( 'rre-dlg-title' ).textContent = 'Tambah baris Result';
			FIELDS.forEach( f => {
				const el = document.getElementById( 'rre-f-' + f.id );
				if ( el ) { el.value = ''; }
			} );
			document.getElementById( 'rre-overlay' ).style.display = 'flex';
			document.getElementById( 'rre-f-date' ).focus();
			return;
		}

		// Mode edit: fetch wikitext dulu, parse params asli, baru isi dialog
		document.getElementById( 'rre-dlg-title' ).textContent = 'Memuat data…';
		document.getElementById( 'rre-overlay' ).style.display = 'flex';

		// Nonaktifkan tombol simpan sementara loading
		const saveBtn = document.getElementById( 'rre-save-btn' );
		saveBtn.disabled = true;

		const pageTitle = mw.config.get( 'wgPageName' );
		getPageWikitext( pageTitle ).then( wikitext => {
			const found = findResultBlock( wikitext, cellParams.date, cellParams.name );
			if ( found ) {
				originalParams = found.params;
				originalBlock  = found.block;
			} else {
				// Fallback: gunakan data dari sel tabel (mungkin source kosong)
				originalParams = Object.assign( {}, cellParams );
				originalBlock  = null;
				showToast( 'Peringatan: blok wikitext tidak ditemukan, beberapa nilai mungkin tidak lengkap.', true );
			}

			document.getElementById( 'rre-dlg-title' ).textContent = 'Edit baris Result';
			FIELDS.forEach( f => {
				const el = document.getElementById( 'rre-f-' + f.id );
				if ( el ) { el.value = originalParams[ f.id ] !== undefined ? originalParams[ f.id ] : ''; }
			} );
			saveBtn.disabled = false;
			document.getElementById( 'rre-f-date' ).focus();
		} ).catch( err => {
			showToast( 'Gagal memuat wikitext: ' + err, true );
			closeDialog();
		} );
	}

	function buildDialog() {
		if ( document.getElementById( 'rre-overlay' ) ) { return; }

		const overlay = document.createElement( 'div' );
		overlay.id = 'rre-overlay';
		overlay.style.display = 'none';

		const dialog = document.createElement( 'div' );
		dialog.id = 'rre-dialog';
		dialog.setAttribute( 'role', 'dialog' );
		dialog.setAttribute( 'aria-modal', 'true' );
		dialog.setAttribute( 'aria-labelledby', 'rre-dlg-title' );

		// Header
		const header = document.createElement( 'div' );
		header.id = 'rre-dialog-header';
		header.innerHTML = '<h2 id="rre-dlg-title">Edit baris Result</h2>';
		const closeBtn = document.createElement( 'button' );
		closeBtn.id = 'rre-close-btn';
		closeBtn.innerHTML = '&times;';
		closeBtn.setAttribute( 'aria-label', 'Tutup dialog' );
		closeBtn.addEventListener( 'click', closeDialog );
		header.appendChild( closeBtn );

		// Form grid
		const grid = document.createElement( 'div' );
		grid.id = 'rre-form-grid';

		FIELDS.forEach( f => {
			const wrap = document.createElement( 'div' );
			wrap.className = 'rre-field' + ( f.full ? ' full' : '' );

			const lbl = document.createElement( 'label' );
			lbl.setAttribute( 'for', 'rre-f-' + f.id );
			lbl.textContent = f.label;
			wrap.appendChild( lbl );

			let input;
			if ( f.type === 'select' ) {
				input = document.createElement( 'select' );
				( f.options || [] ).forEach( opt => {
					const o = document.createElement( 'option' );
					o.value = opt; o.textContent = opt || '— pilih —';
					input.appendChild( o );
				} );
			} else {
				input = document.createElement( 'input' );
				input.type = 'text';
				input.placeholder = f.placeholder || '';
			}
			input.id = 'rre-f-' + f.id;
			wrap.appendChild( input );

			if ( f.hint ) {
				const hint = document.createElement( 'span' );
				hint.className = 'rre-hint';
				hint.textContent = f.hint;
				wrap.appendChild( hint );
			}
			grid.appendChild( wrap );
		} );

		// Footer
		const footer = document.createElement( 'div' );
		footer.id = 'rre-dialog-footer';

		const cancelBtn = document.createElement( 'button' );
		cancelBtn.className = 'rre-btn-cancel';
		cancelBtn.textContent = 'Batal';
		cancelBtn.addEventListener( 'click', closeDialog );

		const saveBtn = document.createElement( 'button' );
		saveBtn.className = 'rre-btn-save';
		saveBtn.id = 'rre-save-btn';
		saveBtn.textContent = 'Simpan';
		saveBtn.addEventListener( 'click', onSave );

		footer.appendChild( cancelBtn );
		footer.appendChild( saveBtn );

		dialog.appendChild( header );
		dialog.appendChild( grid );
		dialog.appendChild( footer );
		overlay.appendChild( dialog );
		document.body.appendChild( overlay );

		// Klik di luar dialog → tutup
		overlay.addEventListener( 'click', e => {
			if ( e.target === overlay ) { closeDialog(); }
		} );

		// ESC → tutup
		document.addEventListener( 'keydown', e => {
			if ( e.key === 'Escape' ) { closeDialog(); }
		} );
	}

	function openDialog( params, newRow ) {
		isNewRow = !!newRow;
		currentParams = params || {};
		buildDialog();

		document.getElementById( 'rre-dlg-title' ).textContent =
			isNewRow ? 'Tambah baris Result' : 'Edit baris Result';

		FIELDS.forEach( f => {
			const el = document.getElementById( 'rre-f-' + f.id );
			if ( el ) { el.value = currentParams[ f.id ] || ''; }
		} );

		document.getElementById( 'rre-overlay' ).style.display = 'flex';
		document.getElementById( 'rre-f-date' ).focus();
	}

	function closeDialog() {
		const overlay = document.getElementById( 'rre-overlay' );
		if ( overlay ) { overlay.style.display = 'none'; }
	}

	function onSave() {
		// Mulai dari salinan params asli (agar parameter yang tidak diubah tetap ada)
		const mergedParams = Object.assign( {}, originalParams );

		// Timpa hanya dengan nilai yang diisi user di dialog
		FIELDS.forEach( f => {
			const el = document.getElementById( 'rre-f-' + f.id );
			if ( el ) { mergedParams[ f.id ] = el.value.trim(); }
		} );

		if ( !mergedParams.date || !mergedParams.name ) {
			showToast( 'Date dan Race Name wajib diisi!', true );
			return;
		}

		const saveBtn = document.getElementById( 'rre-save-btn' );
		saveBtn.textContent = 'Menyimpan…';
		saveBtn.disabled = true;

		const pageTitle = mw.config.get( 'wgPageName' );

		getPageWikitext( pageTitle ).then( wikitext => {
			let updated;
			if ( isNewRow ) {
				updated = appendResultInWikitext( wikitext, mergedParams );
			} else {
				if ( !originalBlock ) {
					// Fallback jika blok asli tidak ditemukan: coba cari ulang sekarang
					const found = findResultBlock( wikitext, mergedParams.date, mergedParams.name );
					if ( found ) {
						updated = replaceResultInWikitext( wikitext, found.block, mergedParams );
					} else {
						throw new Error( 'Blok {{Result}} tidak ditemukan di wikitext. Edit dibatalkan.' );
					}
				} else {
					updated = replaceResultInWikitext( wikitext, originalBlock, mergedParams );
				}
			}

			return savePageEdit(
				pageTitle,
				updated,
				'RaceResult Gadget: ' + ( isNewRow ? 'tambah' : 'edit' ) +
				' baris — ' + mergedParams.name + ' (' + mergedParams.date + ')'
			);
		} ).then( () => {
			closeDialog();
			showToast( 'Tersimpan! Halaman akan dimuat ulang…' );
			setTimeout( () => location.reload(), 1500 );
		} ).catch( err => {
			console.error( '[RRE] save error:', err );
			showToast( 'Gagal menyimpan: ' + ( err.message || ( err.error && err.error.info ) || err ), true );
			saveBtn.textContent = 'Simpan';
			saveBtn.disabled = false;
		} );
	}

	/* ── Inject tombol ke setiap baris tabel ──────────────────── */
	function injectButtons() {
		// Cari semua baris di dalam tabel RaceResult
		// Template biasanya menghasilkan <table class="wikitable"> di dalam div tertentu,
		// atau bisa langsung wikitable. Sesuaikan selector jika perlu.
		const tables = document.querySelectorAll( 'table.wikitable' );
		if ( !tables.length ) { return; }

		tables.forEach( table => {
			const rows = table.querySelectorAll( 'tbody tr' );
			rows.forEach( tr => {
				// Lewati baris "season header" (biasanya hanya 1 sel colspan)
				const cells = tr.querySelectorAll( 'td' );
				if ( cells.length < 4 ) { return; }

				// Ambil teks sel pertama sebagai "date", sel ke-6 sebagai "name"
				// (sesuaikan index jika urutan kolom berbeda)
				const dateCell  = cells[ 0 ];
				const nameCell  = cells[ 5 ] || cells[ 1 ];

				// Kumpulkan parameter dari data-atribut jika ada,
				// atau parse dari konten sel sebagai fallback
				const params = {
					date:       dateCell.textContent.trim(),
					racecourse: ( cells[ 1 ] || {} ).textContent.trim(),
					entry:      ( cells[ 2 ] || {} ).textContent.trim(),
					number:     ( cells[ 3 ] || {} ).textContent.trim(),
					jockey:     ( cells[ 4 ] || {} ).textContent.trim(),
					name:       nameCell.textContent.trim(),
					class:      ( cells[ 6 ] || {} ).textContent.trim(),
					finished:   ( cells[ 7 ] || {} ).textContent.trim(),
					distance:   ( cells[ 8 ] || {} ).textContent.trim(),
					winner:     ( cells[ 9 ] || {} ).textContent.trim(),
