					entry:      getCellText( cells, 'entry' ),
					number:     getCellText( cells, 'number' ),
					jockey:     getCellText( cells, 'jockey' ),
					name:       getCellText( cells, 'name' ),
					class:      getCellText( cells, 'class' ),
					finished:   getCellText( cells, 'finished' ),
					distance:   getCellText( cells, 'distance' ),
					winner:     getCellText( cells, 'winner' ),
					time:       getCellText( cells, 'time' ),
