	function parseResultParams( wikitext ) {
		const params = {};
		// Hapus pembungkus {{Result ... }} terlebih dahulu
		const inner = wikitext.replace( /^\{\{Result\s*/i, '' ).replace( /\}\}\s*$/, '' );
