	/* ── Parse parameter {{Result}} dari satu baris teks wikitext ─ */
	function parseResultParams( wikitext ) {
		const params = {};
		// Cocokkan setiap |key= value
		const re = /\|\s*([\w]+)\s*=\s*((?:[^|{}]|\{\{[^}]*\}\})*)/g;
		let m;
		while ( ( m = re.exec( wikitext ) ) !== null ) {
			params[ m[ 1 ].trim() ] = m[ 2 ].trim();
		}
		return params;
	}

	/* ── Serialisasi kembali ke {{Result|...}} ─────────────────── */
	function buildResultWikitext( params ) {
		const parts = FIELDS.map( f => `|${ f.id }= ${ params[ f.id ] || '' }` );
		return `{{Result${ parts.join( '' ) }}}`;
	}

	/* ── Ambil & simpan wikitext halaman via API ───────────────── */
	function getPageWikitext( title ) {
		return new mw.Api().get( {
			action: 'parse',
			page: title,
			prop: 'wikitext',
			formatversion: 2
		} ).then( data => data.parse.wikitext );
	}

	function savePageEdit( title, newContent, summary ) {
		return new mw.Api().postWithEditToken( {
			action: 'edit',
			title: title,
			text: newContent,
			summary: summary || 'RaceResult Gadget: edit baris Result',
			minor: true
		} );
	}

	/* ── Cari & ganti satu {{Result}} di wikitext ─────────────── */
	function replaceResultInWikitext( fullWikitext, oldParams, newParams ) {
		// Buat pola pencocokan berdasarkan date + name (kombinasi unik)
		const escapedDate = oldParams.date.replace( /[.*+?^${}()|[\]\\]/g, '\\$&' );
		const escapedName = oldParams.name.replace( /[.*+?^${}()|[\]\\]/g, '\\$&' );

		// Regex longgar: cocokkan blok {{Result ... date= X ... name= Y ...}}
		const pattern = new RegExp(
			'\\{\\{Result[^}]*\\|\\s*date\\s*=\\s*' + escapedDate +
			'[^}]*\\|\\s*name\\s*=\\s*' + escapedName + '[^}]*\\}\\}',
			'i'
		);

		const newWikitext = buildResultWikitext( newParams );
		const replaced = fullWikitext.replace( pattern, newWikitext );

		if ( replaced === fullWikitext ) {
			// Fallback: cari berdasarkan date saja
			const fallback = new RegExp(
				'\\{\\{Result[^}]*\\|\\s*date\\s*=\\s*' + escapedDate + '[^}]*\\}\\}',
				'i'
			);
			return fullWikitext.replace( fallback, newWikitext );
		}
		return replaced;
	}

	/* ── Tambah baris {{Result}} baru ke akhir {{RaceResultTable}} */
	function appendResultInWikitext( fullWikitext, newParams ) {
		const newWikitext = buildResultWikitext( newParams );
		// Sisipkan sebelum penutup }}  dari {{RaceResultTable
		return fullWikitext.replace( /(\}\}\s*)$/, '\n' + newWikitext + '\n$1' );
	}

	/* ── Hapus satu {{Result}} dari wikitext ─────────────────── */
	function deleteResultInWikitext( fullWikitext, oldParams ) {
		const escapedDate = oldParams.date.replace( /[.*+?^${}()|[\]\\]/g, '\\$&' );
		const pattern = new RegExp(
			'\\n?\\{\\{Result[^}]*\\|\\s*date\\s*=\\s*' + escapedDate + '[^}]*\\}\\}',
			'i'
		);
		return fullWikitext.replace( pattern, '' );
	}

	/* ── Toast ─────────────────────────────────────────────────── */
