		toastTimer = setTimeout( () => el.classList.remove( 'rre-toast-show' ), 2500 );
	}

	/* ── Dialog ────────────────────────────────────────────────── */
	let currentParams = null;
	let isNewRow = false;

	function buildDialog() {
		if ( document.getElementById( 'rre-overlay' ) ) { return; }

		const overlay = document.createElement( 'div' );
		overlay.id = 'rre-overlay';
		overlay.style.display = 'none';

		const dialog = document.createElement( 'div' );
		dialog.id = 'rre-dialog';
		dialog.setAttribute( 'role', 'dialog' );
		dialog.setAttribute( 'aria-modal', 'true' );
		dialog.setAttribute( 'aria-labelledby', 'rre-dlg-title' );

		// Header
		const header = document.createElement( 'div' );
		header.id = 'rre-dialog-header';
		header.innerHTML = '<h2 id="rre-dlg-title">Edit baris Result</h2>';
		const closeBtn = document.createElement( 'button' );
		closeBtn.id = 'rre-close-btn';
		closeBtn.innerHTML = '&times;';
		closeBtn.setAttribute( 'aria-label', 'Tutup dialog' );
		closeBtn.addEventListener( 'click', closeDialog );
		header.appendChild( closeBtn );

		// Form grid
		const grid = document.createElement( 'div' );
		grid.id = 'rre-form-grid';

		FIELDS.forEach( f => {
			const wrap = document.createElement( 'div' );
			wrap.className = 'rre-field' + ( f.full ? ' full' : '' );

			const lbl = document.createElement( 'label' );
			lbl.setAttribute( 'for', 'rre-f-' + f.id );
			lbl.textContent = f.label;
			wrap.appendChild( lbl );

			let input;
			if ( f.type === 'select' ) {
				input = document.createElement( 'select' );
				( f.options || [] ).forEach( opt => {
					const o = document.createElement( 'option' );
					o.value = opt; o.textContent = opt || '— pilih —';
					input.appendChild( o );
				} );
			} else {
				input = document.createElement( 'input' );
				input.type = 'text';
				input.placeholder = f.placeholder || '';
			}
			input.id = 'rre-f-' + f.id;
			wrap.appendChild( input );

			if ( f.hint ) {
				const hint = document.createElement( 'span' );
				hint.className = 'rre-hint';
				hint.textContent = f.hint;
				wrap.appendChild( hint );
			}
			grid.appendChild( wrap );
		} );

		// Footer
		const footer = document.createElement( 'div' );
		footer.id = 'rre-dialog-footer';

		const cancelBtn = document.createElement( 'button' );
		cancelBtn.className = 'rre-btn-cancel';
		cancelBtn.textContent = 'Batal';
		cancelBtn.addEventListener( 'click', closeDialog );

		const saveBtn = document.createElement( 'button' );
		saveBtn.className = 'rre-btn-save';
		saveBtn.id = 'rre-save-btn';
		saveBtn.textContent = 'Simpan';
		saveBtn.addEventListener( 'click', onSave );

		footer.appendChild( cancelBtn );
		footer.appendChild( saveBtn );

		dialog.appendChild( header );
		dialog.appendChild( grid );
		dialog.appendChild( footer );
		overlay.appendChild( dialog );
