	function openDialog( params, newRow ) {
		isNewRow = !!newRow;
		currentParams = params || {};
		buildDialog();

		document.getElementById( 'rre-dlg-title' ).textContent =
			isNewRow ? 'Tambah baris Result' : 'Edit baris Result';

		FIELDS.forEach( f => {
			const el = document.getElementById( 'rre-f-' + f.id );
			if ( el ) { el.value = currentParams[ f.id ] || ''; }
		} );

		document.getElementById( 'rre-overlay' ).style.display = 'flex';
		document.getElementById( 'rre-f-date' ).focus();
	}

	function closeDialog() {
		const overlay = document.getElementById( 'rre-overlay' );
		if ( overlay ) { overlay.style.display = 'none'; }
	}

	function onSave() {
		const newParams = {};
		FIELDS.forEach( f => {
			const el = document.getElementById( 'rre-f-' + f.id );
			newParams[ f.id ] = el ? el.value.trim() : '';
		} );

		if ( !newParams.date || !newParams.name ) {
			showToast( 'Date dan Race Name wajib diisi!', true );
			return;
		}

		const saveBtn = document.getElementById( 'rre-save-btn' );
		saveBtn.textContent = 'Menyimpan…';
		saveBtn.disabled = true;

		const pageTitle = mw.config.get( 'wgPageName' );

		getPageWikitext( pageTitle ).then( wikitext => {
			let updated;
			if ( isNewRow ) {
				updated = appendResultInWikitext( wikitext, newParams );
			} else {
				updated = replaceResultInWikitext( wikitext, currentParams, newParams );
			}

			return savePageEdit(
				pageTitle,
				updated,
				'RaceResult Gadget: ' + ( isNewRow ? 'tambah' : 'edit' ) +
				' baris — ' + newParams.name + ' (' + newParams.date + ')'
			);
		} ).then( () => {
			closeDialog();
			showToast( 'Tersimpan! Halaman akan dimuat ulang…' );
			setTimeout( () => location.reload(), 1500 );
		} ).catch( err => {
			console.error( '[RRE] save error:', err );
			showToast( 'Gagal menyimpan: ' + ( err.error && err.error.info || err ), true );
			saveBtn.textContent = 'Simpan';
			saveBtn.disabled = false;
		} );
	}

	/* ── Inject tombol ke setiap baris tabel ──────────────────── */
	function injectButtons() {
		// Cari semua baris di dalam tabel RaceResult
		// Template biasanya menghasilkan <table class="wikitable"> di dalam div tertentu,
		// atau bisa langsung wikitable. Sesuaikan selector jika perlu.
		const tables = document.querySelectorAll( 'table.wikitable' );
		if ( !tables.length ) { return; }

		tables.forEach( table => {
			const rows = table.querySelectorAll( 'tbody tr' );
			rows.forEach( tr => {
				// Lewati baris "season header" (biasanya hanya 1 sel colspan)
				const cells = tr.querySelectorAll( 'td' );
				if ( cells.length < 4 ) { return; }

				// Ambil teks sel pertama sebagai "date", sel ke-6 sebagai "name"
				// (sesuaikan index jika urutan kolom berbeda)
				const dateCell  = cells[ 0 ];
				const nameCell  = cells[ 5 ] || cells[ 1 ];

				// Kumpulkan parameter dari data-atribut jika ada,
				// atau parse dari konten sel sebagai fallback
				const params = {
					date:       dateCell.textContent.trim(),
					racecourse: ( cells[ 1 ] || {} ).textContent.trim(),
					entry:      ( cells[ 2 ] || {} ).textContent.trim(),
					number:     ( cells[ 3 ] || {} ).textContent.trim(),
					jockey:     ( cells[ 4 ] || {} ).textContent.trim(),
					name:       nameCell.textContent.trim(),
					class:      ( cells[ 6 ] || {} ).textContent.trim(),
					finished:   ( cells[ 7 ] || {} ).textContent.trim(),
					distance:   ( cells[ 8 ] || {} ).textContent.trim(),
					winner:     ( cells[ 9 ] || {} ).textContent.trim(),
					time:       ( cells[ 10 ] || {} ).textContent.trim(),
					source:     ''   // tidak ditampilkan di sel; bisa di-extend
				};

				// Buat sel aksi terakhir (atau append ke sel terakhir)
				const lastCell = tr.querySelector( 'td:last-child' );

				const editBtn = document.createElement( 'button' );
				editBtn.className = 'rre-btn';
				editBtn.innerHTML = '&#9998; Edit';
				editBtn.title = 'Edit baris ini';
				editBtn.addEventListener( 'click', () => openDialog( params, false ) );

				const delBtn = document.createElement( 'button' );
				delBtn.className = 'rre-btn rre-btn-del';
				delBtn.innerHTML = '&#x1F5D1; Hapus';
				delBtn.title = 'Hapus baris ini';
				delBtn.addEventListener( 'click', () => {
					if ( !confirm( 'Yakin ingin menghapus baris ini?' ) ) { return; }
					const pageTitle = mw.config.get( 'wgPageName' );
					getPageWikitext( pageTitle ).then( wikitext => {
						const updated = deleteResultInWikitext( wikitext, params );
						return savePageEdit(
							pageTitle, updated,
							'RaceResult Gadget: hapus baris — ' + params.name
