					} ).then( () => {
						showToast( 'Baris dihapus! Memuat ulang…' );
						setTimeout( () => location.reload(), 1500 );
					} ).catch( err => {
						showToast( 'Gagal hapus: ' + err, true );
					} );
				} );

				if ( lastCell ) {
					lastCell.appendChild( document.createElement( 'br' ) );
					lastCell.appendChild( editBtn );
					lastCell.appendChild( delBtn );
				}
			} );
		} );

		/* Tombol "Tambah baris" di bawah tabel terakhir */
		const lastTable = tables[ tables.length - 1 ];
		const addBtn = document.createElement( 'button' );
		addBtn.className = 'rre-btn';
		addBtn.style.cssText = 'margin-top:8px; width:100%; justify-content:center; padding:6px;';
		addBtn.innerHTML = '+ Tambah baris Result';
		addBtn.addEventListener( 'click', () => openDialog( {}, true ) );
		lastTable.insertAdjacentElement( 'afterend', addBtn );
	}

