/**
 * Gadget: RaceResult Editor (v2)
 * Parameter {{Result}} diambil langsung dari wikitext halaman via API,
 * bukan dari teks yang dirender di tabel HTML — sehingga markup seperti
 * <ref>...</ref> dan [[wikilink]] tetap terbaca dan tersimpan utuh.
 *
 * Instalasi:
 *  1. Salin ke MediaWiki:Gadget-RaceResultEditor.js
 *  2. Daftarkan di MediaWiki:Gadgets-definition:
 *       * RaceResultEditor[ResourceLoader|default]|RaceResultEditor.js
 */

( function ( mw, $ ) {
	'use strict';

	/* Hanya aktif bila ada wikitable di halaman */
	if ( !document.querySelector( 'table.wikitable' ) ) { return; }

	/* Hanya untuk pengguna yang bisa mengedit */
	if ( !mw.config.get( 'wgIsProbablyEditable' ) ) { return; }

	/* ── CSS ──────────────────────────────────────────────────────── */
