		}
		@keyframes rre-spin { to { transform: rotate(360deg); } }

		#rre-toast {
			position: fixed; bottom: 24px; left: 50%;
			transform: translateX(-50%) translateY(12px);
			background: #14866d; color: #fff;
			padding: 8px 18px; border-radius: 4px; font-size: 13px;
			font-family: sans-serif; opacity: 0; pointer-events: none;
			transition: opacity .25s, transform .25s; z-index: 10100;
		}
		#rre-toast.rre-show { opacity: 1; transform: translateX(-50%) translateY(0); }
		#rre-toast.rre-err  { background: #b32424; }
	` );

	/* ── Definisi field ────────────────────────────────────────────── */
	const FIELDS = [
		{ id: 'date',       label: 'Date',               placeholder: 'Jun 26, 1988',    hint: 'Format: Month DD, YYYY' },
		{ id: 'racecourse', label: 'Racecourse',         placeholder: 'Pulomas' },
		{ id: 'entry',      label: 'Entry',              placeholder: 'jumlah kuda' },
		{ id: 'number',     label: 'Horse No. (HN)',     placeholder: 'nomor kuda' },
		{ id: 'jockey',     label: 'Jockey',             placeholder: 'nama joki' },
		{ id: 'name',       label: 'Race Name',          placeholder: 'nama perlombaan',  full: true },
		{ id: 'class',      label: 'Class',              placeholder: 'Derby, 3 y.o Div I' },
		{
			id: 'finished', label: 'Finished', type: 'select',
			options: [ '', '1st', '2nd', '3rd', '4th', '5th', 'PL', 'NP', 'WO' ]
		},
		{ id: 'distance',   label: 'Distance',           placeholder: '1400m' },
		{ id: 'winner',     label: 'Winner / Runner-up', placeholder: 'nama kuda' },
		{ id: 'time',       label: 'Time',               placeholder: '1.23,7' },
		{
			id: 'source', label: 'Source (ref markup)', type: 'textarea', full: true,
			placeholder: '<ref name="kuda2"/>\natau\n<ref name="neraca89">{{Cite news |date=... |title=...}}</ref>',
			hint: 'Salin markup <ref> lengkap dari wikitext — termasuk {{Cite news}} jika ada'
		}
	];

	/* ── State global ──────────────────────────────────────────────── */
	let parsedResults = [];   // [{ params, rawBlock, startIndex }]
	let editIndex     = null;
	let isNewRow      = false;

	/* ── Toast ────────────────────────────────────────────────────── */
	let toastTimer;
	function showToast( msg, isErr ) {
		let el = document.getElementById( 'rre-toast' );
		if ( !el ) {
			el = document.createElement( 'div' );
			el.id = 'rre-toast';
			document.body.appendChild( el );
		}
		el.textContent = msg;
		el.className = isErr ? 'rre-err' : '';
		void el.offsetWidth;
		el.classList.add( 'rre-show' );
		clearTimeout( toastTimer );
		toastTimer = setTimeout( () => el.classList.remove( 'rre-show' ), 2800 );
	}

	/* ── Parser wikitext ──────────────────────────────────────────── */

	/**
	 * Temukan semua blok {{Result|...}} di wikitext.
	 * Mendukung nested {{ }} dan <ref>...</ref> di dalam nilai parameter.
	 * Mengembalikan array { params, rawBlock, startIndex }.
	 */
	function parseAllResults( wikitext ) {
		const results = [];
		let pos = 0;
		while ( true ) {
			const start = wikitext.indexOf( '{{Result', pos );
			if ( start === -1 ) { break; }

			/* Ekstrak sampai }} penutup yang sesuai (depth-aware) */
			let depth = 0, i = start, end = -1;
			while ( i < wikitext.length ) {
				if ( wikitext[ i ] === '{' && wikitext[ i + 1 ] === '{' ) {
					depth++; i += 2;
				} else if ( wikitext[ i ] === '}' && wikitext[ i + 1 ] === '}' ) {
					depth--;
					if ( depth === 0 ) { end = i + 2; break; }
					i += 2;
				} else {
					i++;
				}
			}
			if ( end === -1 ) { break; }

			const rawBlock = wikitext.slice( start, end );
			results.push( { params: parseResultParams( rawBlock ), rawBlock, startIndex: start } );
			pos = end;
		}
		return results;
	}

	/**
	 * Parse key=value dari satu blok {{Result|...}}.
	 * Split dilakukan per pipe di level teratas sehingga pipe di dalam
	 * {{nested}} atau <ref>...</ref> tidak memutus nilai.
	 */
	function parseResultParams( block ) {
		const params = {};
		/* Hapus pembuka {{Result dan penutup }} */
		const inner = block.replace( /^\{\{Result\s*/, '' ).replace( /\}\}\s*$/, '' );
		splitByTopLevelPipe( inner ).forEach( part => {
			const eq = part.indexOf( '=' );
			if ( eq === -1 ) { return; }
			const key = part.slice( 0, eq ).trim();
			const val = part.slice( eq + 1 ).trim();
			if ( key ) { params[ key ] = val; }
		} );
		return params;
	}

	/**
	 * Split string by '|' hanya di level teratas
	 * (depth kurawal = 0, tidak di dalam <ref>).
	 */
	function splitByTopLevelPipe( str ) {
		const parts = [];
		let depth = 0, inRef = false, cur = '';
		for ( let i = 0; i < str.length; i++ ) {
			if ( str[ i ] === '{' && str[ i + 1 ] === '{' ) {
				depth++; cur += str[ i ]; continue;
			}
			if ( str[ i ] === '}' && str[ i + 1 ] === '}' ) {
				depth--; cur += str[ i ]; continue;
			}
			if ( str.slice( i, i + 4 ) === '<ref' ) { inRef = true; }
			if ( str.slice( i, i + 6 ) === '</ref' ) { inRef = false; }
			if ( str[ i ] === '|' && depth === 0 && !inRef ) {
				parts.push( cur ); cur = ''; continue;
			}
			cur += str[ i ];
		}
		if ( cur ) { parts.push( cur ); }
		return parts;
	}

	/* ── Serialisasi kembali ke {{Result|...}} ────────────────────── */
	function buildResultBlock( params ) {
		const parts = FIELDS.map( f => `|${ f.id }= ${ params[ f.id ] || '' }` );
		return `{{Result${ parts.join( '' ) }}}`;
	}

	/* ── API helpers ──────────────────────────────────────────────── */
	const api = new mw.Api();

	function fetchWikitext( title ) {
		return api.get( {
			action:      'query',
			titles:      title,
			prop:        'revisions',
			rvprop:      'content',
			rvslots:     'main',
			formatversion: 2
		} ).then( data => {
			const page = data.query.pages[ 0 ];
			if ( !page || page.missing ) { throw new Error( 'Halaman tidak ditemukan' ); }
			return page.revisions[ 0 ].slots.main.content;
		} );
	}

	function saveEdit( title, newContent, summary ) {
		return api.postWithEditToken( {
			action:  'edit',
			title:   title,
			text:    newContent,
			summary: summary,
			minor:   true
		} );
	}

	/* ── Operasi wikitext ─────────────────────────────────────────── */

	/* Ganti blok lama dengan blok baru — gunakan indexOf (bukan regex)
	   agar aman terhadap karakter spesial di dalam nilai parameter. */
	function replaceBlock( wikitext, oldRaw, newRaw ) {
		const idx = wikitext.indexOf( oldRaw );
		if ( idx === -1 ) { throw new Error( 'Blok lama tidak ditemukan di wikitext terbaru. Mungkin ada edit bersamaan — coba lagi.' ); }
		return wikitext.slice( 0, idx ) + newRaw + wikitext.slice( idx + oldRaw.length );
	}

	/* Hapus blok, bersihkan baris kosong yang tersisa. */
	function deleteBlock( wikitext, oldRaw ) {
		const idx = wikitext.indexOf( oldRaw );
		if ( idx === -1 ) { throw new Error( 'Blok tidak ditemukan.' ); }
		const before = wikitext.slice( 0, idx ).replace( /\n+$/, '\n' );
		return before + wikitext.slice( idx + oldRaw.length );
	}

	/* Sisipkan blok baru sebelum }} penutup {{RaceResultTable. */
	function appendBlock( wikitext, newRaw ) {
		const tableEnd = wikitext.lastIndexOf( '}}' );
		if ( tableEnd === -1 ) { return wikitext + '\n' + newRaw; }
		return wikitext.slice( 0, tableEnd ) + '\n' + newRaw + '\n' + wikitext.slice( tableEnd );
	}

	/* ── Dialog ───────────────────────────────────────────────────── */
	function buildDialog() {
		if ( document.getElementById( 'rre-overlay' ) ) { return; }

		const overlay = document.createElement( 'div' );
		overlay.id = 'rre-overlay';

		const dialog = document.createElement( 'div' );
		dialog.id = 'rre-dialog';
		dialog.setAttribute( 'role', 'dialog' );
		dialog.setAttribute( 'aria-modal', 'true' );
		dialog.setAttribute( 'aria-labelledby', 'rre-dlg-title' );

		/* Header */
		const hdr = document.createElement( 'div' );
		hdr.id = 'rre-dialog-header';
		hdr.innerHTML = '<h2 id="rre-dlg-title">Edit baris Result</h2>';
		const closeBtn = document.createElement( 'button' );
		closeBtn.id = 'rre-close-btn';
		closeBtn.innerHTML = '&times;';
		closeBtn.setAttribute( 'aria-label', 'Tutup dialog' );
		closeBtn.addEventListener( 'click', closeDialog );
		hdr.appendChild( closeBtn );

		/* Form grid */
		const grid = document.createElement( 'div' );
		grid.id = 'rre-form-grid';

		FIELDS.forEach( f => {
			const wrap = document.createElement( 'div' );
			wrap.className = 'rre-field' + ( f.full ? ' full' : '' );

			const lbl = document.createElement( 'label' );
			lbl.setAttribute( 'for', 'rre-f-' + f.id );
			lbl.textContent = f.label;
			wrap.appendChild( lbl );

			let input;
			if ( f.type === 'select' ) {
				input = document.createElement( 'select' );
				( f.options || [] ).forEach( opt => {
					const o = document.createElement( 'option' );
					o.value = opt;
					o.textContent = opt || '— pilih —';
					input.appendChild( o );
				} );
			} else if ( f.type === 'textarea' ) {
				input = document.createElement( 'textarea' );
				input.placeholder = f.placeholder || '';
			} else {
				input = document.createElement( 'input' );
				input.type = 'text';
				input.placeholder = f.placeholder || '';
			}
			input.id = 'rre-f-' + f.id;
			input.addEventListener( 'input', updatePreview );
			input.addEventListener( 'change', updatePreview );
			wrap.appendChild( input );

			if ( f.hint ) {
				const hint = document.createElement( 'span' );
				hint.className = 'rre-hint';
				hint.textContent = f.hint;
				wrap.appendChild( hint );
			}
			grid.appendChild( wrap );
		} );

		/* Wikitext preview */
		const previewWrap = document.createElement( 'div' );
		previewWrap.id = 'rre-wikitext-wrap';
		previewWrap.innerHTML =
			'<div id="rre-wikitext-header">Preview wikitext</div>' +
			'<div id="rre-wikitext-preview"></div>';

		/* Footer */
		const ftr = document.createElement( 'div' );
		ftr.id = 'rre-dialog-footer';

		const cancelBtn = document.createElement( 'button' );
		cancelBtn.className = 'rre-btn-cancel';
		cancelBtn.textContent = 'Batal';
		cancelBtn.addEventListener( 'click', closeDialog );

		const saveBtn = document.createElement( 'button' );
		saveBtn.className = 'rre-btn-save';
		saveBtn.id = 'rre-save-btn';
		saveBtn.textContent = 'Simpan';
		saveBtn.addEventListener( 'click', onSave );

		ftr.appendChild( cancelBtn );
		ftr.appendChild( saveBtn );

		dialog.appendChild( hdr );
		dialog.appendChild( grid );
		dialog.appendChild( previewWrap );
		dialog.appendChild( ftr );
		overlay.appendChild( dialog );
		document.body.appendChild( overlay );

		overlay.addEventListener( 'click', e => {
			if ( e.target === overlay ) { closeDialog(); }
		} );
		document.addEventListener( 'keydown', e => {
			if ( e.key === 'Escape' ) { closeDialog(); }
		} );
	}

	function updatePreview() {
		const preview = document.getElementById( 'rre-wikitext-preview' );
		if ( preview ) { preview.textContent = buildResultBlock( getFormValues() ); }
	}

	function getFormValues() {
		const params = {};
		FIELDS.forEach( f => {
			const el = document.getElementById( 'rre-f-' + f.id );
			params[ f.id ] = el ? el.value : '';
		} );
		return params;
	}

	function openDialog( idx, newRow ) {
		editIndex = idx;
		isNewRow  = !!newRow;
		buildDialog();

		document.getElementById( 'rre-dlg-title' ).textContent =
			isNewRow ? 'Tambah baris Result' : 'Edit baris Result';

		/* Isi form dari params wikitext — bukan dari HTML tabel */
		const params = ( !isNewRow && idx !== null ) ? parsedResults[ idx ].params : {};
		FIELDS.forEach( f => {
			const el = document.getElementById( 'rre-f-' + f.id );
			if ( el ) { el.value = params[ f.id ] || ''; }
		} );

		updatePreview();
		document.getElementById( 'rre-overlay' ).classList.add( 'rre-open' );
		document.getElementById( 'rre-f-date' ).focus();
	}

	function closeDialog() {
		const ov = document.getElementById( 'rre-overlay' );
		if ( ov ) { ov.classList.remove( 'rre-open' ); }
	}

	function onSave() {
		const params = getFormValues();
		if ( !params.date || !params.name ) {
			showToast( 'Date dan Race Name wajib diisi!', true );
			return;
		}

		const saveBtn = document.getElementById( 'rre-save-btn' );
		saveBtn.textContent = 'Menyimpan…';
		saveBtn.disabled    = true;

		const title   = mw.config.get( 'wgPageName' );
		const newRaw  = buildResultBlock( params );
		const summary = 'RaceResult Gadget: ' +
			( isNewRow ? 'tambah' : 'edit' ) + ' baris — ' +
			params.name + ' (' + params.date + ')';

		/* Selalu fetch ulang wikitext terbaru saat menyimpan
		   untuk menghindari konflik edit. */
		fetchWikitext( title ).then( freshWikitext => {
			let updated;
			if ( isNewRow ) {
				updated = appendBlock( freshWikitext, newRaw );
			} else {
				/* rawBlock dari saat halaman dimuat — cocokkan ke wikitext terbaru */
				updated = replaceBlock( freshWikitext, parsedResults[ editIndex ].rawBlock, newRaw );
			}
			return saveEdit( title, updated, summary );
		} ).then( () => {
			closeDialog();
			showToast( 'Tersimpan! Memuat ulang…' );
			setTimeout( () => location.reload(), 1400 );
		} ).catch( err => {
			console.error( '[RRE]', err );
			showToast( 'Gagal menyimpan: ' + ( err.message || String( err ) ), true );
			saveBtn.textContent = 'Simpan';
			saveBtn.disabled    = false;
		} );
	}

	/* ── Inject tombol ke baris tabel ─────────────────────────────── */
	function injectButtons() {
		const tables = document.querySelectorAll( 'table.wikitable' );
		if ( !tables.length ) { return; }

		/*
		 * Strategi pencocokan: urutan baris di tabel HTML == urutan {{Result}}
		 * di wikitext. Baris "season header" dilewati (cells < 5).
		 */
		let rIdx = 0;

		tables.forEach( table => {
			/* Tambah header kolom aksi */
			const thead = table.querySelector( 'thead tr' );
			if ( thead ) {
				const th = document.createElement( 'th' );
				th.style.cssText = 'width:80px';
				thead.appendChild( th );
			}

			table.querySelectorAll( 'tbody tr' ).forEach( tr => {
				const cells = tr.querySelectorAll( 'td' );
				if ( cells.length < 5 ) {
					/* Season header — tambah td kosong agar kolom sejajar */
					const td = document.createElement( 'td' );
					tr.appendChild( td );
					return;
				}
				if ( rIdx >= parsedResults.length ) { return; }

				const currentIdx = rIdx++;

				const actionTd = document.createElement( 'td' );
				actionTd.style.cssText = 'white-space:nowrap; padding:4px 6px;';

				const editBtn = document.createElement( 'button' );
				editBtn.className = 'rre-btn';
				editBtn.innerHTML = '&#9998;&#xFE0E;';
				editBtn.title = 'Edit — ' + ( parsedResults[ currentIdx ].params.name || '' );
				editBtn.addEventListener( 'click', () => openDialog( currentIdx, false ) );

				const delBtn = document.createElement( 'button' );
				delBtn.className = 'rre-btn rre-btn-del';
				delBtn.innerHTML = '&#x1F5D1;&#xFE0E;';
				delBtn.title = 'Hapus baris ini';
				delBtn.addEventListener( 'click', () => onDelete( currentIdx ) );

				actionTd.appendChild( editBtn );
				actionTd.appendChild( delBtn );
				tr.appendChild( actionTd );
			} );
		} );

		/* Tombol Tambah di bawah tabel terakhir */
		const lastTable = tables[ tables.length - 1 ];
		const addBtn    = document.createElement( 'button' );
		addBtn.className = 'rre-btn';
		addBtn.style.cssText = 'margin-top:8px; display:flex; width:100%; justify-content:center; padding:6px;';
		addBtn.textContent   = '+ Tambah baris Result';
		addBtn.addEventListener( 'click', () => openDialog( null, true ) );
		lastTable.insertAdjacentElement( 'afterend', addBtn );
	}

	function onDelete( idx ) {
		const p = parsedResults[ idx ].params;
		if ( !confirm( 'Hapus baris "' + p.name + '" (' + p.date + ')?' ) ) { return; }

		const title = mw.config.get( 'wgPageName' );
		fetchWikitext( title ).then( freshWikitext => {
			const updated = deleteBlock( freshWikitext, parsedResults[ idx ].rawBlock );
			return saveEdit( title, updated, 'RaceResult Gadget: hapus baris — ' + p.name );
		} ).then( () => {
			showToast( 'Baris dihapus! Memuat ulang…' );
			setTimeout( () => location.reload(), 1400 );
		} ).catch( err => {
			showToast( 'Gagal hapus: ' + ( err.message || String( err ) ), true );
		} );
	}

	/* ── Init ─────────────────────────────────────────────────────── */
	mw.hook( 'wikipage.content' ).add( function () {
		const firstTable = document.querySelector( 'table.wikitable' );
		if ( !firstTable ) { return; }

		/* Indikator loading */
		const loadingEl = document.createElement( 'div' );
		loadingEl.id = 'rre-loading';
		loadingEl.innerHTML = '<span class="rre-spinner"></span> Memuat parameter dari wikitext…';
		firstTable.insertAdjacentElement( 'beforebegin', loadingEl );
		loadingEl.classList.add( 'rre-open' );

		fetchWikitext( mw.config.get( 'wgPageName' ) ).then( wikitext => {
			parsedResults = parseAllResults( wikitext );
			loadingEl.classList.remove( 'rre-open' );

			if ( parsedResults.length === 0 ) {
				console.info( '[RRE] Tidak ada {{Result}} ditemukan.' );
				return;
			}
			injectButtons();
		} ).catch( err => {
			loadingEl.innerHTML = '⚠ Gagal memuat wikitext: ' + err;
			console.error( '[RRE]', err );
		} );
	} );

}( mediaWiki, jQuery ) );

/**
 * RaceRecordEditor.js
