    // =========================================================

    async function fetchPageSource() {

        const data = await api.get({
            action: 'query',
            prop: 'revisions',
            titles: mw.config.get('wgPageName'),
            rvprop: 'content',
            formatversion: 2
        });

        return data.query.pages[0].revisions[0].content;
    }

    // =========================================================
    // PARSE TEMPLATE {{Result}}
    // =========================================================

    function extractResultTemplates(text) {

        const results = [];

        let regex = /\{\{Result\|([\s\S]*?)\}\}/g;
        let match;

        while ((match = regex.exec(text)) !== null) {

            const fullTemplate = match[0];
            const inner = match[1];

            const params = {};

            inner.split('|').forEach(part => {

                const eq = part.indexOf('=');

                if (eq === -1) return;

                const key = part.slice(0, eq).trim();
                const value = part.slice(eq + 1).trim();

                params[key] = value;

            });

            results.push({
                full: fullTemplate,
                params: params
            });
        }

        return results;
    }

    // =========================================================
    // BUAT ULANG TEMPLATE
    // =========================================================

    function buildTemplate(params) {

        return `{{Result
|date=${params.date || ''}
