            }),

            source: new OO.ui.MultilineTextInputWidget({
                value: result.params.source || '',
                rows: 6
            })

        };

        // ---------------------------------------------
        // PANEL
        // ---------------------------------------------

        const panel = new OO.ui.PanelLayout({
            padded: true,
            expanded: false
        });

        const fieldset = new OO.ui.FieldsetLayout();

        function addField(label, widget) {

            fieldset.addItems([
                new OO.ui.FieldLayout(widget, {
                    label: label,
                    align: 'top'
                })
            ]);
        }

        addField('Date', fields.date);
        addField('Racecourse', fields.racecourse);
        addField('Entry', fields.entry);
        addField('Number', fields.number);
        addField('Jockey', fields.jockey);
        addField('Name', fields.name);
        addField('Class', fields.class);
        addField('Finished', fields.finished);
        addField('Distance', fields.distance);
        addField('Winner', fields.winner);
        addField('Time', fields.time);
        addField('Source', fields.source);

        panel.$element.append(fieldset.$element);

        // ---------------------------------------------
        // WINDOW CLASS
        // ---------------------------------------------

        function MyDialog(config) {
            MyDialog.super.call(this, config);
        }

        OO.inheritClass(MyDialog, OO.ui.ProcessDialog);

        MyDialog.static.name = 'raceResultEditor';

        MyDialog.static.title = 'Edit Race Result';

        MyDialog.static.actions = [
            {
                action: 'save',
                label: 'Save',
                flags: ['primary', 'progressive']
            },
            {
                action: 'cancel',
                label: 'Cancel',
                flags: 'safe'
            }
        ];

        MyDialog.prototype.initialize = function () {

            MyDialog.super.prototype.initialize.apply(this, arguments);

            this.content = panel;

            this.$body.append(this.content.$element);

        };

        MyDialog.prototype.getActionProcess = function (action) {

            const dialog = this;

            if (action === 'save') {

                return new OO.ui.Process(async function () {

                    const updated = {

                        date: fields.date.getValue(),
                        racecourse: fields.racecourse.getValue(),
                        entry: fields.entry.getValue(),
                        number: fields.number.getValue(),
                        jockey: fields.jockey.getValue(),
                        name: fields.name.getValue(),
                        class: fields.class.getValue(),
                        finished: fields.finished.getValue(),
                        distance: fields.distance.getValue(),
                        winner: fields.winner.getValue(),
                        time: fields.time.getValue(),
                        source: fields.source.getValue()

                    };

                    const newTemplate = buildTemplate(updated);

                    // replace template lama
                    pageSource = pageSource.replace(
                        result.full,
                        newTemplate
                    );

                    // save ke wiki
                    await api.postWithToken('csrf', {
                        action: 'edit',
                        title: mw.config.get('wgPageName'),
                        text: pageSource,
                        summary: 'Edit race result via gadget'
                    });

                    mw.notify('Race result saved!');

                    dialog.close();

                    location.reload();

                });

            }

            return MyDialog.super.prototype.getActionProcess.call(this, action);

        };

        // ---------------------------------------------
        // OPEN WINDOW
        // ---------------------------------------------

        const windowManager = new OO.ui.WindowManager();

        $('body').append(windowManager.$element);

        const dialog = new MyDialog({
            size: 'large'
        });

        windowManager.addWindows([dialog]);

        windowManager.openWindow(dialog);

    }

    // =========================================================
    // INIT
    // =========================================================

    async function init() {

        try {

            pageSource = await fetchPageSource();

            parsedResults = extractResultTemplates(pageSource);

            addEditButtons();

            console.log(parsedResults);

        } catch (err) {

            console.error(err);

            mw.notify('RaceRecordEditor failed.');

        }
    }

    $(init);

})();

/**
 * RaceRecordEditor.js
 * Gadget untuk edit template {{Result}} via dialog OOUI
 *
 * REQUIREMENTS:
 * - MediaWiki
 * - OOUI
 *
 * Letakkan di:
 * MediaWiki:Gadget-RaceRecordEditor.js
 */

( function () {

    'use strict';

    // =========================================================
    // CONFIG
    // =========================================================

    const TEMPLATE_NAME = 'Result';

    // =========================================================
    // API
    // =========================================================

    const api = new mw.Api();

    // =========================================================
    // MAIN
    // =========================================================

    $( init );

    async function init() {

        // hanya aktif jika ada wikitable
        if ( !$( '.wikitable' ).length ) {
            return;
        }

        // ambil source halaman
        const pageText = await getPageText();

        if ( !pageText.includes( '{{RaceResultTable' ) ) {
            return;
        }

        // parse semua Result
        const results = parseResultTemplates( pageText );

        // inject tombol edit
        injectButtons( results, pageText );
    }

    // =========================================================
    // GET PAGE TEXT
    // =========================================================

    async function getPageText() {

        const data = await api.get( {
            action: 'query',
            prop: 'revisions',
            titles: mw.config.get( 'wgPageName' ),
            rvprop: 'content',
            formatversion: 2
        } );

        return data.query.pages[0].revisions[0].content;
    }

    // =========================================================
    // PARSER
    // =========================================================

    function parseResultTemplates( text ) {

        const results = [];

        const regex = /\{\{Result\|([\s\S]*?)\}\}/g;

        let match;

        while ( ( match = regex.exec( text ) ) !== null ) {

            const fullTemplate = match[0];
            const inner = match[1];

            const params = parseParams( inner );

            results.push( {
                full: fullTemplate,
                params: params,
                start: match.index,
                end: regex.lastIndex
            } );
        }

        return results;
    }

    function parseParams( text ) {

        const params = {};

        text.split( '|' ).forEach( part => {

            const eq = part.indexOf( '=' );

            if ( eq === -1 ) {
                return;
            }

            const key = part.slice( 0, eq ).trim();

            const value = part.slice( eq + 1 ).trim();

            params[ key ] = value;
        } );

        return params;
    }

    // =========================================================
    // BUTTONS
    // =========================================================

    function injectButtons( results, pageText ) {

        const rows = $( '.wikitable tr' );

        let resultIndex = 0;

        rows.each( function () {

            const tdCount = $( this ).find( 'td' ).length;

            if ( tdCount === 0 ) {
                return;
            }

            // skip season rows
            if ( $( this ).text().includes( 'season' ) ) {
                return;
            }

            if ( !results[ resultIndex ] ) {
                return;
            }

            const buttonCell = $( '<td>' )
                .css( {
                    width: '40px',
                    textAlign: 'center'
                } );

            const editBtn = new OO.ui.ButtonWidget( {
                label: '✎',
                framed: true
            } );

            editBtn.on( 'click', function () {

                openEditorDialog(
                    results,
                    resultIndex,
                    pageText
                );
            } );

            buttonCell.append(
                editBtn.$element
            );

            $( this ).append( buttonCell );

            resultIndex++;
        } );
    }

    // =========================================================
    // DIALOG
    // =========================================================

    function openEditorDialog( results, index, pageText ) {

        const data = results[ index ].params;

        class ResultDialog extends OO.ui.ProcessDialog {

            initialize() {

                super.initialize();

                this.panel = new OO.ui.PanelLayout( {
                    padded: true,
                    expanded: false
                } );

                this.fields = {};

                const fieldDefs = [
                    [ 'date', 'Date' ],
                    [ 'racecourse', 'Racecourse' ],
                    [ 'entry', 'Entry' ],
                    [ 'number', 'Horse Number' ],
                    [ 'jockey', 'Jockey' ],
                    [ 'name', 'Race Name' ],
                    [ 'class', 'Class' ],
                    [ 'finished', 'Finished' ],
                    [ 'distance', 'Distance' ],
                    [ 'winner', 'Winner' ],
                    [ 'time', 'Time' ]
                ];

                fieldDefs.forEach( ( item ) => {

                    const key = item[0];
                    const label = item[1];

                    this.fields[ key ] = new OO.ui.TextInputWidget( {
                        value: data[ key ] || ''
                    } );

                    const fieldLayout = new OO.ui.FieldLayout(
                        this.fields[ key ],
                        {
                            label: label,
                            align: 'top'
                        }
                    );

                    this.panel.$element.append(
                        fieldLayout.$element
                    );
                } );

                // SOURCE textarea
                this.fields.source =
                    new OO.ui.MultilineTextInputWidget( {
                        value: data.source || '',
                        rows: 5
                    } );

                const sourceLayout =
                    new OO.ui.FieldLayout(
                        this.fields.source,
                        {
                            label: 'Source',
                            align: 'top'
                        }
                    );

                this.panel.$element.append(
                    sourceLayout.$element
                );

                this.$body.append(
                    this.panel.$element
                );
            }

            getActionProcess( action ) {

                if ( action === 'save' ) {

                    return new OO.ui.Process( async () => {

                        const newParams = {};

                        Object.keys( this.fields ).forEach( ( key ) => {

                            newParams[ key ] =
                                this.fields[ key ].getValue();
                        } );

                        const newTemplate =
                            buildTemplate( newParams );

                        const oldTemplate =
                            results[ index ].full;

                        const newText =
                            pageText.replace(
                                oldTemplate,
                                newTemplate
                            );

                        await savePage( newText );

                        mw.notify(
                            'Race result saved!'
                        );

                        location.reload();
                    } );
                }

                return super.getActionProcess( action );
            }

            getBodyHeight() {
                return 600;
            }
        }

        ResultDialog.static.name = 'ResultDialog';

        ResultDialog.static.title =
            'Edit Race Result';

        ResultDialog.static.actions = [
            {
                action: 'save',
                label: 'Save',
                flags: [ 'primary', 'progressive' ]
            },
            {
                action: 'cancel',
                label: 'Cancel',
                flags: 'safe'
            }
        ];

        const windowManager =
            new OO.ui.WindowManager();

        $( 'body' ).append(
            windowManager.$element
        );

        const dialog = new ResultDialog();

        windowManager.addWindows( [ dialog ] );

        windowManager.openWindow( dialog );
    }

    // =========================================================
    // BUILD TEMPLATE
    // =========================================================

    function buildTemplate( params ) {

        return `{{Result
|date=${ params.date || '' }
|racecourse=${ params.racecourse || '' }
|entry=${ params.entry || '' }
|number=${ params.number || '' }
|jockey=${ params.jockey || '' }
|name=${ params.name || '' }
|class=${ params.class || '' }
|finished=${ params.finished || '' }
|distance=${ params.distance || '' }
|winner=${ params.winner || '' }
|time=${ params.time || '' }
|source=${ params.source || '' }
}}`;
    }

    // =========================================================
    // SAVE
    // =========================================================

    async function savePage( text ) {

        return api.postWithToken( 'csrf', {

            action: 'edit',

            title: mw.config.get(
                'wgPageName'
            ),

            text: text,

            summary:
                'Edit race result via RaceRecordEditor gadget'
        } );
    }

} )();

