/**
 * R.I.P 🐸 (1926-2022)
 * 
 * 一键续秒工具
 * 
 * 原脚本写于2017年，再次发现这个脚本时，长者早已驾鹤西去
 * 
 * 操作方法：
 * 1. 在自己的common.js（[[Special:MyPage/common.js]]）最后一行加入以下代码并保存：
 *    mw.loader.load('https://zh.wikipedia.org/wiki/User:逆襲のあまのじゃく/js/+1s.js?action=raw&ctype=text/javascript');
 * 2. 保存成功后，页面右侧会显示“+1s模式”选框，点击开启。
 * 3. 开启+1s模式后，页面上各种用户名旁边会出现红色的+1s。点击之后即可把他们的1s捐给长者！
 * 
 * 特别安全说明：
 * 默认情况下，该脚本不会产生实际的动作，因此不会对他人造成实际影响。
 *
 * 如果您仍然希望动用管理员权限真正地续秒（将他人封禁1秒），您可以在common.js后面继续增加以下代码，人工开启封禁模式：
 * window.isRealPlus1s = true;
 *
 * 开启封禁模式后，点击续秒之前会弹出警告框，如果不希望看到警告框，再增加：
 * window.isPlus1sIgnoresWarning = true;
 *
 * 注意，请谨慎使用管理员权限操作！
 * 如果您只是想玩管理员权限，可在publictestwiki.com注册账号并在注册满10天后申请权限。
 * 
 * 参见：[[膜蛤文化]]
 */

// <pre>
mw.loader.using(['oojs-ui-core', 'oojs-ui-widgets', 'oojs-ui-windows']).then(function (require) {
    'use strict';
    var isIgnoreWarning = function () {
        return !!window.isPlus1sIgnoresWarning;
    };
    var isRealBlockMode = function () {
        return !!window.isRealPlus1s;
    };
    var getTimeList = function () {
        var timeList = localStorage.getItem('+1sList')
        if (timeList) {
            return JSON.parse(timeList);
        } else {
            return {};
        }
    }

    // 

    var SUMMARY = '天若有情天亦老，[[w:zh:User:逆襲のあまのじゃく/js/+1s.js|我为长者续一秒]] (Test block)';

    mw.loader.addStyleTag('a.donate1second { color: red; } a.donating1second { color: grey; }');

    var block = function (username) {
        var isReal =
            isRealBlockMode() && (
                isIgnoreWarning()
                || window.confirm('是否要利用管理员权限把' + username + '的秒续给长者？')
            )
        if (mw.config.get('wgUserGroups').indexOf('sysop') === -1) {
            isReal = false;
        }
        if (isReal) {
            return $.ajax({
                url: mw.util.wikiScript('api'),
                data: {
                    format: 'json',
                    action: 'block',
                    user: username,
                    expiry: '1 second',
                    reason: SUMMARY,
                    allowusertalk: '',
                    token: mw.user.tokens.get('csrfToken'),
                },
                dataType: 'json',
                type: 'POST',
            });
        } else {
            return Promise.resolve({
                block: {
                    user: username
                }
            })
        }
    };

    var startHaMode = function () {
        var getUserName = function (item) {
            var title = item.getAttribute('title');

            if (title.indexOf('User:') == 0 && title.indexOf('/') > -1) {
                return null;
            }

            // deal with markblocked
            var len = 5;
            if (title.indexOf('User:') == 0) {
                len = 5;
            } else if (title.indexOf('Special:Contributions') == 0) {
                len = 22;
            }

            if (title.indexOf(';') > -1) {
                return title.substr(len, title.indexOf(';') - len);
            } else if (title.indexOf('；') > -1) {
                return title.substr(len, title.indexOf('；') - len);
            } else {
                return title.substr(len);
            }
        };

        var donate1second = function (e) {
            e.preventDefault();
            var username = this.getAttribute('data-username');
            var that = this;

            if (that.className.indexOf('donating1second') !== -1) {
                return;
            }

            that.classList.add('donating1second');

            block(username).then(function (data) {
                if (data.error) {
                    mw.notify("未能把" + username + "的1秒续给长者，因为：" + data.error.info);
                } else {
                    mw.notify("已将" + username + "的1秒续给长者");

                    var timeList = getTimeList();
                    timeList[username] = (timeList[username] || 0) + 1;
                    localStorage.setItem('+1sList', JSON.stringify(timeList));
                }
            }).catch(function () {
                mw.notify("因网络错误而未能把" + username + "的1秒续给长者");
            // }).finally(function () {
            //     that.classList.remove('donating1second');
            });
        };

        const addLinks = function (index, item) {
            var username = getUserName(item);
            if (username) {
                var x = $('<a href="#" class="donate1second"><sup>+1s</sup></a>')
                    .attr('data-username', username)
                    .click(donate1second);
                $(item).after(x);
            }
        };
        $('a[title^="User:"]', '#mw-content-text').each(addLinks);
        $('a.mw-tempuserlink[title^="Special:Contributions/"]', '#mw-content-text').each(addLinks);
        $('a.mw-anonuserlink[title^="Special:Contributions/"]', '#mw-content-text').each(addLinks);
    };

    var isHaMode = function () { return localStorage['+1s'] !== undefined && localStorage['+1s'] !== 'false'; };
    var label = function () { return isHaMode() ? '[√] +1s模式' : '[　] +1s模式'; };

    var node = mw.util.addPortletLink('p-cactions', '#', label());
    $(node).click(function (e) {
        e.preventDefault();
        localStorage['+1s'] = !isHaMode();
        $('a', this).text(label());

        if (isHaMode()) {
            if ($('.donate1second').length === 0) {
                startHaMode();
            }
        } else {
            $('.donate1second').remove();
        }
    });

    var node2 = mw.util.addPortletLink('p-cactions', '#', '+1s排行榜');
    $(node2).click(function (e) {
        e.preventDefault();

        var timeList = getTimeList();
        var items = [];
        for (var key in timeList) {
            items.push({
                username: key,
                time: timeList[key],
            });
        }
        items.sort(function (a, b) { return b.time - a.time; });

        var $container = $('<div>').append($('<strong>').text('续秒排行榜'));

        var $table = $('<table>')
            .addClass('wikitable')
            .css({
                'width': '100%',
                'min-width': '400px',
                'margin-top': '10px'
            });

        var $thead = $('<thead>').append(
            $('<tr>').append(
                $('<th>').text('排名').css('width', '15%'),
                $('<th>').text('用户'),
                $('<th>').text('时间').css('width', '25%')
            )
        );
        $table.append($thead);

        var $tbody = $('<tbody>');
        items.forEach(function (item, index) {
            var userPageUrl = mw.util.getUrl('User:' + item.username);
            var userTalkUrl = mw.util.getUrl('User talk:' + item.username);
            var userContribsUrl = mw.util.getUrl('Special:Contributions/' + item.username);
            var $tr = $('<tr>').append(
                $('<td>').text(index + 1).css('text-align', 'center'),
                $('<td>').append(
                    $('<a>').attr({ href: userPageUrl, target: '_blank' }).text(item.username),
                    '（',
                    $('<a>').attr({ href: userTalkUrl, target: '_blank' }).text('留言'),
                    '·',
                    $('<a>').attr({ href: userContribsUrl, target: '_blank' }).text('编辑记录'),
                    '）'
                ),
                $('<td>').text(item.time + '秒').css('text-align', 'right')
            );
            $tbody.append($tr);
        });
        $table.append($tbody);
        var $html = $container.append($table);

        OO.ui.alert($html, {
            size: 'medium'
        });
    });

    if (isHaMode()) {
        startHaMode();
    }
});
