document.querySelectorAll('.mw-dev-slider').forEach(function(container) {

	const label = container.dataset.label || "Setting";
	const unit = container.dataset.unit || "";
	const min = parseFloat(container.dataset.min);
	const max = parseFloat(container.dataset.max);
	const step = parseFloat(container.dataset.step);
	const value = parseFloat(container.dataset.value);
	const center = parseFloat(container.dataset.center);

	const options = container.dataset.options
		? container.dataset.options.split(',').map(Number)
		: null;

	// Create header
	const header = document.createElement('h4');

	const valueSpan = document.createElement('span');
	valueSpan.className = "mw-dev-value";

	header.textContent = label + " - ";
	header.appendChild(valueSpan);

	// Create slider
	const slider = document.createElement('input');

	slider.type = "range";
	slider.min = min;
	slider.max = max;
	slider.step = step;
	slider.value = value;

	container.prepend(slider);
	container.prepend(header);
	const result = document.getElementById('result');

	// Existing output elements from page
	const ttime = document.getElementById('ttime');
	const stemp = document.getElementById('steamtemp');

	function update() {
		let val = parseFloat(slider.value);

		// Snap to options
		if (options) {
			let closest = options.reduce(function(a, b) {
				return Math.abs(b - val) < Math.abs(a - val)
					? b
					: a;
			});
			val = closest;
			slider.value = closest;
		}
		container.dataset.value = val;
		valueSpan.textContent = val + unit;

		// Slider color
		const dist = val - center;

		let color;

		if (Math.abs(dist) < 0.01) {

			color = "var(--gray1)";

		} else if (dist > 0) {

			const factor = Math.min(
				dist / (max - center),
				1
			);

			color =
				`color-mix(in oklch,
				var(--gray1) ${(1-factor)*100}%,
				var(--green1) ${factor*100}%)`;

		} else {

			const factor = Math.min(
				-dist / (center - min),
				1
			);

			color =
				`color-mix(in oklch,
				var(--gray1) ${(1-factor)*100}%,
				var(--red1) ${factor*100}%)`;
		}

		slider.style.background = color;
	// calculation
    let val2 = parseFloat(slider.value);
    let calc = 40 / ((val2 / 100) + 1);
    let blablabla = parseFloat(calc.toFixed(2)) + " seconds";

	if (ttime) {
		ttime.textContent =
			blablabla;
	}

	if (stemp) {
		stemp.textContent = val2 + "°C";
	}

    result.textContent = blablabla;
	}

	slider.addEventListener('input', update);

	update();

});

