    border-radius: 8px 8px 0 0;
}

.overlay.search-overlay .overlay-header-container > .overlay-header {
    display: block;
    height: auto;
    padding: 0.45em 0;
    border: none;
}

.overlay.search-overlay .overlay-header-container > .overlay-header::before {
    display: inline-block;
    content: "Search";
    color: #fff;
    font-family: UmaRodin, Roboto, sans-serif;
    width: 100%;
    text-align: center;
}

.overlay.search-overlay .overlay-header-container > .overlay-header > .search-header-view {
    position: absolute;
    top: 2.75em;
    left: 0;
    width: 100%;
    padding: 0 8px;
    box-sizing: border-box;
}

.overlay.search-overlay .search-box {
    margin-left: 0;
    width: 100%;
}

.overlay.search-overlay .search-box::before {
    width: 1rem;
    height: 1rem;
    min-width: 0;
    min-height: 0;
    -webkit-mask-size: contain;
    mask-size: contain;
    left: 9px;
    top: 8px;
}

.overlay.search-overlay .search-box .search {
    font-size: 0.9rem;
    border-radius: 100vh;
    border: 1px solid #c9c4da;
}

.overlay.search-overlay .overlay-header-container > .overlay-header > .header-action {
    position: absolute;
    left: 0;
    bottom: 16px;
    width: 100%;
    display: flex;
    justify-content: center;
}

.overlay.search-overlay .overlay-header-container > .overlay-header > .header-action > .cdx-button {
    max-width: none;
    width: 150px;
    height: 32px;
    color: #68401c;
    font-family: UmaRodin, Roboto, sans-serif;
    padding: 0;
    display: block;
}

.overlay.search-overlay .overlay-header-container > .overlay-header > .header-action > .cdx-button > .mf-icon {
    display: none;
}

.overlay.search-overlay .overlay-header-container > .overlay-header > .header-action > .cdx-button span + span {
    clip: unset;
    width: 100%;
    height: 100%;
    margin: 0;
    flex-grow: 1;
    position: static !important;
    text-align: center;
    vertical-align: middle;
    background-image: linear-gradient(190deg, transparent 50%, rgba(98, 93, 116, 0.2));
}

/* cheating vertical-align */
.overlay.search-overlay .overlay-header-container > .overlay-header > .header-action > .cdx-button span + span::after{
    content: '';
    display: inline-block;
    width: 0px;
    height: 100%;
    vertical-align: middle;
}

.overlay.search-overlay > .overlay-content {
    background-color: #f1f1f1;
    margin: 3em 4px 76px 4px;
    width: calc(100% - 8px);
    box-sizing: border-box;
    border-radius: 6px;
    padding: 0;
    height: 100%;
    overflow: auto;
}

.overlay.search-overlay > .overlay-content > .search-results-view,
.overlay.search-overlay > .overlay-content .search-content,
.overlay.search-overlay > .overlay-content .results {
    margin: 0;
    width: 100%;
}

.overlay.search-overlay > .overlay-content .search-content {
    padding: 0 !important;
    margin-top: 8px;
    background: none;
    border: none;
    width: calc(100% - 16px);
    box-sizing: border-box;
}

.overlay.search-overlay > .overlay-content .search-content .caption {
    padding: 10px 16px 10px 12px;
}

.overlay.search-overlay > .overlay-content .search-content,
.overlay.search-overlay li.page-summary {
    background-color: #fff;
    border: 1px solid #dedede;
    border-radius: 6px;
    box-shadow: rgba(114, 114, 114, 0.52) 0px 2px;
    margin-bottom: 10px;
    margin-left: 8px;
    margin-right: 8px;
}

.overlay.search-overlay > .overlay-content .results {
    background: none;
    box-shadow: none;
}

.overlay.search-overlay > .overlay-content .search-content > .mf-icon {
    margin: 0 26px;
}

.mw-body-content .mw-parser-output .mainbox h3 {
    display: block;
    background-color: #93d908;
    background-image: linear-gradient(#93d908, #6fc41a);
    color: #fff;
    font-size: 1.05rem;
    padding: 8px 5px;
}

.mw-body-content .mw-parser-output .mainbox {
    background-color: #fff;
}

.mw-parser-output .umabox {
	border: 1px solid #625d74 !important;
    border-radius: 8px !important;
    box-shadow: 0 2.5px 0 rgba(98, 93, 116, 0.5);
}

.mw-parser-output .umabox:before {
	content: unset !important;
}

.mw-parser-output .umabox .img {
	border-radius: 6px;
	margin: 4px;
}

.mw-parser-output .umabox h4 {
	display: block !important;
	font-size: 1.3em !important;
	padding: 0 0 0.5em 0 !important;
}


/* Responsive */

@media (min-width: 640px) {
    .infobox {
        margin: 0.5em 0 1em 35px !important;
        max-width: 320px !important;
        width: auto !important;
        float: right !important;
        clear: right !important;
    }

    .infobox > tbody {
        max-width: 320px !important;
    }
}

@media (max-width: 640px) {
    .pre-content.heading-holder > .page-heading {
        position: relative;
        left: -16px;
        width: calc(100% + 32px);
    }
}

@media (max-width: 450px) {
    .page-actions-menu .cdx-button {
        min-width: 0;
        min-height: 0;
        padding: 7px;
        margin-right: 4px;
    }

    .minerva-header > .branding-box > a > span {
    	background-image: url(https://umamusu.wiki/w/images/5/5c/Minerva_Branding_Vertical.svg);
        width: 8em;
    }

    #p-associated-pages {
	    max-width: 120px;
	}
}

@media (max-width: 370px) {
    .page-actions-menu .cdx-button {
        padding: 11px;
        margin-right: 0;
    }

    .page-actions-menu {
        float: unset;
        margin: 4px 0 0;
    }

    .page-actions-menu__list {
        justify-content: space-between;
    }

    .minerva-header > .branding-box > a {
        background: none;
    }

    .minerva-header > .branding-box > a > span {
        margin-left: 0;
    }

    #p-associated-pages {
	    max-width: none;
	}
}


/* Font size scaling constraints */

@media (min-width: 510px) {
    .banner-container {
        font-size: 0.7rem;
    }
}

@media (min-width: 1119px) {
    .mw-body .firstHeading {
        font-size: 3rem;
    }
}


/* Animations */

@keyframes dialogOpen {
    0% {
        clip-path: circle(0% at 100% 100%);
        transform: translate(-50%, -50%) scale(0.7);
        opacity: 0;
    }
    100% {
        clip-path: circle(150% at 100% 100%);
        transform: translate(-50%, -50%) scale(1);
        opacity: 1;
    }
}

