        submitSelector: null,
        diffSelector: null,
        previewSelector: null
      })

      this._loading = false
      this._selectionStart = 0
      this._selectionEnd = 0
      this._text = null
      this._summary = ''
      this._minorEdit = false
    }

    get mode() {
      return 'view'
    }

    get text() {
      return this._text
    }

    set text(t) {
      this._text = t
    }

    get summary() {
      return this._summary
    }

    set summary(s) {
      this._summary = s
    }

    get minorEdit() {
      return this._minorEdit
    }

    set minorEdit(v) {
      this._minorEdit = v
    }

    async submit() {
      this._submitForm('wpSave')
      return true
    }

    async showDiff() {
      this._submitForm('wpDiff')
      return true
    }

    async showPreview() {
      this._submitForm('wpPreview')
      return true
    }

    get selectionText() {
      let selStart = this._selectionStart, selEnd = this._selectionEnd
      if (selStart > selEnd) {
        [selStart, selEnd] = [selEnd, selStart]
      }
      return (this._text || '').substring(selStart, selEnd)
    }

    set selectionText(text) {
      let selStart = this._selectionStart, selEnd = this._selectionEnd
      if (selStart > selEnd) {
        [selStart, selEnd] = [selEnd, selStart]
      }
      this._text = (this._text || '').substring(0, selStart) + text + (this._text || '').substring(selEnd)
      this._selectionStart = selStart
      this._selectionEnd = selStart + text.length
    }

    setSelectionRange(start, end) {
      const textLen = (this._text || '').length
      start = clampIndex(start, textLen)
      end = clampIndex(end, textLen)
      if (start > end) {
        [start, end] = [end, start]
      }
      this._selectionStart = start
      this._selectionEnd = end
    }

    getSelectionRange() {
      return [this._selectionStart, this._selectionEnd]
    }

    get readonly() {
      return false
    }

    // 直接在頁面上提交。頁面名稱為目前頁面。
    _submitForm(action) {
      $('<form method="post" style="display:none;">')
        .attr('action', mw.util.getUrl(mw.config.get('wgPageName'), { action: 'submit' }))
        .attr('enctype', 'multipart/form-data')
        .append($('<textarea name="wpTextbox1">').val(this._text || ''),
          $('<input name="wpSummary">').val(this._summary || ''),
          '<input name="wpMinoredit" type="checkbox" value="1"' + (this._minorEdit ? ' checked="checked"' : '') + '>',
          '<input name="format" value="text/x-wiki">',
          '<input name="wpAutoSummary" value="hashhashhashhash">',    // 防止「未填寫摘要」的提示
          '<input name="model" value="wikitext">',
          '<input name="wpEditToken" value="' + mw.user.tokens.get('csrfToken') + '">',
          '<input name="wpUltimateParam" value="1">',
          '<input name="' + (action || 'wpSave') + '" type="hidden" value="1">',
          '<input name="mode" value="text">',
          '<input type="hidden" value="ℳ𝒲♥𝓊𝓃𝒾𝒸ℴ𝒹ℯ" name="wpUnicodeCheck">')
        .appendTo('body').submit()
    }

    async load() {
      this._loading = true
      let result = null

      try {
        const api = new mw.Api()
        const data = await api.get({
          action: 'query',
          prop: 'revisions',
          titles: mw.config.get('wgPageName'),
          rvprop: 'content',
          rvlimit: 1,
          formatversion: 2
        })

        if (data?.query?.pages?.[0]?.revisions?.[0]) {
          const content = data.query.pages[0].revisions[0].content
          this._text = content
          result = content
        } else {
          // 可能是空页面，或已删除，因此允许用户继续编辑
          this._text = ''
          result = null
        }
      } finally {
        this._loading = false
      }
      return result
    }
  }

  // 1.8 - VisualEditor与2017编辑器
  class VisualEditorApi extends BaseApi {
    constructor({
      textboxSelector = null,
      summarySelector = null,
      minorEditSelector = null,
      submitSelector = null,
      diffSelector = null,
      previewSelector = null,
      hasSaveDialog = false
    } = {}) {
      super({
        textboxSelector,
        summarySelector,
        minorEditSelector,
        submitSelector,
        diffSelector,
        previewSelector
      })
      this._pendingSummary = null
      this._pendingMinoredit = null

      this._cachedVeWikiText = null
      this._pendingVeWikiText = null
      this._syncTimer = null
      this._isSyncing = false
      this._isProgrammaticChange = false

      if (this._surface.getMode() === 'visual') {
        this.syncWikiText()
      }

      // 如果用户手工修改了编辑器，则置cachedVeWikiText为null，并等用户停笔后自动更新维基代码
      this._surfaceModel.connect(this, { 'documentUpdate': () => this._onDocumentUpdate() })

      // 监视对话框
      if (hasSaveDialog) {
        mw.hook('ve.saveDialog.stateChanged').add(() => {
          const dialog = ve.init.target.saveDialog

          if (!dialog) {
            return
          }
          if (this._pendingSummary !== null) {
            dialog.setEditSummary(this._pendingSummary || '')
            this._pendingSummary = null
          }
          if (this._pendingMinoredit !== null) {
            dialog.checkboxesByName.wpMinoredit.setSelected(!!this._pendingMinoredit)
            this._pendingMinoredit = null
          }
        })
      }
    }

    get mode() {
      if (this._surface.getMode() === 'visual') {
        return 'visual'
      } else {
        return 'wikitext2017'
      }
    }

    get text() {
      if (this._surface.getMode() === 'visual') {
        // VE模式下，由于维基代码是调服务器异步解析的，因此返回缓存值
        if (this._pendingVeWikiText !== null) {
          return this._pendingVeWikiText
        }
        return this._cachedVeWikiText
      }
      var data = this._surfaceModel.documentModel.data
      if (data && data.data) {
        return this._dataNodeToSource(data.data)
      } else {
        return ''
      }
    }

    set text(text) {
      if (this._surface.getMode() === 'visual') {
        this._pendingVeWikiText = text
        this._cachedVeWikiText = text

        this._autoSyncWikitext(1000)
      } else {
        const docModel = this._surfaceModel.documentModel;
        const tx1 = ve.dm.TransactionBuilder.static.newFromRemoval(
          docModel,
          new ve.Range(0, docModel.getLength())
        );
        this._surfaceModel.change(tx1)

        const tx2 = ve.dm.TransactionBuilder.static.newFromInsertion(
          docModel,
          1,
          text
        );
        this._surfaceModel.change(tx2)
      }
    }

    async syncWikiText() {
      if (!ve.init.target.surface) {
        return Promise.resolve(this.text)
      }
      if (this._surface.getMode() !== 'visual' || this._isSyncing) {
        return Promise.resolve(this.text)
      }
      this._isSyncing = true

      try {
        let resultText = ''

        if (this._pendingVeWikiText !== null) {
          // 写回逻辑：Wikitext -> VE
          const textToPush = this._pendingVeWikiText
          const data = await ve.init.target.parseWikitextFragment(textToPush)
          const html = data.visualeditor.content
          const newDoc = ve.createDocumentFromHtml(html)
          const newDocModel = ve.dm.converter.getModelFromDom(newDoc, this._surfaceModel.getDocument())
          const docModel = this._surfaceModel.documentModel
          const entireRange = new ve.Range(0, docModel.getLength())

          this._isProgrammaticChange = true
          try {
            this._surfaceModel.getLinearFragment(entireRange).insertDocument(newDocModel)
            this._surfaceModel.setNullSelection()
          } finally {
            this._isProgrammaticChange = false
          }

          this._pendingVeWikiText = null
          this._cachedVeWikiText = textToPush
          resultText = textToPush
        } else {
          // 读取逻辑：VE -> Wikitext
          const api = new mw.Api()
          const data = await api.postWithToken('csrf', {
            action: 'visualeditoredit',
            paction: 'serialize',
            page: mw.config.get('wgPageName'),
            errorformat: 'html',
            errorlang: mw.config.get('wgUserLanguage'),
            errorsuselocal: true,
            html: this._surfaceModel.getHtml(),
            formatversion: 2,
            oldid: mw.config.get('wgRevisionId')
          })
          resultText = data.visualeditoredit.content
          this._cachedVeWikiText = resultText
        }
        return resultText
      } finally {
        this._isSyncing = false
      }
    }

    get summary() {
      if (ve.init.target.saveDialog) {
        return ve.init.target.saveDialog.editSummaryInput.$input.val()
      } else {
        return this._pendingSummary || ''
      }
    }

    set summary(text) {
      if (ve.init.target.saveDialog) {
        ve.init.target.saveDialog.setEditSummary(text)
      } else {
        this._pendingSummary = text
      }
    }

    get minorEdit() {
      if (ve.init.target.saveDialog) {
        return ve.init.target.saveDialog.checkboxesByName.wpMinoredit.selected
      } else {
        return !!this._pendingMinoredit
      }
    }

    set minorEdit(v) {
      if (ve.init.target.saveDialog) {
        ve.init.target.saveDialog.checkboxesByName.wpMinoredit.setSelected(!!v)
      } else {
        this._pendingMinoredit = !!v
      }
    }

    async _executeAction(action, action2) {
      await this.syncWikiText()

      const target = ve.init.target
      let dialog = target.saveDialog

      if (dialog && dialog.isVisible()) {
        // 对话框已打开，直接触发
        dialog.executeAction(action2)
      } else {
        if (!target.surface.model.hasBeenModified()) {
          // 发布更改按钮不可点击，先制造一个空事务，使其能被点击
          const surfaceModel = target.getSurface().getModel()
          const tx = ve.dm.TransactionBuilder.static.newFromAttributeChanges(
            surfaceModel.getDocument(), 0, 'x'
          )
          surfaceModel.change(tx)
        }

        target.surface.executeCommand(action)

        // 当对话框动画结束后再执行动作
        if (action2 === 'save') {
          const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

          for (let i = 20; i > 0; i--) {
            if (target.saveDialog) {
              target.saveDialog.executeAction(action2)
              return true
            }
            await sleep(100)
          }

          return false
        }
      }
      return true
    }

    async submit() {
      return this._executeAction('showSave', 'save')
    }

    async showPreview() {
      // 备注：可视化模式下没有预览对话框
      if (this._isVE) {
        return false
      }
      return this._executeAction('showPreview', 'preview')
    }

    async showDiff() {
      return this._executeAction('showChanges', 'review')
    }

    get selectionText() {
      // 注意：編輯器失去焦點時，選中區域會變為NullSelection！
      var selection = this._surfaceModel.getSelection()
      if (!(selection instanceof ve.dm.LinearSelection)) {
        return ''
      }
      if (this._isVE) {
        // 在VE模式返回纯文字
        var fragment = this._surfaceModel.getLinearFragment(selection.getRange())
        return fragment.getText()
      } else {
        var fragment = this._surfaceModel.getLinearFragment(selection.getRange())
        return this._dataNodeToSource(fragment.getData())
      }
    }

    set selectionText(text) {
      var selection = this._surfaceModel.getSelection()
      if (selection instanceof ve.dm.LinearSelection) {
        // wiki模式正常插入源代码，VE模式会插入纯文字
        var fragment = this._surfaceModel.getLinearFragment(selection.getRange())
        fragment.insertContent(text)
      }
    }

    setSelectionRange(start, end) {
      let docLen
      if (this._isVE) {
        const data = this._surfaceModel.getDocument().getData()
        docLen = data?.length ?? data?.getLength()
      } else {
        docLen = this.text.length
      }

      let [currentStart, currentEnd] = this.getSelectionRange()
      if (currentStart === null) {
        currentStart = 0
      }
      if (currentEnd === null) {
        currentEnd = 0
      }
      const [newStart, newEnd] = clampSelection(docLen, [currentStart, currentEnd], [start, end])
      this._surfaceModel.setLinearSelection(new ve.Range(newStart + 1, newEnd + 1))
    }

    getSelectionRange() {
      var selection = this._surfaceModel.getSelection()
      if (selection instanceof ve.dm.LinearSelection) {
        return [selection.getRange().start - 1, selection.getRange().end - 1]
      }
      return [null, null]
    }

    async getSelectionWikitext() {
      if (this._isVE) {
        const doc = this._surfaceModel.getDocument().shallowCloneFromSelection(this._surfaceModel.getSelection())
        return ve.init.target.getWikitextFragment(doc)
      } else {
        return this.selectionText
      }
    }

    get readonly() {
      return this._surface.isReadOnly()
    }

    focus() {
      this._surface.getView().focus()
    }

    async insertText(text, pos, { select = true, replace = true } = {}) {
      if (this._isVE) {
        // 在VE模式中，将text解析成fragment再插入到文档中
        await this.syncWikiText()

        try {
          let range
          let docLen = this.text?.length
          if (!docLen) {
            // 兜底
            docLen = this._surfaceModel.getDocument().getData().length
          }
          if (Array.isArray(pos)) {
            range = new ve.Range(clampIndex(pos[0], docLen) + 1, clampIndex(pos[1], docLen) + 1)
          } else if (typeof pos === 'number') {
            const p = clampIndex(pos, docLen)
            range = new ve.Range(p + 1, p + 1)
          } else {
            const selection = this._surfaceModel.getSelection()
            if (!(selection instanceof ve.dm.LinearSelection)) {
              return false
            }
            const curRange = selection.getRange()
            range = replace ? curRange : new ve.Range(curRange.end)
          }

          const data = await ve.init.target.parseWikitextFragment(text)
          const html = data.visualeditor.content
          const doc = ve.createDocumentFromHtml(html)
          let docModel = ve.dm.converter.getModelFromDom(doc, this._surfaceModel.getDocument())

          // 如果只有一行则视为inline
          let paragraphs = docModel.getData().reduce((total, node) => {
            if (node?.type === 'paragraph') {
              return total + 1
            } else {
              return total
            }
          }, 0)
          if (paragraphs === 1) {
            docModel = docModel.shallowCloneFromRange(new ve.Range(1, docModel.data.getLength() - 3))
          }

          this._isProgrammaticChange = true
          try {
            this._surfaceModel.getLinearFragment(range).insertDocument(docModel)
          } finally {
            this._isProgrammaticChange = false
          }

          const endPos = range.start + docModel.data.getLength()
          if (select) {
            this._surfaceModel.setLinearSelection(new ve.Range(range.start, endPos))
          } else {
            this._surfaceModel.setLinearSelection(new ve.Range(endPos, endPos))
          }

          this._cachedVeWikiText = null

          this.focus()
          return true
        } catch (err) {
          console.error('[EditorAPIs] VE Fragment 插入失败', err)
          return false
        } finally {
          this._isProgrammaticChange = false
        }
      } else {
        return super.insertText(text, pos, { select, replace })
      }
    }

    scrollToLine(n) {
      let index = 0
      if (this._isVE) {
        // 检查是第几个paragraph
        const data = this._surfaceModel.getDocument().getData()
        let row = 0
        if (n > 0) {
          for (let i = 0; i < data.length; i++) {
            if (data[i]?.type === 'paragraph') {
              row++
              if (row === n) {
                index = i
                break
              }
            }
          }
          if (index === 0 && row > 0) {
            index = data.length - 1
          }
        }
      } else {
        index = this.posToIndex(n, 0)
      }
      // 直接利用选中该位置并滚动到选区
      const targetRange = new ve.Range(index + 1, index + 1)
      const virtualSelection = new ve.dm.LinearSelection(targetRange)
      this._surface.scrollSelectionIntoView(virtualSelection)
    }

    scrollToCursor() {
      this._surface.scrollSelectionIntoView()
    }

    get _isVE() {
      return this._surface.getMode() === 'visual'
    }

    get _surface() {
      // 由于用户可能会切换编辑器模式，因此动态获取
      return ve.init.target.getSurface()
    }

    get _surfaceModel() {
      // 由于用户可能会切换编辑器模式，因此动态获取
      return this._surface?.getModel() ?? null
    }

    _dataNodeToSource(data) {
      var r = []
      if (data) {
        for (var i = 0; i < data.length; i++) {
          if (typeof data[i] === 'string') {
            r.push(data[i])
          } else if (data[i] && data[i].type === '/paragraph') {
            r.push('\n')
          }
        }
        // 在源代码模式下，最后一个/paragraph不是换行符
        if (r.length > 0 && r[r.length - 1] === '\n') {
          r.pop()
        }
        return r.join('')
      } else {
        return ''
      }
    }

    _autoSyncWikitext(debounceMs = 1000) {
      if (this._isSyncing) {
        return
      }
      // 自动延时同步
      if (this._syncTimer) {
        clearTimeout(this._syncTimer)
      }
      this._syncTimer = setTimeout(() => {
        this._syncTimer = null
        this.syncWikiText()
      }, debounceMs)
    }

    _onDocumentUpdate() {
      if (!this._isProgrammaticChange) {
        this._cachedVeWikiText = null
        this._autoSyncWikitext(60000)
      }
    }
  }

  class DiscussionToolsApi extends VisualEditorApi {
