        diffSelector: null,
        previewSelector: null,
        hasSaveDialog: false
      })
    }

    get mode() {
      return super.mode === 'visual' ? 'visual-discussion' : 'wikitext2017-discussion'
    }

    set summary(text) {
      if ($(this._summarySelector)?.[0]) {
        $(this._summarySelector)[0].value = text
      }
    }

    get summary() {
      return $(this._summarySelector)?.[0].value ?? null
    }

    set minorEdit(v) {
      // 忽略
    }

    get minorEdit() {
      return false
    }

    // DiscussionTools自动预览，不能查看diff
    async submit() {
      $(this._submitSelector)?.[0].click()
      return true
    }

    async showDiff() {
      return false
    }

    async showPreview() {
      return false
    }
  }

  // 移动端可视化编辑器
  class MobileVEApi extends VisualEditorApi {
    constructor() {
      super({
        textboxSelector: null,
        summarySelector: null,
        minorEditSelector: null,
        submitSelector: null,
        diffSelector: null,
        previewSelector: null,
        hasSaveDialog: false
      })
    }

    get mode() {
      return 'visual-mobile'
    }
  }

  // PART 3：检测当前用户使用哪种编辑器，并分配合适的API实现

  // 各类型编辑器单例
  const instances = {
    wikitext: new TraditionalEditorApi(),
    view: new ViewModeApi(),
    none: new NoneApi(),
    codemirror: null,
    wikEd: null,
    cm6: null, // Hook加载
    ace: null, // Hook加载
    ve: null, // Hook加载
    mobile: null, // Hook加载
    vemobile: null, // Hook加载
    wikiplus: null,
    ipe: null,
    discussiontools: null
  }

  // 判定用户当前所用编辑器
  const getActiveApi = () => {
    // 快速编辑器（弹出层优先级最高）
    if ($('#Wikiplus-Quickedit').length) {
      if (!instances.wikiplus) {
        instances.wikiplus = new QuickEditApi({
          mode: 'wikiplus',
          textboxSelector: '#Wikiplus-Quickedit',
          summarySelector: '#Wikiplus-Quickedit-Summary-Input',
          minorEditSelector: '#Wikiplus-Quickedit-MinorEdit',
          submitSelector: '#Wikiplus-Quickedit-Submit',
          previewSelector: '#Wikiplus-Quickedit-Preview-Submit'
        })
      }
      return instances.wikiplus
    }
    if ($('#wpTextbox1.ipe-quickEdit__textarea').length) {
      if (!instances.ipe) {
        instances.ipe = new QuickEditApi({
          mode: 'ipe',
          textboxSelector: '#wpTextbox1.ipe-quickEdit__textarea',
          summarySelector: '#summary',
          minorEditSelector: '#minor',
          submitSelector: '.ipe-modal-modal__buttons .submit-btn',
          previewSelector: '.ipe-modal-modal__buttons .submit-btn + .ipe-modal-btn',
          diffSelector: '.ipe-modal-modal__buttons .submit-btn + .ipe-modal-btn + .ipe-modal-btn'
        })
      }
      return instances.ipe
    }

    // 讨论工具
    if ($('.ext-discussiontools-ui-targetWidget').length) {
      if (!instances.discussiontools) {
        instances.discussiontools = new DiscussionToolsApi()
      }
      return instances.discussiontools
    }

    // VE / Wikitext 2017
    if (window.ve && ve?.init?.target?.surface) {
      // 移动端VE
      if (ve.init.target.constructor.name === 'VeInitMwMobileArticleTarget') {
        if (!instances.vemobile) {
          instances.vemobile = new MobileVEApi({})
        }
        return instances.vemobile
      }
      if (!instances.ve) {
        instances.ve = new VisualEditorApi({
          hasSaveDialog: true
        })
      }
      return instances.ve
    }

    // 移动端
    if ($('#wikitext-editor').length) {
      if (!instances.mobile) {
        instances.mobile = new MobileFrontendApi({})
      }
      return instances.mobile
    }

    // 标准编辑页面
    if (['edit', 'submit'].indexOf(mw.config.get('wgAction')) !== -1) {
      if ($('#mw-content-text #wpTextbox1 + .cm-editor').length && $('.ext-codemirror-wrapper--hidden').length === 0) {
        return instances.cm6 || instances.wikitext
      }
      if ($('#wpTextbox1 + .CodeMirror').length) {
        if (!instances.codemirror) {
          instances.codemirror = new CodeMirror5Api()
        }
        return instances.codemirror
      }
      if ($('.ace_editor').length) {
        return instances.ace || instances.wikitext
      }
      if (window.wikEd && wikEd.useWikEd) {
        if (!instances.wikEd) {
          instances.wikEd = new WikEdApi()
        }
        return instances.wikEd
      }
      return instances.wikitext
    }

    // 阅读模式兜底
    if (mw.config.get('wgNamespaceNumber') !== -1) {
      return instances.view
    }

    return instances.none
  }

  let isInit = !!!window.wikitextEditor
  let lastMode = 'none'

  const editorProxy = new Proxy({}, {
    get(target, prop) {
      const activeApi = getActiveApi()

      // 特殊处理转换内核时的Hook触发
      const mode = activeApi.mode
      if (mode !== lastMode) {
        const oldMode = lastMode
        lastMode = activeApi.mode
        mw.hook('editorapi.ready').fire(editorProxy, { isInit, oldMode })
        isInit = false

        // VE模式要触发一次代码缓存
        if (mode === 'visual' || mode === 'visual-discussion' || mode === 'visual-mobile') {
          activeApi._pendingVeWikiText = null
          activeApi.syncWikiText()
        }
      }

      if (prop === 'mode') return activeApi.mode
      if (prop === '_version') return VERSION
      if (prop === '_rawApi') return activeApi

      const value = activeApi[prop]
      return (typeof value === 'function') ? value.bind(activeApi) : value
    },

    set(target, prop, value) {
      const activeApi = getActiveApi()
      activeApi[prop] = value
      return true
    },

    ownKeys() {
      const prototype = Object.getPrototypeOf(instances.wikitext)
      const keys = new Set([
        ...Reflect.ownKeys(instances.wikitext),
        ...Reflect.ownKeys(prototype)
      ])
      keys.delete('constructor')
      return Array.from(keys)
    },

    getOwnPropertyDescriptor(target, prop) {
      return { enumerable: true, configurable: true }
    }
  })

  const initObserver = () => {
    let timer = null

    const update = () => {
      // 触发一次访问即可更新状态
      const _ = wikitextEditor.mode
    }

    const observer = new MutationObserver((mutations) => {
      // 只有当增加或删除了 DOM 节点时才处理
      const hasSignificantChange = mutations.some(m => m.addedNodes.length || m.removedNodes.length)
      if (!hasSignificantChange) return

      // 防抖
      if (timer) clearTimeout(timer)
      timer = setTimeout(update, 50)
    })
    observer.observe(document.body, { childList: true, subtree: true })
  }

  const init = () => {
    window.wikitextEditor = editorProxy

    // VisualEditor / WikiEditor 2017
    mw.hook('ve.activationComplete').add(function () {
      if (!instances.ve) {
        instances.ve = new VisualEditorApi({
          hasSaveDialog: true
        })
      }
      console.log('[EditorAPIs] VE 实例已就绪并挂载至代理')
    })

    // 移动端
    mw.hook('mobileFrontend.editorOpened').add(function () {
      instances.mobile = new MobileFrontendApi()
      console.log('[EditorAPIs] 移动编辑器实例已就绪并挂载至代理')
    })

    // CodeMirror 6
    mw.hook('ext.CodeMirror.ready').add((cm) => {
      instances.cm6 = new CodeMirror6Api(cm)
      console.log('[EditorAPIs] CodeMirror 6 实例已就绪并挂载至代理')
    })

    // AceEditor
    mw.hook('codeEditor.configure').add((session) => {
      instances.ace = new AceEditorApi(session)
      console.log('[EditorAPIs] AceEditor 实例已就绪并挂载至代理')
    })

    const initialMode = wikitextEditor.mode

    // 兼容旧脚本
    if (initialMode === 'view' && window.editorapi?.useViewMode) {
      instances.view.load()
    }

    // 监听DOM变化以确保即时响应编辑器切换
    initObserver()
  }

  init()
})

