  };

  let LTConf = {
    SourceLanguageCode: 'en',
    KeepOriginalTextOnNotFound: true,
    KeepOriginalTextOnFound: true,
    CommentOriginalLink: false,
    UseLangLink: true,
    UseTsl: true,
    SelectedTextOnly: true,
    MarkWrongPage: true,
    DoNotConvertDisam: true,
    IgnoreLocalExists: 'follow'
  };
  const storage = localStorage.getItem('LinkTranslatorConf')
  if (storage) {
    try {
      LTConf = JSON.parse(storage);
    } catch (err) {
      console.error('LinkTranslator Error:', err);
    }
  }

  // variables
  var currentJobid = 0;
  var LDSB = '__LEFT_DOUBLE_SQUARE_BRACKETS__';
  var windowManager, dialog;

  /**
   * 调用维基百科API来转换条目标题
   */
  const callTranslateApi = async (options) => {
    const links = options.links || [];
    const lang = options.lang || 'en';
    const tolang = options.tolang || mw.config.get('wgContentLanguage');
    const jobid = options.jobid || currentJobid;

    const uniqueLinks = [...new Set(links)];
    if (uniqueLinks.length === 0) return {};

    const chunks = [];
    for (let i = 0; i < uniqueLinks.length; i += 50) {
      chunks.push(uniqueLinks.slice(i, i + 50));
    }

    const langlinks = {};

    const processTranslateChunk = (linksChunk) => new Promise((resolve, reject) => {
      if (jobid !== currentJobid) {
        resolve(null);
        return;
      }

      const domain = mw.config.get('wgServerName').split('.').slice(1).join('.');
      $.ajax({
        url: `https://${lang}.${domain}/w/api.php`,
        data: {
          action: 'query',
          prop: 'langlinks|pageprops',
          ppprop: 'disambiguation',
          lllang: tolang,
          lllimit: 50,
          titles: linksChunk.join('|'),
          redirects: true,
          converttitles: true,
          format: 'json',
        },
        timeout: 30 * 1000,
        dataType: 'jsonp'
      })
        .done((data) => {
          if (options.updateProgress) {
            options.updateProgress(linksChunk.length);
          }
          resolve(data);
        })
        .fail((_, details) => { reject(details) });
    });

    // 处理重定向和标题转换
    const processMappings = (arr, orinTitle) => {
      if (arr) {
        arr.forEach(item => {
          if (!orinTitle[item.to]) {
            orinTitle[item.to] = [];
          }
          orinTitle[item.to].push(item.from);
        });
      }
    };

    try {
      // 並行處理所有請求分組
      const results = await Promise.all(chunks.map(chunk => processTranslateChunk(chunk)));

      if (jobid !== currentJobid) {
        return null;
      }

      results.forEach(data => {
        if (!data.query) return;

        const orinTitle = {};

        processMappings(data.query.normalized, orinTitle);
        processMappings(data.query.converted, orinTitle);
        processMappings(data.query.redirects, orinTitle);

        const pages = data.query.pages;
        for (const pageid in pages) {
          const page = pages[pageid];
          let titles = [page.title];

          // 找到所有重定向
          let redirectQueue = [page.title];
          while (redirectQueue.length > 0) {
            const current = redirectQueue.shift();
            if (orinTitle[current]) {
              orinTitle[current].forEach(t => {
                if (!titles.includes(t)) {
                  titles.push(t);
                  redirectQueue.push(t);
                }
              });
            }
          }

          for (const title of titles) {
            if (page.ns === 6) {
              if (page.title.includes(':')) {
                langlinks[title] = {
                  title: title,
                  target: 'File:' + page.title.split(':').slice(1).join(':'),
                  orinExists: true,
                  isDisam: false
                };
              } else {
                langlinks[title] = {
                  title: title,
                  target: page.title,
                  orinExists: true,
                  isDisam: false
                };
              }
              continue
            }

            if (page.missing !== undefined) {
              // 頁面不存在
              langlinks[title] = {
                title: title,
                target: null,
                orinExists: false
              };
            } else if (page.langlinks) {
              const targetTitle = page.langlinks[0]['*'];
              langlinks[title] = {
                title: title,
                target: targetTitle,
                orinExists: true,
                isDisam: page.pageprops?.disambiguation !== undefined
              };
            } else {
              // 頁面存在但無跨語言連結
              langlinks[title] = {
                title: title,
                target: null,
                orinExists: true,
                isDisam: page.pageprops?.disambiguation !== undefined
              };
            }
          }
        }
      });
    } catch (err) {
      console.error('LinkTranslator API Error:', err);
      if (jobid === currentJobid) {
        throw err;
      }
    }

    return langlinks;
  };

  /**
   * 检查本地是否存在条目
   */
  const checkLocalExistenceApi = async (options) => {
    const links = options.links || [];
    const jobid = options.jobid || currentJobid;

    if (links.length === 0) {
      return {
        targetNameMap: {},
        targetExistsMap: {},
        targetPageMap: {}
      };
    }

    const chunks = [];
    for (let i = 0; i < links.length; i += 50) {
      chunks.push(links.slice(i, i + 50));
    }

    const processExistenceChunk = (linksChunk) => new Promise((resolve, reject) => {
      if (jobid !== currentJobid) {
        resolve(null);
        return;
      }

      const api = new mw.Api()
      api.get({
        action: 'query',
        titles: linksChunk.join('|'),
        format: 'json',
        redirects: true,
        converttitles: 1
      }).then((data) => {
        if (options.updateProgress) {
          options.updateProgress(linksChunk.length);
        }
        resolve(data);
      }).catch(reject)
    });

    const targetNameMap = {}
    const targetExistsMap = {}
    const targetPageMap = {}
    try {
      const processTarget = (list) => {
        if (list) {
          for (const item of list) {
            targetNameMap[item.from] = item.to
          }
          for (const item in targetNameMap) {
            const to = targetNameMap[item]
            if (targetNameMap[to]) {
              targetNameMap[item] = targetNameMap[to]
            }
          }
        }
      }

      const results = await Promise.all(chunks.map(chunk => processExistenceChunk(chunk)));
      results.forEach(data => {
        if (!data?.query) return;

        // 处理标题转换
        processTarget(data.query.normalized);
        processTarget(data.query.converted);
        processTarget(data.query.redirects);

        // 先标记经过转换之后的页面标题
        const pages = data.query.pages;
        const pageMap = {}
        for (const pageid in pages) {
          const page = pages[pageid];
          const title = page.title;
          pageMap[title] = page;

          const exists =
            page.pageid !== undefined
            || page.known !== undefined   // commons上有文件
            || page.ns === 6;             // 文件页即使缺失也算存在，以免被错误转换

          targetNameMap[title] = title;
          targetPageMap[title] = page
          targetExistsMap[title] = exists
        }

        // 从待转换的原始标题中建立旧标题到实际页面标题的映射（考虑重定向和标题转换）
        for (const item in targetNameMap) {
          const to = targetNameMap[item]
          const page = pageMap[to]
          if (page) {
            targetPageMap[item] = page
            targetExistsMap[item] = targetExistsMap[page.title];
          }
        }
      });
    } catch (err) {
      console.error('LinkTranslator Existence API Error:', err);
      if (jobid === currentJobid) {
        throw err;
      }
    }

    return { targetNameMap, targetExistsMap, targetPageMap };
  }

  // 根据链接制作内链wiki文本
  var makeLink = function (options) {
    var link = options.link || { target: '', display: '' };
    var lang = options.lang || '';
    var newTarget = options.newTarget;
    var output = '';

    if (!link) return '';

    var makeNormalLink = function (target, display) {
      if (target === display || display === '') {
        return LDSB + target + ']]';
      } else {
        return LDSB + target + '|' + display + ']]';
      }
    };

    // 分类或文件链接特殊处理
    const lowerTarget = link.target.toLowerCase().trim()
    if (lowerTarget.includes('category:') || lowerTarget.includes('file:')) {
      options.useLangLink = false;
      options.keepOriginalTextOnFound = (link.display !== '' && link.display !== link.target);
    }
    if (link.rawTarget.startsWith(':')) {
      options.localTarget = ':' + options.localTarget;
    }

    // 本地已存在条目时，如果用户选择忽略，则原样返回，不做任何处理
    if (options.localExists && (options.ignoreLocalExists === true || options.ignoreLocalExists === 'ignore')) {
      return makeNormalLink(link.rawTarget, link.display);
    }
    // 本地已存在条目时，如果用户选择跟随重定向，则直接转换为本地目标链接，不再进行后续检查
    if (options.localExists && options.ignoreLocalExists === 'follow') {
      return makeNormalLink(options.localTarget, link.display);
    }
    // 原语言是消歧义页，且用户选择不转换消歧义页，则原样返回并进行标记
    if (options.isDisam && options.doNotConvertDisam) {
      return '<!-- ' + LTUI.DISAM + ' -->' + makeNormalLink(link.rawTarget, link.display);
    }
    if (newTarget === null) {
      // 未翻译出对应条目时
      // 如果用户选择使用跨语言链接模板，则使用模板进行标记，否则直接返回原链接并根据用户选择决定是否进行标记
      if (options.useLangLink) {
        if (options.useTsl) {
          output = '{{tsl|' + lang + '|' + link.target + '||' + (options.keepOriginalTextOnNotFound ? link.display : '') + '}}';
        } else {
          output = '{{link-' + lang + '||' + link.target + (options.keepOriginalTextOnNotFound ? '|' + link.display : '') + '}}';
        }
      } else {
        output = (options.markWrongPage ? '<!-- ' + LTUI.NOLINK + ' -->' : '') + makeNormalLink(link.target, link.display);
      }
    } else if (newTarget === undefined) {
      // 在原文维基就是红链接时
      output = (options.markWrongPage ? '<!-- ' + LTUI.DONTEXIST + ' -->' : '') + makeNormalLink(link.target, link.display);
    } else {
      // 成功翻译出对应条目时
      output = makeNormalLink(newTarget, options.keepOriginalTextOnFound ? (link.display || link.target) : '');
    }

    // 有发生变化时，如果用户选择注释原链接，则在转换后的链接前注释原链接
    if (options.commentOriginalLink && link.rawTarget !== link.target) {
      output = '<!-- ' + makeNormalLink(link.rawTarget, link.display) + ' -->' + output;
    }

    // 如果原文维基是消歧义则标记
    if (options.isDisam) {
      output = '<!-- ' + LTUI.DISAM + ' -->' + output;
    }

    return output;
  };

  /**
   * 开始进行处理
   */
  const processLinks = async (config, dialogInstance) => {
    var jobid = currentJobid;

    const actions = dialogInstance.getActions();
    actions.setAbilities({ done: false });

    let wikitext
    if (config.SelectedTextOnly) {
      wikitext = await wikitextEditor.getSelectionWikitext();
    } else {
      wikitext = await wikitextEditor.syncWikiText();
    }

    // 识别所有链接（排除文件链接）
    var recogizedLinks = wikitext.match(/(\[\[)(?!(?:Image|File)\:)(.+?)(\|.+?)?(\]\])/gi);

    if (recogizedLinks === null) {
      dialogInstance.getContentElement().text(LTUI.NOLINKINPAGE);
      return;
    }

    // 切换到进度展示
    var $statusList = $('<div>').css({
      'line-height': '1.5em',
      'margin-top': '1em',
      'overflow-y': 'auto',
      'font-size': '0.9em'
    });
    var progressBar = new OO.ui.ProgressBarWidget({ progress: 0 });
    dialogInstance.getContentElement().empty().append(progressBar.$element, $statusList);

    // 分析并展示所有链接
    var realLinks = [];
    var processedLinks = [];
    for (var i = 0; i < recogizedLinks.length; i++) {
      var link = recogizedLinks[i].slice(2, -2);
      var linktarget = link;
      var linkdisplay = link;

      var idx = link.indexOf('|');
      if (idx !== -1) {
        linktarget = link.substring(0, idx);
        linkdisplay = link.substring(idx + 1);
      }
      var rawTarget = linktarget;

      idx = linktarget.indexOf('#');
      if (idx !== -1) {
        linktarget = linktarget.substring(0, idx);
      }

      var $item = $('<div>').attr('id', 'lt-item-' + i).text(recogizedLinks[i] + ' -> ');
      var $newSpan = $('<span>').addClass('lt-newlink').text('...');
      $item.append($newSpan);
      $statusList.append($item);

      realLinks.push(linktarget);
      processedLinks.push({
        target: linktarget,
        rawTarget: rawTarget,
        display: linkdisplay,
        original: recogizedLinks[i]
      });
    }

    try {
      if (jobid !== currentJobid) return;

      // 进度管理
      let checkCompleted = 0;
      let checkTotal = 0;
      let translateCompleted = 0;
      let translateTotal = 0;
      const updateProgress = () => {
        if (jobid !== currentJobid) return;

        let completed = checkCompleted + translateCompleted;
        let total = checkTotal + translateTotal;
        if (total === 0) {
          progressBar.setProgress(0);
        } else {
          const percent = Math.round((completed / total) * 100);
          progressBar.setProgress(percent);
        }
      }

      // 检查本地是否已有条目
      let localExistsResults = {
        targetNameMap: {}, targetExistsMap: {}, targetPageMap: {}
      };
      if (config.IgnoreLocalExists !== 'justdo' && config.IgnoreLocalExists !== false) {
        checkTotal += realLinks.length;
        localExistsResults = await checkLocalExistenceApi({
          links: realLinks,
          jobid,
          updateProgress: (completed) => {
            checkCompleted += completed;
            updateProgress();
          }
        })
      }

      // 翻译链接
      const langlinks = await callTranslateApi({
        links: realLinks,
        lang: config.SourceLanguageCode,
        jobid: jobid,
        updateProgress: (completed) => {
          translateCompleted += completed;
          updateProgress();
        }
      });

      if (!langlinks) {
        return;
      }

      var code = wikitext + '';
      for (var i = 0; i < processedLinks.length; i++) {
        var link = processedLinks[i];

        const isDisam = langlinks[link.target]?.isDisam;
        const localExists = localExistsResults.targetExistsMap[link.target];
        const localTarget = localExistsResults.targetNameMap[link.target];

        var linkCode = makeLink({
          link: link,
          newTarget: langlinks[link.target]?.target,
          lang: config.SourceLanguageCode,
          useLangLink: config.UseLangLink,
          doNotConvertDisam: config.DoNotConvertDisam,
          ignoreLocalExists: config.IgnoreLocalExists,
          useTsl: config.UseTsl,
          keepOriginalTextOnNotFound: config.KeepOriginalTextOnNotFound,
          keepOriginalTextOnFound: config.KeepOriginalTextOnFound,
          commentOriginalLink: config.CommentOriginalLink,
          markWrongPage: config.MarkWrongPage,

          isDisam,
          localExists,
          localTarget
        });

        var $itemSpan = $('#lt-item-' + i + ' .lt-newlink');
        var newCode = linkCode.replace(new RegExp(LDSB, 'g'), '[[');
        $itemSpan.text(newCode).css('color', '#0645ad');

        if (link.original === newCode) {
          $itemSpan.text(LTUI.NOCHANGE).css('color', '#ba6000');
		} else if (localExists && (config.IgnoreLocalExists === true || config.IgnoreLocalExists === 'ignore')) {
          $itemSpan.text(LTUI.NOTCONVERTED + '(' + LTUI.LOCALEXISTS + ')').css('color', '#ba6000');
        } else if (isDisam && config.DoNotConvertDisam) {
          $itemSpan.text(LTUI.NOTCONVERTED + '(' + LTUI.DISAM + ')').css('color', '#ba6000');
        } else if (langlinks[link.target]?.target === null) {
          if (!config.UseLangLink) {
            $itemSpan.text(LTUI.NOLINK).css('color', '#ba0000');
          }
        } else if (langlinks[link.target]?.target === undefined) {
          $itemSpan.text(LTUI.DONTEXIST).css('color', '#ba0000');
        }

        code = code.replace(link.original, linkCode);
      }

      var newtext = code.replace(new RegExp(LDSB, 'g'), '[[');
      progressBar.setProgress(100);
      $statusList.prepend($('<div>').css('color', 'green').append($('<strong>').text(LTUI.Done)));

      const closeAction = actions.get({ actions: 'finish' })[0];
      if (closeAction) {
        closeAction.setFlags({ primary: true, progressive: true });
      }

      if (config.SelectedTextOnly) {
        wikitextEditor.insertText(newtext);
      } else {
        wikitextEditor.text = newtext;
      }
      if (!wikitextEditor.summary) {
        wikitextEditor.summary = LTUI.EditMessage;
      }

      await wikitextEditor.syncWikiText()

      if (window.wikitextEditor.mode === 'view') {
        window.wikitextEditor.showDiff();
      }
    } catch (ex) {
      console.error('LinkTranslator Error:', ex);
      $statusList.prepend($('<div>').css('color', 'red').append($('<strong>').text(LTUI.ERROR + ':' + ex)));
    } finally {
      dialogInstance.getActions().setMode('result');
      actions.setAbilities({ finish: true });
    }

  };

  function LinkTranslatorDialog(config) {
    LinkTranslatorDialog.super.call(this, config);
  }
  OO.inheritClass(LinkTranslatorDialog, OO.ui.ProcessDialog);

  LinkTranslatorDialog.static.name = 'LinkTranslatorDialog';
  LinkTranslatorDialog.static.title = LTUI.LinkTranslator;
  LinkTranslatorDialog.static.actions = [
    {
      action: 'save',
      label: LTUI.Translate,
      flags: ['primary', 'progressive'],
      modes: 'setup'
    },
    {
      action: 'cancel',
      label: LTUI.Cancel,
      flags: 'safe',
      modes: ['setup', 'processing']
    },
    {
      action: 'finish',
      label: LTUI.Done,
      flags: ['primary', 'progressive'],
      modes: 'result'
    }
  ];

  /**
   * 恢复对话框到初始设置界面
   */
  LinkTranslatorDialog.prototype.resetForm = function () {
    // 重新设置 fieldset 内容

    const localFieldSet = new OO.ui.FieldsetLayout({
      label: LTUI.IfLocal,
      classes: ['container']
    });

    localFieldSet.addItems([
      new OO.ui.FieldLayout(this.ignoreLocalRb, { label: LTUI.IgnoreLocalExists, align: 'inline' }),
      new OO.ui.FieldLayout(this.followRedirectRb, { label: LTUI.FollowRedirect, align: 'inline' }),
      new OO.ui.FieldLayout(this.ignoreLocalLinkRb, { label: LTUI.JustTranslate, align: 'inline' }),
    ])

    const foundFieldSet = new OO.ui.FieldsetLayout({
      label: LTUI.IfFound,
      classes: ['container']
    });

    foundFieldSet.addItems([
      new OO.ui.FieldLayout(this.commentCb, { label: LTUI.CommentOriginalLink, align: 'inline' }),
      new OO.ui.FieldLayout(this.keepOriginalOnFoundCb, { label: LTUI.KeepOriginalTextOnFound, align: 'inline' }),
      new OO.ui.FieldLayout(this.doNotConvertDisamCb, { label: LTUI.DoNotConvertDisam, align: 'inline' })
    ])

    const notFoundFieldSet = new OO.ui.FieldsetLayout({
      label: LTUI.IfNotFound,
      classes: ['container']
    });

    notFoundFieldSet.addItems([
      new OO.ui.FieldLayout(this.useCrossTemplateRb, { label: LTUI.UseCrossTemplate, align: 'inline' }),
      new OO.ui.FieldLayout(this.useTslCb, { label: LTUI.UseTsl, align: 'inline' }),
      new OO.ui.FieldLayout(this.keepOriginalOnNotFoundCb, { label: LTUI.KeepOriginalTextOnNotFound, align: 'inline' }),
      new OO.ui.FieldLayout(this.markLinkRb, { label: LTUI.MarkLink, align: 'inline' }),
      new OO.ui.FieldLayout(this.ignoreLinkRb, { label: LTUI.IgnoreLink, align: 'inline' }),
    ])

    var fieldset = new OO.ui.FieldsetLayout({ label: LTUI.LinkTranslator });
    fieldset.addItems([
      new OO.ui.FieldLayout(this.sourceLangInput, { label: LTUI.SourceLanguageCode, align: 'top' }),
    ])

    if (wikitextEditor.mode !== 'view') {
      const editorFieldSet = new OO.ui.FieldsetLayout({
        label: LTUI.EditorOpts,
        classes: ['container']
      });
      editorFieldSet.addItems([
        new OO.ui.FieldLayout(this.selectedOnlyCb, { label: LTUI.SelectedTextOnly, align: 'inline' }),
      ])
      fieldset.addItems([
        editorFieldSet
      ])

      const hasSelectedText = wikitextEditor.selectionText.length > 0
      this.selectedOnlyCb.setSelected(hasSelectedText)
    } else {
      this.selectedOnlyCb.setSelected(false)
    }

    fieldset.addItems([
      localFieldSet,
      foundFieldSet,
      notFoundFieldSet
    ])

    this.content.$element.empty().append(fieldset.$element);

    const updateSubOptions = () => {
      const useTemplate = this.useCrossTemplateRb.isSelected();
      this.useTslCb.setDisabled(!useTemplate);
      this.keepOriginalOnNotFoundCb.setDisabled(!useTemplate);
    }
    this.content.$element.on('change', 'input[name="notfound"]', () => {
      setTimeout(updateSubOptions, 0);
    });
    updateSubOptions()
  };

  LinkTranslatorDialog.prototype.initialize = function () {
    LinkTranslatorDialog.super.prototype.initialize.apply(this, arguments);
    this.content = new OO.ui.PanelLayout({ padded: true, expanded: false });

    this.sourceLangInput = new OO.ui.TextInputWidget({ value: LTConf.SourceLanguageCode });

    this.ignoreLocalRb = new OO.ui.RadioInputWidget({ name: 'localexists', value: 'ignore', selected: LTConf.IgnoreLocalExists === 'ignore' || LTConf.IgnoreLocalExists === true });
    this.followRedirectRb = new OO.ui.RadioInputWidget({ name: 'localexists', value: 'follow', selected: LTConf.IgnoreLocalExists === 'follow' });
    this.ignoreLocalLinkRb = new OO.ui.RadioInputWidget({ name: 'localexists', value: 'justdo', selected: LTConf.IgnoreLocalExists === 'justdo' || !LTConf.IgnoreLocalExists });

    this.selectedOnlyCb = new OO.ui.CheckboxInputWidget({ selected: LTConf.SelectedTextOnly });
    this.commentCb = new OO.ui.CheckboxInputWidget({ selected: LTConf.CommentOriginalLink });
    this.keepOriginalOnFoundCb = new OO.ui.CheckboxInputWidget({ selected: LTConf.KeepOriginalTextOnFound });
    this.doNotConvertDisamCb = new OO.ui.CheckboxInputWidget({ selected: LTConf.DoNotConvertDisam });

    this.useTslCb = new OO.ui.CheckboxInputWidget({ selected: LTConf.UseTsl });
    this.keepOriginalOnNotFoundCb = new OO.ui.CheckboxInputWidget({ selected: LTConf.KeepOriginalTextOnNotFound });

    this.useCrossTemplateRb = new OO.ui.RadioInputWidget({ name: 'notfound', value: 'cross', selected: LTConf.UseLangLink });
    this.markLinkRb = new OO.ui.RadioInputWidget({ name: 'notfound', value: 'mark', selected: !LTConf.UseLangLink && LTConf.MarkWrongPage });
    this.ignoreLinkRb = new OO.ui.RadioInputWidget({ name: 'notfound', value: 'ignore', selected: !LTConf.UseLangLink && !LTConf.MarkWrongPage });

    this.$body.append(this.content.$element);

    this.resetForm();
  };

  LinkTranslatorDialog.prototype.getSetupProcess = function (data) {
    return LinkTranslatorDialog.super.prototype.getSetupProcess.call(this, data)
      .next(() => {
        this.actions.setMode('setup');
      });
  };

  LinkTranslatorDialog.prototype.getActionProcess = function (action) {
    if (action === 'save') {
      var config = {
        SourceLanguageCode: this.sourceLangInput.getValue(),
        IgnoreLocalExists: this.ignoreLocalRb.isSelected() ? 'ignore' : (this.followRedirectRb.isSelected() ? 'follow' : 'justdo'),
        DoNotConvertDisam: this.doNotConvertDisamCb.isSelected(),
        SelectedTextOnly: this.selectedOnlyCb.isSelected(),
        CommentOriginalLink: this.commentCb.isSelected(),
        KeepOriginalTextOnFound: this.keepOriginalOnFoundCb.isSelected(),
        UseLangLink: this.useCrossTemplateRb.isSelected(),
        UseTsl: this.useTslCb.isSelected(),
        KeepOriginalTextOnNotFound: this.keepOriginalOnNotFoundCb.isSelected(),
        MarkWrongPage: this.markLinkRb.isSelected(),
      };
      localStorage.setItem('LinkTranslatorConf', JSON.stringify(config));
      this.getActions().setMode('processing');

      processLinks(config, this);
      return new OO.ui.Process();
    }
    if (action === 'finish' || action === 'cancel') {
      return new OO.ui.Process(this.close());
    }
    return LinkTranslatorDialog.super.prototype.getActionProcess.call(this, action);
  };

  LinkTranslatorDialog.prototype.getContentElement = function () {
    return this.content.$element;
  };

  var callDialog = function (event) {
    if (event && event.preventDefault) {
      event.preventDefault();
    }
    if (wikitextEditor.mode === 'view') {
      wikitextEditor.load();
    }

    if (!windowManager) {
      windowManager = new OO.ui.WindowManager();
      $(document.body).append(windowManager.$element);
      dialog = new LinkTranslatorDialog({ size: 'medium' });
      windowManager.addWindows([dialog]);
    }

    dialog.resetForm();
    windowManager.openWindow(dialog);
  };

  // 支援各路編輯器
  mw.hook('editorapi.ready').add(function (editor, { isInit }) {
    if (editor.mode === 'none' || !isInit) return;
	if (mw.config.get('wgPageContentModel') !== 'wikitext') return;

