    var isOOUI = $('#wpDiffWidget').length > 0;
    var $btn;

    if (isOOUI) {
      $btn = $('<span id="wpLinktranslatorOOUI" class="oo-ui-widget oo-ui-widget-enabled oo-ui-inputWidget oo-ui-buttonElement oo-ui-buttonElement-framed oo-ui-labelElement oo-ui-buttonInputWidget"><input id="wpLinktranslator" value="' + LTUI.TranslateLinks + '" title="' + LTUI.TLTitle + '" type="button" class="oo-ui-inputWidget-input oo-ui-buttonElement-button"/></span>');
      $('#wpDiffWidget').after($btn);
    } else {
      $btn = $('<input id="wpLinktranslator" value="' + LTUI.TranslateLinks + '" title="' + LTUI.TLTitle + '" type="button"/>');
      $('#wpDiff').after('\n', $btn);
    }

    $btn.on('click', callDialog);

    $('#p-link-ts').remove();
    $(mw.util.addPortletLink('p-cactions', '#', LTUI.TranslateLinks, 'p-link-ts')).on('click', callDialog);

    currentJobid++;
  });

  mw.loader.load('https://zh.wikipedia.org/w/index.php?title=User:逆襲のあまのじゃく/tool/EditorAPIs/EditorAPIs.js&action=raw&ctype=text/javascript');
})

