/**
 * EditorAPIs为用户工具的开发者提供统一API接口，是各常用维基代码编辑器的统一抽象层。
 * 通过该接口，用户工具开发者可忽略用户所采用的具体编辑器，专注于编辑功能本身的开发。
 *
 * 该用户工具仅用于用户工具开发者。一般用户安装后不会产生任何效果。
 *
 * EditorAPIs provides a unified interface and abstraction layer for
 * userscript developers across various wiki editors.
 * It enables developers to build editing features with a consistent API,
 * regardless of the user's preferred editor.
 *
 * This script is for developers only and has no visible effect for non-developers.
 *
 * 文档：[[User:逆襲のあまのじゃく/tool/EditorAPIs]]
 * Documentation: [[User:逆襲のあまのじゃく/tool/EditorAPIs/en]]
 */

$(function () {
  'use strict'

  const VERSION = 20260422

  // 加载最新版
  if (window.wikitextEditor && (window.wikitextEditor._version || 0) >= VERSION) {
    return
  }

  // PART 1：基础类和工具函数
  const clampIndex = (pos, len) => Math.max(0, Math.min(len, pos))
  const clampLine = (pos, len) => Math.max(1, Math.min(len, pos))

  const clampSelection = (textLen, [currentStart, currentEnd], [start, end]) => {
    let newStart = (start !== undefined) ? start : (currentStart !== undefined && currentStart !== null ? currentStart : 0)
    let newEnd = (end !== undefined) ? end : (currentEnd !== undefined && currentEnd !== null ? currentEnd : 0)
    newStart = clampIndex(newStart, textLen)
    newEnd = clampIndex(newEnd, textLen)
    if (newStart > newEnd) {
      [newStart, newEnd] = [newEnd, newStart]
    }
    return [newStart, newEnd]
  }

  class BaseApi {
    constructor({
      textboxSelector = '#wpTextbox1',
      summarySelector = '#wpSummary',
      minorEditSelector = '#wpMinoredit',
      submitSelector = '#wpSave',
      diffSelector = '#wpDiff',
      previewSelector = '#wpPreview'
    } = {}) {
      this._textboxSelector = textboxSelector
      this._summarySelector = summarySelector
      this._minorEditSelector = minorEditSelector
      this._submitSelector = submitSelector
      this._diffSelector = diffSelector
      this._previewSelector = previewSelector
    }

    get mode() {
      return 'none'
    }

    get _version() {
      return VERSION
    }

    set text(v) {
      this._textboxSelector && $(this._textboxSelector).val(v)
    }

    get text() {
      const val = $(this._textboxSelector).val()
      if (val === undefined) {
      	return null
      }
      return val
    }

    set summary(v) {
      this._summarySelector && $(this._summarySelector).val(v)
    }

    get summary() {
      const val = $(this._summarySelector).val()
      if (val === undefined) {
      	return null
      }
      return val
    }

    set minorEdit(v) {
      this._minorEditSelector && $(this._minorEditSelector).prop('checked', !!v)
    }

    get minorEdit() {
      return !!$(this._minorEditSelector).prop('checked')
    }

    set selectionStart(pos) {
      this.setSelectionRange(pos, this.selectionEnd)
    }

    get selectionStart() {
      return this.getSelectionRange()[0]
    }

    set selectionEnd(pos) {
      this.setSelectionRange(this.selectionStart, pos)
    }

    get selectionEnd() {
      return this.getSelectionRange()[1]
    }

    set selectionText(text) {
      if (!this._textboxSelector) {
        return
      }
      const t = document.querySelector(this._textboxSelector)
      if (t) {
      	t.setRangeText(text)
      }
    }

    get selectionText() {
      if (!this._textboxSelector) {
        return ''
      }
      const textbox = document.querySelector(this._textboxSelector)
      if (textbox && textbox.value) {
      	return textbox.value.substring(textbox.selectionStart, textbox.selectionEnd)
      } else {
      	return ''
      }
    }

    get readonly() {
      return !!$(this._textboxSelector).prop('readonly')
    }

    async submit() {
      this._submitSelector && $(this._submitSelector).click()
      return !!this._submitSelector
    }

    async showPreview() {
      this._previewSelector && $(this._previewSelector).click()
      return !!this._previewSelector
    }

    async showDiff() {
      this._diffSelector && $(this._diffSelector).click()
      return !!this._diffSelector
    }

    setSelectionRange(start, end) {
      if (!this._textboxSelector) {
        return
      }
      const textbox = document.querySelector(this._textboxSelector)
      if (!textbox) {
        return
      }
      const [newStart, newEnd] = clampSelection(textbox.value.length, [textbox.selectionStart, textbox.selectionEnd], [start, end])
      textbox.selectionStart = newStart
      textbox.selectionEnd = newEnd
    }

    getSelectionRange() {
      if (!this._textboxSelector) {
        return [null, null]
      }
      const textbox = document.querySelector(this._textboxSelector)
      if (!textbox) {
        return [null, null]
      }
      return [textbox.selectionStart, textbox.selectionEnd]
    }

    get lineCount() {
      const txt = this.text || ''
      return txt.split('\n').length
    }

    getLine(n) {
      if (n < 1) {
        return null
      }
      const lines = (this.text || '').split('\n')
      const line = lines[n - 1]
      if (line === undefined) return null
      return line
    }

    indexToPos(index) {
      const text = this.text || ''
      const safeIndex = clampIndex(index, text.length)

      const lines = text.split('\n')
      let currentOffset = 0

      for (let i = 0; i < lines.length; i++) {
        const lineContent = lines[i]
        const lineLength = lineContent.length
        if (safeIndex <= currentOffset + lineLength) {
          return [i + 1, safeIndex - currentOffset]
        }
        currentOffset += lineLength + 1
      }
      let end = 0
      if (lines[lines.length - 1]) {
      	end = lines[lines.length - 1].length
      }
      return [lines.length, end]
    }

    posToIndex(line, col) {
      const text = this.text || ''
      const lines = text.split('\n')
      const totalLines = lines.length

      if (line < 1) {
        return 0
      }
      if (line > totalLines) {
        return text.length
      }

      let offset = 0
      for (let i = 0; i < line - 1; i++) {
        offset += lines[i].length + 1
      }

      const targetLineText = lines[line - 1] || ''
      // col<=0视为0；col>最后一个字符则卡在行末
      const safeCol = clampIndex(col, targetLineText.length)

      return offset + safeCol
    }

    focus() {
      if (!this._textboxSelector) {
        return
      }
      $(this._textboxSelector).focus()
    }

    async insertText(text, pos, { select = true, replace = true } = {}) {
      const currentText = this.text || ''
      const textLen = currentText.length

      let from, to
      if (Array.isArray(pos)) {
        from = clampIndex(pos[0], textLen)
        to = clampIndex(pos[1], textLen)
      } else if (typeof pos === 'number') {
        from = to = clampIndex(pos, textLen)
      } else {
        const currentSel = this.getSelectionRange()
        if (replace) {
          [from, to] = currentSel
        } else {
          from = to = currentSel[1]
        }
      }

      if (from === null || to === null) {
        return false
      }

      this.focus()
      this.setSelectionRange(from, to)
      this.selectionText = text

      const newEnd = from + text.length
      if (select) {
        this.setSelectionRange(from, newEnd)
      } else {
        this.setSelectionRange(newEnd, newEnd)
      }
      this.scrollToCursor()
      return true
    }

    scrollToLine(n) {
      if (!this._textboxSelector) {
        return
      }
      const safeLine = clampLine(n, this.lineCount)
      const textbox = document.querySelector(this._textboxSelector)
      if (!textbox) {
        return
      }

      const style = window.getComputedStyle(textbox)
      let lineHeight = parseFloat(style.lineHeight) || 20
      if (Number.isNaN(lineHeight)) {
        lineHeight = 20
      }
      textbox.scrollTop = (safeLine - 1) * lineHeight
    }

    scrollToCursor() {
      const [line] = this.indexToPos(this.selectionStart)
      this.scrollToLine(line)
    }

    async syncWikiText() {
      return this.text
    }

    async getSelectionWikitext() {
      return this.selectionText
    }
  }

