  // 2.2 - WikEd编辑器
  class WikEdApi extends BaseApi {
    constructor() {
      super()
    }

    get mode() {
      return 'wikEd'
    }

    get text() {
      wikEd.UpdateTextarea()
      return $(this._textboxSelector).val()
    }

    set text(t) {
      $(this._textboxSelector).val(t)
      wikEd.UpdateFrame()
    }

    get selectionText() {
      var obj = {}
      wikEd.GetText(obj, 'selection, cursor')
      return obj.selection.plain || ''
    }

    set selectionText(text) {
      wikEd.EditButton(null, null, null, function (obj) {
        wikEd.GetText(obj, 'selection, cursor')
        if (obj.selection.plain !== '') {
          obj.changed = obj.selection
        } else {
          obj.changed = obj.cursor
        }
        obj.changed.plain = text
        obj.changed.keepSel = true
        return
      })
    }

    getSelectionRange() {
      let obj = {}
      obj.sel = wikEd.GetSelection()
      wikEd.ParseDOM(obj, wikEd.frameBody)
      const start = Math.min(obj.plainAnchor, obj.plainFocus)
      const end = Math.max(obj.plainAnchor, obj.plainFocus)
      return [start, end]
    }

    // 注意：由于wikEd自身的bug，当选区跨越两行以上时，range设置会静默失败
    setSelectionRange(st, en) {
      wikEd.frameWindow.focus()
      wikEd.frameBody.focus()

      let obj = {}
      obj.sel = wikEd.GetSelection()
      wikEd.ParseDOM(obj, wikEd.frameBody)

      let currentStart = Math.min(obj.plainAnchor, obj.plainFocus)
      let currentEnd = Math.max(obj.plainAnchor, obj.plainFocus)
      let [start, end] = clampSelection(obj.plainLength, [currentStart, currentEnd], [st, en])

      let i = 0
      while ((obj.plainStart[i + 1] <= start) && (obj.plainStart[i + 1] !== undefined)) {
        i++
      }
      const startNode = obj.plainNode[i]
      const startOffset = start - obj.plainStart[i]

      let j = i
      while ((obj.plainStart[j + 1] <= end) && (obj.plainStart[j + 1] !== undefined)) {
        j++
      }
      const endNode = obj.plainNode[j]
      const endOffset = end - obj.plainStart[j]

      if (startNode && endNode) {
        const range = wikEd.frameDocument.createRange()
        wikEd.SetRange(range, startNode, startOffset, endNode, endOffset)

        obj.sel.removeAllRanges()
        obj.sel.addRange(range)

        wikEd.ScrollToSelection()
      }
    }

    focus() {
      wikEd.frameWindow.focus()
    }

    async insertText(text, pos, { select = true, replace = true } = {}) {
      if (Array.isArray(pos)) {
        this.setSelectionRange(pos[0], pos[1])
      } else if (typeof pos === 'number') {
        this.setSelectionRange(pos, pos)
      } else if (!replace) {
        const [, end] = this.getSelectionRange()
        if (end !== null) {
          this.setSelectionRange(end, end)
        } else {
          return false
        }
      }

      wikEd.EditButton(null, null, null, (obj) => {
        wikEd.GetText(obj, 'selection, cursor')

        if (replace && obj.selection.plain !== '') {
          obj.changed = obj.selection
        } else {
          obj.changed = obj.cursor
        }

        obj.changed.plain = text
        obj.changed.keepSel = select // 是否保留选区
      })

      return true
    }

    scrollToLine(n) {
      const body = wikEd.frameBody
      let targetNode = null
      let lineCount = 1

      // 寻找第n行的起始节点
      const walker = wikEd.frameDocument.createTreeWalker(
        body,
        NodeFilter.SHOW_ALL,
        null,
        false
      )

      let node = body.firstChild
      if (n === 1) {
        targetNode = node || body
      } else {
        // 循环直到找到第n-1个<br>，它的下一个节点就是第n行
        while (node) {
          if (node.nodeName === 'BR') {
            lineCount++
            if (lineCount === n) {
              targetNode = node.nextSibling || node
              break
            }
          }
          node = walker.nextNode()
        }
      }

      if (targetNode) {
        // 如果节点是文本节点，或者为了更精确的定位，
        // 我们可以创建一个临时 span 插入其中
        const scrollSpan = wikEd.frameDocument.createElement('span')
        scrollSpan.className = 'wikEdScrollBefore'

        try {
          // 插入锚点
          if (targetNode.nodeName === 'BR') {
            targetNode.parentNode.insertBefore(scrollSpan, targetNode.nextSibling)
          } else {
            targetNode.parentNode.insertBefore(scrollSpan, targetNode)
          }

          wikEd.ScrollToNodes(scrollSpan, scrollSpan)

          // 清理锚点
          scrollSpan.parentNode.removeChild(scrollSpan)
        } catch (e) {
          // 如果DOM插入失败，尝试直接滚动到节点
          wikEd.ScrollToNodes(targetNode, targetNode)
        }
      }
    }

    scrollToCursor() {
      wikEd.ScrollToSelection()
    }
  }

  // 2.3 - CodeMirror 6（新版）
  class CodeMirror6Api extends BaseApi {
    constructor(cm) {
      super()
      this._cm = cm
      this._view = cm.view
    }

    get mode() {
      return 'codemirror6'
    }

    get text() {
      return this._view.state.doc.toString()
    }

    set text(t) {
      this._view.dispatch({
        changes: {
          from: 0,
          to: this._view.state.doc.length,
          insert: t
        }
      })
    }

    get selectionText() {
      return this._cm.textSelection.getSelection()
    }

    set selectionText(text) {
      this._cm.textSelection.replaceSelection(text)
    }

    setSelectionRange(start, end) {
      const [currentStart, currentEnd] = this._cm.textSelection.getCaretPosition({ startAndEnd: true })
      const [newStart, newEnd] = clampSelection(this._view.state.doc.length, [currentStart, currentEnd], [start, end])
      this._cm.textSelection.setSelection({
        start: newStart,
        end: newEnd
      })
    }

    getSelectionRange() {
      const [start, end] = this._cm.textSelection.getCaretPosition({ startAndEnd: true })
      return [start, end]
    }

    get lineCount() {
      const txt = this.text || ''
      return txt.split('\n').length
    }

    getLine(n) {
      if (n < 1) return null
      const lines = (this.text || '').split('\n')
      const line = lines[n - 1]
      if (line === undefined) {
      	return null
      }
      return line
    }

    indexToPos(index) {
      const doc = this._view.state.doc
      const safeIndex = clampIndex(index, doc.length)
      const lineObj = doc.lineAt(safeIndex)
      return [lineObj.number, safeIndex - lineObj.from]
    }

    posToIndex(line, col) {
      const doc = this._view.state.doc
      const lineCount = doc.lines

      // 边界处理
      if (line < 1) {
        return 0
      }
      if (line > lineCount) {
        return doc.length
      }

      const lineObj = doc.line(line)
      // col 越界处理：如果 col 超过行长度，则卡在行末
      const safeCol = clampIndex(col, lineObj.length)

      return lineObj.from + safeCol
    }

    focus() {
      this._view.focus()
    }

    async insertText(text, pos, { select = true, replace = true } = {}) {
      const state = this._view.state
      const mainSel = state.selection.main

      let from, to
      const textLen = state.doc.length
      if (Array.isArray(pos)) {
        from = clampIndex(pos[0], textLen)
        to = clampIndex(pos[1], textLen)
      } else if (typeof pos === 'number') {
        from = to = clampIndex(pos, textLen)
      } else {
        from = replace ? mainSel.from : mainSel.to
        to = mainSel.to
        if (from === null || to === null) {
          return false
        }
      }

      const transaction = {
        changes: { from, to, insert: text },
        scrollIntoView: true
      }

      if (select) {
        transaction.selection = { anchor: from, head: from + text.length }
      }

      this._view.dispatch(transaction)
      this._view.focus()
      return true
    }

    scrollToLine(n) {
      const doc = this._view.state.doc
      const safeLine = clampLine(n, doc.lines)
      const lineObj = doc.line(safeLine)
      const EditorView = this._view.constructor
      this._view.dispatch({
        effects: [
          EditorView.scrollIntoView(lineObj.from, { y: 'center' })
        ]
      })
    }

    scrollToCursor() {
      this._view.dispatch({ scrollIntoView: true })
    }
  }

  // 2.4 - CodeMirror 5（旧版）
  class CodeMirror5Api extends BaseApi {
    constructor() {
      super()
    }

    get mode() {
      return 'codemirror'
    }

    get text() {
      const cm = this._getInstance()
      if (!cm) {
      	return null
      }
      return cm.getValue()
    }

    set text(text) {
      const cm = this._getInstance()
      if (cm) {
      	return cm.setValue(text)
      }
    }

    get selectionText() {
      const cm = this._getInstance()
      if (!cm) {
        return ''
      }
      return cm.getSelection()
    }

    set selectionText(text) {
      const cm = this._getInstance()
      if (!cm) {
        return
      }
      cm.replaceSelection(text, 'around')
    }

    setSelectionRange(start, end) {
      const cm = this._getInstance()
      if (!cm) {
        return
      }
      const [currentStart, currentEnd] = this.getSelectionRange()
      const [newStart, newEnd] = clampSelection(
        cm.getValue().length,
        [currentStart, currentEnd],
        [start, end]
      )
      cm.setSelection(cm.posFromIndex(newStart), cm.posFromIndex(newEnd))
    }

    getSelectionRange() {
      const cm = this._getInstance()
      if (!cm) {
        return [null, null]
      }

      const from = cm.getCursor('from')
      const to = cm.getCursor('to')

      return [
        cm.indexFromPos(from),
        cm.indexFromPos(to)
      ]
    }

    focus() {
      const cm = this._getInstance()
      if (cm) {
      	cm.focus()
      }
    }

    indexToPos(index) {
      const cm = this._getInstance()
      if (!cm) {
        return [1, 0]
      }
      const safeIndex = clampIndex(index, cm.getValue().length)
      const pos = cm.posFromIndex(safeIndex)
      return [pos.line + 1, pos.ch]
    }

    posToIndex(line, col) {
      const cm = this._getInstance()
      if (!cm) {
        return 0
      }

      const safeLine = clampLine(line, cm.lineCount())
      const lineText = cm.getLine(safeLine - 1) || ''
      const safeCol = clampIndex(col, lineText.length)

      return cm.indexFromPos({ line: safeLine - 1, ch: safeCol })
    }

    async insertText(text, pos, { select = true, replace = true } = {}) {
      const cm = this._getInstance()
      if (!cm) {
        return false
      }

      let from, to
      const textLen = cm.getValue().length
      if (Array.isArray(pos)) {
        from = cm.posFromIndex(clampIndex(pos[0], textLen))
        to = cm.posFromIndex(clampIndex(pos[1], textLen))
      } else if (typeof pos === 'number') {
        from = to = cm.posFromIndex(clampIndex(pos, textLen))
      } else {
        const sel = cm.listSelections()[0]
        from = replace ? sel.from() : sel.to()
        to = sel.to()
        if (from === null || to === null) {
          return false
        }
      }

      // 执行替换
      cm.replaceRange(text, from, to)

      if (select) {
        // 计算插入后的结束位置
        const newEndIndex = cm.indexFromPos(from) + text.length
        const newEndPos = cm.posFromIndex(newEndIndex)
        cm.setSelection(from, newEndPos)
      } else {
        // 移动光标到插入内容之后
        const newEndIndex = cm.indexFromPos(from) + text.length
        const newEndPos = cm.posFromIndex(newEndIndex)
        cm.setCursor(newEndPos)
      }

      cm.focus()
      return true
    }

    scrollToLine(n) {
      const cm = this._getInstance()
      if (!cm) {
        return
      }
      const safeLine = clampLine(n, cm.lineCount())
      cm.scrollIntoView({ line: safeLine - 1, ch: 0 }, 200)
    }

    scrollToCursor() {
      const cm = this._getInstance()
      if (cm) {
      	cm.scrollIntoView(null)
      }
    }

    _getInstance() {
      const el = document.querySelector('.CodeMirror')
      return el ? el.CodeMirror : null
    }
  }

  // 2.5 - Wikiplus & InPageEdit
  class QuickEditApi extends BaseApi {
    constructor({
      textboxSelector,
      summarySelector,
      minorEditSelector,
      submitSelector,
      diffSelector,
      previewSelector,
      mode = 'none'
    } = {}) {
      super({
        textboxSelector,
        summarySelector,
        minorEditSelector,
        submitSelector,
        diffSelector,
        previewSelector
      })
      this._mode = mode

    }

    get mode() {
      return this._mode
    }

    get text() {
      const cm = this._getInstance()
      if (cm) {
        return cm.view.state.doc.toString()
      } else {
        return $(this._textboxSelector).val()
      }
    }

    set text(v) {
      const cm = this._getInstance()
      if (cm) {
        cm.view.dispatch({
          changes: {
            from: 0,
            to: cm.view.state.doc.length,
            insert: v
          }
        })
      } else {
        $(this._textboxSelector).val(v)
      }
    }

    get selectionText() {
      const cm = this._getInstance()
      if (cm) {
        const mainSel = cm.view.state.selection.main
        return cm.view.state.sliceDoc(mainSel.from, mainSel.to)
      } else {
        return super.selectionText
      }
    }

    set selectionText(text) {
      const cm = this._getInstance()
      if (cm) {
        const mainSel = cm.view.state.selection.main
        cm.view.dispatch({
          changes: {
            from: mainSel.from,
            to: mainSel.to,
            insert: text
          },
          selection: { anchor: mainSel.from, head: mainSel.from + text.length }
        })
      } else {
        super.selectionText = text
      }
    }

    setSelectionRange(start, end) {
      const cm = this._getInstance()
      if (cm) {
        const mainSel = cm.view.state.selection.main
        const [currentStart, currentEnd] = [mainSel.from, mainSel.to]
        const [newStart, newEnd] = clampSelection(cm.view.state.doc.length, [currentStart, currentEnd], [start, end])
        cm.view.dispatch({
          selection: { anchor: newStart, head: newEnd },
          scrollIntoView: true
        })
        cm.view.focus()
      } else {
        if (!this._textboxSelector) {
          return
        }
        const textbox = document.querySelector(this._textboxSelector)
        if (!textbox) {
          return
        }
        const [newStart, newEnd] = clampSelection(textbox.value.length, [textbox.selectionStart, textbox.selectionEnd], [start, end])
        textbox.selectionStart = newStart
        textbox.selectionEnd = newEnd
      }
    }

    getSelectionRange() {
      const cm = this._getInstance()
      if (cm) {
        const mainSel = cm.view.state.selection.main
        return [mainSel.from, mainSel.to]
      } else {
        return super.getSelectionRange()
      }
    }

    focus() {
      const cm = this._getInstance()
      if (cm) {
        cm.view.focus()
      } else {
        super.focus()
      }
    }

    async insertText(text, pos, { select = true, replace = true } = {}) {
      const cm = this._getInstance()
      if (cm) {
        const view = cm.view
        const state = view.state
        const mainSel = state.selection.main

        let from, to
        const textLen = state.doc.length
        if (Array.isArray(pos)) {
          from = clampIndex(pos[0], textLen)
          to = clampIndex(pos[1], textLen)
        } else if (typeof pos === 'number') {
          from = to = clampIndex(pos, textLen)
        } else {
          from = replace ? mainSel.from : mainSel.to
          to = mainSel.to
          if (from === null || to === null) {
            return false
          }
        }

        const transaction = {
          changes: { from, to, insert: text },
          scrollIntoView: true
        }

        if (select) {
          transaction.selection = { anchor: from, head: from + text.length }
        }

        view.dispatch(transaction)
        view.focus()
        return true
      } else {
        return super.insertText(text, pos, { select, replace })
      }
    }

    scrollToLine(n) {
      const cm = this._getInstance()
      if (cm) {
        const view = cm.view
        const doc = view.state.doc
        const safeLine = clampLine(n, doc.lines)
        const lineObj = doc.line(safeLine)
        const EditorView = view.constructor
        view.dispatch({
          effects: [
            EditorView.scrollIntoView(lineObj.from, { y: 'center' })
          ]
        })
      } else {
        return super.scrollToLine(n)
      }
    }

    scrollToCursor() {
      const cm = this._getInstance()
      if (cm) {
        cm.view.dispatch({ scrollIntoView: true })
      } else {
        return super.scrollToCursor()
      }
    }

    _getInstance() {
      if (!this._textboxSelector) {
        return null
      }
      const targetTextarea = document.querySelector(this._textboxSelector)
      if (targetTextarea && window.CodeMirror6 && CodeMirror6.instances) {
        return CodeMirror6.instances.get(targetTextarea)
      }
      return null
    }
  }

  // 2.7 - AceEditor
  class AceEditorApi extends BaseApi {
    constructor(session) {
      super()
      this._session = session
    }

    get mode() {
      return 'codeeditor'
    }

    get text() {
      return this._session.getValue()
    }

    set text(t) {
      this._session.setValue(t)
    }

    get selectionText() {
      const selection = this._session.getSelection()
      const doc = this._session.getDocument()
      return doc.getTextRange(selection.getRange())
    }

    set selectionText(text) {
      const selection = this._session.getSelection()
      this._session.replace(selection.getRange(), text)
    }

    setSelectionRange(start, end) {
      const AceRange = ace.require('ace/range').Range
      const doc = this._session.getDocument()
      const selection = this._session.getSelection()
      const range = selection.getRange()

      const currentStart = doc.positionToIndex(range.start)
      const currentEnd = doc.positionToIndex(range.end)

      const [newStart, newEnd] = clampSelection(
        doc.getValue().length,
        [currentStart, currentEnd],
        [start, end]
      )

      const startPos = doc.indexToPosition(newStart)
      const endPos = doc.indexToPosition(newEnd)

      selection.setSelectionRange(
        new AceRange(startPos.row, startPos.column, endPos.row, endPos.column)
      )
    }

    getSelectionRange() {
      const selection = this._session.getSelection()
      const start = selection.getRange().start
      const end = selection.getRange().end
      const doc = this._session.getDocument()
      const startPos = doc.positionToIndex(start)
      const endPos = doc.positionToIndex(end)
      return [startPos, endPos]
    }

    indexToPos(index) {
      const doc = this._session.getDocument()
      const safeIndex = clampIndex(index, doc.getValue().length)
      const pos = doc.indexToPosition(safeIndex)
      return [pos.row + 1, pos.column]
    }

    posToIndex(line, col) {
      const doc = this._session.getDocument()
      const safeRow = clampIndex(line - 1, doc.getLength() - 1)
      const lineText = doc.getLine(safeRow)
      const safeCol = clampIndex(col, lineText.length)
      return doc.positionToIndex({ row: safeRow, column: safeCol })
    }

    focus() {
      const ace = this._getEditor()
      if (ace) {
      	ace.focus()
      }
    }

    async insertText(text, pos, { select = true, replace = true } = {}) {
      const doc = this._session.getDocument()
      const Range = ace.require('ace/range').Range

      let range
      const docLen = doc.getValue().length
      if (Array.isArray(pos)) {
        const p1 = doc.indexToPosition(clampIndex(pos[0], docLen))
        const p2 = doc.indexToPosition(clampIndex(pos[1], docLen))
        range = new Range(p1.row, p1.column, p2.row, p2.column)
      } else if (typeof pos === 'number') {
        const p = doc.indexToPosition(clampIndex(pos, docLen))
        range = new Range(p.row, p.column, p.row, p.column)
      } else {
        const selRange = this._session.getSelection().getRange()
        if (replace) {
          range = selRange
        } else {
          range = new Range(selRange.end.row, selRange.end.column, selRange.end.row, selRange.end.column)
        }
      }

      this._session.replace(range, text)

      const startIdx = doc.positionToIndex(range.start)
      const endPos = doc.indexToPosition(startIdx + text.length)
      const selection = this._session.getSelection()

      if (select) {
        selection.setSelectionRange(
          new Range(range.start.row, range.start.column, endPos.row, endPos.column)
        )
      } else {
        selection.clearSelection()
        selection.moveCursorToPosition(endPos)
      }

      this.scrollToCursor()
      return true
    }

    scrollToLine(n) {
      const ace = this._getEditor()
      if (ace) {
        ace.scrollToLine(n - 1, true, true)
      }
    }

    scrollToCursor() {
      const ace = this._getEditor()
      if (ace && ace.renderer) {
        ace.renderer.scrollCursorIntoView()
      }
    }

    _getEditor() {
      const aceItem = document.querySelector('.ace_editor')
      if (aceItem && aceItem.env && aceItem.env.editor) {
      	return aceItem.env.editor
      }
      return null
    }
  }

