}

.infobox {
    margin: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    width: 300px;
    padding: 10px;
    border: 1px solid #ccc;
    background-color: rgba(249, 249, 249, 0.85);
}

.infobox-header {
    font-size: 1.5em;
    font-weight: bold;
}

.infobox-content {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-around;
}

.infobox-item {
    flex: 1;
    padding: 5px;
}

.infobox-container {
