@keyframes Highlight {
    0%, 70% {
        background-color: rgba(255, 152, 0, 0.5);
        border-top: 2px solid #ff9800;
        border-bottom: 2px solid #ff9800;
    }
    100% {
        background-color: transparent;
        border-top: 2px solid transparent;
        border-bottom: 2px solid transparent;
    }
}
tr:target td {
    animation: Highlight 4s ease-out forwards !important;
}

tr:target td:first-child {
    animation: Highlightt 4s ease-out forwards,
               Highlight 4s ease-out forwards !important;
}

tr:target td:last-child {
    animation: Highlight 4s ease-out forwards,
               Highlight 4s ease-out forwards !important;
}
