@keyframes highlight-fade-out {
    0%, 70% {
        background-color: rgba(255, 152, 0, 0.5);
        border-top: 2px solid #ff9800;
        border-bottom: 2px solid #ff9800;
    }
    100% {
        background-color: transparent;
        border-top: 2px solid transparent;
        border-bottom: 2px solid transparent;
    }
}

@keyframes highlight-fade-out-left {
    0%, 70% { border-left: 2px solid #ff9800; }
    100% { border-left: 2px solid transparent; }
}

@keyframes highlight-fade-out-right {
    0%, 70% { border-right: 2px solid #ff9800; }
    100% { border-right: 2px solid transparent; }
}
tr:target td {
    animation: highlight-fade-out 4s ease-out forwards !important;
}

tr:target td:first-child {
    animation: highlight-fade-out 4s ease-out forwards,
               highlight-fade-out-left 4s ease-out forwards !important;
}

tr:target td:last-child {
    animation: highlight-fade-out 4s ease-out forwards,
               highlight-fade-out-right 4s ease-out forwards !important;
}
