/*Testing Zone*/
#FeaturedPage{
    max-width: 500px !important;
    display: flex;
    padding: 100px;
    margin: 50px 200px 0px 200px;
    border-radius: 20px;
    border: 1px solid black;
    justify-content: left;
    justify-items: center;
    flex-wrap: nowrap;
    align-items: center;
    background-color: #FFF4AD;
    padding-bottom: 100px;
}
/*Not Testing Zone*/
body{
	max-width: 1500px;
    margin-left: auto;
    margin-right: auto;
    width: 150%;
    min-width: 1200px !important;
    overflow-x: auto !important;
}

#content, #mw-content-text, .mw-body {
    width: 1200px !important;
    margin: 0 auto;
}

.infobox {
    margin: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    width: 300px;
    padding: 10px;
    border: 1px solid #ccc;
    background-color: rgba(249, 249, 249, 0.85);
}

.infobox-header {
    font-size: 1.5em;
    font-weight: bold;
}

.infobox-content {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-around;
}

.infobox-item {
    flex: 1;
    padding: 5px;
}

.infobox-container {
    display: flex;
    justify-content: space-around;
    flex-wrap: wrap;
}
.bdb-wnav-header{
	color: ghostwhite !important;
}
:root{
	/*----Page Stuff----*/
	--background: #FFFAD4; /*Site Background Color*/
	--link: #70B767; /*Site Link Color*/
	--site-hovered-link: #64965d; /*Hovered Link*/
	--pagetext: #000; /*Page Text Black*/
	/*----Editor Tab----*/
	--editor-tab-color: linear-gradient(#3a7bd5, #2a5298);
	--highlight-for-tabs: linear-gradient(#0000ac, #245292);
	/*----Portable Infobox----*/
	--linkdefault: #52bdff; /*Links Default Blue Color In Portable Infobox*/
	--linkhovered: #42a7f5; /*Hovered Link*/
	--nolink: #f00; /*No Link Or New Page*/
	--portable-infobox-color: #6c6c6c;
	--pi-secondary-background: #6c6c6c; /*Border Color*/
	/*---Catlinks---*/
	--catlinks: #FFF;
}
:root.client-darkmode{
	/*----Page Stuff----*/
	--background: #353535; /*Site Darkmode Background Color*/
	--link: #FFE26B; /*Site Dark Link Color*/
	--site-hovered-link: #fad12a; /*Hovered Link*/
	--pagetext: #FFFFFF; /*Page Text White On Darkmode*/
	/*----Portable Infobox----*/
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlinks: #555555;
}
:root.client-theme-clientref-night{
	/*----Page Stuff----*/
	--background: #353535; /*Site Darkmode Background Color*/
	--link: #FFE26B; /*Site Dark Link Color*/
	--site-hovered-link: #fad12a; /*Hovered Link*/
	--pagetext: #FFFFFF; /*Page Text White On Darkmode*/
	/*----Portable Infobox----*/
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlinks: #555555;
}

@keyframes Hightlight{
    5%{ background-color: #62e8f7;}
    50%{ background-color: #62e8f7;}
}
table>tbody>tr:target{
    animation: Hightlight 3s ease-in !important;
    -webkit-animation: Hightlight 3s ease-in !important;
}
h1:target+p,h2:target+p,h3:target+p,h4:target+p,h5:target+p,h6:target+p{
    animation: Hightlight 3s ease-in !important;
    -webkit-animation: Hightlight 3s ease-in !important;
}
/*Custom IDs/Classes*/
/*Dialog-Related*/
html.client-darkmode .wikitable .dialog-related tr{
	font-size:110% !important;
	white-space:nowrap !important;
	text-shadow: 0 0 1px black, 0 0 1px black, 0 0 1px black, 0 0 1px black, 0 0 1px black !important;
}
/*Custom Table oOf Contents In The Waterfall Style, Copied A Part From Roblox Isle Wiki Fandom*/
#custom-toc .toc {
	display: flex;
	flex-wrap: nowrap;
	align-items: flex-start;
	justify-content: space-evenly;
	flex-direction: column;
	align-content: space-around;
    width: 100% !important;
    max-width: 98% !important;
    clear: both !important;
    margin: 0 0 1em 0 !important;
    float: none !important;
}
#custom-toc .toc, 
#custom-toc .toc ul {
    column-width: 180px; 
    column-gap: 20px;
    list-style: none;
    padding: 0;
}

#custom-toc .toc li {
    break-inside: avoid;
    margin-bottom: 5px;
}

#custom-toc .toc ul,#custom-toc .toc li,#custom-toc .toc{
    -webkit-column-break-inside: avoid !important;
    page-break-inside: avoid !important;
    break-inside: avoid-column !important;
}
/*Codes From Roblox Isle Wiki Fandom, This Part... Yeah Yeah*/
#custom-toc .toc:has(> ul > :nth-child(7)) { 
  width: 100%; 
} 
#custom-toc .toc > ul:has(> :nth-child(7)) { 
  column-count: 4; 
  max-width: unset !important; 
  padding: 3px; 
}


/*Portable Infobox, Aka The Stuff In Templates*/
.portable-infobox a{
	color: var(--linkdefault) !important;
}
.portable-infobox a:hover{
	color: var(--linkhovered) !important
}
.portable-infobox a.new{
	color: var(--nolink) !important;
}
html.client-darkmode .portable-infobox,html.client-theme-clientref-night .portable-infobox{
    color: ghostwhite;
}
.pi-layout-default{
    border: 1px solid var(--portable-infobox-color);
    background: transparent;
}
.pi-item.pi-header.pi-secondary-font.pi-item-spacing.pi-secondary-background{ /*Versions (Non-Active)*/
	background: var(--portable-infobox-color);
	color: ghostwhite !important;
}
.pi-section-tab.pi-item-spacing.pi-section-active{ /*versions (active)*/
	background: var(--portable-infobox-color);
	color: ghostwhite !important;
	font-weight: bold;
}
.pi-section-tab.pi-item-spacing{ /*Multi Images (Non-Active)*/
	background: transparent;
}
.pi-tab-link.pi-item-spacing.current{ /*Infobox Images (Current)*/
	background: var(--portable-infobox-color);
	font-weight: bold;
	color: ghostwhite !important;
}

/*catlinks*/
.catlinks{
	background: var(--catlinks);
}
/*Table (Normal One)*/
.table, .skin-theme-clientpref-night table, html.client-darkmode table{
	background: transparent
}
/*Tables*/
.fandom-table,.article-table,.wikitable td{
	background: var(--background)
}
.wikitable th{
	background: #F2EEC9;
	color: black bold;
}
html.client-darkmode .wikitable .mw-collapsible .mw-made-collapsible tr,
html.client-theme-clientref-night .wikitable .mw-collapsible .mw-made-collapsible tr{
	color: white bold;
}
html.client-darkmode .wikitable td,html.client-theme-clientref-night .wikitable td{
	background: var(--background);
	color: white;
}
html.client-darkmode .wikitable th,html.client-theme-clientref-night .wikitable th{
	background: #535353;
	color: ghostwhite;
}
html.client-darkmode .wikitable,html.client-theme-clientref-night > caption{
	font-weight: bold;
	color: ghostwhite;
}

/*Images In Page*/
figure[typeof~='mw:File/Thumb'] figcaption, .mw-file-description, img.mw-file-element, .mw-file-element {
	background: transparent !important;
	margin: 0px !important;
	color: black!important;
}
/*Disable The Thumbnail On Images*/
#content .gallerybox div.thumb,
li.gallerybox div.thumb {
	background: none;
    border: 0px !important;
}

