/* Report‑to‑Steward‑Requests‑Global.js
 * Posts lock reports directly to Steward requests/Global
 * Handles usernames that may contain commas
 */

mw.loader.using(['mediawiki.api', 'mediawiki.util'], function () {
  $(function () {
    var $form = $('<div>').css({ padding: '1em', border: '1px solid #ccc', background: '#f9f9f9' });
    $form.append('<h3>Report user(s) for global lock</h3>');
    $form.append('<label>Section title (reporter may change): </label><input id="reportTitle" style="width:300px" placeholder="Username of user being locked"><br><br>');

    // Username list container
    var $userContainer = $('<div id="userContainer">');
    $form.append($userContainer);
    $form.append('<button id="addUser">Add another username</button><br><br>');

    $form.append('<label>Reason: </label><input id="reason" style="width:300px" placeholder="Include your reason here"><br><br>');
    $form.append('<button id="submitReport">Submit report</button>');
    $('#mw-content-text').prepend($form);

    // Add first username field
    function addUserField() {
      var $row = $('<div class="userRow">').css({ margin: '5px 0' });
      $row.append('<input class="username" style="width:200px" placeholder="username"> ');
      $row.append('<label><input type="checkbox" class="hideName"> Hide?</label>');
      $userContainer.append($row);
    }
    addUserField();

    $('#addUser').click(function (e) {
      e.preventDefault();
      addUserField();
    });

    // Handle submission
    $('#submitReport').click(async function () {
      var title = $('#reportTitle').val().trim();
      var reason = $('#reason').val().trim() || 'No reason provided';
      var users = [];
      $('#userContainer .userRow').each(function () {
        var uname = $(this).find('.username').val().trim();
        var hide = $(this).find('.hideName').is(':checked');
        if (uname) users.push({ name: uname, hide: hide });
      });

      if (!title || users.length === 0) {
        alert('Please fill in the title and at least one username.');
        return;
      }

      // Build wikitext
      var wikitext = '== ' + title + ' ==\n{{status}}\n';
      if (users.length === 1) {
        var u = users[0];
        wikitext += '*{{LockHide|' + u.name + (u.hide ? '|hidename=1' : '') + '}}\n';
      } else {
        users.forEach(function (u) {
          wikitext += '*{{MultiLock|' + u.name + (u.hide ? '|hidename=1' : '') + '}}\n';
        });
      }
      wikitext += '*:' + reason + ' [[User:PB2008|PB2008]] ([[User talk:PB2008|talk]]) 14:01, 24 May 2026 (UTC)';

      // Post to Steward requests/Global
      var api = new mw.Api();
      try {
        await api.postWithEditToken({
          action: 'edit',
          title: 'Steward requests/Global',
          appendtext: '\n' + wikitext + '\n',
          summary: 'Reporting user(s) for global lock'
        });
        mw.notify('Report successfully submitted to Steward requests/Global', { type: 'success' });
      } catch (e) {
        mw.notify('Error submitting report: ' + e, { type: 'error' });
      }
    });
  });
});

