.playground {
    position: relative;
    width: 800px;
    height: 500px;
    background-color: #e0e0e0;
    overflow: hidden;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}

.sky {
    height: 80px;
    background: linear-gradient(to bottom, #87CEEB, #E0F6FF);
}

/* 马路两边 */
.road-side-1, .road-side-2 {
    height: 50px;
    background-color: #70ad47; /* 草地绿 */
    position: relative;
}
.road-side-1 { border-bottom: 5px solid #999; }
.road-side-2 { border-top: 5px solid #999; }

/* 马路与车道线 */
.road {
    position: relative;
    height: 240px;
    background-color: #444;
}
.center-line {
    position: absolute;
    top: 50%;
    left: 0;
    width: 100%;
    height: 4px;
    border-top: 4px dashed #fff;
    transform: translateY(-50%);
}

/* 斑马线 */
.crosswalk {
    position: absolute;
    left: 350px;
    top: 0;
    width: 100px;
    height: 100%;
    background: repeating-linear-gradient(to right, #fff, #fff 15px, transparent 15px, transparent 30px);
    opacity: 0.7;
}

/* ==================== 2. 红绿灯组件 (16s 周期) ==================== */
.light-1 {
    position: absolute;
    left: 460px;
    top: 60px;
    z-index: 10;
}
.light-pole {
    width: 8px;
    height: 70px;
    background-color: #777;
    margin-left: 11px;
}
.light-socket {
    width: 30px;
    height: 70px;
    background-color: #222;
    border-radius: 5px;
    padding: 5px 0;
    display: flex;
    flex-direction: column;
    justify-content: space-around;
    align-items: center;
    position: absolute;
    top: -70px;
}
.light-red, .light-yellow, .light-green {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background-color: #444; /* 默认暗色 */
}

/* 红绿灯动画时间轴对齐 */
.light-green  { animation: greenLightAnim 16s infinite; }
.light-yellow { animation: yellowLightAnim 16s infinite; }
.light-red    { animation: redLightAnim 16s infinite; }

@keyframes greenLightAnim {
    0%, 43.75% { background-color: #ff3333; box-shadow: 0 0 10px #ff3333; } /* 0s-7s 行人视角红灯=车辆绿灯 */
    43.76%, 100% { background-color: #444; box-shadow: none; }
}
@keyframes yellowLightAnim {
    0%, 43.75% { background-color: #444; box-shadow: none; }
    43.76%, 56.25% { background-color: #ffcc00; box-shadow: 0 0 10px #ffcc00; } /* 7s-9s 黄灯 */
    56.26%, 100% { background-color: #444; box-shadow: none; }
}
@keyframes redLightAnim {
    0%, 56.25% { background-color: #444; box-shadow: none; }
    56.26%, 100% { background-color: #00ff00; box-shadow: 0 0 10px #00ff00; } /* 9s-16s 行人视角绿灯=车辆红灯 */
}

/* ==================== 3. 😈🫱🏻👵🏻 行人动画 ==================== */
/* 因为是“闯红灯”，所以：
   0s - 7s (行人红灯): 😈带着老太太穿越马路！
   7s - 9s (黄灯): 到达对面，在路边罚站等待。
   9s - 16s (行人绿灯): 规规矩矩在路边看着，绝不过马路。
*/
.people {
    position: absolute;
    left: 375px;
    top: 95px; /* 初始在上侧路边 */
    font-size: 24px;
    z-index: 5;
    transform: rotate(90deg); /* 调整emoji方向向下走 */
    animation: walkAnim 16s infinite ease-in-out;
}

@keyframes walkAnim {
    0% { top: 95px; transform: rotate(90deg); }
    37.5% { top: 375px; transform: rotate(90deg); } /* 0s-6s 耗时穿过马路到达下侧 */
    43.75%, 56.25% { top: 375px; transform: rotate(270deg); } /* 黄灯时期在下侧调转方向 */
    56.26%, 93.75% { top: 375px; transform: rotate(270deg); } /* 行人绿灯时，死活不动 */
    93.76% { top: 375px; transform: rotate(270deg); } 
    100% { top: 95px; transform: rotate(270deg); } /* 突然瞬移或者在最后周期迅速走回上方（这里设定为15-16s瞬间原路返回准备下一次闯红灯） */
}

/* ==================== 4. 车辆动画 (靠右行驶) ==================== */
.cars {
    position: absolute;
    width: 100%;
    height: 240px;
    top: 130px;
}
.cars > div {
    position: absolute;
    font-size: 32px;
    z-index: 3;
}

/* 车道1：靠右行驶（下半部分，从左往右 ➔ 默认车头朝右，无需翻转） 
   车辆会在 0s-7s 畅通无阻。在 9s-16s 时，如果没过斑马线，必须在斑马线前（left: 300px）停下。
*/
.car-1, .car-2, .car-3, .car-4, .car-5, .car-6, .car-7, .car-8, .car-9, .car-10 {
    top: 140px; 
}

/* 车道2：靠右行驶（上半部分，从右往左 ➔ 车头需要向左，使用 transform: scaleX(-1)）
   车辆在 9s-16s 时，必须在斑马线前（left: 460px）停下。
*/
.car-11, .car-12, .car-13, .car-14, .car-15, .car-16, .car-17, .car-18, .car-19, .car-20 {
    top: 30px;
}

/* --- 具体的车辆动画逻辑 --- */

/* 下车道：从左往右 (斑马线在 350px，停止线在 300px) */
@keyframes driveRightStop {
    0% { left: -60px; }
    40% { left: 300px; }  /* 触发红灯前正好开到停止线 */
    56.25% { left: 300px; } /* 红灯期间死守停止线 */
    100% { left: 850px; } /* 绿灯亮起，冲出屏幕 */
}
/* 下车道：绿灯期间直接冲过去的幸运车 */
@keyframes driveRightFly {
    0% { left: -60px; }
    100% { left: 850px; }
}

/* 上车道：从右往左 (斑马线在 350px+100px，停止线在 460px) */
@keyframes driveLeftStop {
    0% { left: 850px; transform: scaleX(-1); }
    40% { left: 460px; transform: scaleX(-1); } /* 红灯停在右侧等待 */
    56.25% { left: 460px; transform: scaleX(-1); }
    100% { left: -60px; transform: scaleX(-1); }
}
@keyframes driveLeftFly {
    0% { left: 850px; transform: scaleX(-1); }
    100% { left: -60px; transform: scaleX(-1); }
}

/* ==================== 5. 随机分配车辆时间差与行为 ==================== */

/* 批次 A：赶上红灯不得不停下的车 */
.car-1  { animation: driveRightStop 16s infinite linear; animation-delay: 0s; }
.car-11 { animation: driveLeftStop  16s infinite linear; animation-delay: 0.5s; }
.car-2  { animation: driveRightStop 16s infinite linear; animation-delay: 2s; }
.car-12 { animation: driveLeftStop  16s infinite linear; animation-delay: 1.8s; }
.car-5  { animation: driveRightStop 16s infinite linear; animation-delay: 3.5s; } /* 警车也得停 */
.car-6  { animation: driveLeftStop  16s infinite linear; animation-delay: 3.2s; } /* 救护车也给大妈让路 */

/* 批次 B：在绿灯前半段就已经嗖嗖飞过去的快速车 */
.car-3  { animation: driveRightFly 6s infinite linear; animation-delay: -2s; }
.car-13 { animation: driveLeftFly  5s infinite linear; animation-delay: -1s; }
.car-4  { animation: driveRightFly 7s infinite linear; animation-delay: -4s; }
.car-14 { animation: driveLeftFly  6s infinite linear; animation-delay: -3s; }

/* 批次 C：零散错开的其他车辆 */
.car-7  { animation: driveRightFly 5.5s infinite linear; animation-delay: 8s; }
.car-15 { animation: driveLeftFly  6.5s infinite linear; animation-delay: 9s; }
.car-8  { animation: driveRightStop 16s infinite linear; animation-delay: 1s; }
.car-16 { animation: driveLeftStop  16s infinite linear; animation-delay: 2.5s; }
.car-9  { animation: driveRightFly 5s infinite linear; animation-delay: 10s; }
.car-17 { animation: driveLeftFly  5.5s infinite linear; animation-delay: 11s; }
.car-10 { animation: driveRightFly 6s infinite linear; animation-delay: 7s; }
.car-18 { animation: driveLeftFly  6s infinite linear; animation-delay: 7.5s; }
.car-19 { animation: driveRightStop 16s infinite linear; animation-delay: 4s; }
.car-20 { animation: driveLeftStop  16s infinite linear; animation-delay: 3.8s; }

/* ===== 基础场景布局 ===== */
.playground {
  position: relative;
  width: 100%;
  max-width: 800px;
  height: 480px;
  margin: 0 auto;
  background: #7ec0ee;
  overflow: hidden;
  font-family: sans-serif;
  box-shadow: 0 10px 30px rgba(0,0,0,0.3);
}

/* 天空与标题效果 */
.sky {
  height: 80px;
  background: linear-gradient(to bottom, #114488, #3388cc);
  position: relative;
}
.sky::after {
  content: "扶老太太闯红灯模拟器 😈🫱🏻👵🏻";
  position: absolute;
  bottom: 10px;
  left: 20px;
  color: white;
  font-size: 16px;
  font-weight: bold;
  letter-spacing: 2px;
  opacity: 0.8;
}

/* 上侧马路牙子 */
.road-side-1 {
  height: 40px;
  background: #aaaaaa;
  border-bottom: 4px solid #888888;
  box-sizing: border-box;
}

/* 下侧马路牙子 */
.road-side-2 {
  height: 160px;
  background: #aaaaaa;
  border-top: 4px solid #888888;
  box-sizing: border-box;
}

/* 马路主体 */
.road {
  height: 200px;
  background: #333333;
  position: relative;
}

/* 马路标线 */
.line-1, .line-2 {
  position: absolute;
  left: 0;
  width: 100%;
  height: 4px;
  background: #ffffff;
  opacity: 0.6;
}
.line-1 { top: 2px; }
.line-2 { bottom: 2px; }

.center-line {
  position: absolute;
  top: 50%;
  left: 0;
  width: 100%;
  height: 0;
  border-top: 4px dashed #ffffff;
  transform: translateY(-50%);
  opacity: 0.8;
}

/* 斑马线 */
.crosswalk {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 120px;
  height: 100%;
  background: repeating-linear-gradient(
    to bottom,
    #ffffff,
    #ffffff 15px,
    transparent 15px,
    transparent 30px
  );
  opacity: 0.8;
}

/* ===== 信号灯系统（行人视角） ===== */
/* 全局40秒循环：0%-35%红灯，35%-40%黄灯，40%-75%绿灯，75%-80%黄灯，80%-100%红灯 */
.light-1 {
  position: absolute;
  top: 65px;
  left: calc(50% - 90px); /* 放在斑马线左侧 */
  display: flex;
  flex-direction: column-reverse; /* 让灯座在灯杆上方 */
  align-items: center;
  z-index: 10;
}

.light-pole {
  width: 6px;
  height: 55px;
  background: #444444;
}

.light-socket {
  width: 24px;
  height: 65px;
  background: #222222;
  border-radius: 6px;
  display: flex;
  flex-direction: column;
  justify-content: space-around;
  align-items: center;
  padding: 4px 0;
  box-shadow: 0 4px 6px rgba(0,0,0,0.3);
}

.light-red, .light-yellow, .light-green {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #441111;
  transition: all 0.2s;
}

/* 信号灯动画控制 */
.light-red { background: #ff3333; box-shadow: 0 0 10px #ff3333; animation: red-logic 40s infinite; }
.light-yellow { background: #443300; animation: yellow-logic 40s infinite; }
.light-green { background: #114411; animation: green-logic 40s infinite; }

@keyframes red-logic {
  0%, 35%, 80%, 100% { background: #ff3333; box-shadow: 0 0 12px #ff3333; }
  35.1%, 79.9% { background: #441111; box-shadow: none; }
}
@keyframes yellow-logic {
  0%, 35%, 40.1%, 75%, 80.1%, 100% { background: #443300; box-shadow: none; }
  35.1%, 40%, 75.1%, 80% { background: #ffcc00; box-shadow: 0 0 12px #ffcc00; }
}
@keyframes green-logic {
  0%, 40%, 75.1%, 100% { background: #114411; box-shadow: none; }
  40.1%, 75% { background: #33ff33; box-shadow: 0 0 12px #33ff33; }
}

/* ===== 行人（😈🫱🏻👵🏻）动画 ===== */
.people {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  font-size: 28px;
  z-index: 5;
  width: auto;
  height: auto;
  white-space: nowrap;
  animation: pedestrian-walk 40s infinite ease-in-out;
}

@keyframes pedestrian-walk {
  /* 0%-35% 是红灯，行人强行通过 */
  0%   { top: 85px; }  /* 在上侧路边准备 */
  30%  { top: 330px; } /* 穿越马路到达下侧路边 */

  /* 35%-75% 经历黄灯和绿灯，行人在下侧路边乖乖等待 */
  35%  { top: 330px; }
  40%  { top: 330px; }
  75%  { top: 330px; }

  /* 75%-80% 黄灯转换准备 */
  80%  { top: 330px; }

  /* 80%-100% 又是红灯，行人再度折返闯红灯回去 */
  85%  { top: 330px; } /* 开始往回走 */
  98%  { top: 85px; }  /* 回到上侧路边 */
  100% { top: 85px; }
}

/* ===== 车辆动力学系统 ===== */
.cars {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.cars > div {
  position: absolute;
  font-size: 28px;
  width: 40px;
  height: 40px;
}

/* 区分车道：靠右行驶 */
/* 1-10号车：上车道，由右向左行驶（Westbound），不翻转（Emoji默认面朝左） */
.car-1, .car-2, .car-3, .car-4, .car-5, .car-6, .car-7, .car-8, .car-9, .car-10 {
  top: 135px;
}

/* 11-20号车：下车道，由左向右行驶（Eastbound），需要水平翻转 */
.car-11, .car-12, .car-13, .car-14, .car-15, .car-16, .car-17, .car-18, .car-19, .car-20 {
  top: 235px;
  transform: scaleX(-1); 
}

/* === 车辆行为控制（与红绿灯完美咬合） === */

/* 车道1 动画A组：红灯时快速通过，绿灯时在交叉路口（56%位置）排队等待 */
@keyframes move-west-A {
  0%   { left: 110%; }
  15%  { left: 110%; } /* 延时出发，避开正在通过上半马路的行人 */
  28%  { left: 56%; }  /* 顺利穿过马路 */
  38%  { left: -15%; } /* 驶出屏幕 */
  39%  { left: 110%; } /* 瞬间重置回最右侧 */
  55%  { left: 56%; }  /* 绿灯亮起，车辆驶到路口前线，被迫停下 */
  75%  { left: 56%; }  /* 持续等待直到绿灯结束 */
  86%  { left: -15%; } /* 变为红灯，立刻起步开走，并在行人返回前清除 */
  100% { left: -15%; }
}

/* 车道1 动画B组：错峰出行的车辆 */
@keyframes move-west-B {
  0%   { left: 56%; }  /* 初始就在路口，红灯亮起直接开走 */
  10%  { left: -15%; } 
  11%  { left: 110%; }
  32%  { left: 56%; }  /* 下半段红灯通过 */
  39%  { left: -15%; }
  40%  { left: 110%; }
  65%  { left: 56%; }  /* 绿灯中后期赶到路口排队 */
  75%  { left: 56%; }
  85%  { left: -15%; } /* 红灯亮起开走 */
  100% { left: -15%; }
}

/* 车道2 动画A组：由左向右，绿灯时在路口（38%位置）排队等待 */
@keyframes move-east-A {
  0%   { left: -15%; }
  12%  { left: 38%; }  /* 红灯前半段，乘行人还没走到下车道时通过 */
  24%  { left: 110%; }
  25%  { left: -15%; }
  50%  { left: 38%; }  /* 绿灯亮起，在路口前排队 */
  75%  { left: 38%; }
  83%  { left: 110%; } /* 红灯亮起迅速通过，此时行人刚从上边往下走，完美错开 */
  100% { left: 110%; }
}

/* 车道2 动画B组：另一批错峰车流 */
@keyframes move-east-B {
  0%   { left: 38%; }  /* 绿灯结束变红，开走 */
  8%   { left: 110%; }
  9%   { left: -15%; }
  34%  { left: 38%; }  /* 行人已经走过去了，红灯后半段安全通过 */
  42%  { left: 110%; }
  43%  { left: -15%; }
  62%  { left: 38%; }  /* 赶上绿灯排队 */
  75%  { left: 38%; }
  100% { left: 38%; }
}

/* === 分配动画与微调（利用 margin-left 实现逼真的车阵排队效果） === */
.car-1  { animation: move-west-A 40s infinite linear; margin-left: 0px; }
.car-2  { animation: move-west-A 40s infinite linear; margin-left: 50px; }  /* 跟在1号车后面排队 */
.car-3  { animation: move-west-A 40s infinite linear; margin-left: 100px; } /* 跟在2号车后面排队 */
.car-4  { animation: move-west-B 40s infinite linear; margin-left: 0px; }
.car-5  { animation: move-west-B 40s infinite linear; margin-left: 55px; }
.car-6  { animation: move-west-B 40s infinite linear; margin-left: 110px; }
.car-7  { animation: move-west-A 40s infinite linear; margin-left: 160px; }
.car-8  { animation: move-west-B 40s infinite linear; margin-left: 165px; }
.car-9  { animation: move-west-A 40s infinite linear; margin-left: 210px; }
.car-10 { animation: move-west-B 40s infinite linear; margin-left: 220px; }

/* 反向行驶的车排队时，后车应当在左侧，所以 margin-left 为负值 */
.car-11 { animation: move-east-A 40s infinite linear; margin-left: 0px; }
.car-12 { animation: move-east-A 40s infinite linear; margin-left: -50px; } /* 跟在11号车后面排队 */
.car-13 { animation: move-east-A 40s infinite linear; margin-left: -100px; }
.car-14 { animation: move-east-B 40s infinite linear; margin-left: 0px; }
.car-15 { animation: move-east-B 40s infinite linear; margin-left: -55px; }
.car-16 { animation: move-east-B 40s infinite linear; margin-left: -110px; }
.car-17 { animation: move-east-A 40s infinite linear; margin-left: -160px; }
.car-18 { animation: move-east-B 40s infinite linear; margin-left: -165px; }
.car-19 { animation: move-east-A 40s infinite linear; margin-left: -210px; }
.car-20 { animation: move-east-B 40s infinite linear; margin-left: -220px; }

.lta-seal {
    position: relative;
    box-sizing: border-box;
	border-radius: 4px;
}

.lta-seal > div {
    position: absolute;
    border-radius: 4px;
}

/* 白文：红底白字 */
.lta-seal.color-white {
    background-color: #c22c2c;
}
.lta-seal.color-white > div {
    background-color: #ffffff;
}

/* 朱文：白底红字 */
.lta-seal.color-red {
    background-color: transparent;
    border: 3px solid #c22c2c;
    box-sizing: content-box;
}
.lta-seal.color-red > div {
    background-color: #c22c2c;
}

.lta-seal.size-default {
    width: 60px;
    height: 60px;
}

.lta-seal.size-small {
    width: 60px;
    height: 60px;
    transform: scale(0.5);
    transform-origin: top left;
    margin-right: -45px;
    margin-bottom: -45px;
}

.lta-seal.size-large {
    width: 60px;
    height: 60px;
    transform: scale(2.0);
    transform-origin: top left;
    margin-right: 60px;
    margin-bottom: 60px;
}

/* 白文外边框 */
.lta-seal-outer.color-white.has-border {
	border: 4px solid #c22c2c;
    border-radius: 12px;
    padding: 2px;
}

.lta-seal .l-1 { width: 3px;  height: 26px; left: 32px; top: 3px;  }
.lta-seal .l-2 { width: 26px; height: 3px;  left: 32px; top: 26px; }

.lta-seal .t-1 { width: 26px; height: 3px;  left: 32px; top: 32px; }
.lta-seal .t-2 { width: 3px;  height: 26px; left: 43px; top: 32px; }

.lta-seal .a-1 { width: 3px;  height: 26px; left: 3px;  top: 3px;  }
.lta-seal .a-2 { width: 26px; height: 3px;  left: 3px;  top: 3px;  }
