/* Base body styling – no background image, just a solid fallback */
body {
    background-color: #f5f5f5;   /* light fallback (overridden in dark) */
}

/* Desktop side decorations – only on larger screens (≥1024px) */
@media (min-width: 1024px) {
    body::before,
    body::after {
        content: "";
        position: fixed;
        top: 0;
        bottom: 0;
        width: 80px;                /* adjust to your image’s width */
        z-index: 999;
        background-repeat: no-repeat;
        background-size: contain;
        background-position: center;
        pointer-events: none;       /* allows clicks to pass through */
    }

    body::before {
        left: 0;
    }

    body::after {
        right: 0;
    }
}

/* Light mode – use Art1.png */
@media (prefers-color-scheme: light) {
    body {
        background-color: #f5f5f5;
    }
    body::before,
    body::after {
        background-image: url('Art1.png');
    }
}

/* Dark mode – use Art6B.png */
@media (prefers-color-scheme: dark) {
    body {
        background-color: #1a1a1a;
    }
    body::before,
    body::after {
        background-image: url('Art6B.png');
    }
}

