    0%, 50% { background-color: #62e8f7; }
    100% { background-color: transparent; }
}

/* Target tables inside the wiki content */
.mw-parser-output table tr:target {
    animation: Highlight 3s ease-in !important;
    -webkit-animation: Highlight 3s ease-in !important;
}

/* Target elements following a linked heading wrapper */
