@keyframes Highlight {
    0%, 50% { background-color: #62e8f7; }
    100% { background-color: transparent; }
}
@-webkit-keyframes Highlight {
    0%, 50% { background-color: #62e8f7; }
    100% { background-color: transparent; }
}

/* Target tables inside the wiki content */
.mw-parser-output table tr:has(:target){
    animation: Highlight 3s ease-in !important;
    -webkit-animation: Highlight 3s ease-in !important;
}

/* Target elements following a linked heading wrapper, pls work*/
.mw-heading1:target h1 + p,
.mw-heading1:target h1 ~ p:first-of-type,
.mw-heading2:target h2 + p,
.mw-heading2:target h2 ~ p:first-of-type,
.mw-heading3:target h3 + p,
.mw-heading3:target h3 ~ p:first-of-type,
.mw-parser-output :target + table {
    animation: Highlight 3s ease-in !important;
    -webkit-animation: Highlight 3s ease-in !important;
}

/*Custom IDs/Classes*/
/*Dialog-Related*/
html.client-darkmode .wikitable .dialog-related tr{
	font-size:110% !important;
	white-space:nowrap !important;
	text-shadow: 0 0 1px black, 0 0 1px black, 0 0 1px black, 0 0 1px black, 0 0 1px black !important;
}
/*Custom Table oOf Contents In The Waterfall Style, Copied A Part From Roblox Isle Wiki Fandom*/
#custom-toc .toc {
	display: flex;
	flex-wrap: nowrap;
	align-items: flex-start;
	justify-content: space-evenly;
	flex-direction: column;
	align-content: space-around;
    width: 100% !important;
    max-width: 98% !important;
    clear: both !important;
    margin: 0 0 1em 0 !important;
    float: none !important;
}
#custom-toc .toc, 
#custom-toc .toc ul {
    column-width: 180px; 
    column-gap: 20px;
    list-style: none;
    padding: 0;
}

#custom-toc .toc li {
    break-inside: avoid;
    margin-bottom: 5px;
}

#custom-toc .toc ul,#custom-toc .toc li,#custom-toc .toc{
    -webkit-column-break-inside: avoid !important;
    page-break-inside: avoid !important;
    break-inside: avoid-column !important;
}
/*Codes From Roblox Isle Wiki Fandom, This Part... Yeah Yeah*/
#custom-toc .toc:has(> ul > :nth-child(7)) { 
  width: 100%; 
} 
#custom-toc .toc > ul:has(> :nth-child(7)) { 
  column-count: 4; 
  max-width: unset !important; 
  padding: 3px; 
}


