@keyframes Highlight {
    0%, 50% { background-color: #62e8f7; }
    100% { background-color: transparent; }
}
@-webkit-keyframes Highlight {
    0%, 50% { background-color: #62e8f7; }
    100% { background-color: transparent; }
}

/* Target tables inside the wiki content */
.mw-parser-output table tr:has(:target){
    animation: Highlight 3s ease-in !important;
    -webkit-animation: Highlight 3s ease-in !important;
}

/* Target elements following a linked heading wrapper, pls work*/
h1:target + p,
h1:target ~ p:first-of-type,
h2:target + p,
h2:target ~ p:first-of-type,
h3:target + p,
h3:target ~ p:first-of-type,
