$(function () {
    function loadCalendar(year, month) {
        var $wrap = $('#cal-wrap');
        $wrap.addClass('loading');

        var template = '{{#invoke:Calendar|render'
                     + '|year=' + year
                     + '|month=' + month + '}}';

        $.get(mw.util.wikiScript('api'), {
            action: 'parse',
            title:  mw.config.get('wgPageName'),
            text:   template,
            prop:   'text',
            format: 'json',
            disablelimitreport: 1
        }).done(function (data) {
            if (data.parse && data.parse.text) {
                $wrap.replaceWith(data.parse.text['*']);
                bindNav(); // re-bind buttons on new HTML
            }
        });
    }

    function bindNav() {
        $('.cal-nav').off('click').on('click', function (e) {
            e.preventDefault();
            loadCalendar($(this).data('year'), $(this).data('month'));
        });
    }

    bindNav();
});

/**
 * RaceRecordEditor.js
 * Gadget untuk edit template {{Result}} via dialog OOUI
 *
 * REQUIREMENTS:
 * - MediaWiki
 * - OOUI
 *
 * Letakkan di:
 * MediaWiki:Gadget-RaceRecordEditor.js
 */

( function () {

    'use strict';

    // =========================================================
    // CONFIG
    // =========================================================

    const TEMPLATE_NAME = 'Result';

    // =========================================================
    // API
    // =========================================================

    const api = new mw.Api();

    // =========================================================
    // MAIN
    // =========================================================

    $( init );

    async function init() {

        // hanya aktif jika ada wikitable
        if ( !$( '.wikitable' ).length ) {
            return;
        }

        // ambil source halaman
        const pageText = await getPageText();

        if ( !pageText.includes( '{{RaceResultTable' ) ) {
            return;
        }

        // parse semua Result
        const results = parseResultTemplates( pageText );

        // inject tombol edit
        injectButtons( results, pageText );
    }

    // =========================================================
    // GET PAGE TEXT
    // =========================================================

    async function getPageText() {

        const data = await api.get( {
            action: 'query',
            prop: 'revisions',
            titles: mw.config.get( 'wgPageName' ),
            rvprop: 'content',
            formatversion: 2
        } );

        return data.query.pages[0].revisions[0].content;
    }

    // =========================================================
    // PARSER
    // =========================================================

    function parseResultTemplates( text ) {

        const results = [];

        const regex = /\{\{Result\|([\s\S]*?)\}\}/g;

        let match;

        while ( ( match = regex.exec( text ) ) !== null ) {

            const fullTemplate = match[0];
            const inner = match[1];

            const params = parseParams( inner );

            results.push( {
                full: fullTemplate,
                params: params,
                start: match.index,
                end: regex.lastIndex
            } );
        }

        return results;
    }

    function parseParams( text ) {

        const params = {};

        text.split( '|' ).forEach( part => {

            const eq = part.indexOf( '=' );

            if ( eq === -1 ) {
                return;
            }

            const key = part.slice( 0, eq ).trim();

            const value = part.slice( eq + 1 ).trim();

            params[ key ] = value;
        } );

        return params;
    }

    // =========================================================
    // BUTTONS
    // =========================================================

    function injectButtons( results, pageText ) {

        const rows = $( '.wikitable tr' );

        let resultIndex = 0;

        rows.each( function () {

            const tdCount = $( this ).find( 'td' ).length;

            if ( tdCount === 0 ) {
                return;
            }

            // skip season rows
            if ( $( this ).text().includes( 'season' ) ) {
                return;
            }

            if ( !results[ resultIndex ] ) {
                return;
            }

            const buttonCell = $( '<td>' )
                .css( {
                    width: '40px',
                    textAlign: 'center'
                } );

            const editBtn = new OO.ui.ButtonWidget( {
                label: '✎',
                framed: true
            } );

            editBtn.on( 'click', function () {

                openEditorDialog(
                    results,
                    resultIndex,
                    pageText
                );
            } );

            buttonCell.append(
                editBtn.$element
            );

            $( this ).append( buttonCell );

            resultIndex++;
        } );
    }

    // =========================================================
    // DIALOG
    // =========================================================

    function openEditorDialog( results, index, pageText ) {

        const data = results[ index ].params;

        class ResultDialog extends OO.ui.ProcessDialog {

            initialize() {

                super.initialize();

                this.panel = new OO.ui.PanelLayout( {
                    padded: true,
                    expanded: false
                } );

                this.fields = {};

                const fieldDefs = [
                    [ 'date', 'Date' ],
                    [ 'racecourse', 'Racecourse' ],
                    [ 'entry', 'Entry' ],
                    [ 'number', 'Horse Number' ],
                    [ 'jockey', 'Jockey' ],
                    [ 'name', 'Race Name' ],
                    [ 'class', 'Class' ],
                    [ 'finished', 'Finished' ],
                    [ 'distance', 'Distance' ],
                    [ 'winner', 'Winner' ],
                    [ 'time', 'Time' ]
                ];

                fieldDefs.forEach( ( item ) => {

                    const key = item[0];
                    const label = item[1];

                    this.fields[ key ] = new OO.ui.TextInputWidget( {
                        value: data[ key ] || ''
                    } );

                    const fieldLayout = new OO.ui.FieldLayout(
                        this.fields[ key ],
                        {
                            label: label,
                            align: 'top'
                        }
                    );

                    this.panel.$element.append(
                        fieldLayout.$element
                    );
                } );

                // SOURCE textarea
                this.fields.source =
                    new OO.ui.MultilineTextInputWidget( {
                        value: data.source || '',
                        rows: 5
                    } );

                const sourceLayout =
                    new OO.ui.FieldLayout(
                        this.fields.source,
                        {
                            label: 'Source',
                            align: 'top'
                        }
                    );

                this.panel.$element.append(
                    sourceLayout.$element
                );

                this.$body.append(
                    this.panel.$element
                );
            }

            getActionProcess( action ) {

                if ( action === 'save' ) {

                    return new OO.ui.Process( async () => {

                        const newParams = {};

                        Object.keys( this.fields ).forEach( ( key ) => {

                            newParams[ key ] =
                                this.fields[ key ].getValue();
                        } );

                        const newTemplate =
                            buildTemplate( newParams );

                        const oldTemplate =
                            results[ index ].full;

                        const newText =
                            pageText.replace(
                                oldTemplate,
                                newTemplate
                            );

                        await savePage( newText );

                        mw.notify(
                            'Race result saved!'
                        );

                        location.reload();
                    } );
                }

                return super.getActionProcess( action );
            }

            getBodyHeight() {
                return 600;
            }
        }

        ResultDialog.static.name = 'ResultDialog';

        ResultDialog.static.title =
            'Edit Race Result';

        ResultDialog.static.actions = [
            {
                action: 'save',
                label: 'Save',
                flags: [ 'primary', 'progressive' ]
            },
            {
                action: 'cancel',
                label: 'Cancel',
                flags: 'safe'
            }
        ];

        const windowManager =
            new OO.ui.WindowManager();

        $( 'body' ).append(
            windowManager.$element
        );

        const dialog = new ResultDialog();

        windowManager.addWindows( [ dialog ] );

        windowManager.openWindow( dialog );
    }

    // =========================================================
    // BUILD TEMPLATE
    // =========================================================

    function buildTemplate( params ) {

        return `{{Result
|date=${ params.date || '' }
|racecourse=${ params.racecourse || '' }
|entry=${ params.entry || '' }
|number=${ params.number || '' }
|jockey=${ params.jockey || '' }
|name=${ params.name || '' }
|class=${ params.class || '' }
|finished=${ params.finished || '' }
|distance=${ params.distance || '' }
|winner=${ params.winner || '' }
|time=${ params.time || '' }
|source=${ params.source || '' }
}}`;
    }

    // =========================================================
    // SAVE
    // =========================================================

    async function savePage( text ) {

        return api.postWithToken( 'csrf', {

            action: 'edit',

            title: mw.config.get(
                'wgPageName'
            ),

            text: text,

            summary:
                'Edit race result via RaceRecordEditor gadget'
        } );
    }

} )();

$(function () {
    var root = document.getElementById('cal-root');
    if (!root) return;

    // Read initial config from Lua-generated data attributes
    var currentYear  = parseInt(root.getAttribute('data-year'),  10);
    var currentMonth = parseInt(root.getAttribute('data-month'), 10);
    var allEvents    = JSON.parse(root.getAttribute('data-events') || '{}');

    var monthNames = [
        'January','February','March','April','May','June',
        'July','August','September','October','November','December'
    ];

    // ── Helpers ──────────────────────────────────────────────
    function isLeapYear(y) {
        return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
    }

    function daysInMonth(y, m) {
        var d = [31,28,31,30,31,30,31,31,30,31,30,31];
        if (m === 2 && isLeapYear(y)) return 29;
        return d[m - 1];
    }

    // Returns 1=Mon … 7=Sun
    function firstDayOfMonth(y, m) {
        var day = new Date(y, m - 1, 1).getDay(); // 0=Sun
        return day === 0 ? 7 : day;
    }

    function getEvents(y, m, d) {
        var yr = allEvents[String(y)];  if (!yr) return [];
        var mo = yr[String(m)];         if (!mo) return [];
        return mo[String(d)] || [];
    }

    // ── Render ───────────────────────────────────────────────
    function renderCalendar(year, month) {
        var prevMonth = month - 1, prevYear = year;
        if (prevMonth < 1)  { prevMonth = 12; prevYear--;  }
        var nextMonth = month + 1, nextYear = year;
        if (nextMonth > 12) { nextMonth = 1;  nextYear++;  }

        var html = '<div class="cal-wrap"><table class="cal-table">';

        // Navigation header
        html += '<tr><td colspan="7" class="cal-header">'
             +  '<a class="cal-nav" href="#"'
             +      ' data-year="' + prevYear  + '"'
             +      ' data-month="' + prevMonth + '">&#9664;</a>'
             +  '<span class="cal-title">'
             +      monthNames[month - 1] + ' ' + year
             +  '</span>'
             +  '<a class="cal-nav" href="#"'
             +      ' data-year="' + nextYear  + '"'
             +      ' data-month="' + nextMonth + '">&#9654;</a>'
             +  '</td></tr>';

        // Day name row
        html += '<tr>';
        ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].forEach(function (h, i) {
            var cls = i === 5 ? ' class="cal-sat"'
                    : i === 6 ? ' class="cal-sun"' : '';
            html += '<th' + cls + '>' + h + '</th>';
        });
        html += '</tr>';

        // Date cells
        var firstDay  = firstDayOfMonth(year, month);
        var totalDays = daysInMonth(year, month);
        var day = 1, started = false;

        for (var row = 0; row < 6; row++) {
            if (day > totalDays) break;
            html += '<tr>';
            for (var dow = 1; dow <= 7; dow++) {
                var cellCls = dow === 6 ? ' class="cal-sat-cell"'
                            : dow === 7 ? ' class="cal-sun-cell"' : '';
                if (!started && dow === firstDay) started = true;

                if (started && day <= totalDays) {
                    html += '<td' + cellCls + '>';
                    html += '<div class="cal-day-num">' + day + '</div>';

                    var evs = getEvents(year, month, day);
                    if (evs.length) {
                        html += '<div class="cal-events">';
                        evs.forEach(function (ev) {
                            html += '<span class="cal-badge"'
                                 +       ' style="background:' + ev.color + '">'
                                 +       ev.label
                                 + '</span>';
                        });
                        html += '</div>';
                    }
                    html += '</td>';
                    day++;
                } else {
                    html += '<td' + cellCls + '></td>';
                }
            }
            html += '</tr>';
        }

        html += '</table></div>';

        // Inject into page & re-bind nav buttons
        root.innerHTML = html;
        bindNav();
    }

    // ── Navigation binding ───────────────────────────────────
    function bindNav() {
        root.querySelectorAll('.cal-nav').forEach(function (btn) {
            btn.addEventListener('click', function (e) {
                e.preventDefault();
                renderCalendar(
                    parseInt(this.getAttribute('data-year'),  10),
                    parseInt(this.getAttribute('data-month'), 10)
                );
            });
        });
    }

    // ── Boot ─────────────────────────────────────────────────
    renderCalendar(currentYear, currentMonth);
});

