/** Infobox **/
/* All infobox container */
.portable-infobox {
  border: 2px solid #dddddd;
  background-color: #f9f9f9;
  padding: 5px;
  width: 280px;
  font-size: 90%;
  margin: 0 0 15px 15px;
  font-family: sans-serif;
}

/* Horse infobox container */
.portable-infobox.pi-theme-horse .pi-title {
  background: #d2b48c;
}
.portable-infobox.pi-theme-horse .pi-header {
  background: #d2b48c;
}

/* UmaLokal infobox container */
.portable-infobox.pi-theme-umalokal .pi-title {
  background: #ffcccc;
}
.portable-infobox.pi-theme-umalokal .pi-header {
  background: #ffcccc;
}

/* Spacing styling */
.portable-infobox .pi-item-spacing {
    padding: 1px 3px;
}

/* Title styling */
.portable-infobox .pi-title {
  background-color: #dddddd;
  color: #000;
  text-align: center;
  font-weight: bold;
  font-size: 125%;
  padding: 2px;
  margin: 0;
  border: none;
  font-family: sans-serif;
  background: transparent;
}

/* Header styling */
.portable-infobox .pi-header {
  background: transparent;
  color: #000;
  text-align: center;
  font-weight: bold;
  padding: 2px;
  margin: 0;
  border: none;
  font-size: 100%;
  font-family: sans-serif;
}
.portable-infobox.pi .pi-item.pi-header.pi-secondary-font.pi-item-spacing.pi-secondary-background {
    color: black;
    text-align:center;
    font-size: 12px;
	font-family: sans-serif;
	background: #d2b48c;
}

/* Image styling */
.portable-infobox .pi-image-thumbnail {
    width: 100%;
    height: auto;
}
.portable-infobox .pi-image {
    display: flex;
    flex-flow: column nowrap;
    padding: 8px 0;
}

/* Caption styling */
.portable-infobox .pi-caption {
    order: 1;
    text-align: center;
}
.portable-infobox .pi-caption,
.portable-infobox .mw-collapsible-toggle a {
    color: #000;
}

/* Label (left column) styling */
.portable-infobox .pi-data-label {
  font-weight: bold;
  padding: 0px 4px;
  vertical-align: top;
  width: 35%;
}

/* Value (right column) styling */
.portable-infobox .pi-data-value:not(:first-child) {
  margin: auto;
}

/* Data + group (no border) */
.portable-infobox .pi-data,
.portable-infobox .pi-group {
    border: none;
}

/* Responsive for mobile */
@media (max-width: 768px) {
    .portable-infobox {
        float: none;
        margin: 0.5em auto;
        width: 100%;
        font-size: 100%;
    }

    .portable-infobox .pi-data-label {
         font-weight: bold;
         padding: 0px 4px;
         vertical-align: top;
         width: 60%;
    }

    .portable-infobox .pi-data-value {
        margin: auto;
    }
}

.cal-wrap { font-family: sans-serif; max-width: 860px; margin: 0 auto; }
.cal-table { width: 100%; border-collapse: collapse; background: #007848; }

/* ── Header navigation ── */
.cal-header {
    text-align: center;
    padding: 10px;
    background: #004d30;   /* dark green, konsisten dengan tabel */
    color: white;
}

.cal-title {
    font-weight: bold;
    font-size: 1.15em;
    color: #ffffff;
    background: #006040;
    padding: 4px 18px;
    border-radius: 4px;
    letter-spacing: 0.5px;
}

.cal-nav {
    display: inline-block;
    color: #ffffff;
    background: #1a6496;   /* biru sebagai aksen */
    font-size: 1.1em;
    padding: 3px 12px;
    border-radius: 4px;
    text-decoration: none;
    cursor: pointer;
    margin: 0 8px;
    transition: background 0.2s;
}

.cal-nav:hover {
    background: #2980b9;
}

/* ── Day name headers ── */
.cal-table th {
    background: #006040;
    color: #ffffff;
    padding: 8px;
    text-align: center;
    border: 1px solid #00503a;
    font-weight: bold;
}

.cal-sat { color: #aed6f1 !important; }
.cal-sun { color: #f1948a !important; }

/* ── Cells ── */
.cal-table td {
    vertical-align: top;
    padding: 5px;
    min-height: 70px;
    border: 1px solid #00503a;
    background: white;
    width: 14.28%;
}

.cal-sat-cell { background: #d6eaf8 !important; }
.cal-sun-cell { background: #fde8e8 !important; }

/* ── Day number ── */
.cal-day-num {
    font-weight: bold;
    font-size: 1em;
    margin-bottom: 4px;
    color: #222;
}

.cal-sat-cell .cal-day-num { color: #1a6496; }
.cal-sun-cell .cal-day-num { color: #c0392b; }

/* ── Event badges ── */
.cal-events { display: flex; flex-wrap: wrap; gap: 2px; margin-top: 2px; }
.cal-badge {
    display: inline-block;
    color: white;
    font-size: 0.68em;
    padding: 1px 5px;
    border-radius: 3px;
    white-space: nowrap;
}

