	color: #fff
}
#left-navigation,#right-navigation{
	margin-top: 4.4em
}
#ca-talk,#ca-view,#ca-edit,#ca-history,#ca-unwatch,
#ca-ve-edit,#ca-move,#ca-purge,#ca-nstab-user,#ca-addsection{
	background: linear-gradient(45deg, #676767, #000000);
}
#ca-talk span,#ca-view span,#ca-edit span,#ca-history span,#ca-unwatch span,
#ca-ve-edit span,#ca-move span,#ca-purge span,#ca-nstab-user span,#ca-addsection span{
	color: #fff;
	text-decoration: none !important;
}
#ca-ve-edit.selected.icon.mw-list-item.collapsible a > span,
#ca-edit.selected.icon.mw-list-item.collapsible a > span,
#ca-talk.selected.icon.mw-list-item.collapsible a > span,
#ca-view.selected.icon.mw-list-item.collapsible a > span,
#ca-history.selected.icon.mw-list-item.collapsible a > span,
.selected.mw-list-item a > span{
	color: #fff
}
.selected.mw-list-item,
#ca-ve-edit.selected.icon.mw-list-item.collapsible,
#ca-edit.selected.icon.mw-list-item.collapsible,
#ca-talk.selected.icon.mw-list-item.collapsible,
#ca-view.selected.icon.mw-list-item.collapsible,
#ca-history.selected.icon.mw-list-item.collapsible{
	background: linear-gradient(45deg, #676767, #000000);
	border: 4px grey inset;
	position: relative;
	bottom: 8px;
}

/*-----------------Headings-------------------*/

h1,h2,h3,h4,h5,h6,
.mw-heading1,
.mw-heading2,
.mw-heading3,
.mw-heading4,
.mw-heading5,
.mw-heading6{
	font-family:'IM Fell English SC', serif;
	color: #fff
}
.vector-body .mw-heading1 h1,
.vector-body .mw-heading2 h2,
.vector-body .mw-heading3 h3,
.vector-body .mw-heading4 h4,
.vector-body .mw-heading5 h5,
.vector-body .mw-heading6 h6{
	border-bottom: 4px solid #a2a9b1;
	line-height: 15px;
}
.vector-menu-heading-label{
	color:grey
}

/*-------------------Dark Mode Text-----------------*/

.vector-body p,
#content li,tbody,.wikitable > caption{
	color: #fff
}

/*------------------------Misc--------------------------*/
.cdx-message__content{
	color: #fff
}
.oo-ui-iconElement-icon .oo-ui-icon-success .oo-ui-image-success{
	color: #000
}
.mw-newarticletext .plainlinks{
	color: #fff
}

/*-----------------Links--------------------*/


.oo-ui-iconElement .oo-ui-flaggedElement-progressive .oo-ui-buttonWidget .oo-ui-labelElement .mw-rcfilters-ui-changesListWrapperWidget .mw-changeslist-legend a{
	color: #FFE26B
}
.oo-ui-iconElement .oo-ui-flaggedElement-progressive .oo-ui-buttonWidget .oo-ui-labelElement .mw-rcfilters-ui-changesListWrapperWidget .mw-changeslist-legend a:hover{
	color: #fad12a
}
a{
	color: #FFE26B
}
a > span{
	color: #FFE26B
}
a:visited{
	color: #FFE26B
}
a:hover{
	color: #fad12a
}
.oo-ui-labelElement-label{
	color: #000
}

/*------------Footer-------------*/

#footer,.mw-footer{
	border-top:1px solid black
}

/* CSS placed here will be applied to all skins */
/*---------------Root Variables------------------------*/
:root{
	--background-color-warning-subtle: #2d2511;
	--pi-background: #a5a5a5;
	--pi-border-color: #fff;
	/*--color-base: black;*/
}

/*-----------------Apply Background And Font---------------*/

body{
	font-family: 'Cardo';
	background: url("https://static.wikitide.net/worldoftelluswiki/0/05/Stripestexture.png") #080f13;
}
/*--------------Panel--------------------*/
#mw-panel li a > span{
	font-size: medium;
	background: #fff;
	-webkit-background-clip:text;
    -webkit-text-fill-color: transparent;
}
#mw-panel li a span:hover {
	text-decoration: underline !important;
	text-decoration-color: #fff !important;
}
#mw-panel{
	background: linear-gradient(to bottom, #5b5b5b, #1e1e1e, #3d3d3d);
}

/*-------------------Personal Tabs-----------------*/

#mw-head{
	background: url("https://static.wikitide.net/worldoftelluswiki/0/05/Stripestexture.png") #080f13
}
#mw-head #p-personal{
	background: linear-gradient(to bottom, #5b5b5b, #1e1e1e, #3d3d3d);
	position: absolute;
	padding-top:6px;
	padding-right: 20px;
	top: 0px;
	right: 0px;
}
/*Disable Darkmode Completely*/
#pt-darkmode{
	display: none
}
.skin-vector-legacy #pt-uls .uls-trigger::before,
body:not(.skin-vector-2022) #pt-notifications-alert .mw-echo-notifications-badge.mw-echo-notifications-badge-all-read,
body:not(.skin-vector-2022) #pt-notifications-notice .mw-echo-notifications-badge.mw-echo-notifications-badge-all-read{
	filter: invert(1);
	background-clip: none;
}
#mw-head #p-personal .mw-list-item a{
	font-size: medium;
    -webkit-text-fill-color: white;
}
#mw-head #p-personal .mw-list-item li a:hover > span{
	text-decoration-color: #fff !important;
	text-decoration: underline!important;
}
.vector-menu-heading-label{
	color: #9f3526;
	font-size: 170%;
}

/*------------------------------Page-------------------*/

#mw-content-text,.mw-body-content,#content{
	background: #353535;
	padding: 10px;
	margin-top: 31.9px;
	border-left: 1px solid white;
	border-bottom: 1px solid #fff;
	border-top: 1px solid #fff;
	box-shadow:4px 4px 8px 4px rgba(0, 0, 0, 0.2)
}
/*Made The Search Box Background White*/
.vector-search-box-input{
	background: white
}

/*----------------------------Toc (Table Of Content)-----------------------*/
#toc, .toc{
	background: #4546469c;
}
#toc .tocnumber,.toc .tocnumber{
	color: #FFE26B;
}
/*-------------------------Portable Infobox-------------------------*/

.pi-data-label .pi-secondary-font{
	color: #000
}
.portable-infobox .pi-title{
	background: #555555;
}

/*-------------------------Wikitable----------------------*/

.wikitable{
	background-color: #4546469c !important;
}
.wikitable ul{
	list-style-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='5' height='13'><circle cx='2.5' cy='8.5' r='2.5' fill='%23fff'/></svg>");;
}

