.whole-box {
	align-items: center; 
	display: flex; 
	border-radius: 10px; 
	width: 95%; 
	background-color: #171717; 
	align-content: center; 
	padding-left: 10px !important;
	font-weight: 700;
	min-height: 40px;
	padding: 8px 10px;
}

.whole-box p {
    margin: 0;
}

.percentage {
	color: oklch(0.9555 0.0555 96.15);
}

.accept {
	color: #80D67C; 
	margin-top: 0;
	margin-bottom: 0;
}

.tie {
	color: #919191;
	margin-top: 0;
	margin-bottom: 0;
}

.oppose {
	color: #D65858; 
}
.grid-container {
	margin-left:auto; 
	display:flex; 
	gap:5px; 
	align-items: center;
}

.text-percentage {
	margin-right:6px; 
	color: oklch(0.9555 0.0555 96.15);
}

.approve-square {
	width:15px; 
	height:15px;
	background:green; 
	border-radius: 4px;
	display:inline-block;
}

.oppose-square {
	width:15px; 
	height:15px; 
	background:red; 
	border-radius: 4px; 
	display:inline-block;
}

.square-text { /* case for if total votes > 30 */
	margin-right:6px; 
	color: oklch(0.9555 0.0555 96.15);
}

.square-text-color {
	color: oklch(0.9555 0.0555 96.15);
}

.extension {
	text-align: center;
}

