/*
 * MassRollback Gadget v0.0.1
 * Refactored to use MediaWiki Core APIs and Wikimedia Codex.
 * Original by Hoo man. Refactored version.
 * Forked from User:ChasingAir/js/MassRollback.js
 */
mw.loader.using(['mediawiki.util', 'mediawiki.api', 'vue', '@wikimedia/codex', 'ext.gadget.HanAssist'], function (require) {
    'use strict';

    const Vue = require('vue');
    const Codex = require('@wikimedia/codex');
    // Common Codex components
    const CdxDialog = Codex.CdxDialog;
    const CdxSelect = Codex.CdxSelect;
    const CdxTextInput = Codex.CdxTextInput;
    const CdxRadio = Codex.CdxRadio;
    const CdxField = Codex.CdxField;
    const CdxButton = Codex.CdxButton;
    const { conv } = require('ext.gadget.HanAssist');

    // Configuration and Localization
    const config = {
        editSummaries: [
            { label: conv({ hans: '撤销（破坏）', hant: '撤销（破壞）' }), value: conv({ hans: '撤销（破坏）', hant: '撤销（破壞）' }) },
            { label: conv({ hans: '撤销（测试编辑）', hant: '撤销（測試編輯）' }), value: conv({ hans: '撤销（测试编辑）', hant: '撤销（測試編輯）' }) },
            { label: conv({ hans: '撤销', hant: '撤销' }), value: conv({ hans: '撤销', hant: '撤销' }) }
        ]
    };

    mw.messages.set({
        'smartrollback-title': conv({ hans: '智能回退', hant: '智能回退' }),
        'smartrollback-summary-label': conv({ hans: '编辑摘要', hant: '編輯摘要' }),
        'smartrollback-summary-default': conv({ hans: '使用默认', hant: '使用預設' }),
        'smartrollback-summary-custom': conv({ hans: '其他 ->', hant: '其他 ->' }),
        'smartrollback-custom-label': conv({ hans: '自定义摘要', hant: '自定義摘要' }),
        'smartrollback-bot-label': conv({ hans: '标记为bot编辑', hant: '標記為bot編輯' }),
        'smartrollback-bot-yes': conv({ hans: '是', hant: '是' }),
        'smartrollback-bot-no': conv({ hans: '否', hant: '否' }),
        'smartrollback-btn-update': conv({ hans: '更新链接', hant: '更新連結' }),
        'smartrollback-btn-mass': conv({ hans: '撤销一切', hant: '撤销一切' }),
        'smartrollback-confirm-mass': conv({ hans: '你确定要回退本页所有可见的编辑吗？', hant: '你確定要回退本頁所有可见的編輯嗎？' }),
        'smartrollback-processing': conv({ hans: '处理中...', hant: '處理中...' }),
        'smartrollback-done': conv({ hans: '完成', hant: '完成' })
    });

    const App = Vue.defineComponent({
        components: {
            CdxDialog,
            CdxSelect,
            CdxTextInput,
            CdxRadio,
            CdxField,
            CdxButton
        },
        setup() {
            const open = Vue.ref(false);
            const selectedSummary = Vue.ref('default');
            const customSummary = Vue.ref('');
            const isBot = Vue.ref('false');
            const processing = Vue.ref(false);

            // Permissions check
            const userGroups = mw.config.get('wgUserGroups');
            const globalGroups = mw.config.get('wgGlobalGroups') || [];
            const canMarkBot = ['sysop', 'steward', 'swmt', 'global-sysop', 'global-rollback'].some(g =>
                userGroups.includes(g) || globalGroups.includes(g)
            );

            // Menu options for select
            const summaryOptions = Vue.computed(() => {
                const opts = [
                    { label: mw.msg('smartrollback-summary-default'), value: 'default' },
                    ...config.editSummaries,
                    { label: mw.msg('smartrollback-summary-custom'), value: 'custom' }
                ];
                return opts;
            });

            const handleAction = async (action) => {
                const rollbackLinks = getRollbackLinks();
                if (rollbackLinks.length === 0) return;

                let summary = '';
                if (selectedSummary.value === 'custom') {
                    summary = customSummary.value;
                } else if (selectedSummary.value !== 'default') {
                    summary = selectedSummary.value;
                }

                const botParam = isBot.value === 'true';

                if (action === 'mass') {
                    if (!confirm(mw.msg('smartrollback-confirm-mass'))) return;

                    processing.value = true;
                    // API Mass Rollback
                    await performMassRollback(rollbackLinks, summary, botParam);
                    processing.value = false;
                    open.value = false;
                    location.reload();
                }
            };

            const getRollbackLinks = () => {
                // Collect all rollback links
                const links = [];
                const anchors = document.querySelectorAll('.mw-rollback-link a');
                anchors.forEach(a => links.push(a));
                return links;
            };



            const performMassRollback = async (links, summary, bot) => {
                const api = new mw.Api();
                for (const link of links) {
                    const href = link.href;
                    const title = mw.util.getParamValue('title', href);
                    const user = mw.util.getParamValue('from', href);
                    const token = mw.util.getParamValue('token', href); // Usually in query, but cleaner to get fresh one or use generic rollback

                    // Actually, native rollback links usually have the token in the URL.
                    // But for mass rollback, it is safer to use API with a fresh token or extracting params correctly.
                    // We will extract params from the URL for simplicity as the legacy script did, 
                    // but using mw.Api helper if possible.

                    const params = {
                        action: 'rollback',
                        title: title,
                        user: user,
                        markbot: bot,
                        watchlist: 'nochange' // default behavior
                    };

                    if (summary) {
                        params.summary = summary.replace(/\$1/g, user);
                    }

                    // The token in the URL is sometimes for GET access, API requires POST token.
                    // We'll trust mw.Api to handle tokens if we don't pass one, OR explicitely request 'rollback' token.

                    try {
                        await api.postWithToken('rollback', params);
                    } catch (e) {
                        console.error('Rollback failed for', title, e);
                    }
                }
            };

            // Expose to window to be toggleable
            window.toggleSmartRollback = () => {
                open.value = !open.value;
            };

            const msg = (key) => mw.msg(key);

            return {
                open,
                selectedSummary,
                customSummary,
                isBot,
                canMarkBot,
                summaryOptions,
                handleAction,
                processing,
                msg,
                mw,
                CdxDialog, CdxSelect, CdxTextInput, CdxRadio, CdxField, CdxButton
            };
        },
        template: `
            <div id="smart-rollback-app">
                <cdx-dialog v-model:open="open" :title="msg('smartrollback-title')" :close-button-label="msg('hoo-closeButtonText')">

                    <div class="smart-rollback-form">
                        <cdx-field>
                            <template #label>{{ msg('smartrollback-summary-label') }}</template>
                            <cdx-select v-model:selected="selectedSummary" :menu-items="summaryOptions" />
                        </cdx-field>

                        <cdx-field v-if="selectedSummary === 'custom'">
                            <template #label>{{ msg('smartrollback-custom-label') }}</template>
                            <cdx-text-input v-model="customSummary" />
                        </cdx-field>

                        <cdx-field v-if="canMarkBot" :is-fieldset="true">
                            <template #label>{{ msg('smartrollback-bot-label') }}</template>
                            <cdx-radio v-model="isBot" name="isBot" input-value="true">{{ msg('smartrollback-bot-yes') }}</cdx-radio>
                            <cdx-radio v-model="isBot" name="isBot" input-value="false">{{ msg('smartrollback-bot-no') }}</cdx-radio>
                        </cdx-field>
                    </div>

                    <template #footer>

                        <cdx-button action="destructive" weight="primary" @click="handleAction('mass')" :disabled="processing">
                            {{ processing ? msg('smartrollback-processing') : msg('smartrollback-btn-mass') }}
                        </cdx-button>
                    </template>
                </cdx-dialog>
            </div>
        `
    });

    // Mount Logic
    $(function () {
        // Check availability
        if ($('.mw-rollback-link').length === 0) return;

        // Mount Vue App
        const mountPoint = document.createElement('div');
        document.body.appendChild(mountPoint);
        const app = Vue.createMwApp(App);
        app.mount(mountPoint);

        // Add Portlet Link
        const linkId = mw.util.addPortletLink(
            'p-tb',
            '#',
            mw.msg('smartrollback-title'),
            't-smartrollback',
            'Smart Rollback'
        );

        $(linkId).find('a').on('click', function (e) {
            e.preventDefault();
            window.toggleSmartRollback();
        });
    });
});

