#mw-site-navigation .sidebar-chunk a, #mw-related-navigation .sidebar-chunk a, #mw-related-navigation #catlinks-sidebar.sidebar-chunk a {
	color: var(--sidebarColor);
}
@media screen and (min-width: 851px) { /* DESKTOP SIDE MENUS (i.e. nav, wiki tools, etc) */
