/* CSS placed here will be applied to all skins */
/*Remove Elements Resize + Centered Page When Zooming*/
body{
	max-width: 1500px;
    margin-left: auto;
    margin-right: auto;
    width: 150%;
    min-width: 1200px !important;
    overflow-x: auto !important;
}

#content, #mw-content-text, .mw-body {
    width: 1200px !important;
    margin: 0 auto;/*Page Should Be Centered When Zoomed Out*/
}

.infobox {
    margin: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    width: 300px;
    padding: 10px;
    border: 1px solid #ccc;
    background-color: rgba(249, 249, 249, 0.85);
}

.infobox-header {
    font-size: 1.5em;
    font-weight: bold;
}

.infobox-content {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-around;
}

.infobox-item {
    flex: 1;
    padding: 5px;
}

.infobox-container {
    display: flex;
    justify-content: space-around;
    flex-wrap: wrap;
}
.bdb-wnav-header{
	color: ghostwhite !important;
}
/*------------------Root Varibles------------------------*/
:root{
	/*-----------Page Stuff---------*/
	--main-bg: #FFFAD4; /*Site Background Color*/
	--link: #70B767; /*Site Link Color*/
	--hov-link: #64965d; /*Hovered Link*/
	--main-text: #000; /*Page Text Black*/
	/*----------Editor Tab---------*/
	--editor-tab-color: linear-gradient(#3a7bd5, #2a5298);
	--highlight-for-tabs: linear-gradient(#0000ac, #245292);
	/*---------Portable Infobox--------*/
	--defaultlink: #52bdff; /*Links Default Blue Color In Portable Infobox*/
	--pi-hov-link: #42a7f5; /*Hovered Link On Portable Infoboxes*/
	--no-link: #f00; /*No Link Or New Page*/
	--portable-infobox-color: #6c6c6c;
	--pi-secondary-background: #6c6c6c; /*Port Infobox Secondary Border Color*/
	/*---Catlinks---*/
	--catlinks: #FFF;
}
/*----------------Darkmode---------------*/
:root.client-darkmode{
	--main-bg: #353535; /*Site Darkmode Background Color*/
	--link: #FFE26B; /*Site Dark Link Color*/
	--hov-link: #fad12a; /*Hovered Link*/
	--main-text: #FFFFFF; /*Page Text White On Darkmode*/
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlinks: #555555;
}
:root.client-theme-clientref-night{
	--main-bg: #353535;
	--link: #FFE26B;
	--hov-link: #fad12a;
	--main-text: #FFFFFF;
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlink: #555555;
}
/*-------------------------------Custom IDs/Classes----------------------------*/
/*Dialog-Related*/
html.client-darkmode .wikitable .dialog-related tr{
	font-size:110% !important;
	white-space:nowrap !important;
	text-shadow: 0 0 1px black, 0 0 1px black, 0 0 1px black, 0 0 1px black, 0 0 1px black !important;
}
/*Custom Table Of Contents In The Waterfall Style, Copied A Part From Roblox Isle Wiki Fandom*/
#custom-toc .toc {
	width: 98%;
}
#custom-toc .toc, 
#custom-toc .toc ul {
    column-width: 220px; 
    column-gap: 20px;
    list-style: none;
    padding: 0;
}
#custom-toc .toc li {
    break-inside: avoid;
    margin-bottom: 5px;
}


.main-page-box{
	margin-top: 40px;
    margin-left: auto;
    margin-right: auto;
    height: fit-content;
    border-style: solid;
    border-radius: 5px;
    border-width: 1px;
}
.main-page-nav{
	background: linear-gradient(#3a7bd5, #2a5298);
    display: flex;
    justify-content: center;
}
.main-page-content{
	margin-top: 10px;
    margin-bottom: 0px;
    margin-left: auto;
    margin-right: auto;
    height: fit-content;
    width: 90%;
}
.display-wiki-content{
	display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-template-rows: repeat(2, auto);
}
.mp-link{
	width: 80%;
    height: 55px;
    font-size: 110%;
    color: white;
    overflow: hidden;
    background: #ffffffa6;
    border: 2px solid grey;
    border-bottom: 0;
    border-radius: 5px 5px 0 0;
    padding: 0 16px 10px;
    margin-bottom: 1px;
}

/*--------------Portable Infobox, Aka The Stuff In Templates-----------------*/
.portable-infobox a{
	color: var(--defaultlink) !important;
}
.portable-infobox a:hover{
	color: var(--pi-hov-link) !important
}
.portable-infobox a.new{
	color: var(--no-link) !important;
}
html.client-darkmode .portable-infobox,html.client-theme-clientref-night .portable-infobox{
    color: ghostwhite;
}
.pi-layout-default{
    border: 1px solid var(--portable-infobox-color);
    background: transparent;
}
.pi-item.pi-header.pi-secondary-font.pi-item-spacing.pi-secondary-background{ /*Versions (Non-Active)*/
	background: var(--portable-infobox-color);
	color: ghostwhite !important;
}
.pi-section-tab.pi-item-spacing.pi-section-active{ /*versions (active)*/
	background: var(--portable-infobox-color);
	color: ghostwhite !important;
	font-weight: bold;
}
.pi-section-tab.pi-item-spacing{ /*Multi Images (Non-Active)*/
	background: transparent;
}
.pi-tab-link.pi-item-spacing.current{ /*Infobox Images (Current)*/
	background: var(--portable-infobox-color);
	font-weight: bold;
	color: ghostwhite !important;
}

/*------------------------------catlinks-----------------------*/
.catlinks{
	background: var(--catlink);
}
/*----------------------------Table (Normal One)-----------------*/
.table, .skin-theme-clientpref-night table, html.client-darkmode table{
	background: transparent
}
/*-----------------------------Tables-----------------------------------*/
.mw-content-ltr figure[typeof~='mw:File/Thumb'],.fandom-table,.article-table,.wikitable td{
	background: var(--main-bg)
}
.wikitable th{
	background: #F2EEC9;
	color: black bold;
}
html.client-darkmode .wikitable .mw-collapsible .mw-made-collapsible tr,
html.client-theme-clientref-night .wikitable .mw-collapsible .mw-made-collapsible tr{
	color: white bold;
}
html.client-darkmode .wikitable td,html.client-theme-clientref-night .wikitable td{
	background: var(--main-bg);
	color: white;
}
html.client-darkmode .wikitable th,html.client-theme-clientref-night .wikitable th{
	background: #535353;
	color: ghostwhite;
}
html.client-darkmode .wikitable,html.client-theme-clientref-night > caption{
	font-weight: bold;
	color: ghostwhite;
}

/*-------------------------Images In Page---------------------*/
.mw-file-description, img.mw-file-element, .mw-file-element {
	background: transparent !important;
	margin: 0px !important;
	color: black!important;
}
/*Disable The Thumbnail On Images*/
.thumb {
	background: transparent!important;
    border: 0px !important;
}
/*------------Idk What This Is, I Just Look At It In The Console And Copy But It Works Ig--------*/
html.client-darkmode figure[typeof~='mw:File/Thumb'] figcaption, html.client-darkmode .mw-file-description,
html.client-darkmode img.mw-file-element, html.client-darkmode .mw-file-element, html.client-darkmode .thumbinner,
html.client-theme-clientref-night figure[typeof~='mw:File/Thumb'] figcaption,html.client-theme-clientref-night .mw-file-description,
html.client-theme-clientref-night img.mw-file-element,html.client-theme-clientref-night .mw-file-element,html.client-theme-clientref-night .thumbinner{
	background: transparent !important;
	margin: 0px !important;
	color: white!important;
}
/*--------------------------------Setup For Background-------------------------------*/
html, body, html.client-darkmode, html.client-darkmode body{
	background: transparent no-repeat fixed center / cover;
}
/*-----------Light Mode--------*/
html:not(.client-darkmode) body {
    background-image: url("https://static.wikitide.net/robloxislesandboxwiki/2/26/Background.png");
}
/*-----------Dark Background----------*/
html.client-darkmode body,html.client-theme-clientref-night body{
    background-image: url("https://static.wikitide.net/robloxislesandboxwiki/2/26/Background.png");
}

/*-----------------Page Design-----------------*/
.mw-page-container,.mw-body{
    background: var(--main-bg);
    padding: 10px;
    margin: 20px 0 0 200px !important;
    position: relative !important;
    z-index: 1 !important;
}
.mw-content-text, #mw-content-text {
	color: var(--main-text) !important;
}
.mw-body h1,.mw-body h2,.mw-body h3,.mw-body h4,.mw-body h5,.mw-body h6{ /*Headings*/
	color: var(--main-text) !important;
	font-family: "Comic Sans MS";
}
/*---------------Links-----------------*/
.mw-page-container a,
.mw-body a,
a.external.text,
html.client-darkmode .mw-page-container a,
html.client-darkmode .mw-body a,
html.client-darkmode a.external.text,
html.client-theme-clientref-night .mw-page-container a,
html.client-theme-clientref-night .mw-body a,
html.client-theme-clientref-night a.external.text{ /*Links on page*/
	color: var(--link)
}
.mw-page-container a:hover,
.mw-body a:hover,
a.external.text:hover,
html.client-darkmode .mw-page-container a:hover,
html.client-darkmode .mw-body a:hover,
html.client-darkmode a.external.text:hover,
html.client-theme-clientref-night .mw-page-container a:hover,
html.client-theme-clientref-night .mw-body a:hover,
html.client-theme-clientref-night a.external.text:hover{
	color: var(--hov-link)
}
.mw-page-container a.new,
.mw-body a.new{
	color: var(--no-link) !important;
}
a.external.text:visited{
	color: var(--link);
}

/*-----------------Table Of Contents--------------------------*/
.toc{
	background: transparent!important;
}
.toctext, .tocnumber{
	color: black;
}
/*TOC Darkmode*/
html.client-darkmode .toctext,
html.client-darkmode .tocnumber,
html.client-theme-clientref-night .toctext,
html.client-theme-clientref-night .tocnumber{
	color: var(--link);
}
html.client-darkmode .toctext:hover,
html.client-darkmode .tocnumber:hover,
html.client-theme-clientref-night .toctext:hover,
html.client-theme-clientref-night .tocnumber:hover{
	color: var(--hov-link);
}

/*------------------Left Nav Lightmode---------------------*/
#mw-panel{
    background-color: var(--main-bg);
    position: absolute;
    z-index: 1 !important; /*Made It So Page Don't Overlap This Part*/
}
#mw-panel a{ /*Links*/
	color: var(--main-text);
}

/*------------------------Personal Tabs Lightmode--------------------------------*/
#mw-head,
#mw-head-base,
