		--bgImg: url("https://static.miraheze.org/pizzatowerwiki/5/5f/Bg-wiki.png");
		--bgColor: #785c76;
	/* SIDEBARS */
		--sidebarText: white;
		--sidebarColor: #FFE444; /* link color */
		--sidebarBg: #4e3b5a;
		--sidebarImg1: url("https://static.miraheze.org/pizzatowerwiki/3/31/Bg-sidebar-1.png");
		--sidebarImg2: url("https://static.miraheze.org/pizzatowerwiki/5/54/Bg-sidebar-2.png");
		--sidebarImg3: url("https://static.miraheze.org/pizzatowerwiki/9/9c/Bg-sidebar-3.png");
	/* SITE HEADER */
		--searchInputBg: #e8c098; /*For the input box*/
		--searchBtnBg: #d89060;
		--searchBtnHoverBg: #c08038;
	/* CONTENT/BODY */
		--contentBg: #C59AC2;
		--bodyImg: url("https://static.miraheze.org/pizzatowerwiki/d/d5/Border-content.png");
		--underlineBorder: url(https://static.miraheze.org/pizzatowerwiki/9/93/PTWiki-underlineborder.png);

		/* Text */
			--textColor: black;
			--linkColor: #5e26a7;
			--externalColor: #2850a8;
			--newColor: #b03000;
			--newVisitedColor: #803800;
			--hrColor: #4D3A59;
		/* Tabs */
			--tabColor: #FFE444;
			--discussTabColor: #ba0000;
			--inactiveTabBg: #614261;
			--inactiveTabImg1: url("https://static.miraheze.org/pizzatowerwiki/2/22/Bg-tab-inactive-1.png");
			--inactiveTabHoverBg: #4E3B5A;
			--inactiveTabImg2: url("https://static.miraheze.org/pizzatowerwiki/7/78/Bg-tab-inactive-2.png");
			--activeTabImg: url("https://static.miraheze.org/pizzatowerwiki/3/34/Bg-tab-active-1.png");
			/* next 3 are leftovers from vector theme */
			--moreTabImg: url("https://static.miraheze.org/pizzatowerwiki/e/ed/Bg-tab-more.png");
			--moreTabListImg: url("https://static.miraheze.org/pizzatowerwiki/2/22/Bg-tab-inactive-1.png");
			--searchbarImg: url("https://static.miraheze.org/pizzatowerwiki/a/a9/Bg-searchbar.png");
		/* WIKITABLE */
			--tableBg: #B78EB4;
			--tableBorder: #614261;
		/* TABBER */
			--activeTabberBg: #614261;
			/* Text */
				--activeTabberColor: #C69AC3;
				--inactiveTabberColor: #4E3B5A;
		/* FOOTER */
			--frameContentBg: #d8b8f8;
			--frameContentImg: url("https://static.wikitide.net/pizzatowerwiki/0/03/PTWiki-frontPage-boxBottom.png") 4 / 4px round;
		/* EDIT/SAVE NOTICE */
			--successfulEditText: #60d048;
			--notifText: white;
		/* RECENT CHANGES */
			--recentChangesGreen: #086800;
			--recentChangesRed: #982800;

	/* COMMON.CSS */
		--galleryBoxBg: #FFC5FF;
		--galleryBoxImg: url(https://static.miraheze.org/pizzatowerwiki/7/7a/PTWiki-border-gallerybox.png) 40 / 40px round;

		/* idk what these two are used for it's been a while */
		--frameHeaderImg: url("https://static.wikitide.net/pizzatowerwiki/3/3b/PTWiki-frontPage-boxTop.png") 7 / 7px round;

	/* TEMPLATES (NON-SANETIZED CSS) */
		--tabTemplate-activeTabImg: var(--activeTabImg) 5 / 5px round round;
		--tabTemplate-inactiveTabImg1: var(--inactiveTabImg1) 5 / 5px round round;
		--tabTemplate-inactiveTabImg2: var(--inactiveTabImg2) 5 / 5px round round;
		--tabTemplate-underlineBorder: var(--underlineBorder) 0 0 2 0 / 0 0 2px 0 round round;
		/* INFOBOX */
				--infoboxHeaderBackgroundColor: #4e3b5a;
				--infoboxLinkColor: #5e26a7;
				--infoboxBackgroundColor: linear-gradient(180deg,
										rgba(78, 59, 90, 1)0%,
										rgba(78, 59, 90, 1)25px,
										rgba(185, 165, 205, 1)25px,
										rgba(185, 165, 205, 1)50%,
										rgba(185, 165, 205, 1)100%);
				--infoboxHeaderTitleColor: #E9D8F8;
				--infoboxHighlightColor: black;
				--infoboxBorderColor: black;
}
body {
	background-color: var(--bgColor);
	background-image: var(--bgImg);
	background-size: 400px 400px;
	background-repeat: repeat;	
}
#mw-content-container {
	background: transparent;
	border: none;
	padding-bottom: 0;
}
/* SITE HEADER */
#mw-header-container {
	border-bottom: 2px solid transparent;
	background-color: var(--sidebarBg);
	background-clip: padding-box;
	border-image: var(--sidebarImg3) 13 / 0 0 13px 0 round round;
	padding: 8px 0 2px;
}
#mw-header-nav-hack, #mw-header-hack {
	display: none;
}
.wordmark img {
	aspect-ratio: initial;
	width: auto;
	height: 40px;
	margin-top: -5px;
}
#simpleSearch {
	background: transparent;
	border: none;
	box-shadow: none;
}
#searchInput {
	background-color: var(--searchInputBg);
	border: 1px solid black;
}
#searchButton, #mw-searchButton {
	aspect-ratio: 1/1;
	background-color: var(--searchBtnBg);
	border: 1px solid black;
	height: 100%;
	width: auto;
	right: 0;
}
#user-tools {
	position: relative;
	top: -3px;
}
#personal h2 span {
	color: var(--sidebarText);
	font-family: sans-serif;
	font-weight: bold;
}
/* SIDEBARS */
#mw-site-navigation .sidebar-chunk a,
#mw-related-navigation .sidebar-chunk a,
#mw-related-navigation #catlinks-sidebar.sidebar-chunk a { /* sidebar link colors */
	color: var(--sidebarColor);
}
.sidebar-chunk label,
.sidebar-chunk h3 { /* sidebar headers */
	font-weight: bold !important;
}
@media screen and (min-width: 851px) { /* DESKTOP SIDE MENUS (i.e. nav, wiki tools, etc) */
	#mw-site-navigation .sidebar-chunk,
	#mw-related-navigation .sidebar-chunk,
	#mw-related-navigation #catlinks-sidebar.sidebar-chunk {
		background-color: var(--sidebarBg);
		background-clip: padding-box;
		border: 5px solid transparent;
		border-image: var(--sidebarImg1) 5 / 5px round round;
		color: var(--sidebarText);
		padding: 15px 15px 0;
	}
	#mw-site-navigation #site-tools.sidebar-chunk {
		border-image: var(--sidebarImg2) 5 / 5px round round;
	}
	#mw-related-navigation .sidebar-chunk {
		border-image: var(--sidebarImg3) 5 / 5px round round;
	}
}
@media screen and (min-width: 851px) and (max-width: 1099px) {
	#mw-content-container {
		margin-top: 80px;
	}
	#mw-site-navigation,
	#mw-related-navigation {
		top: -4em;
	}
	#mw-site-navigation .sidebar-chunk,
	#mw-related-navigation .sidebar-chunk {
		padding: 5px 10px;
	}
	#mw-site-navigation h2,
	#mw-related-navigation h2 {
		padding: 0;
	}
	#mw-content {
		margin-top: 7em;
	}
}
/* Moving toolbar to the left + making it sticky; taken from Inkipedia */
@media screen and (min-width: 1340px) {
	#mw-content-block {
		display: block;
	}
	#mw-content-wrapper {
		float: right;
		margin-left: -14em;
		width: 100%;
	}
	#mw-related-navigation {
		width: 14em;
		padding: 0 1em 0 0;
	}
	div.color-middle {
		margin-right: 0;
	}
	.mw-wiki-logo {
		display: inline-block;
	}
}
@media screen and (min-width: 1100px) {
	#mw-content,
	#content-bottom-stuff {
		margin-left: 14em;
	}
	#mw-related-navigation { /* keeps menu sticky */
		position: sticky;
		top: 67px;
		padding-bottom: .1em;
	}
	#mw-site-navigation .sidebar-chunk .mw-portlet > div,
	#mw-related-navigation .sidebar-chunk .mw-portlet > div,
	#mw-site-navigation .sidebar-chunk .mw-portlet-body,
	#mw-related-navigation .sidebar-chunk .mw-portlet-body {
		margin-bottom: 20px;
	}
}
@media screen and (max-width: 1099px) {
	#site-tools {
		position: sticky;
		top: 67px;
		padding-bottom: .1em;
	}
}
@media screen and (min-width: 851px) and (max-width: 1099px) { /* wiki tools in tablet view */
	.sidebar-chunk label,
	.sidebar-chunk h2 {
		font-family: sans-serif !important;
		font-weight: bold !important;
	}
}
/* Drop-downs */
@media screen and (min-width: 851px) { /* personal drop-down */
	#personal .dropdown::before,
	#personal .dropdown::after { /* getting rid of the arrow */
		display: none;
	}
	#personal .dropdown {
		background-clip: padding-box;
		background-color: var(--sidebarBg);
		border: 5px solid transparent;
		border-image: var(--sidebarImg3) 5 / 5px round round;
		box-shadow: none;
		color: var(--sidebarText);
		top: 2.5em;
		padding: 15px 15px 0;
	}
	#personal .dropdown a,
	#personal .dropdown a:hover {
		color: var(--sidebarColor);
	}
	#personal .dropdown .mw-portlet > div,
	#personal .dropdown .mw-portlet-body {
		margin-bottom: 1.5em;
	}
}
@media screen and (min-width: 851px) and (max-width: 1099px) { /* wiki tools drop-downs */
	#mw-site-navigation .sidebar-chunk h2 span::before,
	#mw-site-navigation .sidebar-chunk h2 span::after,
	#mw-site-navigation .sidebar-chunk h2 span::before,
	#mw-site-navigation .sidebar-chunk h2 span::after,
	#mw-related-navigation .sidebar-inner::before,
	#mw-related-navigation .sidebar-inner::after { /* getting rid of the arrow */
		display: none;
	}
	#mw-related-navigation .sidebar-inner,
	#mw-site-navigation .sidebar-inner {
		background-clip: padding-box;
		background-color: var(--sidebarBg);
		border: 5px solid transparent;
		box-shadow: none;
		color: var(--sidebarText);
		top: 2.5em !important;
		padding: 15px 15px 0;
	}
	#mw-related-navigation .sidebar-inner {
		border-image: var(--sidebarImg2) 5 / 5px round round;
	}
	#mw-site-navigation .sidebar-inner {
		border-image: var(--sidebarImg1) 5 / 5px round round;
	}
	#mw-related-navigation .sidebar-inner a,
	#mw-related-navigation .sidebar-inner a:hover,
	#mw-site-navigation .sidebar-inner a,
	#mw-site-navigation .sidebar-inner a:hover {
		color: var(--sidebarColor);
	}
	#mw-site-navigation .sidebar-inner .mw-portlet > div,
	#mw-site-navigation .sidebar-inner .mw-portlet-body,
	#mw-related-navigation .sidebar-inner .mw-portlet > div,
	#mw-related-navigation .sidebar-inner .mw-portlet-body {
		margin-bottom: 1.5em;
	}
}
/* BODY */
#mw-content {
	background: transparent;
	border: none;
	box-shadow: none;
	padding: 0;
}
#bodyContent {
	background-color: var(--contentBg);
	background-clip: padding-box;
	border: 3px solid transparent;
	border-image: var(--bodyImg) 5 / 5px round round;
	padding: 24px 36px 36px;
}
@media screen and (min-width: 851px) {
	.ts-inner { /* makes article take up full width */
		max-width: none;
	}
}
@media screen and (max-width: 1099px) { /* compressed view */
	#bodyContent {
		border-right: 0;
		border-left: 0;
		border-image: var(--bodyImg) 5 / 5px 0 5px 0 round round;
	}
}
@media screen and (max-width: 850px) {
	#mw-content-block {
		background: transparent;
	}
}
/* TABS (for how they're placed in terms of HTML elemens, see Timeless.js!) */
/* All tabs/links */
.tools-inline li:hover {
	border-color: transparent !important; /* keep important! */
}
#mw-page-header-links { /* main tab holder */
	margin-bottom: -7px;
}
#mw-page-header-links, .tools-inline ul { /* tab holders */
	display: flex;
	flex-flow: row;
	gap: 10px;
}
#mw-page-header-links .mw-list-item { /* default tab look */
	background-clip: padding-box;
	background-color: var(--inactiveTabBg);
	border: 5px solid transparent;
	border-image: var(--inactiveTabImg1) 5 / 5px round round;
	margin: 0;
	padding: 8px;
}
#mw-page-header-links .mw-list-item a {
	color: var(--tabColor);
}
#mw-page-header-links .mw-list-item.selected { /* selected tab */
	background-color: var(--contentBg);
	border-image: var(--activeTabImg) 5 / 5px round round;
}
#mw-page-header-links .mw-list-item.selected a {
	color: var(--textColor);
}
/* TAB ICONS */
@media screen and (min-width: 851px) {
	.tools-inline li:not(#ca-watch):not(#ca-unwatch) a { /* Removing old icons */
		background-image: none !important;
		padding: 0;
	}
}
@media screen and (max-width: 850px) { /* Display icons on mobile only */
	.tools-inline li a, /* Default icon */
	#ca-talk a, /* Talk */
	#ca-more span, /* More */
	.client-js #ca-edit a, /* Edit */
	#ca-history a, /* History */
	#ca-purge a, /* Purge */
	#t-contributions a, /* User contribs */
	#ca-more span /* More */ {
		background-image: url(https://static.wikitide.net/pizzatowerwiki/e/e2/PTW-20x-2space-mobileicons-sheet.png);
		background-position: left top;
	}
	#ca-talk a { /* Talk */
		background-position-x: -22px;
	}
	#ca-more span { /* More */
		background-position-x: -132px;
	}
	.client-js #ca-edit a { /* Edit */
		background-position-x: -44px;
	}
	#ca-history a { /* History */
		background-position-x: -66px;
	}
	#ca-purge a { /* Purge */
		background-position-x: -88px;
	}
	#t-contributions a { /* User contribs */
		background-position-x: -110px;
	}
}
/* Watch */
#ca-watch a,
#ca-unwatch a {
	background-image: url(https://static.wikitide.net/pizzatowerwiki/1/1f/PTWiki-20px-watch.png);
}
#ca-watch a, #ca-unwatch a:hover {
	background-position: left top;
}
#ca-watch a:hover {
	background-position: -42px top;
}
#ca-unwatch a {
	background-position: -21px top;
}
/* BODY CONTENT */
/* Body headers */
.mw-body h1,
.mw-body h2,
.mw-body .mw-heading1,
.mw-body .mw-heading2,
.sidebar-inner h3,
#personal-inner h3,
.mw-body .toctitle,
.ext-discussiontools-visualenhancements-enabled .ext-discussiontools-init-section { /* old underline / heading border */
	border-color: transparent !important; /* keep important on this */
	font-family: sans-serif;
	font-weight: bold;
}
.mw-body .firstHeading,
.mw-body .mw-heading1,
.mw-body .mw-heading2,
.sidebar-inner h3,
#personal-inner h3,
.mw-body .toctitle,
.mw-body .mw-specialpagesgroup { /* underline bottom border */
	border-image: var(--underlineBorder) 0 0 2 0 / 0 0 2px 0 round round;
}
.mw-body .firstHeading {
	font-size: 1.8em;
}
.ext-discussiontools-visualenhancements-enabled .ext-discussiontools-init-section,
.ext-discussiontools-emptystate:not(:first-child) { /* underline top border */
	border-image: var(--underlineBorder) 2 0 0 0 / 2px 0 0 0 round round;
}
.mw-body .toctitle h2 {
	border: none !important;
}
#siteSub { /* "from [wiki]" */
	font-family: sans-serif;
}

/* DISMISSABLE NOTICE */
.mw-dismissable-notice {
	background: transparent;
	border: none;
	box-shadow: none;
}

/* FOOTER */
.mw-footer-container {
	background-color: var(--sidebarBg);
	background-clip: padding-box;
	border: 3px solid transparent;
	border-top: 0;
	border-image: var(--sidebarImg2) 0 5 5 5 / 0 5px 5px 5px round;
	box-shadow: none;
	color: var(--sidebarText);
	margin-bottom: 10px;
	margin-top: -4px;
	padding: 10px 5px;
}
.mw-footer-container a,
.mw-footer-container a:visited,
.mw-footer-container a:hover,
.mw-footer-container a:visited:hover {
	color: var(--sidebarColor);
}

#mw-footer {
	display: flex;
	flex-flow: row wrap;
	justify-content: center;
	gap: 0 10px;
}
#footer-icons {
	order: 2;
	margin: 0;
	flex-basis: 310px;

	display: flex;
	flex-flow: row wrap;
	justify-content: center;
	gap: 5px;
}
#footer-icons li {
	margin: 0;
	flex-basis: 88px;
}
#footer-icons li>a {
	padding: 0;
}
#footer-list {
	flex-grow: 999;
	flex-basis: 250px;
}
@media screen and (min-width: 1100px) {
	.mw-footer-container {
		margin-left: 14em;
	}
}
@media screen and (max-width: 1099px) { /* compressed view */
.mw-footer-container {
		border-right: 0;
		border-left: 0;
		border-image: var(--sidebarImg2) 5 / 0 0 5px 0 round;
	}
}

