/* CSS placed here will be applied to all skins */
/*Remove Elements Resize + Centered Page When Zooming*/
body{
	max-width: 1500px;
    margin-left: auto;
    margin-right: auto;
    width: 150%;
    min-width: 1200px !important;
    overflow-x: auto !important;
}

#content, #mw-content-text, .mw-body {
    width: 1200px !important;
    margin: 0 auto;/*Page Should Be Centered When Zoomed Out*/
}

.infobox {
    margin: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    width: 300px;
    padding: 10px;
    border: 1px solid #ccc;
    background-color: rgba(249, 249, 249, 0.85);
}

.infobox-header {
    font-size: 1.5em;
    font-weight: bold;
}

.infobox-content {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-around;
}

.infobox-item {
    flex: 1;
    padding: 5px;
}

.infobox-container {
    display: flex;
    justify-content: space-around;
    flex-wrap: wrap;
}
.bdb-wnav-header{
	color: ghostwhite !important;
}
/*------------------Root Varibles------------------------*/
:root{
	--color-progressive: #36c;
	--color-content-added: #00ea51; /*The Div And Span*/
	/*-----------Page Stuff---------*/
	--main-bg: #FFFAD4; /*Site Background Color*/
	--link: #70B767; /*Site Link Color*/
	--hov-link: #64965d; /*Hovered Link*/
	--main-text: #000; /*Page Text Black*/
	/*----------Editor Tab---------*/
	--editor-tab-color: linear-gradient(#3a7bd5, #2a5298);
	--highlight-for-tabs: linear-gradient(#0000ac, #245292);
	/*---------Portable Infobox--------*/
	--defaultlink: #52bdff; /*Links Default Blue Color In Portable Infobox*/
	--pi-hov-link: #42a7f5; /*Hovered Link On Portable Infoboxes*/
	--no-link: #f00; /*No Link Or New Page*/
	--portable-infobox-color: #6c6c6c;
	--pi-secondary-background: #6c6c6c; /*Port Infobox Secondary Border Color*/
	/*---Catlinks---*/
	--catlinks: #FFF;
}
/*----------------Darkmode---------------*/
:root.client-darkmode{
	--color-progressive: #518bff;
	--color-content-added: #00ea51; /*The Div And Span*/
	--main-bg: #353535; /*Site Darkmode Background Color*/
	--link: #FFE26B; /*Site Dark Link Color*/
	--hov-link: #fad12a; /*Hovered Link*/
	--main-text: #FFFFFF; /*Page Text White On Darkmode*/
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlinks: #555555;
}
:root.client-theme-clientref-night{
	--color-progressive: #00ea51;
	--color-content-added: #006400;
	--main-bg: #353535;
	--link: #FFE26B;
	--hov-link: #fad12a;
	--main-text: #FFFFFF;
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlink: #555555;
}
/*-------------------------------Custom IDs/Classes----------------------------*/
/*Dialog-Related*/
html.client-darkmode .wikitable .dialog-related tr{
	font-size:110% !important;
	white-space:nowrap !important;
	text-shadow: 0 0 1px black, 0 0 1px black, 0 0 1px black, 0 0 1px black, 0 0 1px black !important;
}
/*Custom Table Of Contents In The Waterfall Style, Copied A Part From Roblox Isle Wiki Fandom*/
#custom-toc .toc {
	width: 98%;
}
#custom-toc .toc, 
#custom-toc .toc ul {
    column-width: 220px; 
    column-gap: 20px;
    list-style: none;
    padding: 0;
}
