}
.mw-body .firstHeading,
.mw-body .mw-heading1,
.mw-body .mw-heading2,
.sidebar-inner h3,
#personal-inner h3,
.mw-body .toctitle,
.mw-body .mw-specialpagesgroup { /* underline bottom border */
