}
/* TABLE OF CONTENTS */
ul#filetoc,
.toc,
.toccolours,
.mw-warning {
	background-color: var(--tableBg);
	border: 1px solid var(--tableBorder);
	box-shadow: none;
}
.mw-body .toctitle h2 {
	font-family: sans-serif;
}
.tocnumber {
	color: var(--textColor);
}
.toctogglecheckbox:not(:checked) + .toctitle .toctogglelabel:after {
	font-weight: initial;
}
.toc li:last-child {
	margin-bottom: 0;
}

/* DISMISSABLE NOTICE */
.mw-dismissable-notice {
	background: transparent;
	border: none;
	box-shadow: none;
}

/* FOOTER */
.mw-footer-container {
	background-color: var(--sidebarBg);
	background-clip: padding-box;
	border: 3px solid transparent;
	border-top: 0;
	border-image: var(--sidebarImg2) 5 / 0 5px 5px 5px round;
	box-shadow: none;
	color: var(--sidebarText);
	margin-bottom: 10px;
	margin-top: -4px;
	padding: 10px 5px;
}
.mw-footer-container a,
.mw-footer-container a:visited,
.mw-footer-container a:hover,
.mw-footer-container a:visited:hover {
	color: var(--sidebarColor);
}

#mw-footer {
	display: flex;
	flex-flow: row wrap;
	justify-content: center;
	gap: 0 10px;

	font-size: 0.9em;
}
#footer-icons {
	order: 2;
	margin: 0;
	flex-basis: 310px;

	display: flex;
	flex-flow: row wrap;
	justify-content: center;
	align-content: center;
	gap: 5px;
}
#footer-icons li {
	margin: 0;
	flex-basis: 88px;
	height: 31px;
}
#footer-icons li>a {
	padding: 0;
}
.cdx-button {
	transition-property: none;
	transition-duration: 0;
}
.cdx-button:enabled,
.cdx-button.cdx-button--fake-button--enabled {
	height: 31px;
}
.cdx-button:enabled:hover,
.cdx-button.cdx-button--fake-button--enabled:hover,
.cdx-button:enabled:active,
.cdx-button.cdx-button--fake-button--enabled:active,
.cdx-button:enabled.cdx-button--is-active,
.cdx-button.cdx-button--fake-button--enabled.cdx-button--is-active,
.cdx-button:enabled:focus:not(:active):not(.cdx-button--is-active),
.cdx-button.cdx-button--fake-button--enabled:focus:not(:active):not(.cdx-button--is-active) {
	box-shadow: none;
}
.cdx-button--size-large {
	min-height: initial;
}
#footer-copyrightico a, #footer-wikiapairyico a {
	background: transparent;
	border: 0;
}
#footer-list {
	flex-grow: 999;
	flex-basis: 250px;
}
@media screen and (min-width: 1100px) {
	.mw-footer-container {
		margin-left: 14em;
	}
}
@media screen and (max-width: 1099px) { /* compressed view */
.mw-footer-container {
		border-right: 0;
		border-left: 0;
		border-image: var(--sidebarImg2) 5 / 0 0 5px 0 round;
	}
}

/* CSS placed here will be applied to all skins */
/*Remove Elements Resize + Centered Page When Zooming*/
body{
	max-width: 1500px;
    margin-left: auto;
    margin-right: auto;
    width: 150%;
    min-width: 1200px !important;
    overflow-x: auto !important;
}

#content, #mw-content-text, .mw-body {
    width: 1200px !important;
    margin: 0 auto;/*Page Should Be Centered When Zoomed Out*/
}

.infobox {
    margin: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    width: 300px;
    padding: 10px;
    border: 1px solid #ccc;
    background-color: rgba(249, 249, 249, 0.85);
}

.infobox-header {
    font-size: 1.5em;
    font-weight: bold;
}

.infobox-content {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-around;
}

.infobox-item {
    flex: 1;
    padding: 5px;
}

.infobox-container {
    display: flex;
    justify-content: space-around;
    flex-wrap: wrap;
}
.bdb-wnav-header{
	color: ghostwhite !important;
}
/*------------------Root Varibles------------------------*/
:root{
	--color-progressive--focus: #36c;
	--color-progressive: #36c;
	--color-progressive--hover: #36c;
	--color-content-added: #006400; /*The Div And Span*/
	/*-----------Page Stuff---------*/
	--main-bg: #FFFAD4; /*Site Background Color*/
	--link: #70B767; /*Site Link Color*/
	--hov-link: #64965d; /*Hovered Link*/
	--main-text: #000; /*Page Text Black*/
	/*----------Editor Tab---------*/
	--editor-tab-color: linear-gradient(#3a7bd5, #2a5298);
	--highlight-for-tabs: linear-gradient(#0000ac, #245292);
	/*---------Portable Infobox--------*/
	--defaultlink: #52bdff; /*Links Default Blue Color In Portable Infobox*/
	--pi-hov-link: #42a7f5; /*Hovered Link On Portable Infoboxes*/
	--no-link: #f00; /*No Link Or New Page*/
	--portable-infobox-color: #6c6c6c;
	--pi-secondary-background: #6c6c6c; /*Port Infobox Secondary Border Color*/
	/*---Catlinks---*/
	--catlinks: #FFF;
}
/*----------------Darkmode---------------*/
:root.client-darkmode{
	--color-progressive--focus: #2f75ff;
	--color-progressive--hover: #2f75ff;
	--color-progressive: #2f75ff;
	--color-content-added: #00ea51; /*The Div And Span*/
	--main-bg: #353535; /*Site Darkmode Background Color*/
	--link: #FFE26B; /*Site Dark Link Color*/
	--hov-link: #fad12a; /*Hovered Link*/
	--main-text: #FFFFFF; /*Page Text White On Darkmode*/
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlinks: #555555;
}
:root.client-theme-clientref-night{
	--color-progressive--focus: #2f75ff;
	--color-progressive--hover: #2f75ff;
	--color-progressive: #2f75ff;
	--color-content-added: #00ea51;
	--main-bg: #353535;
	--link: #FFE26B;
	--hov-link: #fad12a;
	--main-text: #FFFFFF;
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlink: #555555;
}
