/* CSS placed here will be applied to all skins */
/*Remove Elements Resize + Centered Page When Zooming*/
body{
	max-width: 1500px;
    margin-left: auto;
    margin-right: auto;
    width: 150%;
    min-width: 1200px !important;
    overflow-x: auto !important;
}

#content, #mw-content-text, .mw-body {
    width: 1200px !important;
    margin: 0 auto;/*Page Should Be Centered When Zoomed Out*/
}

.infobox {
    margin: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    width: 300px;
    padding: 10px;
    border: 1px solid #ccc;
    background-color: rgba(249, 249, 249, 0.85);
}

.infobox-header {
    font-size: 1.5em;
    font-weight: bold;
}

.infobox-content {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-around;
}

.infobox-item {
    flex: 1;
    padding: 5px;
}

.infobox-container {
    display: flex;
    justify-content: space-around;
    flex-wrap: wrap;
}
