	}
	.client-js #ca-edit a,
	.client-js #ca-ve-edit a { /* Edit */
		background-position-x: -44px;
	}
	#ca-history a { /* History */
		background-position-x: -66px;
	}
	#ca-purge a { /* Purge */
		background-position-x: -88px;
	}
	#t-contributions a { /* User contribs */
		background-position-x: -110px;
	}
}
/* Watch */
#ca-watch a,
#ca-unwatch a {
	background-image: url(https://static.wikitide.net/pizzatowerwiki/1/1f/PTWiki-20px-watch.png);
}
#ca-watch a, #ca-unwatch a:hover {
	background-position: left top;
}
#ca-watch a:hover {
	background-position: -42px top;
}
#ca-unwatch a {
	background-position: -21px top;
}
/* EDIT NOTIF */
.mw-notification {
	background-color: var(--sidebarBg);
	background-clip: padding-box;
	border: 5px solid transparent;
	border-image: var(--sidebarImg3) 5 / 5px;
	color: var(--sidebarText);
	padding: 10px;
}
.mw-notification a {
	color: var(--sidebarColor);
}
.oo-ui-messageWidget.oo-ui-flaggedElement-success:not(.oo-ui-messageWidget-block) {
	color: var(--successfulEditText);
}
.oo-ui-image-success.oo-ui-icon-success,
.mw-ui-icon-success-success::before {
	background-image: url(https://static.wikitide.net/pizzatowerwiki/3/33/PTW-confirmEdit.png);
	width: 20px;
	height: 20px;
	filter: var(--successFilter);
}
/* BODY CONTENT */
/* Body headers */
.mw-body h1,
.mw-body h2,
.mw-body .mw-heading1,
.mw-body .mw-heading2,
.sidebar-inner h3,
#personal-inner h3,
.mw-body .toctitle,
.ext-discussiontools-visualenhancements-enabled .ext-discussiontools-init-section { /* old underline / heading border */
	border-color: transparent !important; /* keep important on this */
}
.ext-discussiontools-visualenhancements-enabled .ext-discussiontools-init-section,
.mw-body .toctitle,
.mw-body .mw-heading,
.mw-body .mw-heading1,
.mw-body .mw-heading2,
.mw-body h1,
.mw-body h2,
.mw-body h3,
.mw-body h4,
.mw-body h5,
.mw-body h6,
.mw-body dt,
.sidebar-inner h3,
#personal-inner h3 {
	font-family: sans-serif;
	font-weight: bold;
}
.mw-body .firstHeading,
.mw-body .mw-heading1,
.mw-body .mw-heading2,
.sidebar-inner h3,
#personal-inner h3,
.mw-body .toctitle,
.mw-body .mw-specialpagesgroup { /* underline bottom border */
	border-image: var(--underlineBorder) 0 0 2 0 / 0 0 2px 0 round round;
}
.mw-body .firstHeading {
	font-size: 1.8em;
}
.ext-discussiontools-visualenhancements-enabled .ext-discussiontools-init-section,
.ext-discussiontools-emptystate:not(:first-child) { /* underline top border */
	border-image: var(--underlineBorder) 2 0 0 0 / 2px 0 0 0 round round;
}
.mw-body .toctitle h2 {
	border: none !important;
}
#siteSub { /* "from [wiki]" */
	font-family: sans-serif;
}
/* TABLE OF CONTENTS */
ul#filetoc,
.toc,
.toccolours,
.mw-warning {
	background-color: var(--tableBg);
	border: 1px solid var(--tableBorder);
	box-shadow: none;
}
.mw-body .toctitle h2 {
	font-family: sans-serif;
}
.tocnumber {
	color: var(--textColor);
}
.toctogglecheckbox:not(:checked) + .toctitle .toctogglelabel:after {
	font-weight: initial;
}
.toc li:last-child {
	margin-bottom: 0;
}
/* IMAGE FRAMES */
figure[typeof~="mw:File/Thumb"],
figure[typeof~="mw:File/Frame"] { /* images embedded into the article */
	background-clip: padding-box;
	background-color: #ffc5ff;
	border: 3px solid transparent;
	border-collapse: unset;
	border-image: url(https://static.wikitide.net/pizzatowerwiki/7/7a/PTWiki-border-gallerybox.png) 32 / 32px round round;
	box-shadow: none;
	display: block;
	padding: 0 12px 6px 8px;
}
figure[typeof~="mw:File/Thumb"] > :not(figcaption) .mw-file-element,
figure[typeof~="mw:File/Frame"] > :not(figcaption) .mw-file-element { /* image */
	border: 1px solid black;
	margin: 11px 4px 8px;
}
figure[typeof~="mw:File/Thumb"] > figcaption,
figure[typeof~="mw:File/Frame"] > figcaption {
	background-color: transparent;
	border: none;
	box-shadow: none;
	box-sizing: border-box;
	width: 100%;
}
@media screen and (max-width: 850px) {
	figure[typeof~="mw:File/Thumb"],
	figure[typeof~="mw:File/Frame"] {
		display: flex;
		flex-flow: column;
	}
	figure[typeof~="mw:File/Thumb"] > figcaption,
	figure[typeof~="mw:File/Frame"] > figcaption {
		padding: 0 6px 8px;
	}
	figure[typeof~="mw:File/Thumb"] > :not(figcaption) .mw-file-element,
	figure[typeof~="mw:File/Frame"] > :not(figcaption) .mw-file-element { /* image */
		margin: 11px 0 8px;
	}
	.mw-content-ltr figure[typeof~="mw:File/Thumb"] > .mw-file-description:after,
	.mw-content-ltr figure[typeof~="mw:File/Thumb"] > .mw-file-magnify:after { /* link to image icon */
		right: 7px;
	}
}
figure[typeof~="mw:File/Thumb"] > :not(figcaption) .mw-file-element,
figure[typeof~="mw:File/Frame"] > :not(figcaption) .mw-file-element {
	max-width: 100% !important;
}
/* GALLERY BOXES */
.mw-body li.gallerybox div.thumb {
	background-clip: padding-box;
	background-color: #ffc5ff !important;
	border: 3px solid transparent;
	border-image: url(https://static.wikitide.net/pizzatowerwiki/7/7a/PTWiki-border-gallerybox.png) 32 / 32px round round;
	box-shadow: none;
	box-sizing: border-box;
	margin: 0 auto;
	padding: 0 12px 6px 8px;
}
div.gallerytext {
	padding: 0;
	margin: 10px 4px 0;
}
ul.gallery.gallery.gallery { /* don't ask me why there's 3 checks for the gallery glass, it's just like this */
	display: flex;
	flex-flow: row wrap;
	gap: 15px 10px;
}

/* DISMISSABLE NOTICE */
.mw-dismissable-notice {
	background: transparent;
	border: none;
	box-shadow: none;
}

/* FOOTER */
.mw-footer-container {
	background-color: var(--sidebarBg);
	background-clip: padding-box;
	border: 3px solid transparent;
	border-top: 0;
	border-image: var(--sidebarImg2) 5 / 0 5px 5px 5px round;
	box-shadow: none;
