			--codeBg: #406ba1;
			--codeText: #ABFF00;
			--codeAccent: #c8f8a8;
			--codeBorder: white;
			--codeBtn1Norm: url(https://static.wikitide.net/pizzatowerwiki/f/f5/PTWiki-editorButton1-1.png) 20 / 20px round round;
			--codeBtn1Hover: url(https://static.wikitide.net/pizzatowerwiki/9/9b/PTWiki-editorButton1-2.png) 20 / 20px round round;
			--codeBtn2Norm: url(https://static.wikitide.net/pizzatowerwiki/8/8b/PTWiki-editorButton2-1.png) 20 / 20px round round;
			--codeBtn2Hover: url(https://static.wikitide.net/pizzatowerwiki/f/f2/PTWiki-editorButton2-2.png) 20 / 20px round round;
		/* MISC BUTTONS */
			--miscButton1BorderNorm: url(https://static.wikitide.net/pizzatowerwiki/8/8e/PTWiki-miscButton-2.png) 20 / 20px round round;
			--miscButton1BorderHover: url(https://static.wikitide.net/pizzatowerwiki/e/e9/PTWiki-miscButton-1.png) 20 / 20px round round;
			--miscButton1BgNorm: #786898;
			--miscButton1BgHover: #b07898;
			--miscButton2BorderNorm: url(https://static.wikitide.net/pizzatowerwiki/9/99/PTWiki-miscButton2-1.png) 20 / 20px round round;
			--miscButton2BorderHover: url(https://static.wikitide.net/pizzatowerwiki/5/50/PTWiki-miscButton2-2.png) 20 / 20px round round;
			--miscButton2BgNorm: #f8e8d0;
			--miscButton2BgHover: white;
}
a,
a:hover,
a.visited,
a.visited:hover {
	color: var(--linkColor);
}
a.extiw,
a.extiw:active,
a.external,
a.external:hover {
	color: var(--externalColor) !important;
}
a.new,
a.new:hover {
	color: var(--newColor);
}
a.new:visited,
a.new:visited:hover {
	color: var(--newVisitedColor);
}
code,
pre,
.mw-code {
	background-color: var(--codeBg);
	border: 1px solid var(--codeBorder);
	color: var(--codeText);
}
code {
	padding: 2px 4px;
}
code a,
code a:hover,
code a.visited,
code a.visited:hover {
	color: var(--codeBorder);
}
/* MH BUTTONS */
.oo-ui-buttonElement.oo-ui-widget-enabled > .oo-ui-buttonElement-button,
.oo-ui-buttonElement-framed.oo-ui-widget-enabled.oo-ui-flaggedElement-primary.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button {
	background-clip: padding-box;
	border: 3px solid transparent;
	transition-property: none;
}
.oo-ui-buttonElement.oo-ui-widget-enabled > .oo-ui-buttonElement-button:hover,
.oo-ui-buttonElement-framed.oo-ui-widget-enabled.oo-ui-flaggedElement-primary.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button:hover,
.oo-ui-buttonElement.oo-ui-widget-enabled > .oo-ui-buttonElement-button:active,
.oo-ui-buttonElement-framed.oo-ui-widget-enabled.oo-ui-flaggedElement-primary.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button:active {
	border-color: transparent;
}
.mw-htmlform-submit-buttons input[type="submit"].mw-htmlform-submit { /* Upload */
	background-clip: padding-box;
	background-color: var(--miscButton1BgNorm) !important;
	border: 3px solid transparent !important;
	border-image: var(--miscButton1BorderNorm) !important;
}
.mw-htmlform-submit-buttons input[type="submit"].mw-htmlform-submit:hover {
	background-color: var(--miscButton1BgHover) !important;
	border-image: var(--miscButton1BorderHover) !important;
}
/* File list buttons */
.mw-htmlform-submit-buttons .oo-ui-buttonElement-framed.oo-ui-widget-enabled.oo-ui-flaggedElement-primary.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button {
	background-color: var(--miscButton1BgNorm);
	border-image: var(--miscButton1BorderNorm);
}
.mw-htmlform-submit-buttons .oo-ui-buttonElement-framed.oo-ui-widget-enabled.oo-ui-flaggedElement-primary.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button:hover {
	background-color: var(--miscButton1BgHover);
	border-image: var(--miscButton1BorderHover);
}
/* FILE LIST */
.oo-ui-panelLayout-framed {
	border: 1px solid transparent;
	border-image: url(https://static.wikitide.net/pizzatowerwiki/7/76/PTWiki-boxborder.png) 4 / 4px round round;
}
/* COOKIE WARNING */
.mw-cookiewarning-container {
	background-clip: padding-box;
	background-color: #fff5c4;
	border-top: 8px solid transparent;
	border-image: url(https://static.miraheze.org/pizzatowerwiki/6/6a/PTWiki-border-tvbubble-notice.gif) 20 / 20px 0 0 0 round round;
}
.mw-cookiewarning-container .mw-cookiewarning-text {
	color: black;
	font-weight: initial;
}
.mw-cookiewarning-container .oo-ui-buttonElement-framed.oo-ui-widget-enabled.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button { /* More Info button (and the other button technically) */
	background-color: var(--miscButton2BgNorm);
	border-image: var(--miscButton2BorderNorm);
	color: var(--linkColor);
}
.mw-cookiewarning-container .oo-ui-buttonElement-framed.oo-ui-widget-enabled.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button:hover {
	background-color: var(--miscButton2BgHover);
	border-image: var(--miscButton2BorderHover);
}
.mw-cookiewarning-container .oo-ui-buttonElement-framed.oo-ui-widget-enabled.oo-ui-flaggedElement-primary.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button { /* "OK" button */
	background-color: var(--miscButton1BgNorm);
	border-image: var(--miscButton1BorderNorm);
	color: white;
}
.mw-cookiewarning-container .oo-ui-buttonElement-framed.oo-ui-widget-enabled.oo-ui-flaggedElement-primary.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button:hover {
	background-color: var(--miscButton1BgHover);
	border-image: var(--miscButton1BorderHover);
}

