		/* MISC BUTTONS */
			--miscButton1BorderNorm: url(https://static.wikitide.net/pizzatowerwiki/8/8e/PTWiki-miscButton-2.png) 20 / 20px round round;
			--miscButton1BorderHover: url(https://static.wikitide.net/pizzatowerwiki/e/e9/PTWiki-miscButton-1.png) 20 / 20px round round;
			--miscButton1BgNorm: #786898;
			--miscButton1BgHover: #b07898;
			--miscButton2BorderNorm: url(https://static.wikitide.net/pizzatowerwiki/9/99/PTWiki-miscButton2-1.png) 20 / 20px round round;
			--miscButton2BorderHover: url(https://static.wikitide.net/pizzatowerwiki/5/50/PTWiki-miscButton2-2.png) 20 / 20px round round;
			--miscButton2BgNorm: #f8e8d0;
			--miscButton2BgHover: white;
}
a,
a:hover,
a.visited,
