/* To newbie Miraheze admins - DO NOT COPY IF YOU DON'T KNOW CSS, you'll only confuse yourself more, please learn the basics first and start with small things. */
/* Basic elements */
body {
	background-color: var(--bgColor);
	background-image: var(--bgImg);
	background-size: 400px 400px;
	background-repeat: repeat;	
}
#mw-content-container {
	background: transparent;
	border: none;
	padding-bottom: 0;
}
/* SITE HEADER */
#mw-header-container {
	border-bottom: 2px solid transparent;
	background-color: var(--sidebarBg);
	background-clip: padding-box;
	border-image: var(--sidebarImg3) 13 / 0 0 13px 0 round round;
	padding: 8px 0 2px;
}
#mw-header-nav-hack, #mw-header-hack {
	display: none;
}
.wordmark img {
	aspect-ratio: initial;
	width: auto;
	height: 40px;
	margin-top: -5px;
}
#simpleSearch {
	background: transparent;
	border: none;
	box-shadow: none;
}
#searchInput {
	background-color: var(--searchInputBg);
	border: 1px solid black;
}
#searchButton, #mw-searchButton {
	aspect-ratio: 1/1;
	background-color: var(--searchBtnBg);
	border: 1px solid black;
	height: 100%;
	width: auto;
	right: 0;
}
@media screen and (max-width: 850px) {
	#mw-header-container {
		padding: 8px 0 5px;
	}
	#p-logo-text {
		display: none;
	}
	#p-search {
		position: relative;
		left: 60px;
		width: calc(100% - 205px);
	}
	#personal-extra,
	#user-tools h2,
	.sidebar-chunk h2 {
		top: 0;
	}
	#personal-extra {
		right: 50px;
	}
	#user-tools h2 {
		right: 25px;
	}
	#site-navigation h2 {
		background-image: var(--burgerMenu);
		top: 7px;
	}
}
#user-tools {
	position: relative;
	top: -3px;
}
#personal h2 span {
