/* BODY CONTENT */
/* Body headers */
.mw-body h1,
.mw-body h2,
.mw-body .mw-heading1,
.mw-body .mw-heading2,
.sidebar-inner h3,
#personal-inner h3,
.mw-body .toctitle,
.ext-discussiontools-visualenhancements-enabled .ext-discussiontools-init-section { /* old underline / heading border */
