}
.ext-discussiontools-visualenhancements-enabled .ext-discussiontools-init-section,
.mw-body .toctitle,
.mw-body .mw-heading,
.mw-body .mw-heading1,
.mw-body .mw-heading2,
.mw-body h1,
.mw-body h2,
.mw-body h3,
.mw-body h4,
.mw-body h5,
