/*------------------Root Varibles------------------------*/
:root{
	/*-----------Page Stuff---------*/
	--main-bg: #FFFAD4; /*Site Background Color*/
	--link: #70B767; /*Site Link Color*/
	--hov-link: #64965d; /*Hovered Link*/
	--text-primary-color: #000; /*Page Text Black*/
	/*----------Editor Tab---------*/
	--editor-tab-color: linear-gradient(#3a7bd5, #2a5298);
	--highlight-for-tabs: linear-gradient(#0000ac, #245292);
	/*---------Portable Infobox--------*/
	--defaultlink: #52bdff; /*Links Default Blue Color In Portable Infobox*/
	--pi-hov-link: #42a7f5; /*Hovered Link On Portable Infoboxes*/
	--no-link: #f00; /*No Link Or New Page*/
	--portable-infobox-color: #6c6c6c;
	--pi-secondary-background: #6c6c6c; /*Port Infobox Secondary Border Color*/
	/*---Catlinks---*/
	--catlinks: #FFF;
}
/*----------------Darkmode---------------*/
:root.client-darkmode{
	--main-bg: #353535; /*Site Darkmode Background Color*/
	--link: #FFE26B; /*Site Dark Link Color*/
	--hov-link: #fad12a; /*Hovered Link*/
	--text-primary-color: #FFFFFF; /*Page Text White On Darkmode*/
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlinks: #555555;
}
:root.client-theme-clientref-night{
	--main-bg: #353535;
	--link: #FFE26B;
	--hov-link: #fad12a;
	--text-primary-color: #FFFFFF;
	--portable-infobox-color: #f00 !important;
	--pi-secondary-background: #f00 !important;
	--catlink: #555555;
}



