/* Hauptbox: Bestimmt das allgemeine Aussehen des Kastens */
.mw-infobox {
  display: flex;             /* Aktiviert Flexbox, um Rahmen, Icon und Text nebeneinander anzuordnen */
  align-items: center;       /* Zentriert alle Elemente (Rahmen, Icon, Text) vertikal in der Box */
  padding: 12px;             /* Innenabstand: Abstand vom Inhalt zum äußeren Rand der Box */
  margin: 10px 0;            /* Außenabstand: 10px Platz nach oben und unten zu anderen Absätzen */
  border-radius: 4px;        /* Rundet die vier Ecken der Box leicht ab */
}

/* Farbiger Rahmen: Der abgerundete Balken ganz links */
.mw-infobox-border {
  width: 6px;                /* Breite des farbigen Balkens */
  height: 40px;              /* Höhe des Balkens */
  border-radius: 4px;        /* Macht den Balken links und rechts abgerundet */
  margin-right: 15px;        /* Abstand vom Balken nach rechts zum Icon */
  flex-shrink: 0;            /* Verhindert, dass der Balken zusammengedrückt wird */
}

/* Icon-Bereich: Platzhalter für das Font Awesome Symbol */
.mw-infobox-icon {
  display: flex;             /* Erlaubt uns, das Icon exakt zu steuern */
  align-items: center;       /* Zentriert das Icon vertikal in seinem Bereich */
  justify-content: center;   /* Zentriert das Icon horizontal in seinem Bereich */
  width: 30px;               /* Feste Breite, damit der Text immer auf derselben Linie startet */
  margin-right: 15px;        /* Abstand vom Icon nach rechts zum Text */
  flex-shrink: 0;            /* Verhindert, dass das Icon gequetscht wird */
}

/* Text-Bereich: Der eigentliche Inhalt der Box */
.mw-infobox-text {
  flex-grow: 1;              /* Sorgt dafür, dass der Text den restlichen freien Platz ausfüllt */
}

/* --- FARB-STEUERUNG NACH TYP --- */
/* Hier ändern wir jetzt den Balken UND den Hintergrund der Box gleichzeitig */

/* 1. Typ: INFO (Blau) */
.mw-infobox.info {
  background-color: #f0f7ff; /* Sehr helles Blau für den Hintergrund */
}
.mw-infobox.info .mw-infobox-border { 
  background-color: #0066cc; /* Kräftiges Blau für den Balken links */
}

/* 2. Typ: WARNUNG (Rot) */
.mw-infobox.warnung {
  background-color: #fff5f5; /* Sehr helles Rot für den Hintergrund */
}
.mw-infobox.warnung .mw-infobox-border { 
  background-color: #cc0000; /* Kräftiges Rot für den Balken links */
}

/* 3. Typ: ERFOLG (Grün) */
.mw-infobox.erfolg {
