//<nowiki>
/* Gadget: ReportSRG (Miraheze)
   Adds a "Global Lock Report" button in the personal toolbar.
   Clicking opens a form to input usernames and reason.
   Rules:
   - 1 user → {{LockHide|User}}
   - 2–10 users → {{MultiLock|User1|User2|...}}
   - >10 users → limited to 10
   - On Meta (meta.miraheze.org): gadget appends signature automatically
   - Target page: Steward requests/Global
*/

$(function () {
    // 僅在 MetaWiki 顯示 （原設計）
    if (!mw.config.get('wgServer').includes('publictestwiki.com')) {
        return;
    }

    mw.util.addPortletLink(
        'p-personal',
        '#',
        'Global Lock Report',
        'pt-global-lock-report',
        'Report user(s) to Steward requests/Global'
    );

    $('#pt-global-lock-report').on('click', function (e) {
        e.preventDefault();

        var $form = $('<div id="globalLockForm">').css({
            padding: '1em',
            border: '1px solid #ccc',
            background: '#f9f9f9'
        });
        $form.append('<h3>Report user(s) for global lock</h3>');
        $form.append('<label>Section title (required): </label><input id="reportTitle" style="width:300px" placeholder="Username of user being locked"><br><br>');

        var $userContainer = $('<div id="userContainer">');
        $form.append($userContainer);
        $form.append('<button id="addUser">Add another username</button><br><br>');

        $form.append('<label>Reason (required, do NOT sign with ~~~~): </label><input id="reason" style="width:300px" placeholder="Explain the reason here"><br><br>');

        $form.append('<button id="submitReport">Submit report</button> <button id="cancelReport">Cancel</button>');

        $('#mw-content-text').prepend($form);

        function addUserField() {
            if ($('#userContainer .userRow').length >= 10) {
                alert('MultiLock supports at most 10 usernames.');
                return;
            }
            var $row = $('<div class="userRow">').css({ margin: '5px 0' });
            $row.append('<input class="username" style="width:200px" placeholder="username"> ');
            $row.append('<label><input type="checkbox" class="hideName"> Hide?</label>');
            $userContainer.append($row);
        }

        addUserField();
        $('#addUser').click(function (ev) {
            ev.preventDefault();
            addUserField();
        });

        $('#submitReport').click(async function () {
            var title = $('#reportTitle').val().trim();
            var reason = $('#reason').val().trim();
            var users = [];

            $('#userContainer .userRow').each(function () {
                var uname = $(this).find('.username').val().trim();
                var hide = $(this).find('.hideName').is(':checked');
                if (uname) users.push({ name: uname, hide: hide });
            });

            if (!title) {
                alert('Section title is required.');
                return;
            }
            if (!reason) {
                alert('Reason is required.');
                return;
            }
            if (users.length === 0) {
                alert('At least one username must be entered.');
                return;
            }

            var wikitext = '== ' + title + ' ==\n{{status}}\n';

            if (users.length === 1) {
                var u = users[0];
                wikitext += '*{{LockHide|' + u.name + (u.hide ? '|hidename=1' : '') + '}}\n';
            } else {
                var limitedUsers = users.slice(0, 10);
                wikitext += '*{{MultiLock|' + limitedUsers.map(function (u) {
                    return u.name + (u.hide ? '|hidename=1' : '');
                }).join('|') + '}}\n';
            }

            wikitext += '*:' + reason + ' ~~~~';

            var targetTitle = 'Steward requests/Global';

            var api = new mw.Api();
            try {
                await api.postWithEditToken({
                    action: 'edit',
                    title: targetTitle,
                    appendtext: '\n' + wikitext + '\n',
                    summary: 'Reporting user(s) for global lock ([[dev:User:PB2008/ReportSRG.js|ReportSRG]])'
                });
                mw.notify('Report successfully submitted to Steward requests/Global on Meta', { type: 'success' });
            } catch (e) {
                console.error(e);
                mw.notify('Error submitting report: ' + e.toString(), { type: 'error' });
            }
        });

        $('#cancelReport').click(function () {
            $('#globalLockForm').remove();
        });
    });
});
