		background-image: var(--burgerMenu);
		top: 7px;
	}
}
#user-tools {
	position: relative;
	top: -3px;
}
#personal h2 span {
	color: var(--sidebarText);
	font-family: sans-serif;
	font-weight: bold;
}
.oo-ui-icon-bell,
.oo-ui-icon-tray,
#personal h2 { /* old icons */
	background-image: none;
	opacity: 1 !important;
}
#pt-notifications-alert a:before, /* alert */
#pt-notifications-notice a:before, /* notice */
#personal h2:before /* personal */ {
	background-image: url(https://static.wikitide.net/pizzatowerwiki/c/c3/PT-WikiImage-UserIcons.png);
	background-size: auto 100%;
	content: '';
	display: block;
	position: absolute;
	top: 0;
	left: 0;
	width: 20px;
	height: 20px;
}
#pt-notifications-alert .mw-echo-notifications-badge.mw-echo-unseen-notifications:after,
#pt-notifications-notice .mw-echo-notifications-badge.mw-echo-unseen-notifications:after {
	background-color: #e03000;
}
#personal h2:before { /* new personal icon */
	background-position: left top;
	transform: translateY(50%);
}
#pt-notifications-alert a:before { /* new alert icon */
	background-position: -21px top;
}
#pt-notifications-notice a:before { /* new notice icon */
	background-position: -42px top;
}
@media screen and (max-width: 850px) {
	#user-tools h2:after,
	.sidebar-chunk h2:after {
		background-image: var(--sidebarDropdownArrow);
	}
}
/* SIDEBARS */
