.mw-footer-container {
	background-color: var(--sidebarBg);
	background-clip: padding-box;
	border: 3px solid transparent;
	border-top: 0;
	border-image: var(--sidebarImg2) 5 / 0 5px 5px 5px round;
	box-shadow: none;
