            hideLabel: 'Hide?',
            completeAll: 'Please complete title, reason and at least one username.',
            usernameLabel: 'username',
            portletTooltip: 'Report user(s) to Steward requests/Global'
        }
    };

    const hansLangs = ['zh-hans','zh-cn','zh-my','zh-sg','zh'];
    const hantLangs = ['zh-hant','zh-hk','zh-mo','zh-tw'];

    const lang = mw.config.get('wgUserLanguage').toLowerCase();
    let chosen;
    if (hansLangs.includes(lang)) {
        chosen = messages['zh-hans'];
    } else if (hantLangs.includes(lang)) {
        chosen = messages['zh-hant'];
    } else if (lang === 'yue-hans') {
        chosen = messages['yue-hans'];
    } else if (lang === 'yue-hant' || lang === 'yue') {
        chosen = messages['yue-hant'];
    } else {
        chosen = messages['en'];
    }

    mw.util.addPortletLink('p-personal','#',chosen.button,'pt-global-lock-report',chosen.portletTooltip);

    $('#pt-global-lock-report').on('click', function (e) {
        e.preventDefault();

        var $form = $('<div id="globalLockForm">').css({padding:'1em',border:'1px solid #ccc',background:'#f9f9f9'});
        $form.append('<h3>' + chosen.button + '</h3>');
        $form.append('<label>' + chosen.titleLabel + '</label><input id="reportTitle" style="width:300px"><br><br>');

        var $userContainer = $('<div id="userContainer">');
        $form.append($userContainer);
        $form.append('<button id="addUser">' + chosen.addUser + '</button><br><br>');

        $form.append('<label>' + chosen.reasonLabel + '</label><input id="reason" style="width:300px"><br><br>');
        $form.append('<button id="submitReport">' + chosen.submit + '</button> <button id="cancelReport">' + chosen.cancel + '</button>');
        $('#mw-content-text').prepend($form);

        function addUserField() {
            var count = $('#userContainer .userRow').length;
            if (count >= 10) {
                alert(chosen.multiLockLimit);
                $('#addUser').hide();
                return;
            }
            var $row = $('<div class="userRow">').css({margin:'5px 0'});
            $row.append('<input class="username" style="width:200px" placeholder="' + chosen.usernameLabel + '"> ');
            $row.append('<label><input type="checkbox" class="hideName"> ' + chosen.hideLabel + '</label>');
            $userContainer.append($row);

            if ($('#userContainer .userRow').length >= 10) {
                $('#addUser').hide();
            }
        }

        addUserField();
        $('#addUser').click(function (ev) {ev.preventDefault();addUserField();});

        $('#submitReport').click(async function () {
            var title = $('#reportTitle').val().trim();
            var reason = $('#reason').val().trim();
            var users = [];

            $('#userContainer .userRow').each(function () {
                var uname = $(this).find('.username').val().trim();
                var hide = $(this).find('.hideName').is(':checked');
                if (uname) users.push({ name: uname, hide: hide });
            });

            if (!title || !reason || users.length === 0) {
                alert(chosen.completeAll);
                return;
            }

            var wikitext = '== ' + title + ' ==\n{{status}}\n';
            if (users.length === 1) {
                var u = users[0];
                wikitext += '*{{LockHide|' + u.name + (u.hide ? '|hidename=1' : '') + '}}\n';
            } else {
                var limitedUsers = users.slice(0, 10);
                wikitext += '*{{MultiLock|' + limitedUsers.map(function (u) {
                    return u.name + (u.hide ? '|hidename=1' : '');
                }).join('|') + '}}\n';
            }
            wikitext += '*:' + reason + ' ~~~~';

            var targetTitle = 'Steward requests/Global';
            var api = new mw.Api();
            try {
                await api.postWithEditToken({
                    action: 'edit',
                    title: targetTitle,
                    appendtext: '\n' + wikitext + '\n',
                    summary: 'Reporting user(s) for global lock ([[dev:User:PB2008/ReportSRG.js|ReportSRG]])'
                });
                mw.notify(chosen.success,{type:'success'});
            } catch (e) {
                console.error(e);
                mw.notify(chosen.error + e.toString(),{type:'error'});
            }
        });

        $('#cancelReport').click(function () {$('#globalLockForm').remove();});
    });
});
