}
.mw_metadata > tr > th,
.mw-datatable > tr > th,
.mw_metadata > tr > td,
.mw-datatable > tr > td,
.wikitable > tr > th,
.wikitable > tr > td,
.mw_metadata > * > tr > th,
.mw-datatable > * > tr > th,
