/* CODE PREVIEW */
.mw-highlight {
	background: transparent;
}
.mw-content-ltr.mw-highlight-lines pre,
.mw-content-ltr.content .mw-highlight-lines pre {
	background-clip: padding-box;
	border: 5px solid transparent;
	border-image: url(https://static.miraheze.org/pizzatowerwiki/6/6b/PTWiki-spr_computerbubble.png) 35 / 35px round round;
	box-shadow: inset 3.25em 0 0 var(--codeAccent); /* lines (as in like, what line is the code on) */
	padding: 14px 22px 14px 4em;
}
.mw-content-ltr.mw-highlight-lines pre,
.mw-content-ltr.content .mw-highlight-lines pre,
.mw-highlight pre {
	line-height: 1.5; /* to help make code more readable */
}
.mw-content-ltr.mw-highlight .linenos { /* code line number position */
	left: 10px;
}
.mw-highlight .linenos { /* code line number color */
	color: var(--codeBg);
}
.mw-highlight a:hover .linenos,
.mw-highlight .hll a .linenos {
	color: var(--codeBg);
	text-decoration: underline;
}
.mw-highlight .hll { /* highlighting a line of code */
	background-color: #c8f8a83d;
}
.mw-highlight pre,
.mw-highlight .o { /* regular text */
	color: var(--codeText);	
}
.mw-highlight .c,
.mw-highlight .c1,
.mw-highlight .cm,
.mw-highlight .c a,
.mw-highlight .c1 a,
.mw-highlight .cm a { /* comments & comments w/ links */
	color: #98e8f8;
}
.mw-highlight .cp { /* !important */
	color: #f8e080;
}
.mw-highlight .k,
.mw-highlight .o { /* property titles, operators */
	color: var(--codeAccent);
}
.mw-highlight .kc,
.mw-highlight .kr,
.mw-highlight .kd,
.mw-highlight .nf  { /* keywords, lua keywords, javascript keywords, var keyword */
	color: #60d048;
}
.mw-highlight .kt { /* units of measurement */
	color: #f8c0b0;
}
.mw-highlight .mh { /* hex codes */
	color: #d9d9d9;
}
.mw-highlight .mf,
.mw-highlight .mi { /* decimals, integers */
	color: #d8b8f8;
}
.mw-highlight .nb,
.mw-highlight .sx { /* functions, urls */
	color: #60d048;
}
.mw-highlight .nc,
.mw-highlight .nn,
.mw-highlight .nv { /* classes, ids, variables */
	color: white;
}
.mw-highlight .nd,
.mw-highlight .ow { /* pseudo-elements, lua "not" */
	color: #f8a0f8;
}
.mw-highlight .nt { /* html elements */
	color: #f8a880;
}
.mw-highlight .s1,
.mw-highlight .s2,
.mw-highlight .sr { /* strings */
	color: #f8c0b0;
}

/* WIKI TABLES */
.mw_metadata,
.mw-datatable,
.wikitable { /* outer border */
	border: 2px solid var(--tableBorder);
}
.wikitable > tr > th,
.wikitable > * > tr > th,
.mw_metadata th,
.wikitable th,
.mw-datatable th,
.mw-datatable tr:hover td { /* table headers */
	background-color: var(--tableBg);
}
.mw-body .mw-rcfilters-ui-changesListWrapperWidget .mw-changeslist-legend,
.mw-changeslist-legend, .mw-body .mw-search-profile-tabs,
.mw-body fieldset#mw-searchoptions,
.mw_metadata,
.wikitable,
.mw-datatable,
.mw-datatable td { /* table body */
	background-color: var(--contentBg);
}
.mw_metadata > tr > th,
.mw-datatable > tr > th,
.mw_metadata > tr > td,
.mw-datatable > tr > td,
.wikitable > tr > th,
.wikitable > tr > td,
.mw_metadata > * > tr > th,
.mw-datatable > * > tr > th,
.wikitable > * > tr > th,
.mw_metadata > * > tr > td,
.mw-datatable > * > tr > td,
.wikitable > * > tr > td,
.mw-datatable td { /* inner border */
	border: 1px solid var(--tableBorder);
}

