            e.preventDefault();

            const sel = view.state.selection.main;
            const from = sel.from;
            const to = sel.to;

            const insertText = "\t";

            view.dispatch({
                changes: { from, to, insert: insertText },
                selection: {
                    anchor: from + insertText.length
                }
            });
        }
    });
});

