        const normalizedLocale = locale ? String(locale).toLowerCase() : '';
        const fallback = FALLBACK_LIST[normalizedLocale] || DEFAULT_FALLBACK;

        for (const key of fallback) {
            const value = candidates[key];
            if (value != null) {
                return value;
            }
        }
        return null;
    }

    // 核心候选安全选取逻辑
    function safeElect(candidates, locale) {
        if (!isPlainObject(candidates)) {
            throw new TypeError('[HanAssist] 候选参数必须是一个对象。');
        }
        const result = elect(candidates, locale) ?? '';
        return safelyToString(result);
    }

    /**
     * 单条文本转换
     * @param {Object} candidates 包含不同语言/地区变体文本的对象
     * @param {string} locale 目标语言/区域设置（如 'zh-cn', 'zh-tw'）
     */
    function conv(candidates, locale = 'zh-cn') {
        return safeElect(candidates, locale);
    }

    /**
     * 批量文本转换
     * @param {Object} candidatesDict 包含多条候选文本字典的对象
     * @param {string} locale 目标语言/区域设置
     */
    function batchConv(candidatesDict, locale = 'zh-cn') {
        if (!isPlainObject(candidatesDict)) {
            throw new TypeError('[HanAssist] 参数必须是一个对象。');
        }

        const result = {};
        for (const key in candidatesDict) {
            const candidates = candidatesDict[key];
            if (isPlainObject(candidates)) {
                const electResult = elect(candidates, locale) ?? '';
                result[key] = safelyToString(electResult);
            } else {
                result[key] = safelyToString(candidates);
            }
        }
        return result;
    }

