/*---------------Root Variables------------------------*/
:root{
	--background-color-warning-subtle: #2d2511;
	--pi-background: #212121;
	--pi-secondary-background: #21273c;
	--pi-border-color: #fff;
	--color-base: #fff;
	--background-color-progressive-subtle: #04111b;
	--site-primary-color:linear-gradient(to top, #0b1522, #0f2034de);
}

/*-----------------Apply Background And Font---------------*/

body{
	font-family: 'Cardo';
    background: linear-gradient(to top, #0b1522, #0f2034de);
    background-repeat: no-repeat;
    background-attachment: fixed;
}
/*--------------Panel--------------------*/
#mw-panel li a > span{
	font-size: medium;
	background: #fff;
	-webkit-background-clip:text;
    -webkit-text-fill-color: transparent;
}
#mw-panel li a span:hover {
	text-decoration: underline !important;
	text-decoration-color: #fff !important;
}
#mw-panel{
	background:transparent
}

/*-------------------Personal Tabs-----------------*/

#mw-head{
	background:#2a3849
}
#mw-head #p-personal{
	position: absolute;
	padding-top:6px;
	padding-right: 20px;
	top: 0px;
	right: 0px;
}
/*Disable Darkmode Completely*/
#pt-darkmode{
	display: none
}
.skin-vector-legacy #pt-uls .uls-trigger::before,
body:not(.skin-vector-2022) #pt-notifications-alert .mw-echo-notifications-badge.mw-echo-notifications-badge-all-read,
body:not(.skin-vector-2022) #pt-notifications-notice .mw-echo-notifications-badge.mw-echo-notifications-badge-all-read{
	filter: invert(1);
	background-clip: none;
}
#mw-head #p-personal .mw-list-item a{
	font-size: medium;
    -webkit-text-fill-color: white;
}
#mw-head #p-personal .mw-list-item li a:hover > span{
	text-decoration-color: #fff !important;
	text-decoration: underline!important;
}
.vector-menu-heading-label{
	color: #9f3526;
	font-size: 170%;
}
/*--------------------------- Garry --------------------------------*/
figure[typeof~='mw:File/Thumb'] > figcaption, figure[typeof~='mw:File/Frame'] > figcaption{
	color: #000;
}
/*------------------------------Page-------------------*/

#mw-content-text,.mw-body-content,#content{
	background: transparent;
	padding: 10px;
	margin-top: 31.9px;
	border-left: 1px solid white;
	border-bottom: 1px solid #fff;
	border-top: 1px solid #fff;
	box-shadow:4px 4px 8px 4px rgba(0, 0, 0, 0.2)
}
/*Made The Search Box Background White*/
.vector-search-box-input{
	background: white
}

/*----------------------------Toc (Table Of Content)-----------------------*/
#toc, .toc{
	background:transparent;
}
#toc .tocnumber,.toc .tocnumber{
	color:#fff;
}
#toc .toctext,.toc .toctext{
	color:#90ddff;
}
/*-------------------------Portable Infobox-------------------------*/

.portable-infobox .pi-title{
	background: #21273c;
}

.pi-data-label .pi-secondary-font{
	color: #fff
}
.portable-infobox{
	color: #fff;
}

/*-------------------------Wikitable----------------------*/

.wikitable{
	background-color: #4546469c !important;
}
.wikitable > tr > th, .wikitable > * > tr > th{
	background: #21273c;
}

ul{
	list-style-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='5' height='13'><circle cx='2.5' cy='8.5' r='2.5' fill='%23fff'/></svg>");;
}


/*-------------------------------------- Catlinks ---------------------------*/
.catlinks{
	background: transparent;
}
/*-------------------------- Recent Changes ------------------------*/
.mw-rcfilters-ui-changesListWrapperWidget .mw-changeslist-legend{
	background: transparent;
}
.mw-rcfilters-ui-filterWrapperWidget-showNewChanges.oo-ui-flaggedElement-progressive > .oo-ui-buttonElement-button > .oo-ui-labelElement-label {
    color: #fff !important;
}
/*------------------------Content Action---------------*/

pre > span{
	color: #fff
}
#left-navigation,#right-navigation{
	margin-top: 4.4em
}

.vector-menu-tabs, .vector-menu-tabs a, #mw-head .vector-menu-dropdown .vector-menu-heading{
	background: linear-gradient(to top, #0b1522, #0f2034);
	color: white;
}
ul.vector-menu-content-list > li > a > span{
	color: white;
}
label#p-cactions-label.vector-menu-heading {
	background: transparent !important;
	color: white;
}
.selected.mw-list-item,
#ca-ve-edit.selected.icon.mw-list-item.collapsible,
#ca-edit.selected.icon.mw-list-item.collapsible, #ca-talk.selected.icon.mw-list-item.collapsible,
#ca-view.selected.icon.mw-list-item.collapsible, #ca-history.selected.icon.mw-list-item.collapsible{
	background: #0f2034;
	border: 4px #00000059 inset;
	position: relative;
	bottom: 8px;
}
.vector-menu-tabs, .vector-menu-tabs a, #mw-head .vector-menu-dropdown .vector-menu-heading{
	background-image: #0f2034;
    background-repeat: no-repeat;
    background-size: 1px 100%;
}
.vector-menu-dropdown .mw-list-item{
	background: #0f2034
}
.vector-menu-dropdown .mw-list-item > li > a > span{
	color:#fff;
}
.vector-menu-tabs-legacy li{
	background: #0f2034
}
/*-----------------Headings-------------------*/

h1,h2,h3,h4,h5,h6,
.mw-heading1,
.mw-heading2,
.mw-heading3,
.mw-heading4,
.mw-heading5,
.mw-heading6{
	font-family:'IM Fell English SC', serif;
	color: #fff
}
.vector-body .mw-heading1 h1,
.vector-body .mw-heading2 h2,
.vector-body .mw-heading3 h3,
.vector-body .mw-heading4 h4,
.vector-body .mw-heading5 h5,
.vector-body .mw-heading6 h6{
	border-bottom: 4px solid #a2a9b1;
	line-height: 15px;
}
.vector-menu-heading-label{
	color:grey
}

/*-------------------Dark Mode Text-----------------*/

.vector-body p,
#content li,tbody,.wikitable > caption{
	color: #fff
}

/*------------------------Misc--------------------------*/
.cdx-message__content{
	color: #fff
}
.oo-ui-iconElement-icon .oo-ui-icon-success .oo-ui-image-success{
	color: #000
}
.mw-newarticletext .plainlinks{
	color: #fff
}
/*-------------------- Page History ------------------*/
#pagehistory li.selected{
	background: #273449;
}
.cdx-button:enabled, .cdx-button.cdx-button--fake-button--enabled{
	color: #000;
}
/*-----------------Links--------------------*/


.oo-ui-iconElement .oo-ui-flaggedElement-progressive .oo-ui-buttonWidget .oo-ui-labelElement .mw-rcfilters-ui-changesListWrapperWidget .mw-changeslist-legend a{
	color: #90ddff
}
.oo-ui-iconElement .oo-ui-flaggedElement-progressive .oo-ui-buttonWidget .oo-ui-labelElement .mw-rcfilters-ui-changesListWrapperWidget .mw-changeslist-legend a:hover{
	color: #90ddff
}
a{
	color: #90ddff
