/**
* @description: 大量移動子頁面之工具。
* @usage / configuration:
  在使用者common.js中添加：
	mw.loader.load('//publictestwiki.com/w/index.php?title=User:PB2008/massmove.js&action=raw&ctype=text/javascript' );
	mw.util.addPortletLink("p-tb", "//publictestwiki.com/wiki/Special:Massmove", "Mass move", "p-massmove", "Mass move");

  前往[[Special:Massmove]]填寫批次移動表單，僅限擁有 noratelimit 或 suppressredirect 權限之使用者使用。

* @revision: 03:00, 2 February 2019 (UTC) / updated rights check + i18n 13 Aug 2026 (UTC)
* 
* 13 Aug 2026 Import from Chinese Wikipedia https://zh.wikipedia.org/w/index.php?title=User:Hamish/massmove.js&oldid=55556370
**/

mw.loader.using(['mediawiki.api', 'mediawiki.Title', 'mediawiki.user'], function () {
 "use strict";

 var config = mw.config.get(['wgNamespaceNumber', 'wgTitle', 'wgUserGroups', 'skin', 'wgUserLanguage']);

 // Determine variant: zh-hans or zh-hant
 var userLang = (config.wgUserLanguage || 'zh').toLowerCase();
 var isHant = /^(zh-hant|zh-hk|zh-mo|zh-tw)$/.test(userLang);
 // default and zh / zh-hans / zh-cn / zh-my / zh-sg → zh-hans

 var i18n = {
  'zh-hans': {
   pageTitle: '批次移动页面',
   documentTitle: '移动页面',
   siteSub: '维基百科，自由的百科全书',
   intro: '大量移动子页面之工具，请勿滥用，以免遭致封禁。',
   warning: '如有滥用之行为，后果由<u>阁下</u>承担。',
   pagesLabel: '移动清单（每行一个页面，不加[[]]）：',
   prefixRemove: '去除前缀（例如「Template:」）：',
   prefixAdd: '加入前缀（例如「User:Jimbo Wales/」）：',
   moveTalk: '移动讨论页',
   noRedirect: '不留重新导向',
   watch: '监视页面',
   watchNochange: '维持原有设置',
   watchPreferences: '参数设置',
   watchWatch: '加入监视列表',
   watchUnwatch: '取消监视',
   reason: '编辑摘要：',
   submit: '移动',
   done: '完成',
   failedMoves: '失败的移动：'
  },
  'zh-hant': {
   pageTitle: '批次移動頁面',
   documentTitle: '移動頁面',
   siteSub: '維基百科，自由的百科全書',
   intro: '大量移動子頁面之工具，請勿濫用，以免遭致封禁。',
   warning: '如有濫用之行為，後果由<u>閣下</u>承擔。',
   pagesLabel: '移動清單（每行一個頁面，不加[[]]）：',
   prefixRemove: '去除前綴（例如「Template:」）：',
   prefixAdd: '加入前綴（例如「User:Jimbo Wales/」）：',
   moveTalk: '移動討論頁',
   noRedirect: '不留重新導向',
   watch: '監視頁面',
   watchNochange: '維持原有設置',
   watchPreferences: '參數設置',
   watchWatch: '加入監視列表',
   watchUnwatch: '取消監視',
   reason: '編輯摘要：',
   submit: '移動',
   done: '完成',
   failedMoves: '失敗的移動：'
  }
 };

 var msg = i18n[isHant ? 'zh-hant' : 'zh-hans'];

 function removeBlanks(arr) {
  var ret = [];
  var i, len;
  for (i = 0, len = arr.length; i < len; i++) {
   var s = arr[i];
   s = s.trim();
   if (s) {
    ret.push(s);
   }
  }
  return ret;
 }

 function replacePrefix(s, oldPrefix, newPrefix) {
  if (s.indexOf(oldPrefix) === 0) {
   s = s.substr(oldPrefix.length);
  }
  return newPrefix + s;
 }

 function doMassMove() {
  document.getElementById("wpMassMoveSubmit").disabled = true;
  var articles = document.getElementById("wpMassMovePages").value.split("\n");
  articles = removeBlanks(articles);
  if (!articles.length) {
   return;
  }
  var
   api = new mw.Api(),
   wpMassMoveReason = document.getElementById("wpMassMoveReason").value,
   wpMassMovePrefix1 = document.getElementById("wpMassMovePrefix1").value,
   wpMassMovePrefix2 = document.getElementById("wpMassMovePrefix2").value,
   wpMassMoveWatch = document.getElementById("wpMassMoveWatch").value,
   wpMassMoveNoRedirect = document.getElementById("wpMassMoveNoRedirect").checked,
   wpMassMoveMoveTalk = document.getElementById("wpMassMoveMoveTalk").checked,
   moved = 0,
   failed = [],
   error = [],
   onSuccess = function () {
    moved++;
    document.getElementById("wpMassMoveSubmit").value = "(" + moved + ")";
   };

  function makeMoveFunc(article) {
   return function () {
    return $.Deferred(function (deferred) {
     var options = {
      format: 'json',
      action: 'move',
      watchlist: wpMassMoveWatch,
      from: article,
      to: replacePrefix(article, wpMassMovePrefix1, wpMassMovePrefix2),
      reason: wpMassMoveReason
     };
     if (wpMassMoveNoRedirect) {
      options.noredirect = '';
     }
     if (wpMassMoveMoveTalk) {
      options.movetalk = '';
     }
     var promise = api.postWithToken('move', options);
     promise.done(onSuccess);
     promise.fail(function (code, obj) {
      failed.push(article);
      error.push(obj.error.info);
     });
     promise.always(function () {
      deferred.resolve();
     });
    });
   };
  }

  var deferred = makeMoveFunc(articles[0])();
  for (var i = 1, len = articles.length; i < len; i++) {
   deferred = deferred.then(makeMoveFunc(articles[i]));
  }

  $.when(deferred).then(function () {
   document.getElementById("wpMassMoveSubmit").value = msg.done + " (" + moved + ")";
   if (failed.length) {
    var $failedList = $('<ul>');
    for (var x = 0; x < failed.length; x++) {
     var failedTitle = mw.Title.newFromText(failed[x]);
     var $failedItem = $('<li>');
     if (failedTitle) {
      $failedItem.append($('<a>')
       .attr('href', failedTitle.getUrl())
       .text(failed[x])
      );
     } else {
      $failedItem.text(failed[x]);
     }
     $failedItem.append(document.createTextNode(': ' + error[x]));
     $failedList.append($failedItem);
    }
    $('#wpMassMoveFailedContainer')
     .append($('<br />'))
     .append($('<b>')
      .text(msg.failedMoves)
     )
     .append($failedList);
   }
  });
 }

 function massMoveForm() {
  var bodyContent = (config.skin == "cologneblue" ? "article" : "bodyContent");
  document.getElementsByTagName("h1")[0].textContent = msg.pageTitle;
  document.title = msg.documentTitle;
  document.getElementById(bodyContent).innerHTML =
   '<div id="siteSub">' + msg.siteSub + '</div>' +
   '<p>' + msg.intro + '</p>' +
   '<br /><br />' +
   '<form id="wpMassMove" name="wpMassMove">' +
   '<b>' + msg.warning + '</b>' +
   '<div id="wpMassMoveFailedContainer"></div>' +
   '<br /><br />' +
   msg.pagesLabel + '<br />' +
   '<textarea tabindex="1" accesskey="," name="wpMassMovePages" id="wpMassMovePages" rows="10" cols="80"></textarea>' +
   '<br /><br /><table style="background-color:transparent">' +
   '<tr><td>' + msg.prefixRemove + '</td>' +
    '<td><input type="text" id="wpMassMovePrefix1" name="wpMassMovePrefix1" maxlength="255" /></td></tr>' +
   '<tr><td>' + msg.prefixAdd + '</td>' +
    '<td><input type="text" id="wpMassMovePrefix2" name="wpMassMovePrefix2" maxlength="255" /></td></tr>' +
   '<tr><td>' + msg.moveTalk + '</td>' +
    '<td><input type="checkbox" id="wpMassMoveMoveTalk" name="wpMassMoveMoveTalk"/></td></tr>' +
   '<tr><td>' + msg.noRedirect + '</td>' +
    '<td><input type="checkbox" id="wpMassMoveNoRedirect" name="wpMassMoveNoRedirect"/></td></tr>' +
   '<tr><td>' + msg.watch + '</td>' +
    '<td><select id="wpMassMoveWatch">' +
     '<option value="nochange">' + msg.watchNochange + '</option>' +
     '<option value="preferences">' + msg.watchPreferences + '</option>' +
     '<option value="watch">' + msg.watchWatch + '</option>' +
     '<option value="unwatch">' + msg.watchUnwatch + '</option>' +
    '</select></td></tr>' +
   '<tr><td>' + msg.reason + '</td>' +
    '<td><input type="text" id="wpMassMoveReason" name="wpMassMoveReason" maxlength="255" /></td></tr>' +
   '<tr><td><input type="button" id="wpMassMoveSubmit" name="wpMassMoveSubmit" value="' + msg.submit + '" /></td>' +
   '</form>';
  document.getElementById("wpMassMoveSubmit").addEventListener("click", function (e) {
   doMassMove();
  });
 }

 if (config.wgNamespaceNumber == -1 &&
     config.wgTitle.toLowerCase() == "massmove"
 ) {
  mw.user.getRights().then(function (rights) {
   if (rights.indexOf('noratelimit') !== -1 || rights.indexOf('suppressredirect') !== -1) {
    massMoveForm();
   }
  });
 }

