    function processNext() {
        if (paused || queue.length === 0) {
            if (queue.length === 0) {
                finish();
            }
            return;
        }

        var item = queue.shift();
        var from = item.from.replace(/_/g, ' ');
        var to = item.to.replace(/_/g, ' ');

        var api = new mw.Api();
        var options = {
            action: 'move',
            from: from,
            to: to,
            reason: document.getElementById('wpMassMoveReason').value || '',
            watchlist: document.getElementById('wpMassMoveWatch').value
        };

        if (document.getElementById('wpMassMoveNoRedirect').checked) {
            options.noredirect = true;
        }
        if (document.getElementById('wpMassMoveMoveTalk').checked) {
            options.movetalk = true;
        }

