                    setTimeout(processNext, 10000);
                });
        }).fail(function () {
            // Query itself failed → treat as temporary error, retry same pair after 10s
            setStatus(msg.retrying + ' ' + from + ' (query failed)');
            setTimeout(processNext, 10000);
        });
    }

    function finish() {
        paused = true;
        var btn = document.getElementById('wpMassMoveSubmit');
        if (btn) {
            btn.disabled = false;
            btn.value = msg.done + ' (' + moved + ')';
        }
        var pauseBtn = document.getElementById('wpMassMovePause');
        if (pauseBtn) {
            pauseBtn.disabled = true;
        }
        setStatus(msg.finished);

        if (failed.length) {
            var $list = $('<ul>');
            for (var i = 0; i < failed.length; i++) {
                $list.append($('<li>').text(failed[i] + ': ' + errors[i]));
            }
            $('#wpMassMoveFailedContainer')
                .empty()
                .append($('<br>'))
                .append($('<b>').text(msg.failedMoves))
                .append($list);
        }
    }

    function startMove() {
        var oldRaw = document.getElementById('wpMassMoveOld').value.split('\n');
        var newRaw = document.getElementById('wpMassMoveNew').value.split('\n');

        var maxLen = Math.max(oldRaw.length, newRaw.length);
        while (oldRaw.length < maxLen) { oldRaw.push(''); }
        while (newRaw.length < maxLen) { newRaw.push(''); }

        queue = [];
        for (var i = 0; i < maxLen; i++) {
            var from = (oldRaw[i] || '').trim();
            var to = (newRaw[i] || '').trim();
            if (!from && !to) {
                continue;
            }
            queue.push({ from: from, to: to });
        }

        if (!queue.length) {
            setStatus(msg.empty);
            return;
        }

        moved = 0;
        failed = [];
        errors = [];
        paused = false;

        document.getElementById('wpMassMoveSubmit').disabled = true;
        document.getElementById('wpMassMovePause').disabled = false;
        $('#wpMassMoveFailedContainer').empty();
        updateSubmitButton();
        processNext();
    }

    function pauseMove() {
        paused = true;
        document.getElementById('wpMassMoveSubmit').disabled = false;
        document.getElementById('wpMassMovePause').disabled = true;
