    // ---- Core move logic ----
    function processNext() {
        if (paused || queue.length === 0) {
            if (queue.length === 0) {
                finish();
            }
            return;
        }

        // Peek current pair (do not remove yet — may need to retry)
        var item = queue[0];
        var from = (item.from || '').trim().replace(/_/g, ' ');
        var to = (item.to || '').trim().replace(/_/g, ' ');

        // Skip if original title is empty / "none"
        if (!from || from.toLowerCase() === 'none') {
            queue.shift();
            setStatus(msg.skippedEmpty + ' → ' + to);
            setTimeout(processNext, window.massMoveDelay || 300);
            return;
        }

        var api = new mw.Api();

        // 1) Check whether the original page exists
        api.get({
            action: 'query',
            titles: from,
            format: 'json'
        }).then(function (data) {
            var pages = data.query && data.query.pages;
            var missing = false;
            if (pages) {
                for (var id in pages) {
                    if (pages[id].missing !== undefined || id === '-1') {
                        missing = true;
                    }
                }
            }

            if (missing) {
                // Page does not exist → skip this pair
                queue.shift();
                setStatus(msg.skippedMissing + ' ' + from);
                setTimeout(processNext, window.massMoveDelay || 300);
                return;
            }

            // 2) Page exists → try to move
            var options = {
                action: 'move',
                from: from,
                to: to,
                reason: document.getElementById('wpMassMoveReason').value || '',
