                .done(function () {
                    queue.shift(); // success → remove from queue
                    moved++;
                    updateSubmitButton();
                    setStatus(from + ' → ' + to);
                    setTimeout(processNext, window.massMoveDelay || 800);
                })
                .fail(function (code, obj) {
                    // Any failure other than missing page → wait 10s and retry SAME pair
                    var errInfo = (obj && obj.error && obj.error.info) || code || 'unknown';
                    setStatus(msg.retrying + ' ' + from + ' → ' + to + ' (' + errInfo + ')');
                    setTimeout(processNext, 10000);
                });
        }).fail(function () {
            // Query itself failed → treat as temporary error, retry same pair after 10s
            setStatus(msg.retrying + ' ' + from + ' (query failed)');
            setTimeout(processNext, 10000);
