        if (!queue.length) {
            setStatus(msg.empty);
            return;
        }

        moved = 0;
        failed = [];
        errors = [];
        paused = false;

        document.getElementById('wpMassMoveSubmit').disabled = true;
        document.getElementById('wpMassMovePause').disabled = false;
        $('#wpMassMoveFailedContainer').empty();
