//Gary King, "User:Gary King/comments in local time.js," Wikipedia, The Free Encyclopedia, http://en.wikipedia.org/w/index.php?title=User:Gary_King/comments_in_local_time.js&oldid=281324481 (accessed May 28, 2009).
mw.loader.using(['ext.gadget.HanAssist']).then(function (require) {
	'use strict';
	const langConv = require('ext.gadget.HanAssist').conv;

	/**
	 * 计算目标时间与基准时间（默认当前时间）的相对差值
	 * @param {Date} targetDate 目标时间
	 * @param {Date} [baseDate] 基准时间（默认为当前本地时间）
	 * @returns {Object} 包含结构化差值与预设描述文本的对象
	 */
	function calculateDateDifference(targetDate, baseDate) {
		var base = baseDate || new Date();
		var todayZero = new Date(base.getFullYear(), base.getMonth(), base.getDate());
		var targetZero = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate());

		var diffMs = todayZero.getTime() - targetZero.getTime();
		var daysAgo = Math.round(diffMs / 86400000);

		// 判定相对日期
		var relativeDay = '';
		if (daysAgo === 0) {
			relativeDay = '今天';
		} else if (daysAgo === 1) {
			relativeDay = '昨天';
		} else if (daysAgo === -1) {
			relativeDay = '明天';
		}

		var isPast = diffMs >= 0;
		var absDiffMs = Math.abs(diffMs);
		var diffObj = new Date(absDiffMs);

		// 使用 UTC 方法读取 Date(ms) 解析值，避免本地时区偏移干扰
		var diffYears = diffObj.getUTCFullYear() - 1970;
		var diffMonths = diffObj.getUTCMonth();
		var diffDays = diffObj.getUTCDate() - 1;

		var directionWord = isPast ? '前' : langConv({ hans: '后', hant: '後' });

		var parts = [];
		if (diffYears > 0) parts.push(diffYears + '年');
		if (diffMonths > 0) parts.push(diffMonths + langConv({ hans: '个月', hant: '個月' }));
		if (diffDays > 0) parts.push(diffDays + '日');

		var descriptiveDiff = parts.length > 0 ? (parts.join('') + directionWord) : '';
		var descriptiveDiffBracket = descriptiveDiff ? ' (' + descriptiveDiff + ')' : '';

		return {
			daysAgo: daysAgo,                         // 相差天数（今天为0，昨天为1，明天为-1）
			relativeDay: relativeDay,                 // '今天' | '昨天' | '明天' | ''
			isPast: isPast,                           // 是否为过去
			directionWord: directionWord,             // '前' | '后' / '後'
			diffYears: diffYears,                     // 差值年数
			diffMonths: diffMonths,                   // 差值月数
			diffDays: diffDays,                       // 差值天数
			descriptiveDiff: descriptiveDiff,         // 例如: "1个月3日前"
			descriptiveDiffBracket: descriptiveDiffBracket // 例如: " (1个月3日前)"
		};
	}

	function add_leading_zero(number) {
		if (number < 10) number = '0' + number;
		return number;
	}

	/* ==========================================================================
	   1. 原CommentsInLocalTime小工具（未开启ConvenientDiscussions）
	   ========================================================================== */
	var CommentsInLocalTime = function() {
		// mw.config.get('wgCanonicalNamespace') = unsafeWindow.mw.config.get('wgCanonicalNamespace')

		/*
		Settings
