			if (link.classList.contains('cd-localcomments-processed')) return;

			var id = link.hash.slice(1);
			try {
				id = decodeURIComponent(id);
			} catch (e) {}

			var comment = cd.api.getCommentById(id) || cd.api.getCommentByDtId(id);
			if (!comment || !comment.timestampElement) return;

			var sourceTs = comment.timestampElement;
