		var hour = localTime.getUTCHours();
		var minute = add_leading_zero(localTime.getUTCMinutes());
		var dayNames = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];
		var dayOfWeek = dayNames[localTime.getUTCDay()];

		var ampm = '';
		if (!settings.twentyFourHours) {
			ampm = hour <= 11 ? ' am' : ' pm';
			if (hour > 12) hour -= 12;
			else if (hour === 0) hour = 12;
		}

		var formattedDate = '';
		switch ((settings.dateFormat || 'ymd').toLowerCase()) {
			case 'ymd':
				formattedDate = year + '年' + month + '月' + day + '日';
				break;
			case 'ymd0':
				formattedDate = year + '年' + add_leading_zero(month) + '月' + add_leading_zero(day) + '日';
				break;
			default:
				formattedDate = year + '-' + add_leading_zero(month) + '-' + add_leading_zero(day);
		}

		if (settings.dayOfWeek !== false) {
			formattedDate += ' (' + dayOfWeek.replace('星期', '') + ')';
		}

		var offsetStr = localOffsetHours >= 0 ? '+' + localOffsetHours : '−' + Math.abs(localOffsetHours);
		var timeStr = add_leading_zero(hour) + ':' + minute + ampm;

		return formattedDate + ' ' + timeStr + ' (UTC' + offsetStr + ')';
	}

	function processCDComments() {
		var LocalComments = window.LocalComments || {};
		var timeCorrection = mw.user.options.get('timecorrection');
		var needsTimezoneShift = (timeCorrection === 'System|0');
		var localOffsetHours = (typeof LocalComments.utcOffset === 'number') ? LocalComments.utcOffset : getLocalUtcOffset();

		var timestampNodes = document.querySelectorAll('a.cd-comment-timestamp:not(.cd-localcomments-processed)');

		timestampNodes.forEach(function (tsLink) {
			tsLink.classList.add('cd-localcomments-processed');

			var rawTitle = tsLink.getAttribute('title') || tsLink.textContent || '';
			var parsed = parseTimestamp(rawTitle);
			if (!parsed) return;

			// 1. 获取绝对 UTC 毫秒时间戳
			var utcMs = Date.UTC(parsed.year, parsed.month, parsed.day, parsed.hour, parsed.minute);

			// 2. 如果是系统时区 System|0，将链接文本转换为浏览器本地时区
			if (needsTimezoneShift) {
				tsLink.textContent = formatToLocalBrowserTime(utcMs, LocalComments);
			}

			// 3. 计算相对时间差：将 UTC 时间平移到当前本地时区后进行比对
			if (LocalComments.dateDifference !== false) {
				// 获取目标时间在本地时区下的等效时间对象
				var targetLocalDate = new Date(utcMs + localOffsetHours * 3600000);
				var normalizedLocalDate = new Date(
					targetLocalDate.getUTCFullYear(),
					targetLocalDate.getUTCMonth(),
					targetLocalDate.getUTCDate(),
					targetLocalDate.getUTCHours(),
					targetLocalDate.getUTCMinutes()
				);

				var diffText = getRelativeDiffText(normalizedLocalDate);
				if (diffText) {
					var diffSpan = document.createElement('span');
					diffSpan.className = 'cd-localcomments-diff localcomments';
					diffSpan.style.fontSize = '85%';
					diffSpan.style.opacity = '0.85';
					diffSpan.textContent = ' ' + diffText;
					tsLink.parentNode.insertBefore(diffSpan, tsLink.nextSibling);
				}
			}
		});
	}

	/**
	 * 將各章節「最新留言」的時間，改成該留言已轉換後的時間文字。
	 *
	 * @param {Object} cd Convenient Discussions 公開物件
	 */
	function updateSectionLatestCommentTimestamps(cd) {
		if (!cd || !cd.api) {
			return;
		}

		document.querySelectorAll(
			'.cd-section-metadata > .cd-section-bar-item:last-child > a.cd-clickHandled'
		).forEach(function (link) {
			if (link.classList.contains('cd-localcomments-processed')) return;

			var id = link.hash.slice(1);
			try {
				id = decodeURIComponent(id);
			} catch (e) {}

			var comment = cd.api.getCommentById(id) || cd.api.getCommentByDtId(id);
			if (!comment || !comment.timestampElement) return;

			var sourceTs = comment.timestampElement;
			if (sourceTs) {
				link.textContent = sourceTs.textContent.trim();
				if (sourceTs.title) {
					link.title = sourceTs.title;
				}
				link.classList.add('cd-localcomments-processed');
			}
		});
	}

	/* ==========================================================================
	   3. 系统加载
	   ========================================================================== */
	var isCDMode = false;
	window.CommentsinLocalTime = CommentsInLocalTime;
	$(function() {
		if (window.location.href.indexOf('&disable=loco') !== -1) {
			return;
		}

		mw.hook('convenientDiscussions.commentsReady').add(function () {
			isCDMode = true;
			processCDComments();
		});

		mw.hook('convenientDiscussions.pageReady').add(function (cd) {
			isCDMode = true;
			processCDComments();
			updateSectionLatestCommentTimestamps(cd);
		});

		// 未启用CD时加载原插件
		mw.hook('wikipage.content').add(function($item) {
			if ($item.attr('id') === 'mw-content-text') {
				setTimeout(function () {
					if (!window.convenientDiscussions && !isCDMode) {
						runCommentsInLocalTime();
					}
				}, 100);
			}
		});
	});
});

