// MediaWiki:Gadget-UploadWizard.js
( function () {
	'use strict';

	var api = new mw.Api();

	var STEPS = [
		{ id: 'learn', label: 'Learn' },
		{ id: 'upload', label: 'Upload' },
		{ id: 'license', label: 'License' },
		{ id: 'information', label: 'Information' },
		{ id: 'submit', label: 'Submit' }
	];

	var state = {
		stepIndex: 0,
		maxReachedIndex: 0, // prevents skipping ahead without completing steps
		file: null,
		filename: '',
		license: null, // selected item from LICENSES
		description: '',
		source: 'Own work',
		date: '',
		author: '',
		permission: 'See below',
		category: ''
	};

	var $box; // main wizard container, set on open

	function openWizard() {
		var $modal = $( '<div>' ).attr( 'id', 'custom-upload-wizard-overlay' );
		$box = $( '<div>' ).attr( 'id', 'custom-upload-wizard' );
		$modal.append( $box );
		$( 'body' ).append( $modal );
		renderNav();
		renderStep();
	}

	function closeWizard() {
		$( '#custom-upload-wizard-overlay' ).remove();
	}

	function goToStep( index ) {
		state.stepIndex = index;
		renderNav();
		renderStep();
	}

	function goNext() {
		if ( state.stepIndex + 1 > state.maxReachedIndex ) {
			state.maxReachedIndex = state.stepIndex + 1;
		}
		goToStep( state.stepIndex + 1 );
	}

	function goBack() {
		goToStep( state.stepIndex - 1 );
	}

	mw.util.addPortletLink( 'p-tb', '#', 'Upload Wizard', 't-uploadwizard' );
	$( '#t-uploadwizard' ).on( 'click', function ( e ) {
		e.preventDefault();
		openWizard();
	} );

}() );

function renderNav() {
	var $nav = $box.find( '.uw-nav' );
	if ( !$nav.length ) {
		$nav = $( '<div class="uw-nav">' );
		$box.prepend( $nav );
	}
	$nav.empty();

	STEPS.forEach( function ( step, index ) {
		var $tab = $( '<div class="uw-tab">' )
			.text( ( index + 1 ) + '. ' + step.label )
			.attr( 'data-step', step.id );

		if ( index === state.stepIndex ) {
			$tab.addClass( 'uw-tab-active' );
		}
		if ( index <= state.maxReachedIndex ) {
			$tab.addClass( 'uw-tab-enabled' ).on( 'click', function () {
				goToStep( index );
			} );
		} else {
			$tab.addClass( 'uw-tab-disabled' );
		}

		$nav.append( $tab );
	} );

	var $close = $box.find( '.uw-close' );
	if ( !$close.length ) {
		$( '<button class="uw-close">&times;</button>' )
			.on( 'click', closeWizard )
			.appendTo( $box );
	}
}

function renderStep() {
	var $content = $box.find( '.uw-content' );
	if ( !$content.length ) {
		$content = $( '<div class="uw-content">' );
		$box.append( $content );
	}
	$content.empty();

	switch ( STEPS[ state.stepIndex ].id ) {
		case 'learn': renderLearn( $content ); break;
		case 'upload': renderUpload( $content ); break;
		case 'license': renderLicense( $content ); break;
		case 'information': renderInformation( $content ); break;
		case 'submit': renderSubmit( $content ); break;
	}
}

function renderLearn( $content ) {
	$content.append( '<h3>Before you upload</h3>' );
	$content.append(
		'<p>Please read the guide below before uploading a file. ' +
		'Make sure you understand the license requirements and file naming rules.</p>'
	);

	// Replace the URL below with your actual guide image (e.g. File:Upload-guide.png)
	var guideImageTitle = 'File:Upload-guide.png';
	$content.append(
		$( '<img class="uw-learn-img">' )
			.attr( 'src', mw.util.getUrl( guideImageTitle, { action: 'raw' } ) )
			.attr( 'alt', 'Upload guide' )
	);

	// Fallback: fetch actual thumbnail via API in case direct URL doesn't resolve
	api.get( {
		action: 'query',
		titles: guideImageTitle,
		prop: 'imageinfo',
		iiprop: 'url',
		iiurlwidth: 500,
		format: 'json'
	} ).done( function ( data ) {
		var pages = data.query && data.query.pages;
		if ( !pages ) { return; }
		var page = pages[ Object.keys( pages )[ 0 ] ];
		if ( page.imageinfo && page.imageinfo[ 0 ] ) {
			$content.find( '.uw-learn-img' ).attr(
				'src',
				page.imageinfo[ 0 ].thumburl || page.imageinfo[ 0 ].url
			);
		}
	} );

	var $next = $( '<button class="uw-btn-primary">I understand, continue</button>' )
		.on( 'click', goNext );

	$content.append( $next );
}

function renderUpload( $content ) {
	$content.append( '<h3>Select a file</h3>' );

	var $input = $( '<input type="file" accept="image/*,.pdf,.svg,.ogg,.webm">' );
	var $preview = $( '<div class="uw-preview">' );
	var $error = $( '<div class="uw-error">' ).hide();

	$input.on( 'change', function ( e ) {
		var file = e.target.files[ 0 ];
		if ( !file ) { return; }

		state.file = file;
		state.filename = file.name;

		$preview.empty();
		if ( file.type.indexOf( 'image' ) === 0 ) {
			var reader = new FileReader();
			reader.onload = function ( ev ) {
				$preview.append(
					$( '<img>' ).attr( 'src', ev.target.result )
				);
			};
			reader.readAsDataURL( file );
		} else {
			$preview.text( 'Selected file: ' + file.name );
		}
	} );

	var $next = $( '<button class="uw-btn-primary">Continue</button>' ).on( 'click', function () {
		if ( !state.file ) {
			$error.text( 'Please select a file first.' ).show();
			return;
		}
		goNext();
	} );

	$content.append( $input, $preview, $error, $next );
}

function renderLicense( $content ) {
	$content.append( '<h3>Choose a license</h3>' );
	$content.append( '<p>Select the option that best describes the copyright status of this file.</p>' );

	var $error = $( '<div class="uw-error">' ).hide();

	LICENSES.forEach( function ( group ) {
		$content.append( $( '<h4 class="uw-license-category">' ).text( group.category ) );

		group.items.forEach( function ( item ) {
			var inputId = 'uw-license-' + item.template;

			var $radio = $( '<input type="radio" name="uw-license">' )
				.attr( 'id', inputId )
				.prop( 'checked', state.license && state.license.template === item.template )
				.on( 'change', function () {
					state.license = item;
				} );

			var $label = $( '<label>' )
				.attr( 'for', inputId )
				.append(
					$( '<strong>' ).text( item.label ),
					$( '<span class="uw-license-desc">' ).text( ' — ' + item.description )
				);

			$content.append(
				$( '<div class="uw-license-item">' ).append( $radio, $label )
			);
		} );
	} );

	var $back = $( '<button class="uw-btn-secondary">Back</button>' ).on( 'click', goBack );
	var $next = $( '<button class="uw-btn-primary">Continue</button>' ).on( 'click', function () {
		if ( !state.license ) {
			$error.text( 'Please choose a license.' ).show();
			return;
		}
		goNext();
	} );

	$content.append( $error, $back, $next );
}

function renderInformation( $content ) {
	$content.append( '<h3>File information</h3>' );

	var $error = $( '<div class="uw-error">' ).hide();

	function field( label, input, required ) {
		return $( '<div class="uw-field">' ).append(
			$( '<label>' ).text( label + ( required ? ' *' : '' ) ),
			input
		);
	}

	var $desc = $( '<textarea rows="3" placeholder="Describe what this file shows...">' ).val( state.description );
	var $source = $( '<input type="text">' ).val( state.source );
	var $date = $( '<input type="date">' ).val( state.date || new Date().toISOString().slice( 0, 10 ) );
	var $author = $( '<input type="text" placeholder="Name / username">' ).val(
		state.author || mw.config.get( 'wgUserName' ) || ''
	);
	var $permission = $( '<textarea rows="2">' ).val( state.permission );
	var $cat = $( '<input type="text" placeholder="e.g. Event photos">' ).val( state.category );

	$content.append(
		field( 'Description', $desc, true ),
		field( 'Source', $source, true ),
		field( 'Date', $date, false ),
		field( 'Author', $author, true ),
		field( 'Permission', $permission, false ),
		field( 'Category', $cat, false )
	);

	var $back = $( '<button class="uw-btn-secondary">Back</button>' ).on( 'click', goBack );
	var $next = $( '<button class="uw-btn-primary">Continue</button>' ).on( 'click', function () {
		if ( !$desc.val().trim() || !$source.val().trim() || !$author.val().trim() ) {
			$error.text( 'Description, Source, and Author are required.' ).show();
			return;
		}
		state.description = $desc.val().trim();
		state.source = $source.val().trim();
		state.date = $date.val();
		state.author = $author.val().trim();
		state.permission = $permission.val().trim();
		state.category = $cat.val().trim();
		goNext();
	} );

	$content.append( $error, $back, $next );
}

function buildWikitext() {
	var licenseTemplate = state.license ? '{{' + state.license.template + '}}' : '';

	var wikitext =
		'=={{int:filedesc}}==\n' +
		'{{Information\n' +
		'| description = ' + state.description + '\n' +
		'| source      = ' + state.source + '\n' +
		'| date        = ' + state.date + '\n' +
		'| author      = ' + state.author + '\n' +
		'| permission  = ' + ( state.permission || 'See below' ) + '\n' +
		'}}\n\n' +
		'=={{int:license-header}}==\n' +
		licenseTemplate + '\n\n';

	if ( state.category ) {
		wikitext += '[[Category:' + state.category + ']]\n';
	}

	return wikitext;
}

function renderSubmit( $content ) {
	$content.append( '<h3>Review and submit</h3>' );

	$content.append(
		$( '<div class="uw-summary">' ).html(
			'<p><b>File:</b> ' + mw.html.escape( state.filename ) + '</p>' +
			'<p><b>License:</b> ' + mw.html.escape( state.license ? state.license.label : '-' ) + '</p>' +
			'<p><b>Description:</b> ' + mw.html.escape( state.description ) + '</p>' +
			'<p><b>Source:</b> ' + mw.html.escape( state.source ) + '</p>' +
			'<p><b>Author:</b> ' + mw.html.escape( state.author ) + '</p>' +
			'<p><b>Category:</b> ' + mw.html.escape( state.category || '-' ) + '</p>'
		)
	);

	var $status = $( '<div class="uw-status">' );
	var $back = $( '<button class="uw-btn-secondary">Back</button>' ).on( 'click', goBack );
	var $upload = $( '<button class="uw-btn-primary">Upload now</button>' );

	function doUpload( ignoreWarnings ) {
		$status.removeClass( 'uw-error-text' ).text( 'Uploading...' );
		$upload.prop( 'disabled', true );

		api.upload( state.file, {
			filename: state.filename,
			text: buildWikitext(),
			comment: 'Uploaded via custom Upload Wizard',
			ignorewarnings: !!ignoreWarnings
		} ).then( function () {
			$status.removeClass( 'uw-error-text' ).empty().append(
				'Upload successful! ',
				$( '<a target="_blank">' )
					.attr( 'href', mw.util.getUrl( 'File:' + state.filename ) )
					.text( 'View file page' )
			);
			$upload.hide();
			$back.hide();
		} ).catch( function ( code, res ) {
			$upload.prop( 'disabled', false );
			handleUploadError( code, res );
		} );
	}

	function handleUploadError( code, res ) {
		var warnings = res && res.upload && res.upload.warnings;

		if ( warnings ) {
			if ( warnings.duplicate ) {
				$status.addClass( 'uw-error-text' ).empty().append(
					'This file already exists as: ',
					$( '<code>' ).text( warnings.duplicate.join( ', ' ) )
				);
				var $rename = $( '<button class="uw-btn-secondary">Rename and retry</button>' )
					.on( 'click', function () {
						var newName = prompt( 'New file name:', state.filename );
						if ( newName ) {
							state.filename = newName;
							renderStep();
						}
					} );
				$status.append( '<br>', $rename );
				return;
			}
			if ( warnings.exists || warnings[ 'exists-normalized' ] ) {
				$status.addClass( 'uw-error-text' ).text(
					'A file named "' + state.filename + '" already exists. Please choose a different name.'
				);
				return;
			}
			var msg = Object.keys( warnings ).join( ', ' );
			$status.addClass( 'uw-error-text' ).empty().append(
				'Warning: ' + msg + '. ',
				$( '<button class="uw-btn-secondary">Upload anyway</button>' )
					.on( 'click', function () { doUpload( true ); } )
			);
			return;
		}

		$status.addClass( 'uw-error-text' ).text( 'Upload failed: ' + ( code || 'unknown error' ) );
	}

	$upload.on( 'click', function () { doUpload( false ); } );

	$content.append( $status, $back, $upload );
}

#custom-upload-wizard-overlay {
	position: fixed; top: 0; left: 0; right: 0; bottom: 0;
	background: rgba(0,0,0,0.5);
	z-index: 9999;
	display: flex; align-items: center; justify-content: center;
}
#custom-upload-wizard {
	position: relative;
	background: #fff;
	width: 560px; max-width: 92%;
	max-height: 88vh;
	overflow-y: auto;
	border-radius: 6px;
	padding: 20px;
}
#custom-upload-wizard .uw-close {
	position: absolute; top: 10px; right: 14px;
	background: none; border: none; font-size: 22px; cursor: pointer;
}
#custom-upload-wizard .uw-nav {
	display: flex; flex-wrap: wrap; gap: 6px;
	margin-bottom: 16px; border-bottom: 1px solid #eaecf0; padding-bottom: 10px;
}
#custom-upload-wizard .uw-tab {
	font-size: 0.85em; padding: 4px 10px; border-radius: 12px;
	background: #f0f0f0; color: #888;
}
#custom-upload-wizard .uw-tab-enabled { cursor: pointer; color: #333; }
#custom-upload-wizard .uw-tab-active { background: #36c; color: #fff; }
#custom-upload-wizard .uw-tab-disabled { opacity: 0.5; }

#custom-upload-wizard .uw-field { margin-bottom: 12px; }
#custom-upload-wizard .uw-field label {
	display: block; font-weight: bold; margin-bottom: 4px; font-size: 0.9em;
}
#custom-upload-wizard input,
#custom-upload-wizard textarea,
#custom-upload-wizard select {
	width: 100%; box-sizing: border-box; padding: 6px 8px;
	border: 1px solid #a2a9b1; border-radius: 3px; font-size: 0.95em;
}

#custom-upload-wizard .uw-license-category {
	margin-top: 14px; margin-bottom: 6px; font-size: 0.95em; color: #333;
