#custom-upload-wizard .uw-license-item label { font-weight: normal; }
#custom-upload-wizard .uw-license-desc { color: #555; font-size: 0.9em; }

#custom-upload-wizard .uw-learn-img { max-width: 100%; margin: 12px 0; }
