// MediaWiki:Gadget-UploadWizard.js
( function () {
	'use strict';

	var api = new mw.Api();

	var STEPS = [
		{ id: 'learn', label: 'Learn' },
		{ id: 'upload', label: 'Upload' },
		{ id: 'license', label: 'License' },
		{ id: 'information', label: 'Information' },
		{ id: 'submit', label: 'Submit' }
	];

	var state = {
		stepIndex: 0,
		maxReachedIndex: 0, // prevents skipping ahead without completing steps
		file: null,
		filename: '',
		license: null, // selected item from LICENSES
		description: '',
		source: 'Own work',
		date: '',
		author: '',
		permission: 'See below',
		category: ''
	};

	var $box; // main wizard container, set on open

	function openWizard() {
		var $modal = $( '<div>' ).attr( 'id', 'custom-upload-wizard-overlay' );
		$box = $( '<div>' ).attr( 'id', 'custom-upload-wizard' );
		$modal.append( $box );
		$( 'body' ).append( $modal );
		renderNav();
		renderStep();
	}

	function closeWizard() {
		$( '#custom-upload-wizard-overlay' ).remove();
	}

	function goToStep( index ) {
		state.stepIndex = index;
		renderNav();
		renderStep();
	}

	function goNext() {
		if ( state.stepIndex + 1 > state.maxReachedIndex ) {
			state.maxReachedIndex = state.stepIndex + 1;
		}
		goToStep( state.stepIndex + 1 );
	}

	function goBack() {
		goToStep( state.stepIndex - 1 );
	}

	mw.util.addPortletLink( 'p-tb', '#', 'Upload Wizard', 't-uploadwizard' );
	$( '#t-uploadwizard' ).on( 'click', function ( e ) {
		e.preventDefault();
		openWizard();
	} );

}() );

function renderNav() {
	var $nav = $box.find( '.uw-nav' );
	if ( !$nav.length ) {
		$nav = $( '<div class="uw-nav">' );
		$box.prepend( $nav );
	}
	$nav.empty();

	STEPS.forEach( function ( step, index ) {
		var $tab = $( '<div class="uw-tab">' )
			.text( ( index + 1 ) + '. ' + step.label )
			.attr( 'data-step', step.id );

		if ( index === state.stepIndex ) {
			$tab.addClass( 'uw-tab-active' );
		}
		if ( index <= state.maxReachedIndex ) {
			$tab.addClass( 'uw-tab-enabled' ).on( 'click', function () {
				goToStep( index );
			} );
		} else {
			$tab.addClass( 'uw-tab-disabled' );
		}

		$nav.append( $tab );
	} );

	var $close = $box.find( '.uw-close' );
	if ( !$close.length ) {
		$( '<button class="uw-close">&times;</button>' )
			.on( 'click', closeWizard )
			.appendTo( $box );
	}
}

function renderStep() {
	var $content = $box.find( '.uw-content' );
	if ( !$content.length ) {
		$content = $( '<div class="uw-content">' );
		$box.append( $content );
	}
	$content.empty();

	switch ( STEPS[ state.stepIndex ].id ) {
		case 'learn': renderLearn( $content ); break;
		case 'upload': renderUpload( $content ); break;
		case 'license': renderLicense( $content ); break;
		case 'information': renderInformation( $content ); break;
		case 'submit': renderSubmit( $content ); break;
	}
}

function renderLearn( $content ) {
	$content.append( '<h3>Before you upload</h3>' );
	$content.append(
		'<p>Please read the guide below before uploading a file. ' +
		'Make sure you understand the license requirements and file naming rules.</p>'
	);

	// Replace the URL below with your actual guide image (e.g. File:Upload-guide.png)
	var guideImageTitle = 'File:Upload-guide.png';
	$content.append(
		$( '<img class="uw-learn-img">' )
			.attr( 'src', mw.util.getUrl( guideImageTitle, { action: 'raw' } ) )
			.attr( 'alt', 'Upload guide' )
	);

	// Fallback: fetch actual thumbnail via API in case direct URL doesn't resolve
	api.get( {
		action: 'query',
		titles: guideImageTitle,
		prop: 'imageinfo',
		iiprop: 'url',
		iiurlwidth: 500,
		format: 'json'
	} ).done( function ( data ) {
		var pages = data.query && data.query.pages;
		if ( !pages ) { return; }
		var page = pages[ Object.keys( pages )[ 0 ] ];
		if ( page.imageinfo && page.imageinfo[ 0 ] ) {
			$content.find( '.uw-learn-img' ).attr(
				'src',
				page.imageinfo[ 0 ].thumburl || page.imageinfo[ 0 ].url
			);
		}
	} );

	var $next = $( '<button class="uw-btn-primary">I understand, continue</button>' )
		.on( 'click', goNext );

	$content.append( $next );
}

function renderUpload( $content ) {
	$content.append( '<h3>Select a file</h3>' );

	var $input = $( '<input type="file" accept="image/*,.pdf,.svg,.ogg,.webm">' );
