/*
 * ===============================================================
 *              FileUploadWizard.js — VERSI SEDERHANA
 * ---------------------------------------------------------------
 * Diadaptasi dari [[Wikipedia:File Upload Wizard]] (MediaWiki:FileUploadWizard.js),
 * disederhanakan untuk wiki yang hanya mengenal 5 status lisensi:
 *
 *   1. CC BY 4.0        \_ lisensi bebas (free), karya sendiri
 *   2. CC BY-SA 4.0      / atau dari orang lain di bawah lisensi bebas
 *   3. Self               -> non-free, karya sendiri, hak cipta dipertahankan
 *   4. Permission          -> non-free, dari orang lain dengan izin pemilik
 *   5. Fairuse              -> fair dealing / fair use
 *   6. PD                    -> domain publik / kategori lain
 *
 * Semua logika NFCC (non-free content criteria), PD-old, PD-official,
 * USGov, OTRS multi-step, dsb. dari script asli DIHAPUS karena tidak
 * relevan untuk wiki ini. Struktur DOM dibuat langsung lewat JS
 * (bukan lewat penggantian banyak <span id="placeholder..."> seperti
 * versi asli), dan pengiriman berkas memakai mw.Api().upload(),
 * bukan form + iframe manual seperti versi lama. Hasilnya jauh lebih
 * pendek (~350 baris vs ~2400 baris) dan lebih mudah dirawat.
 * ===============================================================
 */
( function () {
	'use strict';

	// -----------------------------------------------------------
	// Konfigurasi 5 kategori lisensi. Untuk menambah/mengubah opsi
	// lisensi, cukup ubah bagian ini saja.
	// -----------------------------------------------------------
	var LICENSE_CATEGORIES = [
		{
			id: 'free',
			label: 'Lisensi bebas',
			hint: 'Karya sendiri dan/atau dari orang lain, di bawah lisensi bebas.',
			// beberapa pilihan tag di dalam kategori ini
			choices: [
				{ tag: 'CC BY-SA 4.0', text: 'This is licensed under the Creative Commons Attribution-Share Alike License 4.0' },
				{ tag: 'CC BY 4.0', text: 'This is licensed under the Creative Commons Attribution License 4.0' }
			],
			fields: [ 'author', 'source', 'date' ]
		},
		{
			id: 'self',
			label: 'Gambar sendiri (lisensi non-bebas)',
			hint: 'This is copyrighted. I created this image myself.',
			tag: 'Self',
			fields: [ 'date' ]
		},
		{
			id: 'permission',
			label: 'Gambar dari orang lain (lisensi non-bebas)',
			hint: 'This is copyrighted, but use is permitted by the copyright holder.',
			tag: 'Permission',
			fields: [ 'author', 'source', 'permission' ]
		},
		{
			id: 'fairuse',
			label: 'Fair dealing / fair use',
			hint: 'This will be used in a way that qualifies as fair dealing under UK law.',
			tag: 'Fairuse',
			fields: [ 'author', 'source', 'article', 'rationale' ]
		},
		{
			id: 'pd',
			label: 'Lainnya (domain publik)',
			hint: 'This is in the public domain.',
			tag: 'PD',
			fields: [ 'author', 'source', 'explanation' ]
		}
	];

	// keterangan tiap field tambahan yang dipakai kategori-kategori di atas
	var FIELD_META = {
		author: { label: 'Pembuat/pemegang hak cipta', type: 'text' },
		source: { label: 'Sumber', type: 'text', hint: 'Dari mana berkas ini didapat?' },
		date: { label: 'Tanggal pembuatan', type: 'text', hint: 'Format YYYY-MM-DD bila memungkinkan.' },
		permission: { label: 'Bukti izin', type: 'textarea', hint: 'Bagaimana izin diperoleh (mis. lewat surel, tautan pernyataan lisensi, dsb.)' },
		article: { label: 'Artikel tempat berkas digunakan', type: 'text' },
		rationale: { label: 'Alasan penggunaan (fair use rationale)', type: 'textarea' },
		explanation: { label: 'Penjelasan status domain publik', type: 'textarea' }
	};

	var api = new mw.Api();
	var state = { file: null, license: null, values: {} };

	function h( tag, attrs, children ) {
		var el = document.createElement( tag );
		attrs = attrs || {};
		for ( var k in attrs ) {
			if ( k === 'text' ) {
				el.textContent = attrs[ k ];
			} else if ( k.indexOf( 'on' ) === 0 ) {
				el[ k ] = attrs[ k ];
			} else {
				el.setAttribute( k, attrs[ k ] );
			}
		}
		( children || [] ).forEach( function ( c ) {
			if ( c ) {
				el.appendChild( c );
			}
		} );
		return el;
	}

	function findCategory( id ) {
		return LICENSE_CATEGORIES.filter( function ( c ) {
			return c.id === id;
		} )[ 0 ];
	}

	// -----------------------------------------------------------
	// Bangun antarmuka
	// -----------------------------------------------------------
	function buildForm() {
		var root = document.getElementById( 'fuwRoot' );
		if ( !root ) {
			return;
		}
		root.innerHTML = '';

		var status = h( 'div', { id: 'fuwStatus', class: 'uploadWarning' } );
		var filenameInput = h( 'input', { type: 'text', id: 'fuwFilename', size: 60 } );
		var fileInput = h( 'input', { type: 'file', id: 'fuwFile' } );
		var descInput = h( 'textarea', { id: 'fuwDesc', rows: 3, style: 'width:90%' } );

		fileInput.onchange = function () {
			state.file = fileInput.files[ 0 ] || null;
			if ( state.file && !filenameInput.value ) {
				filenameInput.value = state.file.name;
			}
		};

		var licenseFieldsWrap = h( 'div', { id: 'fuwLicenseFields' } );

		var licenseRadios = LICENSE_CATEGORIES.map( function ( cat ) {
			var radio = h( 'input', {
				type: 'radio', name: 'fuwLicenseCat', id: 'fuwCat_' + cat.id, value: cat.id
			} );
			radio.onchange = function () {
				selectCategory( cat.id, licenseFieldsWrap );
			};
			return h( 'div', { class: 'fuwLicenseOption' }, [
				radio,
				h( 'label', { for: 'fuwCat_' + cat.id, text: ' ' + cat.label } ),
				h( 'div', { class: 'fuwHint', style: 'color:#555;font-size:90%;margin:0 0 .5em 1.5em', text: cat.hint } )
			] );
		} );

		var submitBtn = h( 'button', { type: 'button', id: 'fuwSubmit', text: 'Unggah' } );
		submitBtn.onclick = doUpload;

		root.appendChild( h( 'div', {}, [
			h( 'h3', { text: 'Langkah 1: Pilih berkas' } ),
			fileInput,
			h( 'h3', { text: 'Langkah 2: Nama dan deskripsi' } ),
			h( 'div', {}, [ h( 'label', { text: 'Nama berkas: ' } ), filenameInput ] ),
			h( 'div', {}, [ h( 'label', { text: 'Deskripsi: ' } ), h( 'br' ), descInput ] ),
			h( 'h3', { text: 'Langkah 3: Status lisensi' } )
		].concat( licenseRadios ).concat( [
			licenseFieldsWrap,
			h( 'h3', { text: 'Langkah 4: Kirim' } ),
			submitBtn,
			status
		] ) ) );

		state.el = { filenameInput: filenameInput, descInput: descInput, status: status };
	}

	function selectCategory( id, wrap ) {
		var cat = findCategory( id );
		state.license = { id: id, tag: null, values: {} };
		wrap.innerHTML = '';

		var tagPicker = null;
		if ( cat.choices ) {
			// kategori "free" punya beberapa pilihan tag (CC BY / CC BY-SA)
			cat.choices.forEach( function ( choice, i ) {
				var r = h( 'input', {
					type: 'radio', name: 'fuwLicenseTag', id: 'fuwTag_' + i, value: choice.tag
				} );
				if ( i === 0 ) {
					r.checked = true;
					state.license.tag = choice.tag;
				}
				r.onchange = function () {
					state.license.tag = choice.tag;
				};
				wrap.appendChild( h( 'div', {}, [
					r, h( 'label', { for: 'fuwTag_' + i, text: ' ' + choice.tag } )
				] ) );
			} );
		} else {
			state.license.tag = cat.tag;
		}

		( cat.fields || [] ).forEach( function ( fieldId ) {
			var meta = FIELD_META[ fieldId ];
			var input = meta.type === 'textarea' ?
				h( 'textarea', { rows: 3, style: 'width:90%', id: 'fuwField_' + fieldId } ) :
				h( 'input', { type: 'text', size: 60, id: 'fuwField_' + fieldId } );
			input.oninput = function () {
				state.license.values[ fieldId ] = input.value;
			};
			var row = h( 'div', { style: 'margin:.3em 0' }, [
				h( 'label', { text: meta.label + ': ' } ),
				h( 'br' ),
				input
			] );
			if ( meta.hint ) {
				row.appendChild( h( 'div', { class: 'fuwHint', style: 'color:#555;font-size:90%', text: meta.hint } ) );
			}
			wrap.appendChild( row );
		} );
	}

	// -----------------------------------------------------------
	// Validasi + rakit teks wiki, lalu kirim lewat mw.Api().upload()
	// -----------------------------------------------------------
	function buildWikitext() {
		var v = state.license.values;
		var desc = state.el.descInput.value.trim();
		var author = v.author || ( '[[User:' + mw.config.get( 'wgUserName' ) + '|' + mw.config.get( 'wgUserName' ) + ']]' );
		var source = v.source || 'Own work';

		var infoBlock = '{{Information\n' +
			'|description = ' + desc + '\n' +
			'|source      = ' + source + '\n' +
			'|date        = ' + ( v.date || '' ) + '\n' +
			'|author      = ' + author + '\n' +
			'|permission  = ' + ( v.permission || '' ) + '\n' +
			'}}';

		var licensingBlock = '{{' + state.license.tag + '}}';

		var extra = '';
		if ( state.license.id === 'fairuse' ) {
			extra = '\n\n=== Fair use rationale ===\n' +
				"'''Artikel''': [[" + ( v.article || '' ) + "]]\n" +
				"'''Alasan''': " + ( v.rationale || '' );
		} else if ( state.license.id === 'pd' ) {
			extra = '\n\n' + ( v.explanation || '' );
		}

		return '== {{int:filedesc}} ==\n' + infoBlock + extra +
			'\n\n== {{int:license-header}} ==\n' + licensingBlock;
	}

	function setStatus( msg, isError ) {
		state.el.status.textContent = msg;
		state.el.status.style.display = msg ? 'block' : 'none';
		state.el.status.style.color = isError ? '#c00' : '#060';
	}

	function validate() {
		if ( !state.file ) {
			return 'Silakan pilih berkas terlebih dahulu.';
		}
		if ( !state.el.filenameInput.value.trim() ) {
			return 'Nama berkas tidak boleh kosong.';
		}
		if ( !state.el.descInput.value.trim() ) {
			return 'Deskripsi tidak boleh kosong.';
		}
		if ( !state.license ) {
			return 'Silakan pilih status lisensi.';
		}
		var missing = ( findCategory( state.license.id ).fields || [] ).filter( function ( f ) {
			// field opsional: permission/rationale/explanation boleh kosong sampai diminta,
			// tapi author & source & date sebaiknya diisi.
			return [ 'permission', 'rationale', 'explanation' ].indexOf( f ) === -1 &&
				!( state.license.values[ f ] || '' ).trim();
		} );
		if ( missing.length ) {
			return 'Mohon lengkapi: ' + missing.map( function ( f ) {
				return FIELD_META[ f ].label;
			} ).join( ', ' );
		}
		return null;
	}

	function doUpload() {
		var err = validate();
		if ( err ) {
			setStatus( err, true );
			return;
		}
		setStatus( 'Mengunggah berkas…', false );
		api.upload( state.file, {
			filename: state.el.filenameInput.value.trim(),
			text: buildWikitext(),
			comment: 'Diunggah lewat File Upload Wizard',
			ignorewarnings: true
		} ).done( function ( data ) {
			var page = data.upload && data.upload.filename ?
				'File:' + data.upload.filename : '';
			setStatus( 'Berhasil diunggah! ' + ( page ? 'Lihat: ' + page : '' ), false );
		} ).fail( function ( code, result ) {
			var msg = ( result && result.error && result.error.info ) || code;
			setStatus( 'Gagal mengunggah: ' + msg, true );
		} );
	}

	// -----------------------------------------------------------
	// Entry point
	// -----------------------------------------------------------
	mw.loader.using( [ 'mediawiki.api', 'mediawiki.user' ] ).then( function () {
		if ( mw.config.get( 'wgUserName' ) === null ) {
			var root = document.getElementById( 'fuwRoot' );
			if ( root ) {
				root.textContent = 'Anda harus masuk (login) untuk mengunggah berkas.';
			}
			return;
		}
		buildForm();
	} );

}() );

