.mp-hero{
  border-radius:22px;
  overflow:hidden;
  box-shadow:0 0 0 2px rgba(0,0,0,.35);
  margin: 26px auto 26px;
  color:#fff;
  max-width:980px;

  background-image:
    linear-gradient(rgba(255, 2, 255, 0.22), rgba(0, 0, 0, 0.60)),
    url("https://static.wikitide.net/nullscapewiki/3/30/NullscapeMPheroBackgroundDownscaled.png");
  background-size:cover;
  background-position:center;
  background-repeat:no-repeat;
}

.mp-hero-banner{
  line-height:0;
  display:flex;
  justify-content:center;
  padding:26px 14px 0;
}

.mp-hero-banner .mw-file-element{
  display:block;
  width:100%;
  max-width:800px;
  height:auto;
  border-radius:18px;
}

.mp-hero-stats{
  text-align:center;
  font-family:"AccanthisADFStd-Regular",Georgia,serif;
  font-size:16px;
  letter-spacing:.4px;
  opacity:.95;
  text-shadow:0 2px 6px rgba(0,0,0,.65);
  margin:10px 0 0;
  padding:0 18px;
}

@media (max-width:800px){
  .mp-hero-stats{
    font-size:14px;
    margin-top:8px;
  }
}


.mp-hero-body{
  padding:16px 22px 22px;
  background:transparent;
}

.mp-hero-bottom{
  display:flex;
  gap:18px;
  align-items:flex-start;
}

.mp-hero-text{
  flex:1 1 0;
  min-width:0;
}

.mp-hero-section{
  font-family:"AccanthisADFStd-Regular",Georgia,serif;
  font-size:25px;
  margin:0 0 5px;
  letter-spacing:.5px;
  text-shadow:0 2px 6px rgba(0,0,0,.65);
}

.mp-hero-desc{
  font-family:"AccanthisADFStd-Regular",Georgia,serif;
  font-size:17px;
  line-height:1.45;
  opacity:.95;
  text-shadow:0 2px 6px rgba(0,0,0,.65);
  overflow-wrap: normal;
  word-break:break-word;
}

.mp-hero-right{
  flex:0 0 180px;
  line-height:0;
  display:flex;
  justify-content:flex-end;
}

.mp-hero-right .mw-file-element{
  display:block;
  width:180px;
  height:auto;
  border-radius:14px;
  box-shadow:0 4px 12px rgba(0,0,0,.5);
  transition:transform 260ms ease, box-shadow 260ms ease;
  transform-origin:center center;
}

.mp-hero-right:hover .mw-file-element{
  transform:scale(1.08) rotate(3deg);
  box-shadow:0 8px 20px rgba(0,0,0,.6);
}

@media (max-width:800px){
  .mp-hero-body{padding:14px 16px 16px;}
  .mp-hero-bottom{flex-direction:column;}
  .mp-hero-right{align-self:center;flex:0 0 auto;justify-content:center;}
  .mp-hero-banner .mw-file-element{max-width:100%;}
  .mp-hero-right .mw-file-element{width:160px;}
}

